    public enum OfficeAppMode { Home, Writer, Calc, Slides, Pdf }

    public class DocTab
    {
        public string Title { get; set; }
        public OfficeAppMode Mode { get; set; }
        public bool Active { get; set; }
        public bool IsModified { get; set; }
        public string FilePath { get; set; }

        // State cho Slides
        public PresentationRoot PresentationData { get; set; }
        public int ActiveSlideIndex { get; set; }
        public float SlideZoomLevel { get; set; }
        public int SlideCanvasScrollX { get; set; }
        public int SlideCanvasScrollY { get; set; }

        // State cho Writer
        public PieceTable WriterPieceTable { get; set; }
        public List<FormattedRun> WriterFormattedRuns { get; set; }
        public List<DocShapeObject> WriterShapes { get; set; }
        public List<DocChartObject> WriterCharts { get; set; }
        public int WriterCursorPosition { get; set; }
        public int WriterSelectionStart { get; set; }
        public int WriterSelectionEnd { get; set; }
        public float WriterZoomLevel { get; set; }
        public float WriterScrollY { get; set; }
        public int WriterViewMode { get; set; }
        public Dictionary<int, int> WriterParagraphAlignments { get; set; }
        public Dictionary<int, Color> WriterParagraphBottomBorders { get; set; }
        public Dictionary<int, int> WriterTablePageX { get; set; }
        public Dictionary<int, int> WriterTablePageY { get; set; }
        public Dictionary<int, int> WriterTableWrapModes { get; set; }
        public Dictionary<int, Size> WriterTableCustomSizes { get; set; }
        public Dictionary<int, List<int>> WriterTableColWidths { get; set; }
        public Dictionary<int, List<int>> WriterTableRowHeights { get; set; }

        // State cho Calc
        public List<SparseMatrix> CalcSheets { get; set; }
        public List<string> CalcSheetNames { get; set; }
        public int CalcActiveSheetIndex { get; set; }
        public uint CalcSelectedRow { get; set; }
        public uint CalcSelectedCol { get; set; }
        public uint CalcSelEndRow { get; set; }
        public uint CalcSelEndCol { get; set; }
        public uint CalcScrollRow { get; set; }
        public uint CalcScrollCol { get; set; }
        public Dictionary<uint, int> CalcColWidths { get; set; }
        public Dictionary<uint, int> CalcRowHeights { get; set; }

        // State cho PDF
        public PdfDocument PdfData { get; set; }
        public int PdfActivePageIndex { get; set; }
        public float PdfZoomLevel { get; set; }
        public float PdfScrollY { get; set; }
        public int PdfSelectedTool { get; set; }

        public DocTab(string title, OfficeAppMode mode, bool active = false, bool isModified = false)
        {
            Title = title;
            Mode = mode;
            Active = active;
            IsModified = isModified;
            FilePath = "";
            ActiveSlideIndex = 0;
            SlideZoomLevel = 1.0f;
            SlideCanvasScrollX = 0;
            SlideCanvasScrollY = 0;

            WriterCursorPosition = 0;
            WriterSelectionStart = 0;
            WriterSelectionEnd = 0;
            WriterZoomLevel = 1.0f;
            WriterScrollY = 0f;
            WriterViewMode = 1;
            WriterParagraphAlignments = new Dictionary<int, int>();
            WriterParagraphBottomBorders = new Dictionary<int, Color>();
            WriterTablePageX = new Dictionary<int, int>();
            WriterTablePageY = new Dictionary<int, int>();
            WriterTableWrapModes = new Dictionary<int, int>();
            WriterTableCustomSizes = new Dictionary<int, Size>();
            WriterTableColWidths = new Dictionary<int, List<int>>();
            WriterTableRowHeights = new Dictionary<int, List<int>>();

            CalcActiveSheetIndex = 0;
            CalcSelectedRow = 1;
            CalcSelectedCol = 1;
            CalcSelEndRow = 1;
            CalcSelEndCol = 1;
            CalcScrollRow = 1;
            CalcScrollCol = 1;
            CalcColWidths = new Dictionary<uint, int>();
            CalcRowHeights = new Dictionary<uint, int>();

            PdfActivePageIndex = 0;
            PdfZoomLevel = 1.0f;
            PdfScrollY = 0f;
            PdfSelectedTool = 0;

            if (mode == OfficeAppMode.Slides)
            {
                PresentationData = new PresentationRoot();
            }
            else if (mode == OfficeAppMode.Writer)
            {
                WriterPieceTable = new PieceTable();
                WriterFormattedRuns = new List<FormattedRun>();
                WriterShapes = new List<DocShapeObject>();
                WriterCharts = new List<DocChartObject>();
            }
            else if (mode == OfficeAppMode.Calc)
            {
                CalcSheets = new List<SparseMatrix> { new SparseMatrix() };
                CalcSheetNames = new List<string> { "Sheet1" };
            }
            else if (mode == OfficeAppMode.Pdf)
            {
                PdfData = new PdfDocument(title);
            }
        }
    }

