        // Tab Strip Horizontal Scroll Properties (Cuộn chuột lướt tab ngang)
        public float TabScrollX = 0f;
        public float TargetTabScrollX = 0f;

        public bool UpdateTabScroll()
        {
            if (Math.Abs(TargetTabScrollX - TabScrollX) > 0.5f)
            {
                TabScrollX += (TargetTabScrollX - TabScrollX) * 0.35f;
                return true;
            }
            else if (TabScrollX != TargetTabScrollX)
            {
                TabScrollX = TargetTabScrollX;
                return true;
            }
            return false;
        }

        public void EnsureActiveTabVisible(int width = 1366)
        {
            if (ActiveDocIndex <= 0) return; // Trang chính luôn cố định ở bên trái
            int docAreaX = 265;
            int docAreaW = Math.Max(100, width - docAreaX - 10);
            int tabOffset = (ActiveDocIndex - 1) * (160 + 4);
            int tabWidth = 160;

            if (tabOffset - TargetTabScrollX < 0)
            {
                TargetTabScrollX = tabOffset;
            }
            else if (tabOffset + tabWidth - TargetTabScrollX > docAreaW)
            {
                TargetTabScrollX = tabOffset + tabWidth - docAreaW + 36;
            }
            int totalDocTabsWidth = (DocTabs.Count - 1) * (160 + 4) + 36;
            int maxTabScroll = Math.Max(0, totalDocTabsWidth - docAreaW);
            TargetTabScrollX = Math.Max(0, Math.Min(maxTabScroll, TargetTabScrollX));
        }

        // Tab Drag & Drop Reordering Properties (Kéo thả sắp xếp lại vị trí tab & Tự động cuộn)
        public bool IsDraggingTab = false;
        public int DraggingTabIndex = -1;
        public float DragMouseStartX = 0;
        public float DragCurrentMouseX = 0;
        public int DragTargetIndex = -1;

        public bool StartTabDrag(int x, int y, int width)
        {
            if (y > 36) return false;
            int docAreaX = 265;
            int docAreaW = Math.Max(10, width - docAreaX - 10);
            Rectangle docClipRect = new Rectangle(docAreaX, 0, docAreaW, 36);

            if (!docClipRect.Contains(x, y)) return false;

            for (int i = 1; i < DocTabs.Count; i++)
            {
                if (i < DocTabCloseBounds.Count && !DocTabCloseBounds[i].IsEmpty && DocTabCloseBounds[i].Contains(x, y))
                {
                    // Đang click nút đóng tab (×), không bắt đầu kéo
                    return false;
                }
                if (i < DocTabBounds.Count && DocTabBounds[i].Contains(x, y))
                {
                    DraggingTabIndex = i;
                    DragMouseStartX = x;
                    DragCurrentMouseX = x;
                    DragTargetIndex = i;
                    IsDraggingTab = false;
                    return true;
                }
            }
            return false;
        }

        public void UpdateTabDrag(int x, int width)
        {
            if (DraggingTabIndex < 1 || DraggingTabIndex >= DocTabs.Count) return;
            DragCurrentMouseX = x;
            if (!IsDraggingTab && Math.Abs(x - DragMouseStartX) > 4)
            {
                IsDraggingTab = true;
            }

            if (IsDraggingTab)
            {
                int docAreaX = 265;
                int tabWidth = 160 + 4;
                float currentTabScroll = TabScrollX;

                // Tính toán chỉ số tab đích để thả vào
                float relativeX = x - docAreaX + currentTabScroll;
                int target = (int)Math.Floor(relativeX / tabWidth) + 1;
                if (target < 1) target = 1;
                if (target >= DocTabs.Count) target = DocTabs.Count - 1;
                DragTargetIndex = target;

                // Tự động cuộn dải tab khi kéo sát mép
                ProcessDragAutoScroll(width);
            }
        }

        public bool ProcessDragAutoScroll(int width)
        {
            if (!IsDraggingTab || DraggingTabIndex < 1) return false;
            int docAreaX = 265;
            int docAreaW = Math.Max(100, width - docAreaX - 10);
            int totalDocTabsWidth = (DocTabs.Count - 1) * (160 + 4) + 36;
            int maxTabScroll = Math.Max(0, totalDocTabsWidth - docAreaW);

            bool scrolled = false;
            if (DragCurrentMouseX < docAreaX + 60)
            {
                // Kéo sát mép trái -> Tự động cuộn sang trái
                float proximity = Math.Max(1f, docAreaX + 60 - DragCurrentMouseX);
                float speed = Math.Min(25f, proximity * 0.4f);
                TargetTabScrollX = Math.Max(0, TargetTabScrollX - speed);
                scrolled = true;
            }
            else if (DragCurrentMouseX > width - 70)
            {
                // Kéo sát mép phải -> Tự động cuộn sang phải
                float proximity = Math.Max(1f, DragCurrentMouseX - (width - 70));
                float speed = Math.Min(25f, proximity * 0.4f);
                TargetTabScrollX = Math.Min(maxTabScroll, TargetTabScrollX + speed);
                scrolled = true;
            }
            return scrolled;
        }

        public bool FinishTabDrag(int width = 1366)
        {
            if (!IsDraggingTab)
            {
                DraggingTabIndex = -1;
                DragTargetIndex = -1;
                return false;
            }

            bool reordered = false;
            if (DraggingTabIndex >= 1 && DragTargetIndex >= 1 && DraggingTabIndex < DocTabs.Count && DragTargetIndex < DocTabs.Count && DraggingTabIndex != DragTargetIndex)
            {
                DocTab draggedTab = DocTabs[DraggingTabIndex];
                DocTabs.RemoveAt(DraggingTabIndex);
                DocTabs.Insert(DragTargetIndex, draggedTab);

                ActiveDocIndex = DragTargetIndex;
                for (int i = 0; i < DocTabs.Count; i++)
                {
                    DocTabs[i].Active = (i == ActiveDocIndex);
                }
                CurrentMode = DocTabs[ActiveDocIndex].Mode;
                EnsureActiveTabVisible(width);
                reordered = true;
            }

            IsDraggingTab = false;
            DraggingTabIndex = -1;
            DragTargetIndex = -1;
            return reordered;
        }

        public void CancelTabDrag()
        {
            IsDraggingTab = false;
            DraggingTabIndex = -1;
            DragTargetIndex = -1;
        }

        public List<string> AvailableSystemFonts = new List<string>();

        public void LoadSystemFonts()
        {
            AvailableSystemFonts.Clear();
            try
            {
                using (InstalledFontCollection installedFonts = new InstalledFontCollection())
                {
                    foreach (FontFamily family in installedFonts.Families)
                    {
                        if (!string.IsNullOrWhiteSpace(family.Name) && !AvailableSystemFonts.Contains(family.Name))
                        {
                            AvailableSystemFonts.Add(family.Name);
                        }
                    }
                }
            }
            catch
            {
                AvailableSystemFonts = new List<string> {
                    "Times New Roman", "Calibri", "Arial", "Courier New",
                    "Georgia", "Segoe UI", "Tahoma", "Verdana", "Trebuchet MS", "Comic Sans MS"
                };
            }

            try
            {
                string localFontDir = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "fonts");
                if (System.IO.Directory.Exists(localFontDir))
                {
                    using (PrivateFontCollection privateFonts = new PrivateFontCollection())
                    {
                        foreach (string fontFile in System.IO.Directory.GetFiles(localFontDir, "*.*"))
                        {
                            if (fontFile.EndsWith(".ttf", StringComparison.OrdinalIgnoreCase) ||
                                fontFile.EndsWith(".otf", StringComparison.OrdinalIgnoreCase))
                            {
                                privateFonts.AddFontFile(fontFile);
                            }
                        }
                        foreach (FontFamily family in privateFonts.Families)
                        {
                            if (!string.IsNullOrWhiteSpace(family.Name) && !AvailableSystemFonts.Contains(family.Name))
                            {
                                AvailableSystemFonts.Add(family.Name);
                            }
                        }
                    }
                }
            }
            catch { }

            // Sắp xếp toàn bộ phông chữ hệ thống theo thứ tự A-Z
            AvailableSystemFonts.Sort(StringComparer.OrdinalIgnoreCase);
        }

        public Color PrimaryColor
        {
            get
            {
                switch (CurrentMode)
                {
                    case OfficeAppMode.Home: return Color.FromArgb(31, 41, 55);
                    case OfficeAppMode.Writer: return Color.FromArgb(43, 87, 154);
                    case OfficeAppMode.Calc: return Color.FromArgb(33, 115, 70);
                    case OfficeAppMode.Slides: return Color.FromArgb(210, 71, 38);
                    case OfficeAppMode.Pdf: return Color.FromArgb(220, 38, 38);
                    default: return Color.FromArgb(31, 41, 55);
                }
            }
        }

        public RibbonBar()
        {
            CurrentMode = OfficeAppMode.Home;
            DocTabs = new List<DocTab>();
            ActiveDocIndex = 0;

            RibbonTabs = new string[] { "Trang đầu", "Chèn", "Thiết kế", "Bố trí", "Tham chiếu", "Hiển thị" };
            ActiveRibbonTab = 0;

            HoverX = -1;
            HoverY = -1;

            SelectedFont = "Times New Roman";
            FontSize = 11.0f;
            IsBold = false;
            IsItalic = false;
            IsUnderline = false;
            IsStrikethrough = false;
            IsSubscript = false;
            IsSuperscript = false;
            CurrentFontColor = Color.Black;
            CurrentHighlightColor = Color.Transparent;
            Alignment = 0;
            ActiveStyle = "Normal";

            LoadSystemFonts();

            ActiveTheme = "Office";
            ThemeFontHeading = "Calibri Light";
            ThemeFontBody = "Calibri";
            ThemeColorPalette = new Color[] { Color.FromArgb(68, 114, 196), Color.FromArgb(237, 125, 49), Color.FromArgb(165, 165, 165), Color.FromArgb(255, 192, 0) };
            ThemeColorPaletteName = "Office";
            ActiveStyleSetIndex = 0;
            ActiveThemeEffectIndex = 0;
            ParagraphSpacingPreset = "Mặc định";
            ParagraphSpacingBefore = 0f;
            ParagraphSpacingAfter = 8f;
            WatermarkText = "";
            WatermarkIsDiagonal = true;
            PageBgColor = Color.White;
            HasPageBorder = false;
            PageBorderColor = Color.FromArgb(43, 87, 154);
            PageBorderWidth = 2.0f;
            PageBorderStyleType = 1;

            MarginMode = 0;
            CustomTopMargin = 1.0f;
            CustomBottomMargin = 1.0f;
            CustomLeftMargin = 1.0f;
            CustomRightMargin = 1.0f;

            IsLandscape = false;
            LineSpacingFactor = 1.15f;

            PaperSizeName = "A4";
            PaperWidthInches = 8.27f;
            PaperHeightInches = 11.69f;
            ColumnCount = 1;
            ColumnSpacingInches = 0.5f;
            ColumnLineBetween = false;
            ColumnPreset = "One";

            ShowRuler = false;
            ShowGridlines = false;

            DocTabs.Add(new DocTab("Trang chính", OfficeAppMode.Home, true));
        }

        public float GetEffectiveLeftMarginInches()
        {
            if (MarginMode == 1) return 0.5f;   // Narrow
            if (MarginMode == 2) return 0.75f;  // Moderate
            if (MarginMode == 3) return 2.0f;   // Wide
            if (MarginMode == 4) return CustomLeftMargin; // Custom
            return 1.0f; // Normal (Default 1.0 inch)
        }

        public float GetEffectiveRightMarginInches()
        {
            if (MarginMode == 1) return 0.5f;   // Narrow
            if (MarginMode == 2) return 0.75f;  // Moderate
            if (MarginMode == 3) return 2.0f;   // Wide
            if (MarginMode == 4) return CustomRightMargin; // Custom
            return 1.0f; // Normal (Default 1.0 inch)
        }

        public float GetEffectiveTopMarginInches()
        {
            if (MarginMode == 1) return 0.5f;   // Narrow
            if (MarginMode == 2) return 1.0f;   // Moderate
            if (MarginMode == 3) return 1.0f;   // Wide
            if (MarginMode == 4) return CustomTopMargin; // Custom
            return 1.0f; // Normal (Default 1.0 inch)
        }

        public float GetEffectiveBottomMarginInches()
        {
            if (MarginMode == 1) return 0.5f;   // Narrow
            if (MarginMode == 2) return 1.0f;   // Moderate
            if (MarginMode == 3) return 1.0f;   // Wide
            if (MarginMode == 4) return CustomBottomMargin; // Custom
            return 1.0f; // Normal (Default 1.0 inch)
        }

        public void UpdateHover(int x, int y)
        {
            HoverX = x;
            HoverY = y;
        }

        public bool IsHovering(Rectangle rect)
        {
            return rect.Contains(HoverX, HoverY);
        }

        public void SaveTabState(int index, SlidesView slidesView, WriterView writerView, CalcView calcView, PdfView pdfView = null)
        {
            if (index < 0 || index >= DocTabs.Count) return;
            DocTab tab = DocTabs[index];
            if (tab.Mode == OfficeAppMode.Slides && slidesView != null)
            {
                tab.PresentationData = slidesView.Presentation;
                tab.ActiveSlideIndex = slidesView.ActiveSlideIndex;
                tab.SlideZoomLevel = slidesView.ZoomLevel;
                tab.SlideCanvasScrollX = slidesView.CanvasScrollX;
                tab.SlideCanvasScrollY = slidesView.CanvasScrollY;
            }
            else if (tab.Mode == OfficeAppMode.Writer && writerView != null)
            {
                tab.WriterPieceTable = writerView.PieceTable;
                tab.WriterFormattedRuns = writerView.FormattedRuns;
                tab.WriterShapes = writerView.DocumentShapes;
                tab.WriterCharts = writerView.DocumentCharts;
                tab.WriterCursorPosition = writerView.CursorPosition;
                tab.WriterSelectionStart = writerView.SelectionStart;
                tab.WriterSelectionEnd = writerView.SelectionEnd;
                tab.WriterZoomLevel = writerView.ZoomLevel;
                tab.WriterScrollY = writerView.SmoothScrollY;
                tab.WriterViewMode = writerView.ViewMode;
                tab.WriterParagraphAlignments = writerView.ParagraphAlignments;
                tab.WriterParagraphBottomBorders = writerView.ParagraphBottomBorders;
                tab.WriterTablePageX = writerView.TablePageX;
                tab.WriterTablePageY = writerView.TablePageY;
                tab.WriterTableWrapModes = writerView.TableWrapModes;
                tab.WriterTableCustomSizes = writerView.TableCustomSizes;
                tab.WriterTableColWidths = writerView.TableColWidths;
                tab.WriterTableRowHeights = writerView.TableRowHeights;
            }
            else if (tab.Mode == OfficeAppMode.Calc && calcView != null)
            {
                tab.CalcSheets = calcView.Sheets;
                tab.CalcSheetNames = calcView.SheetNames;
                tab.CalcActiveSheetIndex = calcView.ActiveSheetIndex;
                tab.CalcSelectedRow = calcView.SelectedRow;
                tab.CalcSelectedCol = calcView.SelectedCol;
                tab.CalcSelEndRow = calcView.SelEndRow;
                tab.CalcSelEndCol = calcView.SelEndCol;
                tab.CalcScrollRow = calcView.ScrollRow;
                tab.CalcScrollCol = calcView.ScrollCol;
                tab.CalcColWidths = calcView.CustomColWidths != null ? new Dictionary<uint, int>(calcView.CustomColWidths) : new Dictionary<uint, int>();
                tab.CalcRowHeights = calcView.CustomRowHeights != null ? new Dictionary<uint, int>(calcView.CustomRowHeights) : new Dictionary<uint, int>();
            }
            else if (tab.Mode == OfficeAppMode.Pdf && pdfView != null)
            {
                tab.PdfData = pdfView.Document;
                tab.PdfActivePageIndex = pdfView.ActivePageIndex;
                tab.PdfZoomLevel = pdfView.ZoomLevel;
                tab.PdfScrollY = pdfView.ScrollY;
                tab.PdfSelectedTool = pdfView.SelectedTool;
            }
        }

        public void LoadTabState(int index, SlidesView slidesView, WriterView writerView, CalcView calcView, PdfView pdfView = null)
        {
            if (index < 0 || index >= DocTabs.Count) return;
            DocTab tab = DocTabs[index];
            CurrentMode = tab.Mode;

            if (tab.Mode == OfficeAppMode.Slides && slidesView != null)
            {
                RibbonTabs = new string[] { "Trang đầu", "Chèn", "Thiết kế", "Chuyển tiếp", "Hoạt họa", "Trình chiếu", "Hiển thị" };
                if (ActiveRibbonTab >= RibbonTabs.Length) ActiveRibbonTab = 0;
                if (tab.PresentationData == null) tab.PresentationData = new PresentationRoot();
                slidesView.Presentation = tab.PresentationData;
                slidesView.ActiveSlideIndex = Math.Max(0, Math.Min(slidesView.Presentation.Slides.Count - 1, tab.ActiveSlideIndex));
                slidesView.ZoomLevel = tab.SlideZoomLevel > 0 ? tab.SlideZoomLevel : 1.0f;
                slidesView.CanvasScrollX = tab.SlideCanvasScrollX;
                slidesView.CanvasScrollY = tab.SlideCanvasScrollY;
                slidesView.SelectedShapeIndex = -1;
                if (slidesView.SelectedShapeIndices != null) slidesView.SelectedShapeIndices.Clear();
                slidesView.EndInlineEditing();
            }
            else if (tab.Mode == OfficeAppMode.Writer && writerView != null)
            {
                RibbonTabs = new string[] { "Trang đầu", "Chèn", "Thiết kế", "Bố trí", "Tham chiếu", "Hiển thị" };
                if (ActiveRibbonTab >= RibbonTabs.Length) ActiveRibbonTab = 0;
                if (tab.WriterPieceTable == null) tab.WriterPieceTable = new PieceTable();
                writerView.PieceTable = tab.WriterPieceTable;
                writerView.FormattedRuns = tab.WriterFormattedRuns ?? new List<FormattedRun>();
                writerView.DocumentShapes = tab.WriterShapes ?? new List<DocShapeObject>();
                writerView.DocumentCharts = tab.WriterCharts ?? new List<DocChartObject>();
                writerView.CursorPosition = tab.WriterCursorPosition;
                writerView.SelectionStart = tab.WriterSelectionStart;
                writerView.SelectionEnd = tab.WriterSelectionEnd;
                writerView.ZoomLevel = tab.WriterZoomLevel > 0 ? tab.WriterZoomLevel : 1.0f;
                writerView.SmoothScrollY = tab.WriterScrollY;
                writerView.TargetScrollY = tab.WriterScrollY;
                writerView.ViewMode = tab.WriterViewMode;
                writerView.ParagraphAlignments = tab.WriterParagraphAlignments ?? new Dictionary<int, int>();
                writerView.ParagraphBottomBorders = tab.WriterParagraphBottomBorders ?? new Dictionary<int, Color>();
                writerView.TablePageX = tab.WriterTablePageX ?? new Dictionary<int, int>();
                writerView.TablePageY = tab.WriterTablePageY ?? new Dictionary<int, int>();
                writerView.TableWrapModes = tab.WriterTableWrapModes ?? new Dictionary<int, int>();
                writerView.TableCustomSizes = tab.WriterTableCustomSizes ?? new Dictionary<int, Size>();
                writerView.TableColWidths = tab.WriterTableColWidths ?? new Dictionary<int, List<int>>();
                writerView.TableRowHeights = tab.WriterTableRowHeights ?? new Dictionary<int, List<int>>();
            }
            else if (tab.Mode == OfficeAppMode.Calc && calcView != null)
            {
                RibbonTabs = new string[] { "Trang đầu", "Chèn", "Bố trí trang", "Công thức", "Dữ liệu", "Xem lại", "Hiển thị" };
                if (ActiveRibbonTab >= RibbonTabs.Length) ActiveRibbonTab = 0;
                if (tab.CalcSheets == null || tab.CalcSheets.Count == 0)
                {
                    tab.CalcSheets = new List<SparseMatrix> { new SparseMatrix() };
                    tab.CalcSheetNames = new List<string> { "Sheet1" };
                }
                calcView.Sheets = tab.CalcSheets;
                calcView.SheetNames = tab.CalcSheetNames ?? new List<string> { "Sheet1" };
                calcView.ActiveSheetIndex = Math.Max(0, Math.Min(calcView.Sheets.Count - 1, tab.CalcActiveSheetIndex));
                calcView.SelectedRow = tab.CalcSelectedRow > 0 ? tab.CalcSelectedRow : 1;
                calcView.SelectedCol = tab.CalcSelectedCol > 0 ? tab.CalcSelectedCol : 1;
                calcView.SelEndRow = tab.CalcSelEndRow > 0 ? tab.CalcSelEndRow : calcView.SelectedRow;
                calcView.SelEndCol = tab.CalcSelEndCol > 0 ? tab.CalcSelEndCol : calcView.SelectedCol;
                calcView.ScrollRow = tab.CalcScrollRow > 0 ? tab.CalcScrollRow : 1;
                calcView.ScrollCol = tab.CalcScrollCol > 0 ? tab.CalcScrollCol : 1;
                calcView.CustomColWidths = tab.CalcColWidths != null ? new Dictionary<uint, int>(tab.CalcColWidths) : new Dictionary<uint, int>();
                calcView.CustomRowHeights = tab.CalcRowHeights != null ? new Dictionary<uint, int>(tab.CalcRowHeights) : new Dictionary<uint, int>();
            }
            else if (tab.Mode == OfficeAppMode.Pdf && pdfView != null)
            {
                RibbonTabs = new string[] { "Trang đầu", "Chú thích", "Chỉnh sửa", "Trang", "Ký & Bảo mật", "Hiển thị" };
                if (ActiveRibbonTab >= RibbonTabs.Length) ActiveRibbonTab = 0;
                if (tab.PdfData == null) tab.PdfData = new PdfDocument(tab.Title);
                pdfView.Document = tab.PdfData;
                pdfView.ActivePageIndex = Math.Max(0, Math.Min(pdfView.Document.Pages.Count - 1, tab.PdfActivePageIndex));
                pdfView.ZoomLevel = tab.PdfZoomLevel > 0 ? tab.PdfZoomLevel : 1.0f;
                pdfView.ScrollY = tab.PdfScrollY;
                pdfView.TargetScrollY = tab.PdfScrollY;
                pdfView.SelectedTool = tab.PdfSelectedTool;
            }
        }

        public void AddDocTab(string title, OfficeAppMode mode, SlidesView slidesView = null, WriterView writerView = null, CalcView calcView = null, PdfView pdfView = null)
        {
            SaveTabState(ActiveDocIndex, slidesView, writerView, calcView, pdfView);

            foreach (var tab in DocTabs) tab.Active = false;
            DocTab newTab = new DocTab(title, mode, true, false);

            if (mode == OfficeAppMode.Slides)
            {
                newTab.PresentationData = new PresentationRoot();
                SlideNode defaultSlide = new SlideNode { Layout = SlideLayoutType.TitleSlide };
                if (slidesView != null)
                {
                    slidesView.ApplySlideLayoutTemplate(defaultSlide, SlideLayoutType.TitleSlide);
                }
                newTab.PresentationData.Slides.Add(defaultSlide);
            }
            else if (mode == OfficeAppMode.Writer)
            {
                newTab.WriterPieceTable = new PieceTable("");
                newTab.WriterFormattedRuns = new List<FormattedRun>();
                newTab.WriterCursorPosition = 0;
            }
            else if (mode == OfficeAppMode.Calc)
            {
                newTab.CalcSheets = new List<SparseMatrix> { new SparseMatrix(), new SparseMatrix(), new SparseMatrix() };
                newTab.CalcSheetNames = new List<string> { "Sheet1", "Sheet2", "Sheet3" };
                newTab.CalcColWidths = new Dictionary<uint, int>();
                newTab.CalcRowHeights = new Dictionary<uint, int>();
                if (calcView != null)
                {
                    calcView.CustomColWidths.Clear();
                    calcView.CustomRowHeights.Clear();
                }
            }
            else if (mode == OfficeAppMode.Pdf)
            {
                newTab.PdfData = new PdfDocument(title);
                newTab.PdfActivePageIndex = 0;
                newTab.PdfZoomLevel = 1.0f;
                newTab.PdfScrollY = 0f;
                newTab.PdfSelectedTool = 0;
                if (pdfView != null)
                {
                    pdfView.Document = newTab.PdfData;
                    pdfView.ActivePageIndex = 0;
                    pdfView.ZoomLevel = 1.0f;
                    pdfView.ScrollY = 0f;
                }
            }

            DocTabs.Add(newTab);
            ActiveDocIndex = DocTabs.Count - 1;
            CurrentMode = mode;
            EnsureActiveTabVisible();

            LoadTabState(ActiveDocIndex, slidesView, writerView, calcView, pdfView);
        }

        public void SwitchDocTab(int index, SlidesView slidesView = null, WriterView writerView = null, CalcView calcView = null, PdfView pdfView = null)
        {
            if (index >= 0 && index < DocTabs.Count)
            {
                if (index == ActiveDocIndex && DocTabs[index].Active) return;

                SaveTabState(ActiveDocIndex, slidesView, writerView, calcView, pdfView);

                for (int i = 0; i < DocTabs.Count; i++)
                {
                    DocTabs[i].Active = (i == index);
                }
                ActiveDocIndex = index;
                CurrentMode = DocTabs[index].Mode;
                EnsureActiveTabVisible();

                LoadTabState(ActiveDocIndex, slidesView, writerView, calcView, pdfView);
            }
        }

        public bool CloseDocTab(int index, SlidesView slidesView = null, WriterView writerView = null, CalcView calcView = null, PdfView pdfView = null)
        {
            if (index < 0 || index >= DocTabs.Count) return false;
            DocTab tab = DocTabs[index];

            if (tab.Mode == OfficeAppMode.Home) return false;

            if (tab.IsModified)
            {
                DialogResult result = MessageBox.Show(
                    "Tài liệu '" + tab.Title + "' có những thay đổi chưa được lưu.\n\nBạn có muốn LƯU tài liệu trước khi đóng không?",
                    "Cảnh báo chưa lưu - GenOffice",
                    MessageBoxButtons.YesNoCancel,
                    MessageBoxIcon.Warning,
                    MessageBoxDefaultButton.Button1
                );

                if (result == DialogResult.Yes)
                {
                    tab.IsModified = false;
                }
                else if (result == DialogResult.No)
                {
                }
                else
                {
                    return false;
                }
            }

            DocTabs.RemoveAt(index);
            if (ActiveDocIndex >= DocTabs.Count)
            {
                ActiveDocIndex = DocTabs.Count - 1;
            }
            for (int i = 0; i < DocTabs.Count; i++)
            {
                DocTabs[i].Active = (i == ActiveDocIndex);
            }
            if (ActiveDocIndex >= 0 && ActiveDocIndex < DocTabs.Count)
            {
                CurrentMode = DocTabs[ActiveDocIndex].Mode;
                LoadTabState(ActiveDocIndex, slidesView, writerView, calcView, pdfView);
            }
            return true;
        }

        private GraphicsPath CreateRoundedRectanglePath(Rectangle rect, int radius)
        {
            GraphicsPath path = new GraphicsPath();
            int d = radius * 2;
            if (d > rect.Width) d = rect.Width;
            if (d > rect.Height) d = rect.Height;

            path.AddArc(rect.X, rect.Y, d, d, 180, 90);
            path.AddArc(rect.Right - d, rect.Y, d, d, 270, 90);
            path.AddArc(rect.Right - d, rect.Bottom - d, d, d, 0, 90);
            path.AddArc(rect.X, rect.Bottom - d, d, d, 90, 90);
            path.CloseFigure();
            return path;
        }

        private void FillRoundedRectangle(Graphics g, Brush brush, Rectangle rect, int radius)
        {
            using (GraphicsPath path = CreateRoundedRectanglePath(rect, radius))
            {
                g.FillPath(brush, path);
            }
        }

        private void DrawRoundedRectangle(Graphics g, Pen pen, Rectangle rect, int radius)
        {
            using (GraphicsPath path = CreateRoundedRectanglePath(rect, radius))
            {
                g.DrawPath(pen, path);
            }
        }

        private void DrawInteractiveButton(Graphics g, Rectangle rect, bool isActive, int radius = 4)
        {
            bool isHover = IsHovering(rect);
            if (isActive && isHover)
            {
                using (SolidBrush b = new SolidBrush(Color.FromArgb(190, 220, 255)))
                    FillRoundedRectangle(g, b, rect, radius);
                using (Pen p = new Pen(Color.FromArgb(16, 110, 190), 1.2f))
                    DrawRoundedRectangle(g, p, rect, radius);
            }
            else if (isActive)
            {
                using (SolidBrush b = new SolidBrush(Color.FromArgb(204, 230, 255)))
                    FillRoundedRectangle(g, b, rect, radius);
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.0f))
                    DrawRoundedRectangle(g, p, rect, radius);
            }
            else if (isHover)
            {
                using (SolidBrush b = new SolidBrush(Color.FromArgb(232, 240, 250)))
                    FillRoundedRectangle(g, b, rect, radius);
                using (Pen p = new Pen(Color.FromArgb(190, 210, 235), 1.0f))
                    DrawRoundedRectangle(g, p, rect, radius);
            }
        }

        private void DrawAlignmentIcon(Graphics g, int x, int y, int alignType, Color color)
        {
            using (Pen pen = new Pen(color, 1.6f))
            {
                pen.StartCap = LineCap.Round;
                pen.EndCap = LineCap.Round;
                pen.LineJoin = LineJoin.Round;

                float ox = x + 4;
                float oy = y + 4;

                if (alignType == 0) // Align Left
                {
                    g.DrawLine(pen, ox + 1, oy + 2, ox + 14, oy + 2);
                    g.DrawLine(pen, ox + 1, oy + 6, ox + 9, oy + 6);
                    g.DrawLine(pen, ox + 1, oy + 10, ox + 14, oy + 10);
                    g.DrawLine(pen, ox + 1, oy + 14, ox + 7, oy + 14);
                }
                else if (alignType == 1) // Center
                {
                    g.DrawLine(pen, ox + 1, oy + 2, ox + 14, oy + 2);
                    g.DrawLine(pen, ox + 3.5f, oy + 6, ox + 11.5f, oy + 6);
                    g.DrawLine(pen, ox + 1, oy + 10, ox + 14, oy + 10);
                    g.DrawLine(pen, ox + 4.5f, oy + 14, ox + 10.5f, oy + 14);
                }
                else if (alignType == 2) // Align Right
                {
                    g.DrawLine(pen, ox + 1, oy + 2, ox + 14, oy + 2);
                    g.DrawLine(pen, ox + 6, oy + 6, ox + 14, oy + 6);
                    g.DrawLine(pen, ox + 1, oy + 10, ox + 14, oy + 10);
                    g.DrawLine(pen, ox + 8, oy + 14, ox + 14, oy + 14);
                }
                else if (alignType == 3) // Justify
                {
                    g.DrawLine(pen, ox + 1, oy + 2, ox + 14, oy + 2);
                    g.DrawLine(pen, ox + 1, oy + 6, ox + 14, oy + 6);
                    g.DrawLine(pen, ox + 1, oy + 10, ox + 14, oy + 10);
                    g.DrawLine(pen, ox + 1, oy + 14, ox + 14, oy + 14);
                }
            }
        }

        private void DrawOpenIconLarge(Graphics g, float x, float y)
        {
            using (SolidBrush backBrush = new SolidBrush(Color.FromArgb(217, 119, 6)))
            using (Pen backPen = new Pen(Color.FromArgb(180, 83, 9), 1.2f))
            using (SolidBrush paperBrush = new SolidBrush(Color.White))
            using (Pen paperPen = new Pen(Color.FromArgb(203, 213, 225), 1.0f))
            using (Pen linePen = new Pen(Color.FromArgb(148, 163, 184), 1.0f))
            using (SolidBrush flapBrush = new SolidBrush(Color.FromArgb(245, 158, 11)))
            using (Pen flapPen = new Pen(Color.FromArgb(180, 83, 9), 1.3f) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
            {
                // Back Folder Body & Tab
                using (GraphicsPath bp = new GraphicsPath())
                {
                    bp.AddLine(x + 4, y + 8, x + 11, y + 8);
                    bp.AddLine(x + 11, y + 8, x + 14, y + 11);
                    bp.AddLine(x + 14, y + 11, x + 28, y + 11);
                    bp.AddLine(x + 28, y + 11, x + 28, y + 27);
                    bp.AddLine(x + 28, y + 27, x + 4, y + 27);
                    bp.CloseFigure();
                    g.FillPath(backBrush, bp);
                    g.DrawPath(backPen, bp);
                }

                // White paper inside
                RectangleF paper = new RectangleF(x + 8, y + 5, 16, 16);
                g.FillRectangle(paperBrush, paper);
                g.DrawRectangle(paperPen, paper.X, paper.Y, paper.Width, paper.Height);
                g.DrawLine(linePen, x + 11, y + 9, x + 20, y + 9);
                g.DrawLine(linePen, x + 11, y + 13, x + 18, y + 13);

                // Front Tilted Flap
                PointF[] flap = new PointF[] {
                    new PointF(x + 3, y + 15),
                    new PointF(x + 27, y + 15),
                    new PointF(x + 24, y + 28),
                    new PointF(x + 2, y + 28)
                };
                g.FillPolygon(flapBrush, flap);
                g.DrawPolygon(flapPen, flap);
            }
        }

        private void DrawSaveIconLarge(Graphics g, float x, float y)
        {
            using (SolidBrush diskBrush = new SolidBrush(Color.FromArgb(37, 99, 235)))
            using (Pen diskPen = new Pen(Color.FromArgb(29, 78, 216), 1.2f))
            using (SolidBrush shutterBrush = new SolidBrush(Color.FromArgb(226, 232, 240)))
            using (Pen shutterPen = new Pen(Color.FromArgb(148, 163, 184), 1.0f))
            using (SolidBrush notchBrush = new SolidBrush(Color.FromArgb(30, 64, 175)))
            using (SolidBrush labelBrush = new SolidBrush(Color.White))
            using (Pen labelBorder = new Pen(Color.FromArgb(203, 213, 225), 1.0f))
            using (Pen linePen = new Pen(Color.FromArgb(148, 163, 184), 1.0f))
            {
                // Floppy Disk Body
                using (GraphicsPath dp = new GraphicsPath())
                {
                    dp.AddLine(x + 4, y + 4, x + 22, y + 4);
                    dp.AddLine(x + 22, y + 4, x + 26, y + 8);
                    dp.AddLine(x + 26, y + 8, x + 26, y + 27);
                    dp.AddLine(x + 26, y + 27, x + 4, y + 27);
                    dp.CloseFigure();
                    g.FillPath(diskBrush, dp);
                    g.DrawPath(diskPen, dp);
                }

                // Metal Shutter at top
                RectangleF shutter = new RectangleF(x + 8, y + 4, 12, 10);
                g.FillRectangle(shutterBrush, shutter);
                g.DrawRectangle(shutterPen, shutter.X, shutter.Y, shutter.Width, shutter.Height);
                g.FillRectangle(notchBrush, x + 14, y + 6, 3.5f, 6);

                // White Label Area at bottom
                RectangleF label = new RectangleF(x + 7, y + 16, 16, 11);
                g.FillRectangle(labelBrush, label);
                g.DrawRectangle(labelBorder, label.X, label.Y, label.Width, label.Height);
                g.DrawLine(linePen, x + 10, y + 20, x + 20, y + 20);
                g.DrawLine(linePen, x + 10, y + 24, x + 18, y + 24);
            }
        }

        private void DrawOpenIcon(Graphics g, float x, float y, float w, float h, Color color)
        {
            DrawOpenIconLarge(g, x - 3, y - 4);
        }

        private void DrawSaveIcon(Graphics g, float x, float y, float w, float h, Color color)
        {
            DrawSaveIconLarge(g, x - 2, y - 4);
        }

        private void DrawPasteIconLarge(Graphics g, float x, float y)
        {
            // Big Elegant MS Word Style Clipboard
            using (Pen boardPen = new Pen(Color.FromArgb(180, 83, 9), 1.5f))
            using (SolidBrush boardBrush = new SolidBrush(Color.FromArgb(245, 158, 11)))
            using (SolidBrush paperBrush = new SolidBrush(Color.White))
            using (Pen paperBorder = new Pen(Color.FromArgb(203, 213, 225), 1.0f))
            using (Pen linePen = new Pen(Color.FromArgb(148, 163, 184), 1.0f))
            using (SolidBrush clipBrush = new SolidBrush(Color.FromArgb(100, 116, 139)))
            using (Pen clipPen = new Pen(Color.FromArgb(71, 85, 105), 1.2f))
            {
                // Wooden Clipboard Board
                RectangleF boardRect = new RectangleF(x + 6, y + 3, 24, 28);
                using (GraphicsPath bp = new GraphicsPath())
                {
                    bp.AddArc(boardRect.X, boardRect.Y, 4, 4, 180, 90);
                    bp.AddArc(boardRect.Right - 4, boardRect.Y, 4, 4, 270, 90);
                    bp.AddArc(boardRect.Right - 4, boardRect.Bottom - 4, 4, 4, 0, 90);
                    bp.AddArc(boardRect.X, boardRect.Bottom - 4, 4, 4, 90, 90);
                    bp.CloseFigure();
                    g.FillPath(boardBrush, bp);
                    g.DrawPath(boardPen, bp);
                }

                // White Paper
                RectangleF paperRect = new RectangleF(x + 10, y + 7, 16, 21);
                g.FillRectangle(paperBrush, paperRect);
                g.DrawRectangle(paperBorder, paperRect.X, paperRect.Y, paperRect.Width, paperRect.Height);

                // Subtle text lines on paper
                g.DrawLine(linePen, x + 13, y + 12, x + 23, y + 12);
                g.DrawLine(linePen, x + 13, y + 16, x + 23, y + 16);
                g.DrawLine(linePen, x + 13, y + 20, x + 20, y + 20);

                // Top Metal Clip
                RectangleF clipRect = new RectangleF(x + 13, y + 1, 10, 5);
                g.FillRectangle(clipBrush, clipRect);
                g.DrawRectangle(clipPen, clipRect.X, clipRect.Y, clipRect.Width, clipRect.Height);
            }
        }

