            using (SolidBrush b = new SolidBrush(Color.FromArgb(250, 204, 21)))
            {
                // Tilted marker pen
                PointF[] penPts = new PointF[] {
                    new PointF(x + 2, y + 10),
                    new PointF(x + 8, y + 2),
                    new PointF(x + 12, y + 5),
                    new PointF(x + 6, y + 13)
