        private void DrawFormatPainterIcon(Graphics g, float x, float y, Color color)
        {
            using (Pen handlePen = new Pen(color, 1.5f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
            using (SolidBrush ferrule = new SolidBrush(Color.FromArgb(148, 163, 184)))
            using (SolidBrush bristles = new SolidBrush(Color.FromArgb(217, 119, 6)))
            using (Pen paintTrail = new Pen(Color.FromArgb(245, 158, 11), 1.8f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
            {
                // Wooden angled handle
                g.DrawLine(handlePen, x + 2, y + 13, x + 7, y + 7);
                // Silver Ferrule
                g.FillRectangle(ferrule, x + 6.5f, y + 5, 4, 3);
                // Orange Bristles
                PointF[] br = new PointF[] {
                    new PointF(x + 7, y + 5),
