        private void DrawVectorHomeIcon(Graphics g, float x, float y, float size, Color color)
        {
            float s = size / 16f;
            using (Pen p = new Pen(color, 1.5f) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
            using (SolidBrush b = new SolidBrush(color))
            {
                // Roof
                g.DrawLine(p, x + 2 * s, y + 8 * s, x + 8 * s, y + 3 * s);
                g.DrawLine(p, x + 8 * s, y + 3 * s, x + 14 * s, y + 8 * s);
                // Chimney
                g.DrawLine(p, x + 12 * s, y + 6 * s, x + 12 * s, y + 4 * s);

                // Body
                g.DrawLine(p, x + 4 * s, y + 8 * s, x + 4 * s, y + 14 * s);
                g.DrawLine(p, x + 12 * s, y + 8 * s, x + 12 * s, y + 14 * s);
                g.DrawLine(p, x + 4 * s, y + 14 * s, x + 12 * s, y + 14 * s);

                // Door
                g.FillRectangle(b, x + 7 * s, y + 10 * s, 2 * s, 4 * s);
            }
        }

        private void DrawVectorTabDocIcon(Graphics g, float x, float y, float size, OfficeAppMode mode, bool isActive)
        {
            if (mode == OfficeAppMode.Home)
            {
                DrawVectorHomeIcon(g, x, y, size, isActive ? Color.FromArgb(99, 102, 241) : Color.FromArgb(148, 163, 184));
                return;
            }

            Color col = (mode == OfficeAppMode.Writer) ? Color.FromArgb(37, 99, 235) :
                        ((mode == OfficeAppMode.Calc) ? Color.FromArgb(5, 150, 105) :
                        ((mode == OfficeAppMode.Slides) ? Color.FromArgb(234, 88, 12) : Color.FromArgb(220, 38, 38)));

            float s = size / 16f;
            using (GraphicsPath docP = new GraphicsPath())
            using (SolidBrush b = new SolidBrush(col))
            {
                docP.AddLine(x + 3 * s, y + 2 * s, x + 10 * s, y + 2 * s);
                docP.AddLine(x + 10 * s, y + 2 * s, x + 13 * s, y + 5 * s);
                docP.AddLine(x + 13 * s, y + 5 * s, x + 13 * s, y + 14 * s);
                docP.AddLine(x + 13 * s, y + 14 * s, x + 3 * s, y + 14 * s);
                docP.CloseFigure();
                g.FillPath(b, docP);

                // Corner fold in white
                using (SolidBrush wb = new SolidBrush(Color.White))
                using (GraphicsPath foldP = new GraphicsPath())
                {
                    foldP.AddPolygon(new PointF[] {
                        new PointF(x + 10 * s, y + 2 * s),
                        new PointF(x + 13 * s, y + 5 * s),
                        new PointF(x + 10 * s, y + 5 * s)
                    });
                    g.FillPath(wb, foldP);
                }
            }
        }

