        public void Draw(Graphics g, int width, int height, WriterView writerView = null, SlidesView slidesView = null, CalcView calcView = null, PdfView pdfView = null)
        {
            if (CurrentMode == OfficeAppMode.Slides)
            {
                if (slidesView != null && slidesView.IsRemovingBackground)
                {
                    RibbonTabs = new string[] { "Loại bỏ nền (Background Removal)", "Trình chiếu", "Hiển thị", "Định dạng Hình ảnh" };
                    ActiveRibbonTab = 0;
                }
                else if (slidesView != null && slidesView.SelectedShape != null)
                {
                    if (slidesView.SelectedShape.Type == ShapeType.Video || !string.IsNullOrEmpty(slidesView.SelectedShape.VideoPath))
                    {
                        RibbonTabs = new string[] { "Trang đầu", "Chèn", "Thiết kế", "Chuyển tiếp", "Hoạt họa", "Trình chiếu", "Hiển thị", "Định dạng Video", "Phát lại" };
                    }
                    else if (slidesView.SelectedShape.Type == ShapeType.Table)
                    {
                        RibbonTabs = new string[] { "Trang đầu", "Chèn", "Thiết kế", "Chuyển tiếp", "Hoạt họa", "Trình chiếu", "Hiển thị", "Thiết kế Bảng" };
                    }
                    else if (slidesView.SelectedShape.Type == ShapeType.Image || slidesView.SelectedShape.CachedImage != null || !string.IsNullOrEmpty(slidesView.SelectedShape.ImagePath))
                    {
                        RibbonTabs = new string[] { "Trang đầu", "Chèn", "Thiết kế", "Chuyển tiếp", "Hoạt họa", "Trình chiếu", "Hiển thị", "Định dạng Hình ảnh" };
                    }
                    else
                    {
                        RibbonTabs = new string[] { "Trang đầu", "Chèn", "Thiết kế", "Chuyển tiếp", "Hoạt họa", "Trình chiếu", "Hiển thị", "Định dạng Hình dạng" };
                    }
                }
                else
                {
                    RibbonTabs = new string[] { "Trang đầu", "Chèn", "Thiết kế", "Chuyển tiếp", "Hoạt họa", "Trình chiếu", "Hiển thị" };
                    if (ActiveRibbonTab >= RibbonTabs.Length) ActiveRibbonTab = 0;
                }
            }
            else if (CurrentMode == OfficeAppMode.Writer)
            {
                if (writerView != null && writerView.IsEditingHeaderFooter)
                {
                    RibbonTabs = new string[] { "Trang đầu", "Chèn", "Thiết kế", "Bố trí", "Tham chiếu", "Hiển thị", "Đầu trang & Chân trang" };
                }
                else if (writerView != null && writerView.IsEditingEquation)
                {
                    RibbonTabs = new string[] { "Trang đầu", "Chèn", "Thiết kế", "Bố trí", "Tham chiếu", "Hiển thị", "Công thức" };
                }
                else if (writerView != null && writerView.IsChartSelected)
                {
                    RibbonTabs = new string[] { "Trang đầu", "Chèn", "Thiết kế", "Bố trí", "Tham chiếu", "Hiển thị", "Thiết kế Biểu đồ" };
                }
                else if (writerView != null && writerView.ActiveShape != null && writerView.ActiveShape.ShapeType == "Image")
                {
                    RibbonTabs = new string[] { "Trang đầu", "Chèn", "Thiết kế", "Bố trí", "Tham chiếu", "Hiển thị", "Định dạng Hình ảnh" };
                }
                else if (writerView != null && writerView.IsShapeSelected)
                {
                    RibbonTabs = new string[] { "Trang đầu", "Chèn", "Thiết kế", "Bố trí", "Tham chiếu", "Hiển thị", "Định dạng Hình dạng" };
                }
                else
                {
                    RibbonTabs = new string[] { "Trang đầu", "Chèn", "Thiết kế", "Bố trí", "Tham chiếu", "Hiển thị" };
                    if (ActiveRibbonTab > 5) ActiveRibbonTab = 0;
                }
            }
            else if (CurrentMode == OfficeAppMode.Calc)
            {
                RibbonTabs = new string[] { "Trang đầu", "Chèn", "Bố trí trang", "Công thức", "Dữ liệu", "Xem lại", "Hiển thị" };
                if (ActiveRibbonTab >= RibbonTabs.Length) ActiveRibbonTab = 0;
            }
            else if (CurrentMode == OfficeAppMode.Pdf)
            {
                RibbonTabs = new string[] { "Trang đầu", "Chú thích", "Chỉnh sửa", "Trang", "Ký & Bảo mật", "Hiển thị" };
                if (ActiveRibbonTab >= RibbonTabs.Length) ActiveRibbonTab = 0;
            }

            if (width <= 0) return;

            g.SmoothingMode = SmoothingMode.HighQuality;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            // 1. Title Bar (Top 36px) - Pure Crystal Liquid Glass (Kính Pha Lê Sáng Đồng Nhất)
            Rectangle topBarRect = new Rectangle(0, 0, width, 36);

            // Layer 1: Seamless Crystal Frosted Ice Glass Base (Đồng nhất, không loang lổ)
            using (LinearGradientBrush glassBaseBrush = new LinearGradientBrush(topBarRect, Color.FromArgb(246, 249, 254), Color.FromArgb(226, 234, 246), 90f))
            {
                g.FillRectangle(glassBaseBrush, topBarRect);
            }

            // Layer 2: Specular Glass Curved Horizon Glare (Top 18px Crystal Gloss Reflection trải đều toàn thanh)
            Rectangle glareRect = new Rectangle(0, 0, Math.Max(10, width), 18);
            using (LinearGradientBrush glareBrush = new LinearGradientBrush(glareRect, Color.FromArgb(190, 255, 255, 255), Color.FromArgb(20, 255, 255, 255), 90f))
            {
                g.FillRectangle(glareBrush, glareRect);
            }

            // Layer 3: Crystal Glass Rim Highlight Line (Y = 0)
            using (Pen rimPen = new Pen(Color.FromArgb(255, 255, 255), 1.2f))
            {
                g.DrawLine(rimPen, 0, 0.6f, width, 0.6f);
            }

            // Layer 4: Bottom Glass Refraction Border Line (Y = 35)
            using (Pen btmPen = new Pen(Color.FromArgb(203, 213, 225), 1.0f))
            {
                g.DrawLine(btmPen, 0, 35.5f, width, 35.5f);
            }

            // GENOFFICE Glass Pill Badge
            Rectangle logoPillRect = new Rectangle(8, 4, 120, 28);
            using (GraphicsPath logoPillPath = CreateRoundedRectanglePath(new RectangleF(logoPillRect.X, logoPillRect.Y, logoPillRect.Width, logoPillRect.Height), 7f))
            using (LinearGradientBrush pillBg = new LinearGradientBrush(logoPillRect, Color.FromArgb(240, 255, 255, 255), Color.FromArgb(190, 255, 255, 255), 90f))
            using (Pen pillBorder = new Pen(Color.FromArgb(180, 200, 228), 1.0f))
            {
                g.FillPath(pillBg, logoPillPath);
                g.DrawPath(pillBorder, logoPillPath);
            }

            // GENOFFICE Vector Logo & Brand Name (3-in-1 Master Suite)
            DrawVectorAppLogo(g, 13, 5, 26);
            using (Font brandFont = new Font("Segoe UI", 10.0f, FontStyle.Bold))
            using (SolidBrush brandShadow = new SolidBrush(Color.FromArgb(80, 255, 255, 255)))
            using (SolidBrush brandBrush = new SolidBrush(Color.FromArgb(30, 41, 59)))
            {
                g.DrawString("GENOFFICE", brandFont, brandShadow, 45, 9);
                g.DrawString("GENOFFICE", brandFont, brandBrush, 44, 8);
            }

            StringFormat ellipsisFormat = new StringFormat
            {
                Trimming = StringTrimming.EllipsisCharacter,
                FormatFlags = StringFormatFlags.NoWrap,
                LineAlignment = StringAlignment.Center
            };

            // Document Tabs Strip
            DocTabBounds.Clear();
            DocTabCloseBounds.Clear();

            using (Font tabFont = new Font("Segoe UI", 9.5f, FontStyle.Regular))
            using (Font tabActiveFont = new Font("Segoe UI", 9.5f, FontStyle.Bold))
            {
                // 1. PINNED HOME TAB ("Trang chính" - Luôn cố định bên trái)
                if (DocTabs.Count > 0 && DocTabs[0].Mode == OfficeAppMode.Home)
                {
                    bool isHomeActive = (ActiveDocIndex == 0);
                    Rectangle homeRect = new Rectangle(136, 6, 124, 30);
                    DocTabBounds.Add(homeRect);
                    DocTabCloseBounds.Add(Rectangle.Empty);
                    bool isHoverHome = IsHovering(homeRect);

                    if (isHomeActive)
                    {
                        // Active Home Tab: Frosted Porcelain Glass with ambient drop shadow & top neon accent
                        using (GraphicsPath tabPath = CreateTopRoundedTabPath(new RectangleF(homeRect.X, homeRect.Y, homeRect.Width, homeRect.Height), 7f))
                        {
                            using (SolidBrush shadowB = new SolidBrush(Color.FromArgb(30, 0, 0, 0)))
                            {
                                g.FillRectangle(shadowB, homeRect.X - 1, homeRect.Y + 2, homeRect.Width + 2, homeRect.Height);
                            }
                            using (LinearGradientBrush activeBg = new LinearGradientBrush(homeRect, Color.FromArgb(255, 255, 255), Color.FromArgb(248, 250, 255), 90f))
                            {
                                g.FillPath(activeBg, tabPath);
                            }
                            using (Pen glassBorder = new Pen(Color.FromArgb(195, 210, 235), 1.0f))
                            {
                                g.DrawPath(glassBorder, tabPath);
                            }
                            using (Pen accentPen = new Pen(Color.FromArgb(99, 102, 241), 3.2f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
                            {
                                g.DrawLine(accentPen, homeRect.X + 6, homeRect.Y + 1.5f, homeRect.Right - 6, homeRect.Y + 1.5f);
                            }
                        }
                    }
                    else
                    {
                        // Inactive Home Tab: Frosted Crystal Capsule
                        Rectangle pillRect = new Rectangle(homeRect.X, homeRect.Y, homeRect.Width, homeRect.Height - 1);
                        using (GraphicsPath tabPath = CreateRoundedRectanglePath(new RectangleF(pillRect.X, pillRect.Y, pillRect.Width, pillRect.Height), 6f))
                        using (LinearGradientBrush idleBg = new LinearGradientBrush(pillRect,
                            isHoverHome ? Color.FromArgb(245, 255, 255, 255) : Color.FromArgb(170, 255, 255, 255),
                            isHoverHome ? Color.FromArgb(210, 255, 255, 255) : Color.FromArgb(115, 255, 255, 255), 90f))
                        using (Pen glassBorder = new Pen(isHoverHome ? Color.FromArgb(140, 175, 230) : Color.FromArgb(175, 195, 225), 1.0f))
                        {
                            g.FillPath(idleBg, tabPath);
                            g.DrawPath(glassBorder, tabPath);

                            // Top specular line on the capsule
                            using (Pen pillGlare = new Pen(Color.FromArgb(240, 255, 255, 255), 1.0f))
                            {
                                g.DrawLine(pillGlare, pillRect.X + 6, pillRect.Y + 1, pillRect.Right - 6, pillRect.Y + 1);
                            }
                        }
                    }

                    DrawVectorTabDocIcon(g, homeRect.X + 10, homeRect.Y + 7, 16, OfficeAppMode.Home, isHomeActive);
                    Rectangle homeTextRect = new Rectangle(homeRect.X + 30, homeRect.Y, homeRect.Width - 36, homeRect.Height);
                    using (SolidBrush textBrush = new SolidBrush(isHomeActive ? Color.FromArgb(15, 23, 42) : (isHoverHome ? Color.FromArgb(15, 23, 42) : Color.FromArgb(51, 65, 85))))
                    {
                        g.DrawString(DocTabs[0].Title, isHomeActive ? tabActiveFont : tabFont, textBrush, homeTextRect, ellipsisFormat);
                    }
                }

                // 2. SCROLLABLE DOCUMENT TABS STRIP (Cuộn chuột lướt ngang các tab tài liệu)
                int docAreaX = 268; // Bắt đầu ngay sau tab Trang chính cố định
                int docAreaW = Math.Max(10, width - docAreaX - 10);
                Rectangle docClipRect = new Rectangle(docAreaX, 0, docAreaW, 36);

                int totalDocTabsWidth = (DocTabs.Count - 1) * (160 + 4) + 36;
                int maxTabScroll = Math.Max(0, totalDocTabsWidth - docAreaW);
                if (TargetTabScrollX > maxTabScroll) TargetTabScrollX = maxTabScroll;
                if (TargetTabScrollX < 0) TargetTabScrollX = 0;
                if (TabScrollX > maxTabScroll) TabScrollX = maxTabScroll;
                if (TabScrollX < 0) TabScrollX = 0;

                int currentTabScroll = (int)Math.Round(TabScrollX);

                GraphicsState gTabClip = g.Save();
                g.SetClip(docClipRect);

                int docTabX = docAreaX - currentTabScroll;
                for (int i = 1; i < DocTabs.Count; i++)
                {
                    bool isActive = (i == ActiveDocIndex);
                    int tabWidth = 160;
                    Rectangle tabRect = new Rectangle(docTabX, 6, tabWidth, 30);
                    DocTabBounds.Add(tabRect);
                    bool isHover = docClipRect.Contains(HoverX, HoverY) && IsHovering(tabRect);

                    if (IsDraggingTab && DraggingTabIndex == i)
                    {
                        // Ghost placeholder for dragged tab
                        using (GraphicsPath ghostPath = CreateTopRoundedTabPath(new RectangleF(tabRect.X, tabRect.Y, tabRect.Width, tabRect.Height), 7f))
                        using (Pen ghostPen = new Pen(Color.FromArgb(160, 99, 102, 241), 1.5f) { DashStyle = DashStyle.Dash })
                        using (SolidBrush ghostBrush = new SolidBrush(Color.FromArgb(120, 255, 255, 255)))
                        {
                            g.FillPath(ghostBrush, ghostPath);
                            g.DrawPath(ghostPen, ghostPath);
                        }
                        DocTabCloseBounds.Add(Rectangle.Empty);
                    }
                    else
                    {
                        if (isActive)
                        {
                            // Active Tab: Pure Frosted Porcelain Body
                            using (GraphicsPath tabPath = CreateTopRoundedTabPath(new RectangleF(tabRect.X, tabRect.Y, tabRect.Width, tabRect.Height), 7f))
                            {
                                using (SolidBrush shadowB = new SolidBrush(Color.FromArgb(30, 0, 0, 0)))
                                {
                                    g.FillRectangle(shadowB, tabRect.X - 1, tabRect.Y + 2, tabRect.Width + 2, tabRect.Height);
                                }
                                using (LinearGradientBrush activeBg = new LinearGradientBrush(tabRect, Color.FromArgb(255, 255, 255), Color.FromArgb(248, 250, 255), 90f))
                                {
                                    g.FillPath(activeBg, tabPath);
                                }
                                using (Pen glassBorder = new Pen(Color.FromArgb(195, 210, 235), 1.0f))
                                {
                                    g.DrawPath(glassBorder, tabPath);
                                }
                                Color accentCol = (DocTabs[i].Mode == OfficeAppMode.Writer) ? Color.FromArgb(37, 99, 235) :
                                                 ((DocTabs[i].Mode == OfficeAppMode.Calc) ? Color.FromArgb(5, 150, 105) :
                                                 ((DocTabs[i].Mode == OfficeAppMode.Slides) ? Color.FromArgb(234, 88, 12) : Color.FromArgb(225, 29, 72)));
                                using (Pen accentPen = new Pen(accentCol, 3.2f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
                                {
                                    g.DrawLine(accentPen, tabRect.X + 6, tabRect.Y + 1.5f, tabRect.Right - 6, tabRect.Y + 1.5f);
                                }
                            }
                        }
                        else
                        {
                            // Inactive Tab: Frosted Crystal Capsule
                            Rectangle pillRect = new Rectangle(tabRect.X, tabRect.Y, tabRect.Width, tabRect.Height - 1);
                            using (GraphicsPath tabPath = CreateRoundedRectanglePath(new RectangleF(pillRect.X, pillRect.Y, pillRect.Width, pillRect.Height), 6f))
                            using (LinearGradientBrush idleBg = new LinearGradientBrush(pillRect,
                                isHover ? Color.FromArgb(245, 255, 255, 255) : Color.FromArgb(170, 255, 255, 255),
                                isHover ? Color.FromArgb(210, 255, 255, 255) : Color.FromArgb(115, 255, 255, 255), 90f))
                            using (Pen glassBorder = new Pen(isHover ? Color.FromArgb(140, 175, 230) : Color.FromArgb(175, 195, 225), 1.0f))
                            {
                                g.FillPath(idleBg, tabPath);
                                g.DrawPath(glassBorder, tabPath);

                                // Top specular line on the capsule
                                using (Pen pillGlare = new Pen(Color.FromArgb(240, 255, 255, 255), 1.0f))
                                {
                                    g.DrawLine(pillGlare, pillRect.X + 6, pillRect.Y + 1, pillRect.Right - 6, pillRect.Y + 1);
                                }
                            }
                        }

                        DrawVectorTabDocIcon(g, tabRect.X + 10, tabRect.Y + 7, 16, DocTabs[i].Mode, isActive);

                        Rectangle textRect = new Rectangle(tabRect.X + 30, tabRect.Y, tabRect.Width - 56, tabRect.Height);
                        using (SolidBrush textBrush = new SolidBrush(isActive ? Color.FromArgb(15, 23, 42) : (isHover ? Color.FromArgb(15, 23, 42) : Color.FromArgb(51, 65, 85))))
                        {
                            g.DrawString(DocTabs[i].Title, isActive ? tabActiveFont : tabFont, textBrush, textRect, ellipsisFormat);
                        }

                        Rectangle closeRect = new Rectangle(tabRect.Right - 24, tabRect.Y + 6, 18, 18);
                        DocTabCloseBounds.Add(closeRect);
                        bool isHoverClose = docClipRect.Contains(HoverX, HoverY) && IsHovering(closeRect);
                        if (isHoverClose)
                        {
                            using (SolidBrush closeBg = new SolidBrush(Color.FromArgb(254, 226, 226)))
                            using (Pen closeBorder = new Pen(Color.FromArgb(239, 68, 68), 1f))
                            {
                                g.FillEllipse(closeBg, closeRect);
                                g.DrawEllipse(closeBorder, closeRect);
                            }
                            DrawVectorTabCloseCross(g, closeRect.X + 9, closeRect.Y + 9, 8, Color.FromArgb(220, 38, 38));
                        }
                        else
                        {
                            if (isActive)
                            {
                                using (SolidBrush closeBg = new SolidBrush(Color.FromArgb(20, 0, 0, 0)))
                                {
                                    g.FillEllipse(closeBg, closeRect);
                                }
                            }
                            else
                            {
                                using (SolidBrush closeBg = new SolidBrush(Color.FromArgb(80, 255, 255, 255)))
                                {
                                    g.FillEllipse(closeBg, closeRect);
                                }
                            }
                            DrawVectorTabCloseCross(g, closeRect.X + 9, closeRect.Y + 9, 8, isActive ? Color.FromArgb(100, 116, 139) : Color.FromArgb(120, 135, 160));
                        }
                    }

                    docTabX += tabWidth + 4;
                }

                // '+' New Tab button (Crystal Liquid Glass Orb)
                Rectangle newTabRect = new Rectangle(docTabX + 2, 9, 24, 24);
                DocTabPlusBounds = newTabRect;
                bool isHoverAdd = docClipRect.Contains(HoverX, HoverY) && IsHovering(newTabRect);
                using (LinearGradientBrush addBg = new LinearGradientBrush(newTabRect, 
                    isHoverAdd ? Color.FromArgb(99, 102, 241) : Color.FromArgb(225, 255, 255, 255), 
                    isHoverAdd ? Color.FromArgb(79, 70, 229) : Color.FromArgb(170, 255, 255, 255), 90f))
                using (Pen addBorder = new Pen(isHoverAdd ? Color.FromArgb(129, 140, 248) : Color.FromArgb(175, 195, 225), 1.0f))
                {
                    g.FillEllipse(addBg, newTabRect);
                    g.DrawEllipse(addBorder, newTabRect);
                }
                DrawVectorTabPlus(g, newTabRect.X + 12, newTabRect.Y + 12, 10, isHoverAdd ? Color.White : Color.FromArgb(71, 85, 105));

                // Draw Drop Insertion Marker when dragging
                if (IsDraggingTab && DragTargetIndex >= 1 && DragTargetIndex < DocTabs.Count)
                {
                    int markerX = docAreaX - currentTabScroll + (DragTargetIndex - 1) * (160 + 4) - 2;
                    if (DragTargetIndex > DraggingTabIndex) markerX += 160 + 4;
                    using (Pen markerGlow = new Pen(Color.FromArgb(140, 59, 130, 246), 6f))
                    using (Pen markerCore = new Pen(Color.FromArgb(37, 99, 235), 2.5f))
                    {
                        g.DrawLine(markerGlow, markerX, 4, markerX, 36);
                        g.DrawLine(markerCore, markerX, 4, markerX, 36);
                    }
                }

                // Draw Elevated Floating Dragged Tab
                if (IsDraggingTab && DraggingTabIndex >= 1 && DraggingTabIndex < DocTabs.Count)
                {
                    DocTab draggedTab = DocTabs[DraggingTabIndex];
                    int floatX = (int)Math.Round(DragCurrentMouseX - 80);
                    Rectangle floatRect = new Rectangle(floatX, 4, 160, 32);

                    // Drop shadow
                    using (GraphicsPath shadowPath = CreateTopRoundedTabPath(new RectangleF(floatRect.X + 2, floatRect.Y + 2, floatRect.Width, floatRect.Height), 8f))
                    using (SolidBrush shadowB = new SolidBrush(Color.FromArgb(80, 0, 0, 0)))
                    {
                        g.FillPath(shadowB, shadowPath);
                    }

                    using (GraphicsPath floatPath = CreateTopRoundedTabPath(new RectangleF(floatRect.X, floatRect.Y, floatRect.Width, floatRect.Height), 8f))
                    {
                        using (SolidBrush floatBg = new SolidBrush(Color.FromArgb(250, 252, 255)))
                        {
                            g.FillPath(floatBg, floatPath);
                        }
                        using (Pen borderPen = new Pen(Color.FromArgb(99, 102, 241), 2.0f))
                        {
                            g.DrawPath(borderPen, floatPath);
                        }
                        Color accentCol = (draggedTab.Mode == OfficeAppMode.Writer) ? Color.FromArgb(37, 99, 235) :
                                         ((draggedTab.Mode == OfficeAppMode.Calc) ? Color.FromArgb(5, 150, 105) :
                                         Color.FromArgb(234, 88, 12));
                        using (Pen accentPen = new Pen(accentCol, 3.5f))
                        {
                            g.DrawLine(accentPen, floatRect.X + 4, floatRect.Y + 1.5f, floatRect.Right - 4, floatRect.Y + 1.5f);
                        }
                    }

                    DrawVectorTabDocIcon(g, floatRect.X + 10, floatRect.Y + 8, 16, draggedTab.Mode, true);
                    Rectangle textRect = new Rectangle(floatRect.X + 30, floatRect.Y, floatRect.Width - 36, floatRect.Height);
                    using (SolidBrush textBrush = new SolidBrush(Color.FromArgb(15, 23, 42)))
                    {
                        g.DrawString(draggedTab.Title, tabActiveFont, textBrush, textRect, ellipsisFormat);
                    }
                }

                g.Restore(gTabClip);
            }

            // 2. Ribbon Header Strip (Y: 36 to 64)
            using (SolidBrush headerBrush = new SolidBrush(Color.FromArgb(248, 250, 252)))
            using (Pen headerBorder = new Pen(Color.FromArgb(226, 232, 240), 1f))
            {
                g.FillRectangle(headerBrush, 0, 36, width, 28);
                g.DrawLine(headerBorder, 0, 64, width, 64);
            }

            if (CurrentMode == OfficeAppMode.Home)
            {
                DrawVectorHomeIcon(g, 16, 42, 16, Color.FromArgb(99, 102, 241));
                using (Font hFont = new Font("Segoe UI", 9.5f, FontStyle.Bold))
                using (SolidBrush hBrush = new SolidBrush(Color.FromArgb(15, 23, 42)))
                {
                    g.DrawString("Trang chủ", hFont, hBrush, 36, 40);
                }
                return;
            }

            StringFormat tabCenterFormat = new StringFormat
            {
                Alignment = StringAlignment.Center,
                LineAlignment = StringAlignment.Center
            };

            if (CurrentMode == OfficeAppMode.Calc)
            {
                ExcelTableInfo curTbl;
                bool insideTable = (calcView != null && calcView.IsSelectionInsideTable(out curTbl));
                if (insideTable)
                {
                    if (RibbonTabs.Length != 8 || RibbonTabs[7] != "Thiết kế Bảng")
                    {
                        RibbonTabs = new string[] { "Trang đầu", "Chèn", "Bố trí trang", "Công thức", "Dữ liệu", "Xem lại", "Hiển thị", "Thiết kế Bảng" };
                    }
                }
                else
                {
                    if (RibbonTabs.Length > 7 && RibbonTabs[7] == "Thiết kế Bảng")
                    {
                        RibbonTabs = new string[] { "Trang đầu", "Chèn", "Bố trí trang", "Công thức", "Dữ liệu", "Xem lại", "Hiển thị" };
                        if (ActiveRibbonTab >= RibbonTabs.Length) ActiveRibbonTab = 0;
                    }
                }
            }

            if (CurrentMode == OfficeAppMode.Pdf)
            {
                bool hasSelection = (pdfView != null && (pdfView.SelectedText != null || pdfView.EditingText != null));
                if (hasSelection)
                {
                    if (RibbonTabs.Length != 7 || RibbonTabs[6] != "Định dạng Hộp chữ")
                    {
                        RibbonTabs = new string[] { "Trang đầu", "Chú thích", "Chỉnh sửa", "Trang", "Ký & Bảo mật", "Hiển thị", "Định dạng Hộp chữ" };
                        ActiveRibbonTab = 6; // Tự động mở tab Định dạng Hộp chữ!
                    }
                }
                else
                {
                    if (RibbonTabs.Length > 6 && RibbonTabs[6] == "Định dạng Hộp chữ")
                    {
                        RibbonTabs = new string[] { "Trang đầu", "Chú thích", "Chỉnh sửa", "Trang", "Ký & Bảo mật", "Hiển thị" };
                        if (ActiveRibbonTab >= RibbonTabs.Length) ActiveRibbonTab = 0;
                    }
                }
            }

            RibbonTabBounds.Clear();
            int rTabX = 16;
            using (Font rFont = new Font("Segoe UI", 9.5f, FontStyle.Regular))
            using (Font rBoldFont = new Font("Segoe UI", 9.5f, FontStyle.Bold))
            {
                for (int i = 0; i < RibbonTabs.Length; i++)
                {
                    bool isContextual = (RibbonTabs[i].Contains("Hình dạng") || RibbonTabs[i].Contains("Hình ảnh") || RibbonTabs[i].Contains("Biểu đồ") || RibbonTabs[i].Contains("Bảng") || RibbonTabs[i].Contains("Đầu trang") || RibbonTabs[i].Contains("Hộp chữ") || RibbonTabs[i].Contains("Video") || RibbonTabs[i].Contains("Phát lại"));
                    Color tabAccent = RibbonTabs[i].Contains("Hộp chữ") ? Color.FromArgb(37, 99, 235) : (RibbonTabs[i].Contains("Bảng") ? Color.FromArgb(16, 124, 65) : (isContextual ? Color.FromArgb(210, 71, 38) : PrimaryColor));

                    int rWidth = Math.Max(72, (int)g.MeasureString(RibbonTabs[i], isContextual ? rBoldFont : rFont).Width + 24);
                    Rectangle rRect = new Rectangle(rTabX, 36, rWidth, 28);
                    RibbonTabBounds.Add(rRect);
                    bool isHoverRTab = IsHovering(rRect);

                    if (i == ActiveRibbonTab)
                    {
                        FillRoundedRectangle(g, Brushes.White, rRect, 4);
                        using (SolidBrush lineBrush = new SolidBrush(tabAccent))
                        {
                            g.FillRectangle(lineBrush, rTabX, 61, rWidth, 3);
                        }
                        using (SolidBrush txtBrush = new SolidBrush(tabAccent))
                        {
                            g.DrawString(RibbonTabs[i], rBoldFont, txtBrush, rRect, tabCenterFormat);
                        }
                    }
                    else if (isHoverRTab)
                    {
                        using (SolidBrush hBrush = new SolidBrush(Color.FromArgb(240, 243, 248)))
                        {
                            FillRoundedRectangle(g, hBrush, rRect, 4);
                        }
                        if (isContextual)
                        {
                            using (SolidBrush ctxHovTxt = new SolidBrush(tabAccent))
                            {
                                g.DrawString(RibbonTabs[i], rBoldFont, ctxHovTxt, rRect, tabCenterFormat);
                            }
                        }
                        else
                        {
                            g.DrawString(RibbonTabs[i], rFont, Brushes.Navy, rRect, tabCenterFormat);
                        }
                    }
                    else if (isContextual)
                    {
                        using (SolidBrush ctxTxt = new SolidBrush(tabAccent))
                        {
                            g.DrawString(RibbonTabs[i], rBoldFont, ctxTxt, rRect, tabCenterFormat);
                        }
                        using (Pen topPen = new Pen(tabAccent, 2f))
                        {
                            g.DrawLine(topPen, rTabX + 6, 37, rTabX + rWidth - 6, 37);
                        }
                    }
                    else
                    {
                        g.DrawString(RibbonTabs[i], rFont, Brushes.DimGray, rRect, tabCenterFormat);
                    }
                    rTabX += rWidth + 4;
                }
            }

            // 3. Ribbon Action Toolbar Body (Y: 64 to 155, height 91px)
            g.FillRectangle(Brushes.White, 0, 64, width, 91);
            g.DrawLine(Pens.LightGray, 0, 154, width, 154);

            if (CurrentMode == OfficeAppMode.Writer)
            {
                DrawWriterRibbonContent(g, width, writerView);
            }
            else if (CurrentMode == OfficeAppMode.Calc)
            {
                DrawExcelRibbonToolbar(g, width, calcView);
            }
            else if (CurrentMode == OfficeAppMode.Slides)
            {
                DrawPowerPointRibbonToolbar(g, width, slidesView);
            }
            else if (CurrentMode == OfficeAppMode.Pdf)
            {
                DrawPdfRibbonToolbar(g, width, pdfView);
            }
        }

        private void DrawWriterRibbonContent(Graphics g, int width, WriterView writerView = null)
        {
            switch (ActiveRibbonTab)
            {
                case 0: DrawTabTrangDau(g, width); break;
                case 1: DrawTabChen(g, width); break;
                case 2: DrawTabThietKe(g, width); break;
                case 3: DrawTabBoTri(g, width, writerView); break;
                case 4: DrawTabThamChieu(g, width, writerView); break;
                case 5: DrawTabHienThi(g, width, writerView); break;
                case 6:
                    if (writerView != null && writerView.IsChartSelected)
                        DrawTabChartDesign(g, width);
                    else if (writerView != null && writerView.ActiveShape != null && writerView.ActiveShape.ShapeType == "Image")
                        DrawTabPictureFormat(g, width, writerView);
                    else if (writerView != null && writerView.IsShapeSelected)
                        DrawTabShapeFormat(g, width, writerView);
                    else if (writerView != null && writerView.IsEditingEquation)
                        DrawTabEquation(g, width, writerView);
                    else
                        DrawTabHeaderFooter(g, width);
                    break;
                default: DrawTabTrangDau(g, width); break;
            }
        }

