                DrawListNumberedIcon(g, 560, 71, Color.FromArgb(51, 65, 85));
                DrawDropdownChevron(g, 577, 78, Color.FromArgb(71, 85, 105));

                Rectangle mListRect = new Rectangle(588, 68, 28, 24);
                DrawInteractiveButton(g, mListRect, false, 3);
                DrawLucideListTree(g, 590, 71, Color.FromArgb(51, 65, 85));
                DrawDropdownChevron(g, 607, 78, Color.FromArgb(71, 85, 105));

                Rectangle decIndentRect = new Rectangle(618, 68, 22, 24);
                DrawInteractiveButton(g, decIndentRect, false, 3);
                DrawLucideOutdent(g, 620, 71, Color.FromArgb(51, 65, 85));

                Rectangle incIndentRect = new Rectangle(642, 68, 22, 24);
                DrawInteractiveButton(g, incIndentRect, false, 3);
                DrawLucideIndent(g, 644, 71, Color.FromArgb(51, 65, 85));

                Rectangle sortRect = new Rectangle(666, 68, 22, 24);
                DrawInteractiveButton(g, sortRect, false, 3);
                DrawLucideSortAZ(g, 668, 71, Color.FromArgb(51, 65, 85));

                Rectangle showHideRect = new Rectangle(690, 68, 22, 24);
                bool isMarksActive = ShowFormattingMarks;
                DrawInteractiveButton(g, showHideRect, isMarksActive, 3);
                DrawLucidePilcrow(g, 692, 71, isMarksActive ? Color.FromArgb(16, 110, 190) : Color.FromArgb(51, 65, 85));

                // Bottom Row: Align Left, Center, Right, Justify, Line Spacing▾, Shading▾, Borders▾
                int alignX = 528;
                for (int a = 0; a < 4; a++)
                {
                    Rectangle aRect = new Rectangle(alignX, 96, 22, 24);
                    bool isCurAlign = (Alignment == a);
                    DrawInteractiveButton(g, aRect, isCurAlign, 3);
                    DrawAlignmentIcon(g, alignX - 4, 96, a, isCurAlign ? Color.FromArgb(16, 110, 190) : Color.FromArgb(51, 65, 85));
                    alignX += 24;
                }

                // Line Spacing ↕≡▾
                Rectangle lsRect = new Rectangle(626, 96, 28, 24);
                DrawInteractiveButton(g, lsRect, false, 3);
                DrawLucideLineSpacing(g, 628, 99, Color.FromArgb(51, 65, 85));

                // Shading 🪣▾
                Rectangle shadeRect = new Rectangle(656, 96, 28, 24);
                DrawInteractiveButton(g, shadeRect, false, 3);
                DrawLucidePaintBucket(g, 658, 99, Color.FromArgb(51, 65, 85));

