                g.DrawLine(Pens.LightGray, 722, 68, 722, 148);

                // ==================== Group 4: Quick Styles Gallery (Kiểu hiển thị) (X: 730+) ====================
                int styleX = 730;
                string[] styleNames = new string[] { "Normal", "No Spacing", "Heading 1", "Heading 2", "Heading 3", "Title", "Subtitle" };
                
                // Calculate dynamic number of cards that fit comfortably based on Ribbon width
                int numStyleCards = Math.Max(2, Math.Min(styleNames.Length, (width - 130 - styleX) / 68));
                if (numStyleCards > 5) numStyleCards = 5;

                for (int s = 0; s < numStyleCards; s++)
                {
                    Rectangle sBox = new Rectangle(styleX, 68, 62, 56);
                    bool isActiveStyle = (ActiveStyle == styleNames[s]);
                    
                    if (isActiveStyle)
                    {
                        using (SolidBrush ab = new SolidBrush(Color.FromArgb(239, 246, 255)))
                        using (Pen ap = new Pen(Color.FromArgb(37, 99, 235), 1.2f))
                        {
                            FillRoundedRectangle(g, ab, sBox, 3);
                            DrawRoundedRectangle(g, ap, sBox, 3);
                        }
                    }
                    else
                    {
                        using (SolidBrush ib = new SolidBrush(Color.White))
                        using (Pen ip = new Pen(Color.FromArgb(226, 232, 240), 1f))
                        {
                            FillRoundedRectangle(g, ib, sBox, 3);
                            DrawRoundedRectangle(g, ip, sBox, 3);
                        }
                    }

                    Color sampleCol = (styleNames[s].StartsWith("Heading") ? Color.FromArgb(43, 87, 154) : (styleNames[s] == "Subtitle" ? Color.FromArgb(100, 116, 139) : Color.FromArgb(15, 23, 42)));
                    using (SolidBrush sampleBrush = new SolidBrush(sampleCol))
                    using (Font sampleFont = new Font("Segoe UI", (styleNames[s] == "Title") ? 10.0f : 8.5f, (styleNames[s] != "Normal") ? (styleNames[s] == "Subtitle" ? FontStyle.Italic : FontStyle.Bold) : FontStyle.Regular))
                    {
                        g.DrawString("AaBb", sampleFont, sampleBrush, styleX + 5, 72);
                    }
                    g.DrawString(styleNames[s], labelFont, Brushes.Gray, styleX + 3, 103);

                    styleX += 68;
                }

                int styleDividerX = 730 + (numStyleCards * 68) + 6;
                g.DrawString("Kiểu hiển thị", labelFont, Brushes.Gray, 730 + (numStyleCards * 68) / 2 - 28, 137);
                g.DrawLine(Pens.LightGray, styleDividerX, 68, styleDividerX, 148);

                // ==================== Group 5: Editing (Chỉnh sửa) ====================
                int editX = styleDividerX + 8;
                Rectangle searchBox = new Rectangle(editX, 68, 108, 20);
                DrawInteractiveButton(g, searchBox, false, 3);
                DrawLucideSearch(g, editX + 3, 70, Color.FromArgb(51, 65, 85));
                g.DrawString("Tìm kiếm ▾", btnFont, Brushes.Black, editX + 24, 70);

                Rectangle replaceBox = new Rectangle(editX, 89, 108, 20);
                DrawInteractiveButton(g, replaceBox, false, 3);
                DrawLucideReplace(g, editX + 3, 91, Color.FromArgb(51, 65, 85));
                g.DrawString("Thay thế", btnFont, Brushes.Black, editX + 24, 91);

                Rectangle selectBox = new Rectangle(editX, 110, 108, 20);
                DrawInteractiveButton(g, selectBox, false, 3);
                DrawLucideSelectPointer(g, editX + 3, 112, Color.FromArgb(51, 65, 85));
                g.DrawString("Chọn vùng ▾", btnFont, Brushes.Black, editX + 24, 112);

                g.DrawString("Chỉnh sửa", labelFont, Brushes.Gray, editX + 24, 137);
            }
        }

        private void DrawTabChen(Graphics g, int width)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;
                int curX = 14;

                // 1. Nhóm Trang (Pages)
                DrawVectorBtn(g, curX, 68, 92, 20, (g1, x1, y1) => {
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    using (Pen p = new Pen(Color.FromArgb(148, 163, 184), 1.2f))
                    using (SolidBrush bTop = new SolidBrush(Color.FromArgb(37, 99, 235)))
                    using (SolidBrush bLine = new SolidBrush(Color.FromArgb(203, 213, 225)))
                    {
                        g1.FillRectangle(bg, x1, y1, 11, 14);
                        g1.DrawRectangle(p, x1, y1, 11, 14);
                        g1.FillRectangle(bTop, x1 + 1, y1 + 1, 10, 4);
                        g1.FillRectangle(bLine, x1 + 2, y1 + 7, 7, 1.5f);
                        g1.FillRectangle(bLine, x1 + 2, y1 + 10, 5, 1.5f);
                    }
                }, "Trang bìa");

                DrawVectorBtn(g, curX, 88, 92, 20, (g1, x1, y1) => {
                    using (SolidBrush bg = new SolidBrush(Color.White))
                    using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.2f))
                    using (SolidBrush fold = new SolidBrush(Color.FromArgb(219, 234, 254)))
                    {
                        PointF[] pagePts = new PointF[] {
                            new PointF(x1, y1),
                            new PointF(x1 + 7, y1),
                            new PointF(x1 + 11, y1 + 4),
                            new PointF(x1 + 11, y1 + 14),
                            new PointF(x1, y1 + 14)
                        };
                        g1.FillPolygon(bg, pagePts);
                        g1.DrawPolygon(p, pagePts);
                        PointF[] foldPts = new PointF[] {
                            new PointF(x1 + 7, y1),
                            new PointF(x1 + 11, y1 + 4),
                            new PointF(x1 + 7, y1 + 4)
                        };
                        g1.FillPolygon(fold, foldPts);
                        g1.DrawPolygon(p, foldPts);
                    }
                }, "Trang trắng");

                DrawVectorBtn(g, curX, 108, 92, 20, (g1, x1, y1) => {
                    using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.2f))
                    using (Pen dashPen = new Pen(Color.FromArgb(239, 68, 68), 1.2f) { DashStyle = DashStyle.Dash })
                    {
                        g1.DrawRectangle(p, x1, y1, 11, 4.5f);
                        g1.DrawLine(dashPen, x1 - 1, y1 + 6.5f, x1 + 12, y1 + 6.5f);
                        g1.DrawRectangle(p, x1, y1 + 8.5f, 11, 4.5f);
                    }
                }, "Ngắt trang");
                curX += 96;
                g.DrawString("Trang", labelFont, Brushes.Gray, curX - 65, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 10;

                // 2. Nhóm Bảng (Tables)
                DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => {
                    using (SolidBrush hdrBrush = new SolidBrush(Color.FromArgb(219, 234, 254)))
                    using (SolidBrush hdrBorder = new SolidBrush(Color.FromArgb(37, 99, 235)))
                    using (Pen borderPen = new Pen(Color.FromArgb(51, 65, 85), 1.3f))
                    using (Pen innerPen = new Pen(Color.FromArgb(148, 163, 184), 1.0f))
                    {
                        g1.FillRectangle(hdrBrush, x1, y1 + 1, 20, 5);
                        g1.FillRectangle(hdrBorder, x1, y1 + 1, 20, 2);
                        g1.DrawRectangle(borderPen, x1, y1 + 1, 20, 18);
                        g1.DrawLine(innerPen, x1 + 6.6f, y1 + 1, x1 + 6.6f, y1 + 19);
                        g1.DrawLine(innerPen, x1 + 13.3f, y1 + 1, x1 + 13.3f, y1 + 19);
                        g1.DrawLine(borderPen, x1, y1 + 6, x1 + 20, y1 + 6);
                        g1.DrawLine(innerPen, x1, y1 + 12, x1 + 20, y1 + 12);
                    }
                }, "Bảng");
                curX += 68;
                g.DrawString("Bảng", labelFont, Brushes.Gray, curX - 50, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 10;

                // 3. Nhóm Minh họa (Illustrations)
                DrawVectorToolBtnLarge(g, curX, 68, 60, 60, (g1, x1, y1) => { // Hình ảnh
                    using (SolidBrush skyBrush = new SolidBrush(Color.FromArgb(224, 242, 254)))
                    using (Pen framePen = new Pen(Color.FromArgb(37, 99, 235), 1.4f))
                    using (SolidBrush sunBrush = new SolidBrush(Color.FromArgb(245, 158, 11)))
                    using (SolidBrush mtn1 = new SolidBrush(Color.FromArgb(16, 185, 129)))
                    using (SolidBrush mtn2 = new SolidBrush(Color.FromArgb(5, 150, 105)))
                    {
                        g1.FillRectangle(skyBrush, x1 - 1, y1 + 1, 22, 17);
                        g1.DrawRectangle(framePen, x1 - 1, y1 + 1, 22, 17);
                        g1.FillEllipse(sunBrush, x1 + 13, y1 + 4, 4.5f, 4.5f);
                        PointF[] p1 = new PointF[] {
                            new PointF(x1 + 7, y1 + 17),
                            new PointF(x1 + 14, y1 + 9),
                            new PointF(x1 + 20, y1 + 17)
                        };
                        g1.FillPolygon(mtn2, p1);
                        PointF[] p2 = new PointF[] {
                            new PointF(x1, y1 + 17),
                            new PointF(x1 + 6, y1 + 10),
                            new PointF(x1 + 13, y1 + 17)
                        };
                        g1.FillPolygon(mtn1, p2);
                    }
                }, "Hình ảnh");
                curX += 66;

                DrawVectorToolBtnLarge(g, curX, 68, 60, 60, (g1, x1, y1) => { // Hình khối
                    using (SolidBrush bBlue = new SolidBrush(Color.FromArgb(219, 234, 254)))
                    using (Pen pBlue = new Pen(Color.FromArgb(37, 99, 235), 1.5f))
                    using (SolidBrush bOrange = new SolidBrush(Color.FromArgb(254, 215, 170)))
                    using (Pen pOrange = new Pen(Color.FromArgb(234, 88, 12), 1.5f))
                    {
                        g1.FillRectangle(bBlue, x1, y1 + 2, 13, 13);
                        g1.DrawRectangle(pBlue, x1, y1 + 2, 13, 13);
                        g1.FillEllipse(bOrange, x1 + 7, y1 + 7, 13, 13);
                        g1.DrawEllipse(pOrange, x1 + 7, y1 + 7, 13, 13);
                    }
                }, "Hình khối");
                curX += 66;

                DrawVectorToolBtnLarge(g, curX, 68, 60, 60, (g1, x1, y1) => { // SmartArt
                    using (Pen linePen = new Pen(Color.FromArgb(100, 116, 139), 1.4f))
                    using (SolidBrush bTop = new SolidBrush(Color.FromArgb(6, 182, 212)))
                    using (SolidBrush bLeft = new SolidBrush(Color.FromArgb(245, 158, 11)))
                    using (SolidBrush bRight = new SolidBrush(Color.FromArgb(139, 92, 246)))
                    {
                        float cx = x1 + 10, cy = y1 + 5;
                        float lx = x1 + 3, ly = y1 + 15;
                        float rx = x1 + 17, ry = y1 + 15;
                        g1.DrawLine(linePen, cx, cy + 3, lx + 3, ly);
                        g1.DrawLine(linePen, cx, cy + 3, rx - 3, ly);
                        g1.FillEllipse(bTop, cx - 3.5f, cy - 3.5f, 7, 7);
                        g1.FillEllipse(bLeft, lx - 3.5f, ly - 3.5f, 7, 7);
                        g1.FillEllipse(bRight, rx - 3.5f, ry - 3.5f, 7, 7);
                    }
                }, "SmartArt");
                curX += 66;

                DrawVectorToolBtnLarge(g, curX, 68, 60, 60, (g1, x1, y1) => { // Biểu đồ
                    using (Pen axisPen = new Pen(Color.FromArgb(51, 65, 85), 1.5f))
                    using (SolidBrush b1 = new SolidBrush(Color.FromArgb(59, 130, 246)))
                    using (SolidBrush b2 = new SolidBrush(Color.FromArgb(16, 185, 129)))
                    using (SolidBrush b3 = new SolidBrush(Color.FromArgb(245, 158, 11)))
                    using (Pen trendPen = new Pen(Color.FromArgb(239, 68, 68), 1.4f))
                    {
                        g1.DrawLine(axisPen, x1, y1 + 18, x1 + 20, y1 + 18);
                        g1.FillRectangle(b1, x1 + 2, y1 + 11, 4, 7);
                        g1.FillRectangle(b2, x1 + 8, y1 + 5, 4, 13);
                        g1.FillRectangle(b3, x1 + 14, y1 + 8, 4, 10);
                        g1.DrawLine(trendPen, x1 + 4, y1 + 11, x1 + 10, y1 + 5);
                        g1.DrawLine(trendPen, x1 + 10, y1 + 5, x1 + 16, y1 + 8);
                    }
                }, "Biểu đồ");
                curX += 66;

                DrawVectorToolBtnLarge(g, curX, 68, 60, 60, (g1, x1, y1) => { // Ảnh chụp
                    using (Pen monPen = new Pen(Color.FromArgb(51, 65, 85), 1.4f))
                    using (SolidBrush monBg = new SolidBrush(Color.FromArgb(224, 242, 254)))
                    using (SolidBrush camBrush = new SolidBrush(Color.FromArgb(37, 99, 235)))
                    {
                        g1.FillRectangle(monBg, x1, y1 + 2, 20, 13);
                        g1.DrawRectangle(monPen, x1, y1 + 2, 20, 13);
                        g1.DrawLine(monPen, x1 + 6, y1 + 18, x1 + 14, y1 + 18);
                        g1.DrawLine(monPen, x1 + 10, y1 + 15, x1 + 10, y1 + 18);
                        g1.FillEllipse(camBrush, x1 + 7.5f, y1 + 5.5f, 5, 5);
                    }
                }, "Ảnh chụp");
                curX += 66;

                g.DrawString("Minh họa", labelFont, Brushes.Gray, curX - 185, 137);
