                DrawVectorBtn(g, curX, 108, 92, 20, (g1, x1, y1) => { // Phần nhanh
                    using (SolidBrush b1 = new SolidBrush(Color.FromArgb(59, 130, 246)))
                    using (SolidBrush b2 = new SolidBrush(Color.FromArgb(147, 197, 253)))
