            }
        }

        private void DrawVectorBtn(Graphics g, int x, int y, int w, int h, Action<Graphics, int, int> drawIcon, string title = "", bool isActive = false)
        {
            Rectangle box = new Rectangle(x, y, w, h);
            DrawInteractiveButton(g, box, isActive, 2);
            drawIcon(g, x + 5, y + (h - 14) / 2);
            if (!string.IsNullOrEmpty(title))
            {
                using (Font txtFont = new Font("Segoe UI", 7.8f, FontStyle.Regular))
                using (SolidBrush tb = new SolidBrush(isActive ? Color.FromArgb(220, 38, 38) : Color.FromArgb(30, 41, 59)))
                {
                    g.DrawString(title, txtFont, tb, x + 24, y + (h - 14) / 2 - 1);
                }
            }
        }

        private void DrawVectorToolBtnLarge(Graphics g, int x, int y, int w, int h, Action<Graphics, int, int> drawIcon, string title, bool isActive = false)
        {
            Rectangle box = new Rectangle(x, y, w, h);
            DrawInteractiveButton(g, box, isActive, 4);
            drawIcon(g, x + (w - 20) / 2, y + 8);
            using (Font txtFont = new Font("Segoe UI", 7.8f, FontStyle.Bold))
            using (SolidBrush tb = new SolidBrush(isActive ? Color.FromArgb(220, 38, 38) : Color.FromArgb(30, 41, 59)))
            using (StringFormat sf = new StringFormat() { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center })
            {
                g.DrawString(title, txtFont, tb, new RectangleF(x, y + 36, w, h - 38), sf);
            }
        }

