                }, "Nghệ thuật ▾");
                curX += 90;

                DrawVectorBtn(g, curX, 68, 86, 20, (g1, x1, y1) => {
                    for (int r = 0; r < 2; r++) for (int c = 0; c < 2; c++) if ((r + c) % 2 == 0) g1.FillRectangle(Brushes.Gray, x1 + 1 + c * 5, y1 + 2 + r * 5, 5, 5);
                }, "Độ mờ ▾");
                DrawVectorBtn(g, curX, 88, 86, 20, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1 + 1, y1 + 3, 9, 9);
                    g1.DrawLine(iconPen, x1 + 8, y1 + 7, x1 + 13, y1 + 7);
