                }, "Hiệu ứng ✨ ▾");
                DrawVectorBtn(g, curX, 108, 92, 20, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1 + 2, 6, 6);
                    g1.DrawRectangle(iconPen, x1 + 7, y1 + 6, 6, 6);
                }, "Bố cục ▾");
                curX += 98;

                g.DrawString("Kiểu hình ảnh", labelFont, Brushes.Gray, curX - 225, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 3. Nhóm Tiếp cận (Accessibility)
                DrawVectorToolBtnLarge(g, curX, 68, 76, 60, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1, 18, 14);
                    g1.DrawLine(iconPen, x1 + 3, y1 + 4, x1 + 15, y1 + 4);
