                curX += 82;
                g.DrawString("Tiếp cận", labelFont, Brushes.Gray, curX - 60, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 4. Nhóm Sắp xếp (Arrange)
                DrawVectorToolBtnLarge(g, curX, 68, 70, 60, (g1, x1, y1) => {
                    g1.DrawArc(iconPen, x1 + 2, y1 + 2, 16, 12, 180, 180);
                    g1.DrawLine(iconPen, x1 + 2, y1 + 12, x1 + 18, y1 + 12);
                }, "Ngắt dòng ▾");
                curX += 76;

                DrawVectorBtn(g, curX, 68, 114, 20, (g1, x1, y1) => {
                    g1.DrawRectangle(iconPen, x1, y1 + 1, 12, 12);
                    g1.FillRectangle(Brushes.DodgerBlue, x1 + 3, y1 + 4, 10, 10);
                }, "Lên trước ⭡");
                DrawVectorBtn(g, curX, 88, 114, 20, (g1, x1, y1) => {
                    g1.FillRectangle(Brushes.DodgerBlue, x1, y1 + 1, 10, 10);
                    g1.DrawRectangle(iconPen, x1 + 3, y1 + 4, 12, 12);
                }, "Về sau ⭣");
                DrawVectorBtn(g, curX, 108, 114, 20, (g1, x1, y1) => {
                    g1.DrawArc(iconPen, x1 + 1, y1 + 1, 13, 13, 45, 270);
                }, "Xoay ảnh ↻");
                curX += 120;
                g.DrawString("Sắp xếp", labelFont, Brushes.Gray, curX - 110, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 5. Nhóm Kích cỡ (Size)
                DrawVectorToolBtnLarge(g, curX, 68, 56, 60, (g1, x1, y1) => {
