        private void DrawWatermarkRibbonIcon(Graphics g, int x, int y)
        {
            Rectangle pRect = new Rectangle(x + 2, y, 20, 24);
            using (SolidBrush pb = new SolidBrush(Color.White)) g.FillRectangle(pb, pRect);
            using (Pen pp = new Pen(Color.FromArgb(100, 115, 130), 1.4f))
            {
                g.DrawRectangle(pp, pRect);
                g.DrawLine(pp, pRect.Right - 6, pRect.Top, pRect.Right - 6, pRect.Top + 6);
                g.DrawLine(pp, pRect.Right - 6, pRect.Top + 6, pRect.Right, pRect.Top + 6);
            }
            using (Font f = new Font("Arial", 11f, FontStyle.Bold))
            using (SolidBrush b = new SolidBrush(Color.FromArgb(230, 80, 80)))
            {
                g.DrawString("A", f, b, x + 4, y + 5);
            }
        }

        private void DrawPageColorRibbonIcon(Graphics g, int x, int y)
        {
            Rectangle pRect = new Rectangle(x + 2, y, 20, 24);
            using (SolidBrush pb = new SolidBrush(Color.White)) g.FillRectangle(pb, pRect);
            using (Pen pp = new Pen(Color.FromArgb(100, 115, 130), 1.4f))
            {
                g.DrawRectangle(pp, pRect);
            }
            // Paint bucket pouring blue paint
            using (SolidBrush bucketB = new SolidBrush(Color.FromArgb(37, 99, 235)))
            {
                g.FillPolygon(bucketB, new PointF[] { new PointF(x + 8, y + 4), new PointF(x + 16, y + 4), new PointF(x + 14, y + 14), new PointF(x + 6, y + 14) });
                g.FillEllipse(bucketB, x + 10, y + 15, 5, 7);
            }
        }

        private void DrawPageBorderRibbonIcon(Graphics g, int x, int y)
        {
            Rectangle pRect = new Rectangle(x + 2, y, 20, 24);
            using (SolidBrush pb = new SolidBrush(Color.White)) g.FillRectangle(pb, pRect);
            using (Pen pp = new Pen(Color.FromArgb(100, 115, 130), 1.2f))
            {
                g.DrawRectangle(pp, pRect);
            }
            using (Pen orangePen = new Pen(Color.FromArgb(234, 88, 12), 2.2f))
            {
                g.DrawRectangle(orangePen, x + 6, y + 4, 12, 16);
            }
        }

        private void DrawThemesRibbonIcon(Graphics g, int x, int y)
        {
            using (Font f = new Font("Segoe UI", 12f, FontStyle.Bold))
            using (SolidBrush tb = new SolidBrush(Color.FromArgb(43, 87, 154)))
            {
                g.DrawString("Aa", f, tb, x, y - 2);
            }
            Color[] c4 = new Color[] { Color.FromArgb(68, 114, 196), Color.FromArgb(237, 125, 49), Color.FromArgb(165, 165, 165), Color.FromArgb(255, 192, 0) };
            for (int k = 0; k < 4; k++)
            {
                using (SolidBrush b = new SolidBrush(c4[k])) g.FillRectangle(b, x + 2 + (k % 2) * 8, y + 13 + (k / 2) * 6, 7, 5);
            }
        }

        private void DrawTabThietKe(Graphics g, int width)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.5f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 9.0f, FontStyle.Bold))
            using (Pen iconPen = new Pen(Color.FromArgb(45, 55, 72), 1.8f))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                int curX = 14;

                // 1. Nhóm Định dạng tài liệu (Document Formatting)
                // Nút Chủ đề (Themes)
                DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => {
                    DrawThemesRibbonIcon(g1, x1, y1);
                }, "Chủ đề ▾");
                curX += 68;

                // 4 Thẻ mẫu kiểu dáng tài liệu trực quan (Style Gallery Previews)
                string[] pTitles = new string[] { "TITLE", "TITLE", "Title", "TITLE" };
                string[] pHeadings = new string[] { "Heading 1", "Heading 1", "Heading 1", "Heading 1" };
                Color[] pColors = new Color[] {
                    (ThemeColorPalette != null && ThemeColorPalette.Length > 0) ? ThemeColorPalette[0] : Color.FromArgb(68, 114, 196),
                    Color.FromArgb(31, 41, 55),
                    Color.FromArgb(120, 53, 15),
                    Color.FromArgb(5, 150, 105)
                };

                for (int p = 0; p < 4; p++)
                {
                    Rectangle pBox = new Rectangle(curX, 68, 68, 58);
                    bool isCur = (ActiveStyleSetIndex == p);
                    DrawInteractiveButton(g, pBox, isCur, 3);

                    using (SolidBrush pBg = new SolidBrush(Color.White)) g.FillRectangle(pBg, pBox.X + 3, pBox.Y + 3, pBox.Width - 6, 52);
                    using (Pen borderP = new Pen(isCur ? Color.FromArgb(37, 99, 235) : Color.LightGray, isCur ? 1.8f : 1.0f)) g.DrawRectangle(borderP, pBox.X + 3, pBox.Y + 3, pBox.Width - 6, 52);

                    using (Font tf = new Font("Segoe UI", 7.0f, FontStyle.Bold))
                    using (SolidBrush tb = new SolidBrush(pColors[p]))
                    {
                        g.DrawString(pTitles[p], tf, tb, pBox.X + 6, pBox.Y + 6);
                    }
                    using (Font hf = new Font("Segoe UI", 6.0f, FontStyle.Bold))
                    {
                        g.DrawString(pHeadings[p], hf, Brushes.DimGray, pBox.X + 6, pBox.Y + 18);
                    }
                    using (Pen lp = new Pen(Color.FromArgb(200, 200, 200), 1f))
                    {
                        g.DrawLine(lp, pBox.X + 6, pBox.Y + 30, pBox.Right - 8, pBox.Y + 30);
                        g.DrawLine(lp, pBox.X + 6, pBox.Y + 36, pBox.Right - 14, pBox.Y + 36);
                        g.DrawLine(lp, pBox.X + 6, pBox.Y + 42, pBox.Right - 8, pBox.Y + 42);
                    }

                    curX += 72;
                }

                // Nhóm công cụ phụ: Màu sắc, Phông chữ, Hiệu ứng
                DrawVectorBtn(g, curX, 68, 95, 20, (g1, x1, y1) => {
                    Color[] c4 = (ThemeColorPalette != null && ThemeColorPalette.Length >= 4) ? ThemeColorPalette : new Color[] { Color.FromArgb(68, 114, 196), Color.FromArgb(91, 155, 213), Color.FromArgb(237, 125, 49), Color.FromArgb(255, 192, 0) };
                    for (int k = 0; k < 4; k++)
                    {
                        using (SolidBrush b = new SolidBrush(c4[k])) g1.FillRectangle(b, x1 + (k % 2) * 6, y1 + (k / 2) * 6, 5, 5);
                    }
                }, "Màu sắc ▾");
                DrawVectorBtn(g, curX, 89, 95, 20, (g1, x1, y1) => {
                    using (Font af = new Font("Segoe UI", 9.0f, FontStyle.Bold)) g1.DrawString("A", af, Brushes.Navy, x1, y1 - 2);
                }, "Phông chữ ▾");
                DrawVectorBtn(g, curX, 110, 95, 20, (g1, x1, y1) => {
                    g1.DrawEllipse(iconPen, x1, y1 + 1, 10, 10);
                    g1.DrawEllipse(iconPen, x1 + 5, y1 + 1, 10, 10);
                }, "Hiệu ứng ▾");
                curX += 100;

                // Nhóm Giãn cách đoạn & Đặt mặc định
                DrawVectorBtn(g, curX, 68, 135, 20, (g1, x1, y1) => {
                    g1.DrawLine(iconPen, x1, y1 + 2, x1 + 12, y1 + 2);
                    g1.DrawLine(iconPen, x1, y1 + 6, x1 + 12, y1 + 6);
                    g1.DrawLine(iconPen, x1, y1 + 10, x1 + 12, y1 + 10);
                }, "Giãn cách đoạn ▾");
                DrawVectorBtn(g, curX, 89, 135, 20, (g1, x1, y1) => {
                    using (Pen gp = new Pen(Color.FromArgb(16, 124, 65), 1.8f))
                    {
                        g1.DrawEllipse(gp, x1, y1 + 1, 11, 11);
                        g1.DrawLine(gp, x1 + 3, y1 + 6, x1 + 5, y1 + 9);
                        g1.DrawLine(gp, x1 + 5, y1 + 9, x1 + 9, y1 + 4);
                    }
                }, "Đặt làm mặc định");
                curX += 140;

                g.DrawString("Định dạng tài liệu", labelFont, Brushes.Gray, 240, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 14;

                // 2. Nhóm Nền trang (Page Background) - Hình mờ, Màu trang, Viền trang
                DrawVectorToolBtnLarge(g, curX, 68, 72, 60, (g1, x1, y1) => {
                    DrawWatermarkRibbonIcon(g1, x1, y1);
                }, "Hình mờ ▾");
                curX += 78;

                DrawVectorToolBtnLarge(g, curX, 68, 72, 60, (g1, x1, y1) => {
                    DrawPageColorRibbonIcon(g1, x1, y1);
                }, "Màu trang ▾");
                curX += 78;

                DrawVectorToolBtnLarge(g, curX, 68, 72, 60, (g1, x1, y1) => {
                    DrawPageBorderRibbonIcon(g1, x1, y1);
                }, "Viền trang");
                curX += 78;

                g.DrawString("Nền trang", labelFont, Brushes.Gray, curX - 150, 137);
            }
        }

        private void DrawTabBoTri(Graphics g, int width, WriterView writerView = null)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font labelFontBold = new Font("Segoe UI", 7.5f, FontStyle.Bold))
            using (Font spinFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            using (Font spinArrowFont = new Font("Segoe UI", 6.0f, FontStyle.Bold))
            using (Pen spinBorder = new Pen(Color.FromArgb(180, 180, 180), 1.0f))
            using (Pen spinBtnBorder = new Pen(Color.FromArgb(210, 210, 210), 1.0f))
            {
                int curX = 14;

                // ==================== 1. NHÓM THIẾT LẬP TRANG (PAGE SETUP) ====================
                int pageSetupStartX = curX;

                // Lề trang (Margins)
                BtnMarginsBounds = new Rectangle(curX, 68, 58, 62);
                DrawVectorToolBtnLarge(g, BtnMarginsBounds.X, BtnMarginsBounds.Y, BtnMarginsBounds.Width, BtnMarginsBounds.Height, (g1, x1, y1) => DrawMarginsRibbonIcon(g1, x1, y1), "Lề ▾");
                curX += 62;

                // Hướng giấy (Orientation)
                BtnOrientationBounds = new Rectangle(curX, 68, 64, 62);
                DrawVectorToolBtnLarge(g, BtnOrientationBounds.X, BtnOrientationBounds.Y, BtnOrientationBounds.Width, BtnOrientationBounds.Height, (g1, x1, y1) => DrawOrientationRibbonIcon(g1, x1, y1), "Hướng ▾");
                curX += 68;

                // Khổ giấy (Size)
                BtnPageSizeBounds = new Rectangle(curX, 68, 66, 62);
                DrawVectorToolBtnLarge(g, BtnPageSizeBounds.X, BtnPageSizeBounds.Y, BtnPageSizeBounds.Width, BtnPageSizeBounds.Height, (g1, x1, y1) => DrawPageSizeRibbonIcon(g1, x1, y1), "Khổ giấy ▾");
                curX += 70;

                // Chia cột (Columns)
                BtnColumnsBounds = new Rectangle(curX, 68, 66, 62);
                DrawVectorToolBtnLarge(g, BtnColumnsBounds.X, BtnColumnsBounds.Y, BtnColumnsBounds.Width, BtnColumnsBounds.Height, (g1, x1, y1) => DrawColumnsRibbonIcon(g1, x1, y1), "Chia cột ▾");
                curX += 70;

                // 3 nút nhỏ xếp tầng (Breaks, Line Numbers, Hyphenation)
                BtnBreaksBounds = new Rectangle(curX, 68, 120, 20);
                DrawVectorBtn(g, BtnBreaksBounds.X, BtnBreaksBounds.Y, BtnBreaksBounds.Width, BtnBreaksBounds.Height, (g1, x1, y1) => DrawBreaksRibbonIcon(g1, x1, y1), "Ngắt trang ▾");

                BtnLineNumbersBounds = new Rectangle(curX, 89, 120, 20);
                DrawVectorBtn(g, BtnLineNumbersBounds.X, BtnLineNumbersBounds.Y, BtnLineNumbersBounds.Width, BtnLineNumbersBounds.Height, (g1, x1, y1) => DrawLineNumbersRibbonIcon(g1, x1, y1), "Số dòng ▾");

                BtnHyphenationBounds = new Rectangle(curX, 110, 120, 20);
                DrawVectorBtn(g, BtnHyphenationBounds.X, BtnHyphenationBounds.Y, BtnHyphenationBounds.Width, BtnHyphenationBounds.Height, (g1, x1, y1) => DrawHyphenationRibbonIcon(g1, x1, y1), "Dấu nối ▾");
                curX += 126;

                // Tiêu đề nhóm & Dialog launcher
                g.DrawString("Thiết lập trang", labelFont, Brushes.Gray, (pageSetupStartX + curX) / 2 - 38, 137);
                BtnPageSetupLauncherBounds = new Rectangle(curX - 16, 134, 13, 13);
                DrawDialogLauncherIcon(g, BtnPageSetupLauncherBounds.X, BtnPageSetupLauncherBounds.Y);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 16;

                // ==================== 2. NHÓM ĐOẠN VĂN (PARAGRAPH) ====================
                int paraStartX = curX;

                // Cột Thụt lề (Indent)
                g.DrawString("Thụt lề", labelFontBold, Brushes.DimGray, curX, 70);

                // Trái (Left Indent)
                DrawIndentLeftRibbonIcon(g, curX, 89);
                g.DrawString("Trái:", labelFont, Brushes.Black, curX + 18, 89);
                Rectangle spinLeftBox = new Rectangle(curX + 50, 87, 72, 20);
                g.FillRectangle(Brushes.White, spinLeftBox);
                g.DrawRectangle(spinBorder, spinLeftBox);
                g.DrawString(ParagraphIndentLeft.ToString("0.#") + "\"", spinFont, Brushes.Black, spinLeftBox.X + 4, spinLeftBox.Y + 3);
                SpinIndentLeftUpBounds = new Rectangle(spinLeftBox.Right - 16, spinLeftBox.Y, 16, 10);
                SpinIndentLeftDownBounds = new Rectangle(spinLeftBox.Right - 16, spinLeftBox.Y + 10, 16, 10);
                g.DrawRectangle(spinBtnBorder, SpinIndentLeftUpBounds);
                g.DrawRectangle(spinBtnBorder, SpinIndentLeftDownBounds);
                g.DrawString("▲", spinArrowFont, Brushes.DimGray, SpinIndentLeftUpBounds.X + 2, SpinIndentLeftUpBounds.Y - 1);
                g.DrawString("▼", spinArrowFont, Brushes.DimGray, SpinIndentLeftDownBounds.X + 2, SpinIndentLeftDownBounds.Y - 1);

                // Phải (Right Indent)
                DrawIndentRightRibbonIcon(g, curX, 110);
                g.DrawString("Phải:", labelFont, Brushes.Black, curX + 18, 110);
                Rectangle spinRightBox = new Rectangle(curX + 50, 108, 72, 20);
                g.FillRectangle(Brushes.White, spinRightBox);
                g.DrawRectangle(spinBorder, spinRightBox);
                g.DrawString(ParagraphIndentRight.ToString("0.#") + "\"", spinFont, Brushes.Black, spinRightBox.X + 4, spinRightBox.Y + 3);
                SpinIndentRightUpBounds = new Rectangle(spinRightBox.Right - 16, spinRightBox.Y, 16, 10);
                SpinIndentRightDownBounds = new Rectangle(spinRightBox.Right - 16, spinRightBox.Y + 10, 16, 10);
                g.DrawRectangle(spinBtnBorder, SpinIndentRightUpBounds);
                g.DrawRectangle(spinBtnBorder, SpinIndentRightDownBounds);
                g.DrawString("▲", spinArrowFont, Brushes.DimGray, SpinIndentRightUpBounds.X + 2, SpinIndentRightUpBounds.Y - 1);
                g.DrawString("▼", spinArrowFont, Brushes.DimGray, SpinIndentRightDownBounds.X + 2, SpinIndentRightDownBounds.Y - 1);
                curX += 134;

                // Cột Giãn cách (Spacing)
                g.DrawString("Giãn cách", labelFontBold, Brushes.DimGray, curX, 70);

                // Trước (Spacing Before)
                DrawSpacingBeforeRibbonIcon(g, curX, 89);
                g.DrawString("Trước:", labelFont, Brushes.Black, curX + 18, 89);
                Rectangle spinBeforeBox = new Rectangle(curX + 56, 87, 68, 20);
                g.FillRectangle(Brushes.White, spinBeforeBox);
                g.DrawRectangle(spinBorder, spinBeforeBox);
                g.DrawString(((int)ParagraphSpacingBefore).ToString() + " pt", spinFont, Brushes.Black, spinBeforeBox.X + 4, spinBeforeBox.Y + 3);
                SpinSpacingBeforeUpBounds = new Rectangle(spinBeforeBox.Right - 16, spinBeforeBox.Y, 16, 10);
                SpinSpacingBeforeDownBounds = new Rectangle(spinBeforeBox.Right - 16, spinBeforeBox.Y + 10, 16, 10);
                g.DrawRectangle(spinBtnBorder, SpinSpacingBeforeUpBounds);
                g.DrawRectangle(spinBtnBorder, SpinSpacingBeforeDownBounds);
                g.DrawString("▲", spinArrowFont, Brushes.DimGray, SpinSpacingBeforeUpBounds.X + 2, SpinSpacingBeforeUpBounds.Y - 1);
                g.DrawString("▼", spinArrowFont, Brushes.DimGray, SpinSpacingBeforeDownBounds.X + 2, SpinSpacingBeforeDownBounds.Y - 1);

                // Sau (Spacing After)
                DrawSpacingAfterRibbonIcon(g, curX, 110);
                g.DrawString("Sau:", labelFont, Brushes.Black, curX + 18, 110);
                Rectangle spinAfterBox = new Rectangle(curX + 56, 108, 68, 20);
                g.FillRectangle(Brushes.White, spinAfterBox);
                g.DrawRectangle(spinBorder, spinAfterBox);
                g.DrawString(((int)ParagraphSpacingAfter).ToString() + " pt", spinFont, Brushes.Black, spinAfterBox.X + 4, spinAfterBox.Y + 3);
                SpinSpacingAfterUpBounds = new Rectangle(spinAfterBox.Right - 16, spinAfterBox.Y, 16, 10);
                SpinSpacingAfterDownBounds = new Rectangle(spinAfterBox.Right - 16, spinAfterBox.Y + 10, 16, 10);
                g.DrawRectangle(spinBtnBorder, SpinSpacingAfterUpBounds);
                g.DrawRectangle(spinBtnBorder, SpinSpacingAfterDownBounds);
                g.DrawString("▲", spinArrowFont, Brushes.DimGray, SpinSpacingAfterUpBounds.X + 2, SpinSpacingAfterUpBounds.Y - 1);
                g.DrawString("▼", spinArrowFont, Brushes.DimGray, SpinSpacingAfterDownBounds.X + 2, SpinSpacingAfterDownBounds.Y - 1);
                curX += 136;

                // Tiêu đề nhóm & Dialog launcher
                g.DrawString("Đoạn văn", labelFont, Brushes.Gray, (paraStartX + curX) / 2 - 25, 137);
                BtnParagraphLauncherBounds = new Rectangle(curX - 16, 134, 13, 13);
                DrawDialogLauncherIcon(g, BtnParagraphLauncherBounds.X, BtnParagraphLauncherBounds.Y);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 16;

                // ==================== 3. NHÓM SẮP XẾP (ARRANGE) ====================
                int arrStartX = curX;

                // Vị trí (Position)
                BtnPositionBounds = new Rectangle(curX, 68, 58, 62);
                DrawVectorToolBtnLarge(g, BtnPositionBounds.X, BtnPositionBounds.Y, BtnPositionBounds.Width, BtnPositionBounds.Height, (g1, x1, y1) => DrawPositionRibbonIcon(g1, x1, y1), "Vị trí ▾");
                curX += 62;

                // Ngắt dòng (Wrap Text)
                BtnWrapTextBounds = new Rectangle(curX, 68, 70, 62);
                DrawVectorToolBtnLarge(g, BtnWrapTextBounds.X, BtnWrapTextBounds.Y, BtnWrapTextBounds.Width, BtnWrapTextBounds.Height, (g1, x1, y1) => DrawWrapTextRibbonIcon(g1, x1, y1), "Ngắt dòng ▾");
                curX += 74;

                // Lên trước (Bring Forward)
                BtnBringForwardBounds = new Rectangle(curX, 68, 70, 62);
                DrawVectorToolBtnLarge(g, BtnBringForwardBounds.X, BtnBringForwardBounds.Y, BtnBringForwardBounds.Width, BtnBringForwardBounds.Height, (g1, x1, y1) => DrawBringForwardRibbonIcon(g1, x1, y1), "Lên trước ▾");
                curX += 74;

                // Về sau (Send Backward)
                BtnSendBackwardBounds = new Rectangle(curX, 68, 68, 62);
                DrawVectorToolBtnLarge(g, BtnSendBackwardBounds.X, BtnSendBackwardBounds.Y, BtnSendBackwardBounds.Width, BtnSendBackwardBounds.Height, (g1, x1, y1) => DrawSendBackwardRibbonIcon(g1, x1, y1), "Về sau ▾");
                curX += 72;

                // Ngăn Lựa chọn (Selection Pane) - Khung vàng cam sáng khi kích hoạt giống Microsoft Word
                bool isSelPaneOpen = (writerView != null && writerView.ShowSelectionPane);
                BtnSelectionPaneBounds = new Rectangle(curX, 68, 78, 62);

                if (isSelPaneOpen)
                {
                    using (SolidBrush goldBg = new SolidBrush(Color.FromArgb(255, 237, 213))) // Tailwind amber-100
                    using (Pen goldBorder = new Pen(Color.FromArgb(217, 119, 6), 1.3f))
                    {
                        FillRoundedRectangle(g, goldBg, BtnSelectionPaneBounds, 4);
                        DrawRoundedRectangle(g, goldBorder, BtnSelectionPaneBounds, 4);
                    }
                }
                else
                {
                    DrawInteractiveButton(g, BtnSelectionPaneBounds, false, 4);
                }

                DrawSelectionPaneRibbonIcon(g, BtnSelectionPaneBounds.X + (BtnSelectionPaneBounds.Width - 20) / 2, 72);
                using (Font txtFont = new Font("Segoe UI", 7.8f, FontStyle.Bold))
                using (SolidBrush tb = new SolidBrush(isSelPaneOpen ? Color.FromArgb(180, 83, 9) : Color.FromArgb(30, 41, 59)))
                using (StringFormat sf = new StringFormat() { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center })
                {
                    g.DrawString("Ngăn chọn", txtFont, tb, new RectangleF(BtnSelectionPaneBounds.X, 104, BtnSelectionPaneBounds.Width, 22), sf);
                }
                curX += 84;

                // 3 nút nhỏ xếp tầng (Align, Group, Rotate)
                BtnAlignBounds = new Rectangle(curX, 68, 114, 20);
                DrawVectorBtn(g, BtnAlignBounds.X, BtnAlignBounds.Y, BtnAlignBounds.Width, BtnAlignBounds.Height, (g1, x1, y1) => DrawAlignRibbonIcon(g1, x1, y1), "Căn chỉnh ▾");

                BtnGroupBounds = new Rectangle(curX, 89, 114, 20);
                DrawVectorBtn(g, BtnGroupBounds.X, BtnGroupBounds.Y, BtnGroupBounds.Width, BtnGroupBounds.Height, (g1, x1, y1) => DrawGroupRibbonIcon(g1, x1, y1), "Nhóm ▾");

                BtnRotateBounds = new Rectangle(curX, 110, 114, 20);
                DrawVectorBtn(g, BtnRotateBounds.X, BtnRotateBounds.Y, BtnRotateBounds.Width, BtnRotateBounds.Height, (g1, x1, y1) => DrawRotateRibbonIcon(g1, x1, y1), "Xoay hình ▾");
                curX += 120;

                // Tiêu đề nhóm Sắp xếp
                g.DrawString("Sắp xếp", labelFont, Brushes.Gray, (arrStartX + curX) / 2 - 25, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            }
        }

        // ==================== CÁC HÀM VẼ VECTOR LUCIDE HIỆN ĐẠI CHO TAB BỐ TRÍ ====================
        private void DrawMarginsRibbonIcon(Graphics g, int x, int y)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (GraphicsPath path = ShapeRenderer.CreateShapePath("RoundedRectangle", new Rectangle(x + 1, y, 20, 24)))
            {
                g.FillPath(Brushes.White, path);
                using (Pen p = new Pen(Color.FromArgb(71, 85, 105), 1.2f))
                    g.DrawPath(p, path);
            }
            using (Pen dashPen = new Pen(Color.FromArgb(37, 99, 235), 1.0f) { DashStyle = DashStyle.Dash })
            {
                g.DrawRectangle(dashPen, x + 5, y + 4, 12, 16);
            }
            using (Pen linePen = new Pen(Color.FromArgb(148, 163, 184), 1.2f))
            {
                g.DrawLine(linePen, x + 7, y + 8, x + 15, y + 8);
                g.DrawLine(linePen, x + 7, y + 12, x + 15, y + 12);
                g.DrawLine(linePen, x + 7, y + 16, x + 13, y + 16);
            }
        }

        private void DrawOrientationRibbonIcon(Graphics g, int x, int y)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (GraphicsPath pBack = ShapeRenderer.CreateShapePath("RoundedRectangle", new Rectangle(x + 6, y + 7, 20, 14)))
            {
                g.FillPath(Brushes.White, pBack);
                using (Pen p = new Pen(Color.FromArgb(148, 163, 184), 1.2f))
                    g.DrawPath(p, pBack);
            }
            using (GraphicsPath pFront = ShapeRenderer.CreateShapePath("RoundedRectangle", new Rectangle(x, y + 1, 15, 21)))
            {
                g.FillPath(Brushes.White, pFront);
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.4f))
                    g.DrawPath(p, pFront);
            }
            using (Pen linePen = new Pen(Color.FromArgb(148, 163, 184), 1.0f))
            {
                g.DrawLine(linePen, x + 3, y + 6, x + 12, y + 6);
                g.DrawLine(linePen, x + 3, y + 11, x + 12, y + 11);
                g.DrawLine(linePen, x + 3, y + 16, x + 9, y + 16);
            }
        }

        private void DrawPageSizeRibbonIcon(Graphics g, int x, int y)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (GraphicsPath path = ShapeRenderer.CreateShapePath("RoundedRectangle", new Rectangle(x + 4, y + 4, 16, 20)))
            {
                g.FillPath(Brushes.White, path);
                using (Pen p = new Pen(Color.FromArgb(71, 85, 105), 1.2f))
                    g.DrawPath(p, path);
            }
            using (Pen dimPen = new Pen(Color.FromArgb(2, 132, 199), 1.4f))
            {
                dimPen.StartCap = LineCap.Round;
                dimPen.EndCap = LineCap.Round;
                g.DrawLine(dimPen, x + 2, y + 1, x + 22, y + 1);
                g.DrawLine(dimPen, x + 2, y + 1, x + 5, y - 1);
                g.DrawLine(dimPen, x + 2, y + 1, x + 5, y + 3);
                g.DrawLine(dimPen, x + 22, y + 1, x + 19, y - 1);
                g.DrawLine(dimPen, x + 22, y + 1, x + 19, y + 3);

                g.DrawLine(dimPen, x + 1, y + 2, x + 1, y + 26);
                g.DrawLine(dimPen, x + 1, y + 2, x - 1, y + 5);
                g.DrawLine(dimPen, x + 1, y + 2, x + 3, y + 5);
                g.DrawLine(dimPen, x + 1, y + 26, x - 1, y + 23);
                g.DrawLine(dimPen, x + 1, y + 26, x + 3, y + 23);
            }
        }

        private void DrawColumnsRibbonIcon(Graphics g, int x, int y)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (GraphicsPath col1 = ShapeRenderer.CreateShapePath("RoundedRectangle", new Rectangle(x + 1, y + 1, 9, 22)))
            using (GraphicsPath col2 = ShapeRenderer.CreateShapePath("RoundedRectangle", new Rectangle(x + 13, y + 1, 9, 22)))
            {
                using (SolidBrush bg = new SolidBrush(Color.FromArgb(239, 246, 255)))
                {
                    g.FillPath(bg, col1);
                    g.FillPath(bg, col2);
                }
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.2f))
                {
                    g.DrawPath(p, col1);
                    g.DrawPath(p, col2);
                }
            }
            using (SolidBrush lb = new SolidBrush(Color.FromArgb(96, 165, 250)))
            {
                for (int i = 0; i < 4; i++)
                {
                    g.FillRectangle(lb, x + 3, y + 5 + i * 4, 5, 2);
                    g.FillRectangle(lb, x + 15, y + 5 + i * 4, 5, 2);
                }
            }
        }

        private void DrawBreaksRibbonIcon(Graphics g, int x, int y)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (Pen p = new Pen(Color.FromArgb(71, 85, 105), 1.1f))
            {
                g.DrawRectangle(p, x, y, 14, 5);
                g.DrawRectangle(p, x, y + 9, 14, 5);
            }
            using (Pen breakPen = new Pen(Color.FromArgb(37, 99, 235), 1.2f) { DashStyle = DashStyle.Dash })
            {
                g.DrawLine(breakPen, x - 2, y + 7, x + 16, y + 7);
            }
        }

        private void DrawLineNumbersRibbonIcon(Graphics g, int x, int y)
        {
            using (Font numFont = new Font("Segoe UI", 6.5f, FontStyle.Bold))
            using (SolidBrush nb = new SolidBrush(Color.FromArgb(37, 99, 235)))
            using (Pen linePen = new Pen(Color.FromArgb(148, 163, 184), 1.2f))
            {
                g.DrawString("1", numFont, nb, x - 2, y - 1);
                g.DrawLine(linePen, x + 7, y + 4, x + 15, y + 4);

                g.DrawString("2", numFont, nb, x - 2, y + 7);
                g.DrawLine(linePen, x + 7, y + 12, x + 15, y + 12);
            }
        }

        private void DrawHyphenationRibbonIcon(Graphics g, int x, int y)
        {
            using (Font f = new Font("Segoe UI", 6.5f, FontStyle.Bold))
            using (SolidBrush tb = new SolidBrush(Color.FromArgb(37, 99, 235)))
            using (Pen linePen = new Pen(Color.FromArgb(148, 163, 184), 1.2f))
            {
                g.DrawString("a-", f, tb, x - 2, y - 1);
                g.DrawLine(linePen, x + 8, y + 4, x + 15, y + 4);

                g.DrawString("bc", f, tb, x - 2, y + 7);
                g.DrawLine(linePen, x + 8, y + 12, x + 15, y + 12);
            }
        }

