        private void DrawPositionRibbonIcon(Graphics g, int x, int y)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (GraphicsPath path = ShapeRenderer.CreateShapePath("RoundedRectangle", new Rectangle(x + 1, y, 19, 23)))
            {
                g.FillPath(Brushes.White, path);
                using (Pen p = new Pen(Color.FromArgb(71, 85, 105), 1.2f))
                    g.DrawPath(p, path);
            }
            using (Pen linePen = new Pen(Color.FromArgb(203, 213, 225), 1.2f))
            {
                g.DrawLine(linePen, x + 4, y + 4, x + 17, y + 4);
                g.DrawLine(linePen, x + 4, y + 16, x + 17, y + 16);
                g.DrawLine(linePen, x + 4, y + 19, x + 13, y + 19);
            }
            using (SolidBrush b = new SolidBrush(Color.FromArgb(37, 99, 235)))
                g.FillRectangle(b, x + 6, y + 7, 9, 7);
        }

        private void DrawWrapTextRibbonIcon(Graphics g, int x, int y)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (Pen archPen = new Pen(Color.FromArgb(37, 99, 235), 2.0f))
            {
                archPen.StartCap = LineCap.Round;
                archPen.EndCap = LineCap.Round;
                g.DrawArc(archPen, x + 6, y + 5, 10, 10, 180, 180);
                g.DrawLine(archPen, x + 6, y + 10, x + 6, y + 16);
                g.DrawLine(archPen, x + 16, y + 10, x + 16, y + 16);
            }
            using (Pen linePen = new Pen(Color.FromArgb(148, 163, 184), 1.2f))
            {
                linePen.StartCap = LineCap.Round;
                linePen.EndCap = LineCap.Round;
                g.DrawLine(linePen, x + 1, y + 2, x + 21, y + 2);
                g.DrawLine(linePen, x + 1, y + 8, x + 4, y + 8);
                g.DrawLine(linePen, x + 18, y + 8, x + 21, y + 8);
                g.DrawLine(linePen, x + 1, y + 13, x + 4, y + 13);
                g.DrawLine(linePen, x + 18, y + 13, x + 21, y + 13);
                g.DrawLine(linePen, x + 1, y + 19, x + 21, y + 19);
            }
        }

