        private void DrawSelectionPaneRibbonIcon(Graphics g, int x, int y)
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (GraphicsPath pBack = ShapeRenderer.CreateShapePath("RoundedRectangle", new Rectangle(x + 1, y + 5, 15, 17)))
            {
                g.FillPath(Brushes.White, pBack);
                using (Pen p = new Pen(Color.FromArgb(148, 163, 184), 1.2f))
                    g.DrawPath(p, pBack);
            }

            using (GraphicsPath pFront = ShapeRenderer.CreateShapePath("RoundedRectangle", new Rectangle(x + 7, y + 1, 15, 16)))
            {
                using (SolidBrush b = new SolidBrush(Color.FromArgb(245, 158, 11)))
                    g.FillPath(b, pFront);
                using (Pen p = new Pen(Color.FromArgb(217, 119, 6), 1.2f))
                    g.DrawPath(p, pFront);
            }

            Point[] cursorPoly = new Point[]
            {
                new Point(x + 16, y + 9),
                new Point(x + 22, y + 15),
                new Point(x + 19, y + 16),
                new Point(x + 22, y + 22),
                new Point(x + 20, y + 23),
                new Point(x + 17, y + 17),
                new Point(x + 14, y + 19)
            };
            using (SolidBrush cb = new SolidBrush(Color.White))
                g.FillPolygon(cb, cursorPoly);
            using (Pen cp = new Pen(Color.FromArgb(30, 41, 59), 1.2f))
            {
                cp.LineJoin = LineJoin.Round;
                g.DrawPolygon(cp, cursorPoly);
            }
        }

