        #region POPUP MENUS CHO TAB BỐ TRÍ (LAYOUT)
        private Bitmap CreateMenuVectorIcon(int w, int h, Action<Graphics, int, int> draw)
        {
            Bitmap bmp = new Bitmap(w, h);
            using (Graphics g = Graphics.FromImage(bmp))
            {
                g.SmoothingMode = SmoothingMode.AntiAlias;
                draw(g, 0, 0);
            }
            return bmp;
        }

        private void ShowAlignPopupMenu(Point screenPos, WriterView writerView, Form parentForm)
        {
            ContextMenuStrip menu = new ContextMenuStrip();
            menu.RenderMode = ToolStripRenderMode.System;

            menu.Items.Add("Căn lề trái (Align Left)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.5f)) g.DrawLine(p, x + 2, y + 1, x + 2, y + 15);
                using (SolidBrush b = new SolidBrush(Color.FromArgb(148, 163, 184))) {
                    g.FillRectangle(b, x + 4, y + 3, 10, 4);
                    g.FillRectangle(b, x + 4, y + 9, 6, 4);
                }
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.AlignShapes("Left", this); if (parentForm != null) parentForm.Invalidate(); } });

            menu.Items.Add("Căn giữa ngang (Align Center)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.2f) { DashStyle = DashStyle.Dash }) g.DrawLine(p, x + 8, y + 1, x + 8, y + 15);
                using (SolidBrush b = new SolidBrush(Color.FromArgb(148, 163, 184))) {
                    g.FillRectangle(b, x + 3, y + 3, 10, 4);
                    g.FillRectangle(b, x + 5, y + 9, 6, 4);
                }
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.AlignShapes("Center", this); if (parentForm != null) parentForm.Invalidate(); } });

            menu.Items.Add("Căn lề phải (Align Right)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.5f)) g.DrawLine(p, x + 14, y + 1, x + 14, y + 15);
                using (SolidBrush b = new SolidBrush(Color.FromArgb(148, 163, 184))) {
                    g.FillRectangle(b, x + 2, y + 3, 10, 4);
                    g.FillRectangle(b, x + 6, y + 9, 6, 4);
                }
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.AlignShapes("Right", this); if (parentForm != null) parentForm.Invalidate(); } });

            menu.Items.Add(new ToolStripSeparator());

            menu.Items.Add("Căn lề trên (Align Top)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.5f)) g.DrawLine(p, x + 1, y + 2, x + 15, y + 2);
                using (SolidBrush b = new SolidBrush(Color.FromArgb(148, 163, 184))) {
                    g.FillRectangle(b, x + 3, y + 4, 4, 10);
                    g.FillRectangle(b, x + 9, y + 4, 4, 6);
                }
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.AlignShapes("Top", this); if (parentForm != null) parentForm.Invalidate(); } });

            menu.Items.Add("Căn giữa dọc (Align Middle)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.2f) { DashStyle = DashStyle.Dash }) g.DrawLine(p, x + 1, y + 8, x + 15, y + 8);
                using (SolidBrush b = new SolidBrush(Color.FromArgb(148, 163, 184))) {
                    g.FillRectangle(b, x + 3, y + 3, 4, 10);
                    g.FillRectangle(b, x + 9, y + 5, 4, 6);
                }
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.AlignShapes("Middle", this); if (parentForm != null) parentForm.Invalidate(); } });

            menu.Items.Add("Căn lề dưới (Align Bottom)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.5f)) g.DrawLine(p, x + 1, y + 14, x + 15, y + 14);
                using (SolidBrush b = new SolidBrush(Color.FromArgb(148, 163, 184))) {
                    g.FillRectangle(b, x + 3, y + 2, 4, 10);
                    g.FillRectangle(b, x + 9, y + 6, 4, 6);
                }
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.AlignShapes("Bottom", this); if (parentForm != null) parentForm.Invalidate(); } });

            menu.Items.Add(new ToolStripSeparator());

            menu.Items.Add("Phân phối đều ngang (Distribute Horizontally)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.2f)) {
                    g.DrawLine(p, x + 2, y + 1, x + 2, y + 15);
                    g.DrawLine(p, x + 14, y + 1, x + 14, y + 15);
                }
                using (SolidBrush b = new SolidBrush(Color.FromArgb(148, 163, 184))) g.FillRectangle(b, x + 6, y + 4, 4, 8);
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.DistributeShapes("Horizontal"); if (parentForm != null) parentForm.Invalidate(); } });

            menu.Items.Add("Phân phối đều dọc (Distribute Vertically)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.2f)) {
                    g.DrawLine(p, x + 1, y + 2, x + 15, y + 2);
                    g.DrawLine(p, x + 1, y + 14, x + 15, y + 14);
                }
                using (SolidBrush b = new SolidBrush(Color.FromArgb(148, 163, 184))) g.FillRectangle(b, x + 4, y + 6, 8, 4);
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.DistributeShapes("Vertical"); if (parentForm != null) parentForm.Invalidate(); } });

            menu.Items.Add(new ToolStripSeparator());

            ToolStripMenuItem mAlignPage = new ToolStripMenuItem("Căn theo trang (Align to Page)");
            mAlignPage.Checked = (writerView != null && writerView.AlignToPage);
            mAlignPage.Click += delegate(object s, EventArgs e) { if (writerView != null) { writerView.AlignToPage = true; writerView.AlignToMargin = false; if (parentForm != null) parentForm.Invalidate(); } };
            menu.Items.Add(mAlignPage);

            ToolStripMenuItem mAlignMargin = new ToolStripMenuItem("Căn theo lề (Align to Margin)");
            mAlignMargin.Checked = (writerView != null && writerView.AlignToMargin);
            mAlignMargin.Click += delegate(object s, EventArgs e) { if (writerView != null) { writerView.AlignToMargin = true; writerView.AlignToPage = false; if (parentForm != null) parentForm.Invalidate(); } };
            menu.Items.Add(mAlignMargin);

            ToolStripMenuItem mAlignSelected = new ToolStripMenuItem("Căn theo các đối tượng đã chọn (Align Selected Objects)");
            mAlignSelected.Checked = (writerView != null && !writerView.AlignToMargin && !writerView.AlignToPage);
            mAlignSelected.Click += delegate(object s, EventArgs e) { if (writerView != null) { writerView.AlignToMargin = false; writerView.AlignToPage = false; if (parentForm != null) parentForm.Invalidate(); } };
            menu.Items.Add(mAlignSelected);

            menu.Items.Add(new ToolStripSeparator());

            ToolStripMenuItem mGuides = new ToolStripMenuItem("Dùng đường gióng căn chỉnh (Use Alignment Guides)");
            mGuides.Checked = (writerView != null && writerView.UseAlignmentGuides);
            mGuides.Click += delegate(object s, EventArgs e) { if (writerView != null) { writerView.UseAlignmentGuides = !writerView.UseAlignmentGuides; if (parentForm != null) parentForm.Invalidate(); } };
            menu.Items.Add(mGuides);

            ToolStripMenuItem mGridlines = new ToolStripMenuItem("Hiện đường lưới (View Gridlines)");
            mGridlines.Checked = ShowGridlines;
            mGridlines.Click += delegate(object s, EventArgs e) { ShowGridlines = !ShowGridlines; if (parentForm != null) parentForm.Invalidate(); };
            menu.Items.Add(mGridlines);

            menu.Show(screenPos);
        }

        private void ShowRotatePopupMenu(Point screenPos, WriterView writerView, Form parentForm)
        {
            ContextMenuStrip menu = new ContextMenuStrip();
            menu.RenderMode = ToolStripRenderMode.System;

            menu.Items.Add("Xoay phải 90° (Rotate Right 90°)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.3f)) {
                    g.DrawArc(p, x + 2, y + 2, 11, 11, 270, 200);
                    g.DrawLine(p, x + 9, y + 1, x + 12, y + 2);
                    g.DrawLine(p, x + 12, y + 2, x + 10, y + 5);
                }
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.RotateShape(90); if (parentForm != null) parentForm.Invalidate(); } });

            menu.Items.Add("Xoay trái 90° (Rotate Left 90°)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.3f)) {
                    g.DrawArc(p, x + 3, y + 2, 11, 11, 180, 200);
                    g.DrawLine(p, x + 7, y + 1, x + 4, y + 2);
                    g.DrawLine(p, x + 4, y + 2, x + 6, y + 5);
                }
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.RotateShape(-90); if (parentForm != null) parentForm.Invalidate(); } });

            menu.Items.Add("Lật dọc (Flip Vertical)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(71, 85, 105), 1.0f) { DashStyle = DashStyle.Dash }) g.DrawLine(p, x + 1, y + 8, x + 15, y + 8);
                using (SolidBrush b1 = new SolidBrush(Color.FromArgb(37, 99, 235)))
                    g.FillPolygon(b1, new Point[] { new Point(x + 4, y + 2), new Point(x + 12, y + 2), new Point(x + 8, y + 6) });
                using (SolidBrush b2 = new SolidBrush(Color.FromArgb(148, 163, 184)))
                    g.FillPolygon(b2, new Point[] { new Point(x + 4, y + 14), new Point(x + 12, y + 14), new Point(x + 8, y + 10) });
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.FlipShape(false); if (parentForm != null) parentForm.Invalidate(); } });

            menu.Items.Add("Lật ngang (Flip Horizontal)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(71, 85, 105), 1.0f) { DashStyle = DashStyle.Dash }) g.DrawLine(p, x + 8, y + 1, x + 8, y + 15);
                using (SolidBrush b1 = new SolidBrush(Color.FromArgb(37, 99, 235)))
                    g.FillPolygon(b1, new Point[] { new Point(x + 2, y + 4), new Point(x + 2, y + 12), new Point(x + 6, y + 8) });
                using (SolidBrush b2 = new SolidBrush(Color.FromArgb(148, 163, 184)))
                    g.FillPolygon(b2, new Point[] { new Point(x + 14, y + 4), new Point(x + 14, y + 12), new Point(x + 10, y + 8) });
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.FlipShape(true); if (parentForm != null) parentForm.Invalidate(); } });

            menu.Show(screenPos);
        }

        private void ShowGroupPopupMenu(Point screenPos, WriterView writerView, Form parentForm)
        {
            ContextMenuStrip menu = new ContextMenuStrip();
            menu.RenderMode = ToolStripRenderMode.System;

            bool canGroup = (writerView != null && (writerView.SelectedShapes.Count >= 2 || (writerView.ActiveShape != null && writerView.DocumentShapes.Count >= 2)));
            bool canUngroup = (writerView != null && writerView.ActiveShape != null && writerView.ActiveShape.ShapeType == "Group");
            bool canRegroup = (writerView != null && writerView.LastUngroupedShapes != null && writerView.LastUngroupedShapes.Count >= 2);

            ToolStripMenuItem mGroup = new ToolStripMenuItem("Nhóm (Group)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen dash = new Pen(Color.FromArgb(37, 99, 235), 1.0f) { DashStyle = DashStyle.Dash }) g.DrawRectangle(dash, x + 1, y + 1, 14, 14);
                using (SolidBrush b = new SolidBrush(Color.FromArgb(148, 163, 184))) {
                    g.FillRectangle(b, x + 3, y + 3, 4, 4);
                    g.FillRectangle(b, x + 9, y + 9, 4, 4);
                }
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.GroupSelectedShapes(); if (parentForm != null) parentForm.Invalidate(); } });
            mGroup.Enabled = canGroup;
            menu.Items.Add(mGroup);

            ToolStripMenuItem mRegroup = new ToolStripMenuItem("Nhóm lại (Regroup)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.2f)) g.DrawArc(p, x + 2, y + 2, 12, 12, 45, 270);
                using (SolidBrush b = new SolidBrush(Color.FromArgb(148, 163, 184))) g.FillRectangle(b, x + 5, y + 5, 6, 6);
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.RegroupSelectedShapes(); if (parentForm != null) parentForm.Invalidate(); } });
            mRegroup.Enabled = canRegroup;
            menu.Items.Add(mRegroup);

            ToolStripMenuItem mUngroup = new ToolStripMenuItem("Bỏ nhóm (Ungroup)", CreateMenuVectorIcon(16, 16, delegate(Graphics g, int x, int y) {
                using (Pen p = new Pen(Color.FromArgb(220, 38, 38), 1.2f)) {
                    g.DrawLine(p, x + 2, y + 8, x + 5, y + 5);
                    g.DrawLine(p, x + 14, y + 8, x + 11, y + 11);
                }
                using (SolidBrush b = new SolidBrush(Color.FromArgb(148, 163, 184))) {
                    g.FillRectangle(b, x + 3, y + 3, 4, 4);
                    g.FillRectangle(b, x + 9, y + 9, 4, 4);
                }
            }), delegate(object s, EventArgs e) { if (writerView != null) { writerView.UngroupSelectedShape(); if (parentForm != null) parentForm.Invalidate(); } });
            mUngroup.Enabled = canUngroup;
            menu.Items.Add(mUngroup);

            menu.Show(screenPos);
        }

        private void ShowPositionPopupMenu(Point screenPos, WriterView writerView, Form parentForm)
        {
            PositionDropDownForm posDlg = new PositionDropDownForm(screenPos, 0);
            posDlg.OnPreviewPosition += delegate(int pIdx) {
                if (writerView != null)
                {
                    writerView.PreviewPositionShape(pIdx, this);
                    if (parentForm != null) parentForm.Invalidate();
                }
            };
            posDlg.OnCancelPreview += delegate() {
                if (writerView != null)
                {
                    writerView.CancelShapeLivePreview();
                    if (parentForm != null) parentForm.Invalidate();
                }
            };
            posDlg.OnPositionSelected += delegate(int posIdx) {
                if (writerView != null)
                {
                    writerView.CommitShapeLivePreview();
                    if (posIdx == 0)
                    {
                        if (writerView.ActiveShape != null) writerView.ActiveShape.WrapMode = 0;
                    }
                    else
                    {
                        writerView.PositionShape(posIdx - 1, this);
                    }
                    if (parentForm != null) parentForm.Invalidate();
                }
            };
            posDlg.OnMoreLayoutOptionsClicked += delegate() {
                if (writerView != null)
                {
                    using (LayoutOptionsDialogForm layoutDlg = new LayoutOptionsDialogForm(writerView.ActiveShape, 0))
                    {
                        if (layoutDlg.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            if (writerView.ActiveShape != null)
                            {
                                writerView.ActiveShape.WrapMode = layoutDlg.WrapMode;
                                writerView.ActiveShape.RotationAngle = layoutDlg.RotationAngle;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    }
                }
            };
            posDlg.Show();
        }

        private void ShowWrapTextPopupMenu(Point screenPos, WriterView writerView, Form parentForm)
        {
            int curWrap = (writerView != null && writerView.ActiveShape != null) ? writerView.ActiveShape.WrapMode : 1;
            WrapTextDropDownForm wrapDlg = new WrapTextDropDownForm(screenPos, curWrap);
            wrapDlg.OnPreviewWrapMode += delegate(int mode) {
                if (writerView != null)
                {
                    writerView.PreviewWrapMode(mode);
                    if (parentForm != null) parentForm.Invalidate();
                }
            };
            wrapDlg.OnCancelPreview += delegate() {
                if (writerView != null)
                {
                    writerView.CancelShapeLivePreview();
                    if (parentForm != null) parentForm.Invalidate();
                }
            };
            wrapDlg.OnWrapModeSelected += delegate(int mode) {
                if (writerView != null)
                {
                    writerView.CommitShapeLivePreview();
                    if (writerView.ActiveShape != null) writerView.ActiveShape.WrapMode = mode;
                    if (parentForm != null) parentForm.Invalidate();
                }
            };
            wrapDlg.OnMoreLayoutOptionsClicked += delegate() {
                if (writerView != null)
                {
                    using (LayoutOptionsDialogForm layoutDlg = new LayoutOptionsDialogForm(writerView.ActiveShape, 1))
                    {
                        if (layoutDlg.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            if (writerView.ActiveShape != null)
                            {
                                writerView.ActiveShape.WrapMode = layoutDlg.WrapMode;
                                writerView.ActiveShape.RotationAngle = layoutDlg.RotationAngle;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    }
                }
            };
            wrapDlg.Show();
        }

        private void ShowBringForwardPopupMenu(Point screenPos, WriterView writerView, Form parentForm)
        {
            ContextMenuStrip menu = new ContextMenuStrip();
            menu.RenderMode = ToolStripRenderMode.System;

            menu.Items.Add("Lên trước 1 lớp (Bring Forward)", null, delegate(object s, EventArgs e) {
                if (writerView != null)
                {
                    if (writerView.ActiveShape != null) writerView.MoveShapeUp(writerView.ActiveShape);
                    else if (writerView.ActiveChart != null) writerView.MoveChartUp(writerView.ActiveChart);
                    if (parentForm != null) parentForm.Invalidate();
                }
            });

            menu.Items.Add("Lên trên cùng (Bring to Front)", null, delegate(object s, EventArgs e) {
                if (writerView != null && writerView.ActiveShape != null)
                {
                    writerView.DocumentShapes.Remove(writerView.ActiveShape);
                    writerView.DocumentShapes.Add(writerView.ActiveShape);
                    if (parentForm != null) parentForm.Invalidate();
                }
            });

            menu.Items.Add("Lên trước văn bản (Bring in Front of Text)", null, delegate(object s, EventArgs e) {
                if (writerView != null && writerView.ActiveShape != null)
                {
                    writerView.ActiveShape.WrapMode = 6;
                    if (parentForm != null) parentForm.Invalidate();
                }
            });

            menu.Show(screenPos);
        }

        private void ShowSendBackwardPopupMenu(Point screenPos, WriterView writerView, Form parentForm)
        {
            ContextMenuStrip menu = new ContextMenuStrip();
            menu.RenderMode = ToolStripRenderMode.System;

            menu.Items.Add("Về sau 1 lớp (Send Backward)", null, delegate(object s, EventArgs e) {
                if (writerView != null)
                {
                    if (writerView.ActiveShape != null) writerView.MoveShapeDown(writerView.ActiveShape);
                    else if (writerView.ActiveChart != null) writerView.MoveChartDown(writerView.ActiveChart);
                    if (parentForm != null) parentForm.Invalidate();
                }
            });

            menu.Items.Add("Xuống dưới cùng (Send to Back)", null, delegate(object s, EventArgs e) {
                if (writerView != null && writerView.ActiveShape != null)
                {
                    writerView.DocumentShapes.Remove(writerView.ActiveShape);
                    writerView.DocumentShapes.Insert(0, writerView.ActiveShape);
                    if (parentForm != null) parentForm.Invalidate();
                }
            });

            menu.Items.Add("Xuống sau văn bản (Send Behind Text)", null, delegate(object s, EventArgs e) {
                if (writerView != null && writerView.ActiveShape != null)
                {
                    writerView.ActiveShape.WrapMode = 5;
                    if (parentForm != null) parentForm.Invalidate();
                }
            });

            menu.Show(screenPos);
        }

        private void ShowOrientationPopupMenu(Point screenPos, Form parentForm)
        {
            ContextMenuStrip menu = new ContextMenuStrip();
            menu.RenderMode = ToolStripRenderMode.System;

            ToolStripMenuItem mPort = new ToolStripMenuItem("Dọc (Portrait)");
            mPort.Checked = !IsLandscape;
            mPort.Click += delegate(object s, EventArgs e) { IsLandscape = false; if (parentForm != null) parentForm.Invalidate(); };
            menu.Items.Add(mPort);

            ToolStripMenuItem mLand = new ToolStripMenuItem("Ngang (Landscape)");
            mLand.Checked = IsLandscape;
            mLand.Click += delegate(object s, EventArgs e) { IsLandscape = true; if (parentForm != null) parentForm.Invalidate(); };
            menu.Items.Add(mLand);

            menu.Show(screenPos);
        }

        private void ShowPageSizePopupMenu(Point screenPos, Form parentForm)
        {
            PaperSizeDropDownForm sizeDlg = new PaperSizeDropDownForm(screenPos, PaperSizeName);
            sizeDlg.OnPaperSizeSelected += delegate(PaperSizeItem item) {
                PaperSizeName = item.Name;
                PaperWidthInches = item.WidthInches;
                PaperHeightInches = item.HeightInches;
                if (parentForm != null) parentForm.Invalidate();
            };
            sizeDlg.OnMorePaperSizesClicked += delegate() {
                float top = GetEffectiveTopMarginInches();
                using (PageSetupForm pageSetupDlg = new PageSetupForm(top, top, GetEffectiveLeftMarginInches(), GetEffectiveRightMarginInches(), IsLandscape, 1, PaperSizeName))
                {
                    if (pageSetupDlg.ShowDialog(parentForm) == DialogResult.OK)
                    {
                        IsLandscape = pageSetupDlg.IsLandscape;
                        PaperSizeName = pageSetupDlg.PaperSize;
                        PaperWidthInches = pageSetupDlg.PaperWidthInches;
                        PaperHeightInches = pageSetupDlg.PaperHeightInches;
                        if (parentForm != null) parentForm.Invalidate();
                    }
                }
            };
            sizeDlg.Show();
        }

        private void ShowColumnsPopupMenu(Point screenPos, Form parentForm)
        {
            ColumnsDropDownForm colDlg = new ColumnsDropDownForm(screenPos, ColumnPreset);
            colDlg.OnColumnPresetSelected += delegate(ColumnPresetItem item) {
                ColumnCount = item.ColumnCount;
                ColumnPreset = item.PresetType;
                if (parentForm != null) parentForm.Invalidate();
            };
            colDlg.OnMoreColumnsClicked += delegate() {
                using (ColumnsDialogForm colDialog = new ColumnsDialogForm(ColumnCount, ColumnSpacingInches, ColumnLineBetween, ColumnPreset))
                {
                    if (colDialog.ShowDialog(parentForm) == DialogResult.OK)
                    {
                        ColumnCount = colDialog.ColumnCount;
                        ColumnSpacingInches = colDialog.ColumnSpacingInches;
                        ColumnLineBetween = colDialog.LineBetween;
                        ColumnPreset = colDialog.PresetType;
                        if (parentForm != null) parentForm.Invalidate();
                    }
                }
            };
            colDlg.Show();
        }

        private void ShowBreaksPopupMenu(Point screenPos, WriterView writerView, Form parentForm)
        {
            BreaksDropDownForm breakDlg = new BreaksDropDownForm(screenPos);
            breakDlg.OnBreakSelected += delegate(string bType) {
                if (writerView != null)
                {
                    if (bType == "Page" || bType == "NextPage" || bType == "EvenPage" || bType == "OddPage")
                    {
                        writerView.InsertPageBreak();
                    }
                    else if (bType == "Column")
                    {
                        writerView.InsertText("\n[--- COLUMN BREAK ---]\n");
                    }
                    else if (bType == "TextWrapping")
                    {
                        writerView.InsertText("\n[--- TEXT WRAPPING BREAK ---]\n");
                    }
                    else if (bType == "Continuous")
                    {
                        writerView.InsertText("\n[--- SECTION BREAK (CONTINUOUS) ---]\n");
                    }
                    if (parentForm != null) parentForm.Invalidate();
                }
            };
            breakDlg.Show();
        }

        private void ShowLineNumbersPopupMenu(Point screenPos, Form parentForm)
        {
            ContextMenuStrip menu = new ContextMenuStrip();
            menu.RenderMode = ToolStripRenderMode.System;

            menu.Items.Add("Không có (None)", null, delegate(object s, EventArgs e) { if (parentForm != null) parentForm.Invalidate(); });
            menu.Items.Add("Liên tục (Continuous)", null, delegate(object s, EventArgs e) { if (parentForm != null) parentForm.Invalidate(); });
            menu.Items.Add("Bắt đầu lại ở mỗi trang (Restart Each Page)", null, delegate(object s, EventArgs e) { if (parentForm != null) parentForm.Invalidate(); });
            menu.Items.Add("Bắt đầu lại ở mỗi đoạn (Restart Each Section)", null, delegate(object s, EventArgs e) { if (parentForm != null) parentForm.Invalidate(); });

            menu.Show(screenPos);
        }

        private void ShowHyphenationPopupMenu(Point screenPos, Form parentForm)
        {
            ContextMenuStrip menu = new ContextMenuStrip();
            menu.RenderMode = ToolStripRenderMode.System;

            menu.Items.Add("Không (None)", null, delegate(object s, EventArgs e) { if (parentForm != null) parentForm.Invalidate(); });
            menu.Items.Add("Tự động (Automatic)", null, delegate(object s, EventArgs e) { if (parentForm != null) parentForm.Invalidate(); });
            menu.Items.Add("Thủ công (Manual)...", null, delegate(object s, EventArgs e) { if (parentForm != null) parentForm.Invalidate(); });

            menu.Show(screenPos);
        }
        #endregion

        private void DrawTabThamChieu(Graphics g, int width, WriterView writerView = null)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                int curX = 14;

                // ==========================================
                // 1. NHÓM: MỤC LỤC (Table of Contents)
                // ==========================================
                // 1.1 Mục lục tự động (Large)
                DrawVectorToolBtnLarge(g, curX, 68, 68, 60, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(30, 58, 138), 1.5f))
                    using (SolidBrush fillBg = new SolidBrush(Color.FromArgb(248, 250, 252)))
                    using (SolidBrush fillHdr = new SolidBrush(Color.FromArgb(37, 99, 235)))
                    {
                        // Drop shadow
                        g1.FillRectangle(new SolidBrush(Color.FromArgb(203, 213, 225)), x1 + 3, y1 + 3, 16, 18);
                        // Page canvas
                        g1.FillRectangle(fillBg, x1 + 1, y1 + 1, 16, 18);
                        g1.DrawRectangle(pNavy, x1 + 1, y1 + 1, 16, 18);
                        // Header bar with gold dot
                        g1.FillRectangle(fillHdr, x1 + 3, y1 + 3, 12, 3);
                        g1.FillEllipse(new SolidBrush(Color.FromArgb(245, 158, 11)), x1 + 12, y1 + 3, 2, 2);
                        // TOC bullet rows
                        using (Pen pBlue = new Pen(Color.FromArgb(37, 99, 235), 1.3f))
                        using (Pen pSky = new Pen(Color.FromArgb(56, 189, 248), 1.3f))
                        using (Pen pDot = new Pen(Color.FromArgb(148, 163, 184), 1.1f) { DashStyle = DashStyle.Dot })
                        {
                            // Level 1
                            g1.DrawLine(pBlue, x1 + 3, y1 + 9, x1 + 8, y1 + 9);
                            g1.DrawLine(pDot, x1 + 9, y1 + 9, x1 + 13, y1 + 9);
                            g1.FillRectangle(new SolidBrush(Color.FromArgb(220, 38, 38)), x1 + 14, y1 + 8, 2, 2);
                            // Level 2 (indented)
                            g1.DrawLine(pSky, x1 + 5, y1 + 13, x1 + 9, y1 + 13);
                            g1.DrawLine(pDot, x1 + 10, y1 + 13, x1 + 13, y1 + 13);
                            g1.FillRectangle(new SolidBrush(Color.FromArgb(37, 99, 235)), x1 + 14, y1 + 12, 2, 2);
                            // Level 1
                            g1.DrawLine(pBlue, x1 + 3, y1 + 16, x1 + 8, y1 + 16);
                            g1.DrawLine(pDot, x1 + 9, y1 + 16, x1 + 13, y1 + 16);
                            g1.FillRectangle(new SolidBrush(Color.FromArgb(220, 38, 38)), x1 + 14, y1 + 15, 2, 2);
                        }
                    }
                }, "Mục lục ▾");
                curX += 72;

                // 1.2 Thêm văn bản (Add Text Level) & Cập nhật mục lục (Update TOC)
                DrawVectorBtn(g, curX, 68, 128, 28, (g1, x1, y1) => {
                    using (Pen pGreen = new Pen(Color.FromArgb(16, 185, 129), 1.5f))
                    using (SolidBrush fillBadge = new SolidBrush(Color.FromArgb(236, 253, 245)))
                    {
                        g1.FillRectangle(fillBadge, x1, y1 + 1, 14, 13);
                        g1.DrawRectangle(pGreen, x1, y1 + 1, 14, 13);
                        // Stepped level lines
                        g1.DrawLine(new Pen(Color.FromArgb(16, 185, 129), 1.3f), x1 + 2, y1 + 4, x1 + 8, y1 + 4);
                        g1.DrawLine(new Pen(Color.FromArgb(52, 211, 153), 1.3f), x1 + 4, y1 + 7, x1 + 9, y1 + 7);
                        // Plus glyph in emerald circle
                        g1.FillEllipse(new SolidBrush(Color.FromArgb(16, 185, 129)), x1 + 8, y1 + 7, 7, 7);
                        g1.DrawLine(new Pen(Color.White, 1.3f), x1 + 11, y1 + 8, x1 + 11, y1 + 13);
                        g1.DrawLine(new Pen(Color.White, 1.3f), x1 + 9, y1 + 10, x1 + 14, y1 + 10);
                    }
                }, "Thêm văn bản ▾");
                DrawVectorBtn(g, curX, 98, 128, 28, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.4f))
                    using (SolidBrush fillBg = new SolidBrush(Color.FromArgb(239, 246, 255)))
                    using (Pen pAmber = new Pen(Color.FromArgb(245, 158, 11), 1.6f))
                    {
                        g1.FillRectangle(fillBg, x1, y1 + 1, 14, 13);
                        g1.DrawRectangle(pNavy, x1, y1 + 1, 14, 13);
                        g1.DrawArc(pAmber, x1 + 2, y1 + 3, 10, 9, 30, 270);
                        // Arrow head
                        g1.DrawLine(pAmber, x1 + 10, y1 + 4, x1 + 12, y1 + 6);
                        g1.DrawLine(pAmber, x1 + 10, y1 + 8, x1 + 12, y1 + 6);
                    }
                }, "Cập nhật bảng");
                curX += 134;

                g.DrawString("Mục lục", labelFont, Brushes.Gray, curX - 125, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 2. NHÓM: CHÚ THÍCH (Footnotes & Endnotes)
                // ==========================================
                // 2.1 Chèn Chú thích Footnote (AB¹)
                DrawVectorToolBtnLarge(g, curX, 68, 72, 60, (g1, x1, y1) => {
                    using (Font abF = new Font("Segoe UI", 9.5f, FontStyle.Bold))
                    using (Font supF = new Font("Segoe UI", 7.5f, FontStyle.Bold))
                    using (Pen pSep = new Pen(Color.FromArgb(37, 99, 235), 1.6f))
                    {
                        // Main text glyph
                        g1.DrawString("AB", abF, new SolidBrush(Color.FromArgb(30, 41, 59)), x1 - 2, y1 - 2);
                        // Superscript badge with circular highlight
                        g1.FillEllipse(new SolidBrush(Color.FromArgb(254, 226, 226)), x1 + 13, y1 - 3, 9, 9);
                        g1.DrawString("¹", supF, new SolidBrush(Color.FromArgb(220, 38, 38)), x1 + 14, y1 - 4);
                        // Footnote separator line & page footnote rows
                        g1.DrawLine(pSep, x1 - 1, y1 + 16, x1 + 19, y1 + 16);
                        g1.DrawString("¹", new Font("Segoe UI", 6.0f, FontStyle.Bold), new SolidBrush(Color.FromArgb(220, 38, 38)), x1 - 2, y1 + 14);
                        g1.DrawLine(new Pen(Color.FromArgb(148, 163, 184), 1.2f), x1 + 5, y1 + 18, x1 + 18, y1 + 18);
                    }
                }, "Chèn Footnote");
                curX += 76;

                // 2.2 Chèn Endnote & Chú thích tiếp theo
                DrawVectorBtn(g, curX, 68, 124, 28, (g1, x1, y1) => {
                    using (Pen pIndigo = new Pen(Color.FromArgb(99, 102, 241), 1.4f))
                    using (SolidBrush fillBg = new SolidBrush(Color.FromArgb(238, 242, 255)))
                    using (Font supF = new Font("Segoe UI", 8.0f, FontStyle.Bold))
                    {
                        g1.FillRectangle(fillBg, x1, y1 + 1, 13, 14);
                        g1.DrawRectangle(pIndigo, x1, y1 + 1, 13, 14);
                        g1.FillEllipse(new SolidBrush(Color.FromArgb(99, 102, 241)), x1 + 7, y1 + 1, 7, 7);
                        g1.DrawString("i", new Font("Segoe UI", 5.5f, FontStyle.Bold), Brushes.White, x1 + 9, y1 + 1);
                        g1.DrawLine(new Pen(Color.FromArgb(165, 180, 252), 1.1f), x1 + 2, y1 + 11, x1 + 10, y1 + 11);
                    }
                }, "Chèn Endnote");
                DrawVectorBtn(g, curX, 98, 124, 28, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.6f))
                    using (SolidBrush fillDot = new SolidBrush(Color.FromArgb(245, 158, 11)))
                    {
                        g1.DrawLine(pNavy, x1 + 1, y1 + 7, x1 + 11, y1 + 7);
                        g1.DrawLine(pNavy, x1 + 7, y1 + 3, x1 + 11, y1 + 7);
                        g1.DrawLine(pNavy, x1 + 7, y1 + 11, x1 + 11, y1 + 7);
                        g1.FillEllipse(fillDot, x1 + 13, y1 + 5, 4, 4);
                    }
                }, "Chú thích tiếp ▾");
                curX += 128;

                // 2.3 Hiện danh sách chú thích (Show Notes Pane)
                DrawVectorToolBtnLarge(g, curX, 68, 68, 60, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.4f))
                    using (SolidBrush fillBg = new SolidBrush(Color.FromArgb(248, 250, 252)))
                    using (SolidBrush fillNote = new SolidBrush(Color.FromArgb(254, 243, 199)))
                    {
                        g1.FillRectangle(fillBg, x1 + 1, y1 + 1, 16, 17);
                        g1.DrawRectangle(pNavy, x1 + 1, y1 + 1, 16, 17);
                        // Bottom note section highlight
                        g1.FillRectangle(fillNote, x1 + 2, y1 + 10, 14, 7);
                        g1.DrawLine(new Pen(Color.FromArgb(217, 119, 6), 1.3f), x1 + 1, y1 + 10, x1 + 17, y1 + 10);
                        // Eye symbol / Bookmark
                        g1.FillEllipse(new SolidBrush(Color.FromArgb(37, 99, 235)), x1 + 6, y1 + 3, 6, 4);
                        g1.FillEllipse(Brushes.White, x1 + 8, y1 + 4, 2, 2);
                    }
                }, "Hiện chú thích");
                curX += 74;

                g.DrawString("Chú thích", labelFont, Brushes.Gray, curX - 160, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 3. NHÓM: TRÍCH DẪN & TÀI LIỆU THAM KHẢO
                // ==========================================
                // 3.1 Chèn Trích dẫn (Insert Citation)
                DrawVectorToolBtnLarge(g, curX, 68, 74, 60, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(30, 58, 138), 1.4f))
                    using (SolidBrush fillParchment = new SolidBrush(Color.FromArgb(254, 243, 199)))
                    using (SolidBrush fillSpine = new SolidBrush(Color.FromArgb(30, 58, 138)))
                    {
                        // Open book pages
                        PointF[] leftPage = new PointF[] { new PointF(x1 + 1, y1 + 3), new PointF(x1 + 9, y1 + 1), new PointF(x1 + 9, y1 + 17), new PointF(x1 + 1, y1 + 18) };
                        PointF[] rightPage = new PointF[] { new PointF(x1 + 9, y1 + 1), new PointF(x1 + 17, y1 + 3), new PointF(x1 + 17, y1 + 18), new PointF(x1 + 9, y1 + 17) };
                        g1.FillPolygon(fillParchment, leftPage);
                        g1.DrawPolygon(pNavy, leftPage);
                        g1.FillPolygon(fillParchment, rightPage);
                        g1.DrawPolygon(pNavy, rightPage);
                        // Spine center seam
                        g1.DrawLine(new Pen(Color.FromArgb(217, 119, 6), 1.5f), x1 + 9, y1 + 1, x1 + 9, y1 + 17);
                        // Gold Quote mark
                        using (Font qFont = new Font("Georgia", 8.5f, FontStyle.Bold))
                        {
                            g1.DrawString("“", qFont, new SolidBrush(Color.FromArgb(217, 119, 6)), x1 + 2, y1 + 2);
                        }
                    }
                }, "Trích dẫn ▾");
                curX += 78;

                // 3.2 Quản lý nguồn & Kiểu trích dẫn
                string activeCitStyle = (writerView != null && !string.IsNullOrEmpty(writerView.CurrentCitationStyle)) ? writerView.CurrentCitationStyle : "APA";
                DrawVectorBtn(g, curX, 68, 128, 28, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.4f))
                    using (SolidBrush fillCard = new SolidBrush(Color.FromArgb(239, 246, 255)))
                    {
                        // Library card catalog drawer
                        g1.FillRectangle(fillCard, x1, y1 + 2, 14, 11);
                        g1.DrawRectangle(pNavy, x1, y1 + 2, 14, 11);
                        // Color classification tags
                        g1.FillRectangle(new SolidBrush(Color.FromArgb(16, 185, 129)), x1 + 2, y1 + 4, 3, 2);
                        g1.FillRectangle(new SolidBrush(Color.FromArgb(245, 158, 11)), x1 + 6, y1 + 4, 3, 2);
                        g1.FillRectangle(new SolidBrush(Color.FromArgb(239, 68, 68)), x1 + 10, y1 + 4, 3, 2);
                        g1.DrawLine(pNavy, x1 + 2, y1 + 8, x1 + 12, y1 + 8);
                    }
                }, "Quản lý nguồn");
                DrawVectorBtn(g, curX, 98, 128, 28, (g1, x1, y1) => {
                    using (Font qFont = new Font("Georgia", 9.0f, FontStyle.Bold))
                    {
                        g1.DrawString("“ ”", qFont, new SolidBrush(Color.FromArgb(217, 119, 6)), x1 - 2, y1 - 2);
                    }
                }, "Kiểu: " + activeCitStyle + " ▾");
                curX += 134;

                // 3.3 Thư mục tài liệu tham khảo (Bibliography)
                DrawVectorToolBtnLarge(g, curX, 68, 70, 60, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(30, 58, 138), 1.3f))
                    using (SolidBrush fillBook1 = new SolidBrush(Color.FromArgb(37, 99, 235)))
                    using (SolidBrush fillBook2 = new SolidBrush(Color.FromArgb(16, 185, 129)))
                    using (SolidBrush fillBook3 = new SolidBrush(Color.FromArgb(245, 158, 11)))
                    {
                        // Stacked luxury hardcover book spines with gold bands
                        g1.FillRectangle(fillBook1, x1 + 1, y1 + 13, 16, 4);
                        g1.DrawRectangle(pNavy, x1 + 1, y1 + 13, 16, 4);
                        g1.DrawLine(new Pen(Color.FromArgb(254, 243, 199), 1.2f), x1 + 4, y1 + 13, x1 + 4, y1 + 17);

                        g1.FillRectangle(fillBook2, x1 + 3, y1 + 8, 14, 4);
                        g1.DrawRectangle(pNavy, x1 + 3, y1 + 8, 14, 4);
                        g1.DrawLine(new Pen(Color.FromArgb(254, 243, 199), 1.2f), x1 + 6, y1 + 8, x1 + 6, y1 + 12);

                        g1.FillRectangle(fillBook3, x1 + 2, y1 + 3, 15, 4);
                        g1.DrawRectangle(pNavy, x1 + 2, y1 + 3, 15, 4);
                        g1.DrawLine(new Pen(Color.FromArgb(254, 243, 199), 1.2f), x1 + 5, y1 + 3, x1 + 5, y1 + 7);
                    }
                }, "Thư mục ▾");
                curX += 76;

                g.DrawString("Trích dẫn & Nguồn", labelFont, Brushes.Gray, curX - 190, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 4. NHÓM: PHỤ ĐỀ & BẢNG BIỂU (Captions)
                // ==========================================
                // 4.1 Chèn Phụ đề (Insert Caption)
                DrawVectorToolBtnLarge(g, curX, 68, 70, 60, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(30, 58, 138), 1.5f))
                    using (SolidBrush fillBg = new SolidBrush(Color.FromArgb(240, 249, 255)))
                    {
                        g1.FillRectangle(fillBg, x1 + 1, y1 + 1, 16, 12);
                        g1.DrawRectangle(pNavy, x1 + 1, y1 + 1, 16, 12);
                        // Golden Sun
                        g1.FillEllipse(new SolidBrush(Color.FromArgb(245, 158, 11)), x1 + 4, y1 + 4, 3, 3);
                        // Emerald Mountain
                        PointF[] mtn = new PointF[] { new PointF(x1 + 3, y1 + 11), new PointF(x1 + 7, y1 + 5), new PointF(x1 + 11, y1 + 11) };
                        g1.FillPolygon(new SolidBrush(Color.FromArgb(16, 185, 129)), mtn);
                        // Caption bar with tag
                        g1.FillRectangle(new SolidBrush(Color.FromArgb(219, 234, 254)), x1 + 1, y1 + 14, 16, 4);
                        g1.DrawRectangle(new Pen(Color.FromArgb(37, 99, 235), 1.2f), x1 + 1, y1 + 14, 16, 4);
                    }
                }, "Chèn Phụ đề");
                curX += 74;

                // 4.2 Bảng hình ảnh & Cập nhật bảng hình ảnh
                DrawVectorBtn(g, curX, 68, 132, 28, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.4f))
                    using (SolidBrush fillBg = new SolidBrush(Color.FromArgb(248, 250, 252)))
                    {
                        g1.FillRectangle(fillBg, x1, y1 + 2, 13, 11);
                        g1.DrawRectangle(pNavy, x1, y1 + 2, 13, 11);
                        g1.FillRectangle(new SolidBrush(Color.FromArgb(56, 189, 248)), x1 + 2, y1 + 4, 3, 3);
                        g1.DrawLine(pNavy, x1 + 6, y1 + 5, x1 + 11, y1 + 5);
                        g1.DrawLine(pNavy, x1 + 2, y1 + 9, x1 + 11, y1 + 9);
                    }
                }, "Chèn bảng hình");
                DrawVectorBtn(g, curX, 98, 132, 28, (g1, x1, y1) => {
                    using (Pen pTeal = new Pen(Color.FromArgb(13, 148, 136), 1.5f))
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.2f))
                    {
                        g1.DrawRectangle(pNavy, x1, y1 + 2, 13, 11);
                        g1.DrawArc(pTeal, x1 + 3, y1 + 4, 7, 7, 30, 270);
                        g1.DrawLine(pTeal, x1 + 8, y1 + 4, x1 + 10, y1 + 6);
                    }
                }, "Cập nhật bảng hình");
                curX += 138;

                // 4.3 Tham chiếu chéo (Cross Reference)
                DrawVectorToolBtnLarge(g, curX, 68, 72, 60, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.5f))
                    using (Pen pGreen = new Pen(Color.FromArgb(16, 185, 129), 1.5f))
                    using (SolidBrush fillBg = new SolidBrush(Color.FromArgb(240, 253, 244)))
                    {
                        g1.FillRectangle(fillBg, x1 + 2, y1 + 2, 14, 14);
                        g1.DrawRectangle(pGreen, x1 + 2, y1 + 2, 14, 14);
                        // Interlocking link chain
                        g1.DrawLine(pNavy, x1 + 4, y1 + 9, x1 + 14, y1 + 9);
                        g1.DrawLine(pNavy, x1 + 9, y1 + 4, x1 + 9, y1 + 14);
                        g1.DrawLine(new Pen(Color.FromArgb(245, 158, 11), 1.8f), x1 + 4, y1 + 4, x1 + 14, y1 + 14);
                    }
                }, "Tham chiếu chéo");
                curX += 78;

                g.DrawString("Phụ đề & Bảng", labelFont, Brushes.Gray, curX - 165, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 5. NHÓM: CHỈ MỤC TÀI LIỆU (Index)
                // ==========================================
                DrawVectorBtn(g, curX, 68, 122, 28, (g1, x1, y1) => {
                    using (Pen pAmber = new Pen(Color.FromArgb(217, 119, 6), 1.5f))
                    using (SolidBrush fillTag = new SolidBrush(Color.FromArgb(254, 243, 199)))
                    {
                        PointF[] tag = new PointF[] { new PointF(x1 + 1, y1 + 4), new PointF(x1 + 7, y1 + 4), new PointF(x1 + 12, y1 + 9), new PointF(x1 + 8, y1 + 13), new PointF(x1 + 1, y1 + 13) };
                        g1.FillPolygon(fillTag, tag);
                        g1.DrawPolygon(pAmber, tag);
                        g1.FillEllipse(Brushes.DarkOrange, x1 + 3, y1 + 6, 2, 2);
                    }
                }, "Đánh dấu mục");
                DrawVectorBtn(g, curX, 98, 122, 28, (g1, x1, y1) => {
                    using (Font aFont = new Font("Segoe UI", 8.0f, FontStyle.Bold))
                    {
                        g1.DrawString("A-Z", aFont, new SolidBrush(Color.FromArgb(37, 99, 235)), x1 - 1, y1 + 1);
                    }
                }, "Chèn chỉ mục");
                curX += 126;

                // 5.3 Cập nhật chỉ mục (Update Index)
                DrawVectorToolBtnLarge(g, curX, 68, 68, 60, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.4f))
                    using (SolidBrush fillBg = new SolidBrush(Color.FromArgb(248, 250, 252)))
                    using (Pen pEmerald = new Pen(Color.FromArgb(16, 185, 129), 1.6f))
                    {
                        g1.FillRectangle(fillBg, x1 + 1, y1 + 1, 16, 17);
                        g1.DrawRectangle(pNavy, x1 + 1, y1 + 1, 16, 17);
                        g1.DrawString("Z", new Font("Segoe UI", 6.5f, FontStyle.Bold), new SolidBrush(Color.FromArgb(37, 99, 235)), x1 + 2, y1 + 1);
                        g1.DrawArc(pEmerald, x1 + 5, y1 + 7, 9, 8, 30, 270);
                        g1.DrawLine(pEmerald, x1 + 12, y1 + 8, x1 + 14, y1 + 10);
                    }
                }, "Cập nhật mục");
                curX += 74;

                g.DrawString("Chỉ mục", labelFont, Brushes.Gray, curX - 110, 137);
            }
        }

        private void DrawTabHienThi(Graphics g, int width, WriterView writerView = null)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                int curX = 14;

                // ==========================================
                // 1. NHÓM: CHẾ ĐỘ XEM (Views)
                // ==========================================
                int viewMode = writerView != null ? writerView.ViewMode : 1;
                // 1.1 Bố trí In (Print Layout)
                DrawVectorToolBtnLarge(g, curX, 68, 66, 60, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.5f))
                    using (SolidBrush fillBg = new SolidBrush(Color.FromArgb(248, 250, 252)))
                    {
                        // Drop shadow
                        g1.FillRectangle(new SolidBrush(Color.FromArgb(203, 213, 225)), x1 + 4, y1 + 3, 14, 17);
                        g1.FillRectangle(fillBg, x1 + 2, y1 + 1, 14, 17);
                        g1.DrawRectangle(pNavy, x1 + 2, y1 + 1, 14, 17);
                        // Margin guideline dotted frame
                        g1.DrawRectangle(new Pen(Color.FromArgb(148, 163, 184), 1.0f) { DashStyle = DashStyle.Dot }, x1 + 5, y1 + 4, 8, 11);
                    }
                }, "Bố trí In", viewMode == 1);
                curX += 70;

                // 1.2 Chế độ Đọc (Read Mode)
                DrawVectorToolBtnLarge(g, curX, 68, 66, 60, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.5f))
                    using (SolidBrush fillBg = new SolidBrush(Color.FromArgb(241, 245, 249)))
                    {
                        // Open book pages
                        g1.FillRectangle(fillBg, x1, y1 + 2, 8, 15);
                        g1.DrawRectangle(pNavy, x1, y1 + 2, 8, 15);
                        g1.FillRectangle(fillBg, x1 + 9, y1 + 2, 8, 15);
                        g1.DrawRectangle(pNavy, x1 + 9, y1 + 2, 8, 15);
                        g1.DrawLine(new Pen(Color.FromArgb(100, 116, 139), 1.2f), x1 + 2, y1 + 6, x1 + 6, y1 + 6);
                        g1.DrawLine(new Pen(Color.FromArgb(100, 116, 139), 1.2f), x1 + 2, y1 + 10, x1 + 6, y1 + 10);
                        g1.DrawLine(new Pen(Color.FromArgb(100, 116, 139), 1.2f), x1 + 11, y1 + 6, x1 + 15, y1 + 6);
                        g1.DrawLine(new Pen(Color.FromArgb(100, 116, 139), 1.2f), x1 + 11, y1 + 10, x1 + 15, y1 + 10);
                    }
                }, "Chế độ Đọc", viewMode == 0);
                curX += 70;

                // 1.3 Bố trí Web (Web Layout)
                DrawVectorToolBtnLarge(g, curX, 68, 66, 60, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.5f))
                    using (SolidBrush fillBg = new SolidBrush(Color.FromArgb(248, 250, 252)))
                    {
                        g1.FillRectangle(fillBg, x1 + 1, y1 + 2, 16, 14);
                        g1.DrawRectangle(pNavy, x1 + 1, y1 + 2, 16, 14);
                        g1.FillRectangle(new SolidBrush(Color.FromArgb(37, 99, 235)), x1 + 1, y1 + 2, 16, 4);
                        g1.DrawLine(new Pen(Color.FromArgb(16, 185, 129), 1.2f), x1 + 3, y1 + 9, x1 + 13, y1 + 9);
                        g1.DrawLine(new Pen(Color.FromArgb(100, 116, 139), 1.2f), x1 + 3, y1 + 12, x1 + 10, y1 + 12);
                    }
                }, "Bố trí Web", viewMode == 2);
                curX += 70;

                // 1.4 Cấu trúc (Outline) & Bản nháp (Draft)
                DrawVectorBtn(g, curX, 68, 106, 28, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.5f))
                    {
                        g1.FillEllipse(new SolidBrush(Color.FromArgb(37, 99, 235)), x1 + 1, y1 + 4, 3, 3);
                        g1.DrawLine(pNavy, x1 + 6, y1 + 5, x1 + 12, y1 + 5);
                        g1.FillEllipse(new SolidBrush(Color.FromArgb(37, 99, 235)), x1 + 3, y1 + 9, 3, 3);
                        g1.DrawLine(pNavy, x1 + 8, y1 + 10, x1 + 13, y1 + 10);
                    }
                }, "Đề cương");
                DrawVectorBtn(g, curX, 98, 106, 28, (g1, x1, y1) => {
                    using (Pen pSlate = new Pen(Color.FromArgb(100, 116, 139), 1.4f))
                    {
                        g1.DrawRectangle(pSlate, x1 + 1, y1 + 2, 12, 13);
                        g1.DrawLine(pSlate, x1 + 3, y1 + 5, x1 + 9, y1 + 5);
                        g1.DrawLine(pSlate, x1 + 3, y1 + 8, x1 + 9, y1 + 8);
                    }
                }, "Bản nháp");
                curX += 110;

                // 1.5 Tập trung (Immersive Focus Mode)
                DrawVectorToolBtnLarge(g, curX, 68, 66, 60, (g1, x1, y1) => {
                    using (Pen pGold = new Pen(Color.FromArgb(245, 158, 11), 1.5f))
                    using (SolidBrush fillBg = new SolidBrush(Color.FromArgb(254, 243, 199)))
                    {
                        g1.FillRectangle(fillBg, x1 + 2, y1 + 2, 14, 14);
                        g1.DrawRectangle(pGold, x1 + 2, y1 + 2, 14, 14);
                        // Focus target diamond
                        PointF[] diamond = new PointF[] { new PointF(x1 + 9, y1 + 5), new PointF(x1 + 13, y1 + 9), new PointF(x1 + 9, y1 + 13), new PointF(x1 + 5, y1 + 9) };
                        g1.FillPolygon(new SolidBrush(Color.FromArgb(245, 158, 11)), diamond);
                        g1.FillEllipse(Brushes.White, x1 + 8, y1 + 8, 2, 2);
                    }
                }, "Tập trung");
                curX += 72;

                g.DrawString("Chế độ xem", labelFont, Brushes.Gray, curX - 250, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 2. NHÓM: HIỂN THỊ (Show)
                // ==========================================
                // 2.1 Thước kẻ (Ruler)
                DrawVectorToolBtnLarge(g, curX, 68, 64, 60, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(ShowRuler ? Color.FromArgb(37, 99, 235) : Color.FromArgb(71, 85, 105), 1.5f))
                    using (SolidBrush fillBg = new SolidBrush(ShowRuler ? Color.FromArgb(239, 246, 255) : Color.FromArgb(248, 250, 252)))
                    {
                        g1.FillRectangle(fillBg, x1, y1 + 4, 18, 10);
                        g1.DrawRectangle(pNavy, x1, y1 + 4, 18, 10);
                        g1.DrawLine(pNavy, x1 + 3, y1 + 4, x1 + 3, y1 + 8);
                        g1.DrawLine(pNavy, x1 + 7, y1 + 4, x1 + 7, y1 + 6);
                        g1.DrawLine(pNavy, x1 + 11, y1 + 4, x1 + 11, y1 + 8);
                        g1.DrawLine(pNavy, x1 + 15, y1 + 4, x1 + 15, y1 + 6);
                    }
                }, "Thước kẻ", ShowRuler);
                curX += 68;

                // 2.2 Đơn vị đo (cm / inch) & Đường lưới (Gridlines)
                string unitTag = (writerView != null && writerView.CurrentRulerUnit == RulerUnit.Inches) ? "Đơn vị: inch" : "Đơn vị: cm";
                DrawVectorBtn(g, curX, 68, 118, 28, (g1, x1, y1) => {
                    using (Font uFont = new Font("Segoe UI", 8.0f, FontStyle.Bold))
                    using (SolidBrush fillBg = new SolidBrush(Color.FromArgb(240, 249, 255)))
                    using (Pen borderP = new Pen(Color.FromArgb(56, 189, 248), 1.2f))
                    {
                        g1.FillRectangle(fillBg, x1, y1 + 1, 14, 13);
                        g1.DrawRectangle(borderP, x1, y1 + 1, 14, 13);
                        string tag = (writerView != null && writerView.CurrentRulerUnit == RulerUnit.Inches) ? "in" : "cm";
                        g1.DrawString(tag, uFont, new SolidBrush(Color.FromArgb(2, 132, 199)), x1 + 1, y1);
                    }
                }, unitTag);
                DrawVectorBtn(g, curX, 98, 118, 28, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(ShowGridlines ? Color.FromArgb(37, 99, 235) : Color.FromArgb(71, 85, 105), 1.2f) { DashStyle = DashStyle.Dash })
                    using (SolidBrush fillBg = new SolidBrush(ShowGridlines ? Color.FromArgb(239, 246, 255) : Color.White))
                    {
                        g1.FillRectangle(fillBg, x1, y1 + 2, 14, 12);
                        g1.DrawRectangle(Pens.LightGray, x1, y1 + 2, 14, 12);
                        g1.DrawLine(pNavy, x1 + 5, y1 + 2, x1 + 5, y1 + 14);
                        g1.DrawLine(pNavy, x1 + 9, y1 + 2, x1 + 9, y1 + 14);
                        g1.DrawLine(pNavy, x1, y1 + 6, x1 + 14, y1 + 6);
                        g1.DrawLine(pNavy, x1, y1 + 10, x1 + 14, y1 + 10);
                    }
                }, "Đường lưới", ShowGridlines);
                curX += 122;

                // 2.3 Ngăn Điều hướng (Navigation Pane)
                bool showNav = (writerView != null && writerView.ShowNavigationPane);
                DrawVectorToolBtnLarge(g, curX, 68, 68, 60, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(showNav ? Color.FromArgb(37, 99, 235) : Color.FromArgb(71, 85, 105), 1.4f))
                    using (SolidBrush fillBg = new SolidBrush(showNav ? Color.FromArgb(191, 219, 254) : Color.FromArgb(226, 232, 240)))
                    {
                        g1.DrawRectangle(pNavy, x1, y1 + 2, 18, 14);
                        g1.FillRectangle(fillBg, x1 + 1, y1 + 3, 6, 12);
                        g1.DrawLine(pNavy, x1 + 7, y1 + 2, x1 + 7, y1 + 16);
                    }
                }, "Điều hướng", showNav);
                curX += 72;

                g.DrawString("Hiển thị", labelFont, Brushes.Gray, curX - 180, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 3. NHÓM: THU PHÓNG (Zoom)
                // ==========================================
                // 3.1 100% Zoom
                float curZoom = writerView != null ? writerView.ZoomLevel : 1.0f;
                DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.5f))
                    using (Font zFont = new Font("Segoe UI", 7.0f, FontStyle.Bold))
                    {
                        g1.DrawEllipse(pNavy, x1 + 1, y1 + 1, 14, 14);
                        g1.DrawLine(pNavy, x1 + 12, y1 + 12, x1 + 17, y1 + 17);
                        g1.DrawString("100", zFont, new SolidBrush(Color.FromArgb(37, 99, 235)), x1 + 1, y1 + 2);
                    }
                }, "100%", Math.Abs(curZoom - 1.0f) < 0.05f);
                curX += 66;

                // 3.2 Một trang & Nhiều trang
                DrawVectorBtn(g, curX, 68, 112, 28, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.4f))
                    using (SolidBrush fillBg = new SolidBrush(Color.FromArgb(241, 245, 249)))
                    {
                        g1.FillRectangle(fillBg, x1 + 2, y1 + 2, 10, 13);
                        g1.DrawRectangle(pNavy, x1 + 2, y1 + 2, 10, 13);
                    }
                }, "Một trang");
                DrawVectorBtn(g, curX, 98, 112, 28, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.2f))
                    {
                        g1.DrawRectangle(pNavy, x1, y1 + 2, 6, 12);
                        g1.DrawRectangle(pNavy, x1 + 8, y1 + 2, 6, 12);
                    }
                }, "Nhiều trang");
                curX += 116;

                // 3.3 Độ rộng trang & Thu phóng tự do
                DrawVectorBtn(g, curX, 68, 116, 28, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(Color.FromArgb(37, 99, 235), 1.5f))
                    using (Pen pRed = new Pen(Color.FromArgb(220, 38, 38), 1.5f))
                    {
                        g1.DrawRectangle(pNavy, x1 + 2, y1 + 3, 11, 11);
                        g1.DrawLine(pRed, x1 - 1, y1 + 8, x1 + 16, y1 + 8);
                        g1.DrawLine(pRed, x1 + 1, y1 + 6, x1 - 1, y1 + 8);
                        g1.DrawLine(pRed, x1 + 1, y1 + 10, x1 - 1, y1 + 8);
                        g1.DrawLine(pRed, x1 + 14, y1 + 6, x1 + 16, y1 + 8);
                        g1.DrawLine(pRed, x1 + 14, y1 + 10, x1 + 16, y1 + 8);
                    }
                }, "Độ rộng trang");
                DrawVectorBtn(g, curX, 98, 116, 28, (g1, x1, y1) => {
                    using (Pen pAmber = new Pen(Color.FromArgb(217, 119, 6), 1.5f))
                    {
                        g1.DrawEllipse(pAmber, x1 + 1, y1 + 2, 10, 10);
                        g1.DrawLine(pAmber, x1 + 8, y1 + 9, x1 + 13, y1 + 14);
                        g1.DrawLine(pAmber, x1 + 6, y1 + 4, x1 + 6, y1 + 10);
                        g1.DrawLine(pAmber, x1 + 3, y1 + 7, x1 + 9, y1 + 7);
                    }
                }, "Thu phóng ▾");
                curX += 122;

                g.DrawString("Thu phóng", labelFont, Brushes.Gray, curX - 200, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 4. NHÓM: NỀN & MÀU TRANG (Canvas Theme)
                // ==========================================
                DrawVectorToolBtnLarge(g, curX, 68, 72, 60, (g1, x1, y1) => {
                    // Easel palette with 4 luxury color swatches
                    g1.FillRectangle(Brushes.White, x1 + 1, y1 + 1, 7, 7);
                    g1.DrawRectangle(Pens.Gray, x1 + 1, y1 + 1, 7, 7);

                    g1.FillRectangle(new SolidBrush(Color.FromArgb(253, 246, 226)), x1 + 10, y1 + 1, 7, 7);
                    g1.DrawRectangle(new Pen(Color.FromArgb(217, 119, 6), 1.0f), x1 + 10, y1 + 1, 7, 7);

                    g1.FillRectangle(new SolidBrush(Color.FromArgb(51, 65, 85)), x1 + 1, y1 + 10, 7, 7);
                    g1.DrawRectangle(Pens.DarkSlateGray, x1 + 1, y1 + 10, 7, 7);

                    g1.FillRectangle(new SolidBrush(Color.FromArgb(30, 30, 30)), x1 + 10, y1 + 10, 7, 7);
                    g1.DrawRectangle(Pens.Black, x1 + 10, y1 + 10, 7, 7);
                }, "Màu trang ▾");
                curX += 76;

                g.DrawString("Nền trang", labelFont, Brushes.Gray, curX - 60, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==========================================
                // 5. NHÓM: CỬA SỔ & NGĂN (Window & Panes)
                // ==========================================
                bool showSel = (writerView != null && writerView.ShowSelectionPane);
                DrawVectorToolBtnLarge(g, curX, 68, 68, 60, (g1, x1, y1) => {
                    using (Pen pNavy = new Pen(showSel ? Color.FromArgb(37, 99, 235) : Color.FromArgb(71, 85, 105), 1.4f))
                    using (SolidBrush fillBg = new SolidBrush(showSel ? Color.FromArgb(254, 215, 170) : Color.FromArgb(241, 245, 249)))
                    {
                        g1.FillRectangle(fillBg, x1 + 2, y1 + 1, 14, 16);
                        g1.DrawRectangle(pNavy, x1 + 2, y1 + 1, 14, 16);
                        // Layer stripes
                        g1.DrawLine(new Pen(Color.FromArgb(37, 99, 235), 1.5f), x1 + 5, y1 + 5, x1 + 13, y1 + 5);
                        g1.DrawLine(new Pen(Color.FromArgb(16, 185, 129), 1.5f), x1 + 5, y1 + 9, x1 + 13, y1 + 9);
                        g1.DrawLine(new Pen(Color.FromArgb(245, 158, 11), 1.5f), x1 + 5, y1 + 13, x1 + 13, y1 + 13);
                    }
                }, "Lựa chọn", showSel);
                curX += 72;

