        private void DrawTabEquation(Graphics g, int width, WriterView writerView)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.0f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            using (Font mathSymFont = new Font("Cambria Math", 10.0f, FontStyle.Bold))
            using (Pen iconPen = new Pen(Color.FromArgb(45, 55, 72), 1.8f))
            {
                g.SmoothingMode = SmoothingMode.HighQuality;
                int curX = 14;

                // 1. Nhóm Công cụ (Tools)
                DrawVectorToolBtnLarge(g, curX, 68, 64, 60, (g1, x1, y1) => {
                    using (Font piF = new Font("Segoe UI", 13.0f, FontStyle.Bold)) g1.DrawString("π", piF, Brushes.DarkBlue, x1 + 2, y1);
                }, "Công thức ▾");
                curX += 68;

                DrawVectorToolBtnLarge(g, curX, 68, 60, 60, (g1, x1, y1) => {
                    using (Font penF = new Font("Segoe UI", 12.0f)) g1.DrawString("✎", penF, Brushes.SteelBlue, x1, y1);
                }, "Viết tay");
                curX += 66;

                g.DrawString("Công cụ", labelFont, Brushes.Gray, curX - 100, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 2. Nhóm Ký hiệu toán học (Math Symbols Palette: 2 rows of 16 buttons = 32 math symbols)
                string[] mSymbols = new string[] {
                    "±", "∞", "=", "≠", "~", "×", "÷", "!", "∝", "<", "≪", ">", "≫", "≤", "≥", "∓",
                    "≅", "≈", "≡", "∀", "∂", "∃", "∇", "∈", "∉", "∋", "∏", "∑", "√", "∛", "∫", "π"
                };

                for (int si = 0; si < mSymbols.Length; si++)
                {
                    int r = si / 16;
                    int c = si % 16;
                    int sx = curX + c * 22;
                    int sy = 70 + r * 28;
                    Rectangle sBox = new Rectangle(sx, sy, 20, 26);

                    DrawInteractiveButton(g, sBox, false, 2);
                    SizeF msz = g.MeasureString(mSymbols[si], mathSymFont);
                    g.DrawString(mSymbols[si], mathSymFont, Brushes.Navy, sx + (20 - msz.Width) / 2, sy + (26 - msz.Height) / 2);
                }
                curX += 16 * 22 + 6;

                g.DrawString("Ký hiệu toán học", labelFont, Brushes.Gray, curX - 220, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // 3. Nhóm Cấu trúc công thức (Structures)
                string[] structNames = new string[] { "Phân số ▾", "Chỉ số ▾", "Căn thức ▾", "Tích phân ▾", "Toán tử ▾", "Dấu ngoặc ▾", "Hàm số ▾", "Trọng âm ▾", "Giới hạn ▾", "Ma trận ▾" };
                string[] structIcons = new string[] { "x/y", "eˣ", "√x", "∫", "∑", "{}", "sin", "ä", "lim", "[::]" };

                for (int st = 0; st < structNames.Length; st++)
                {
                    Rectangle stBox = new Rectangle(curX, 68, 54, 60);
                    DrawInteractiveButton(g, stBox, false, 3);
                    using (Font ifont = new Font("Cambria Math", 10.0f, FontStyle.Bold))
                    {
                        SizeF isz = g.MeasureString(structIcons[st], ifont);
                        g.DrawString(structIcons[st], ifont, Brushes.Navy, curX + (54 - isz.Width) / 2, 75);
                    }
                    using (Font tf = new Font("Segoe UI", 7.0f, FontStyle.Bold))
                    {
                        g.DrawString(structNames[st], tf, Brushes.Black, curX + 2, 106);
                    }
                    curX += 58;
                }

                g.DrawString("Cấu trúc công thức", labelFont, Brushes.Gray, curX - 340, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 14;

                // 4. Nhóm Đóng Công thức
                Rectangle closeBox = new Rectangle(curX, 68, 115, 62);
                using (SolidBrush redBrush = new SolidBrush(Color.FromArgb(195, 25, 25)))
                {
                    FillRoundedRectangle(g, redBrush, closeBox, 4);
                }
                using (Pen redPen = new Pen(Color.White, 2.5f))
                {
                    g.DrawLine(redPen, curX + 48, 73, curX + 66, 91);
                    g.DrawLine(redPen, curX + 66, 73, curX + 48, 91);
                }
                g.DrawString("Đóng Công thức", boldFont, Brushes.White, curX + 10, 96);
            }
        }

        private void DrawToolBtn(Graphics g, int x, int y, int w, int h, string icon, string title, string groupName)
        {
            Rectangle box = new Rectangle(x, y, w, h);
