        private void DrawExcelTableVector(Graphics g, int x, int y, int w, int h)
        {
            using (SolidBrush bBg = new SolidBrush(Color.White)) g.FillRectangle(bBg, x, y, w, h);
            // Blue header row
            using (SolidBrush bHdr = new SolidBrush(Color.FromArgb(31, 78, 120)))
            {
                g.FillRectangle(bHdr, x, y, w, 6);
            }
            // Alternating light blue rows
            using (SolidBrush bAlt = new SolidBrush(Color.FromArgb(222, 235, 247)))
            {
                g.FillRectangle(bAlt, x, y + 6, w, 5);
                g.FillRectangle(bAlt, x, y + 16, w, 4);
            }
            using (Pen p = new Pen(Color.FromArgb(176, 196, 222), 1.0f))
            {
                using (Pen pBorder = new Pen(Color.FromArgb(31, 78, 120), 1.2f))
                {
                    g.DrawRectangle(pBorder, x, y, w, h);
                }
                g.DrawLine(p, x + w / 3, y + 6, x + w / 3, y + h);
                g.DrawLine(p, x + (w * 2) / 3, y + 6, x + (w * 2) / 3, y + h);
                g.DrawLine(p, x, y + 11, x + w, y + 11);
                g.DrawLine(p, x, y + 16, x + w, y + 16);
            }
            // Dots in header row
            using (SolidBrush wDot = new SolidBrush(Color.White))
            {
                g.FillEllipse(wDot, x + 3, y + 2, 2, 2);
                g.FillEllipse(wDot, x + w / 3 + 3, y + 2, 2, 2);
                g.FillEllipse(wDot, x + (w * 2) / 3 + 3, y + 2, 2, 2);
            }
        }

