        private void Draw3DModelVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.3f))
            {
                int cx = x + w / 2;
                int cy = y + h / 2;
                Point[] topPts = new Point[] { new Point(cx, y + 1), new Point(x + w - 2, y + h / 3), new Point(cx, cy), new Point(x + 2, y + h / 3) };
                g.DrawPolygon(p, topPts);
                g.DrawLine(p, cx, cy, cx, y + h - 1);
                g.DrawLine(p, x + 2, y + h / 3, x + 2, y + h * 2 / 3);
                g.DrawLine(p, x + w - 2, y + h / 3, x + w - 2, y + h * 2 / 3);
                g.DrawLine(p, x + 2, y + h * 2 / 3, cx, y + h - 1);
                g.DrawLine(p, x + w - 2, y + h * 2 / 3, cx, y + h - 1);
            }
        }

