        private void DrawCommentVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.3f))
            using (SolidBrush bg = new SolidBrush(Color.FromArgb(240, 253, 250)))
            {
                GraphicsPath path = new GraphicsPath();
                path.AddLine(x + 2, y + 2, x + w - 2, y + 2);
                path.AddLine(x + w - 2, y + 2, x + w - 2, y + h - 7);
                path.AddLine(x + w - 2, y + h - 7, x + 10, y + h - 7);
                path.AddLine(x + 10, y + h - 7, x + 4, y + h - 1);
                path.AddLine(x + 4, y + h - 1, x + 6, y + h - 7);
                path.AddLine(x + 6, y + h - 7, x + 2, y + h - 7);
                path.CloseFigure();
                g.FillPath(bg, path);
                g.DrawPath(p, path);
                g.DrawLine(p, x + 5, y + 5, x + w - 5, y + 5);
                g.DrawLine(p, x + 5, y + 8, x + w - 8, y + 8);
            }
        }

        private void DrawTextBoxVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.2f))
            {
                p.DashStyle = DashStyle.Dash;
                g.DrawRectangle(p, x + 1, y + 1, w - 2, h - 2);
            }
            using (Font f = new Font("Segoe UI", 10.5f, FontStyle.Bold))
            using (SolidBrush b = new SolidBrush(col))
            {
                g.DrawString("A", f, b, x + 4, y - 1);
            }
        }

        private void DrawHeaderFooterVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.2f))
            using (SolidBrush b = new SolidBrush(col))
            {
                g.DrawRectangle(p, x + 2, y + 1, w - 4, h - 2);
                g.FillRectangle(b, x + 4, y + 3, w - 8, 3);
                g.FillRectangle(b, x + 4, y + h - 6, w - 8, 3);
            }
        }

        private void DrawEquationVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Font f = new Font("Cambria Math", 11f, FontStyle.Bold))
            using (SolidBrush b = new SolidBrush(col))
            {
                g.DrawString("π", f, b, x + 2, y - 2);
            }
            using (Pen p = new Pen(col, 1.3f))
            {
                g.DrawLine(p, x + 12, y + 12, x + 14, y + 6);
                g.DrawLine(p, x + 14, y + 6, x + 20, y + 6);
            }
        }

        private void DrawVideoVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.2f))
            using (SolidBrush b = new SolidBrush(col))
            {
                g.DrawRectangle(p, x + 1, y + 3, w - 2, h - 6);
                Point[] tri = new Point[] {
                    new Point(x + w / 2 - 2, y + h / 2 - 4),
                    new Point(x + w / 2 + 5, y + h / 2),
                    new Point(x + w / 2 - 2, y + h / 2 + 4)
                };
                g.FillPolygon(b, tri);
            }
        }

        private void DrawAudioVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.3f))
            using (SolidBrush b = new SolidBrush(col))
            {
                Point[] spk = new Point[] {
                    new Point(x + 3, y + h / 2 - 3),
                    new Point(x + 7, y + h / 2 - 3),
                    new Point(x + 12, y + 3),
                    new Point(x + 12, y + h - 3),
                    new Point(x + 7, y + h / 2 + 3),
                    new Point(x + 3, y + h / 2 + 3)
                };
                g.FillPolygon(b, spk);
                g.DrawArc(p, x + 12, y + 4, 6, h - 8, -60, 120);
                g.DrawArc(p, x + 14, y + 1, 9, h - 2, -60, 120);
            }
        }

        private void DrawScreenRecordVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.2f))
            using (SolidBrush rb = new SolidBrush(Color.FromArgb(239, 68, 68)))
            {
                g.DrawRectangle(p, x + 1, y + 2, w - 8, h - 4);
                Point[] cam = new Point[] {
                    new Point(x + w - 6, y + h / 2),
                    new Point(x + w - 1, y + 4),
                    new Point(x + w - 1, y + h - 4)
                };
                using (SolidBrush b = new SolidBrush(col)) g.FillPolygon(b, cam);
                g.FillEllipse(rb, x + 4, y + 5, 6, 6);
            }
        }
