        private void DrawCalcTabTableDesign(Graphics g, int width, CalcView calcView, ExcelTableInfo tbl)
        {
            if (tbl == null) return;
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.5f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 9f, FontStyle.Bold))
            using (Font grpFont = new Font("Segoe UI", 8f, FontStyle.Bold))
            using (Pen divPen = new Pen(Color.FromArgb(226, 232, 240), 1f))
            {
                // ==================== Group 1: Thuộc tính (Properties) ====================
                g.DrawString("Tên Bảng:", labelFont, Brushes.DimGray, 12, 69);
                Rectangle nameBox = new Rectangle(12, 85, 82, 22);
                using (SolidBrush bgB = new SolidBrush(Color.White))
                using (Pen bPen = new Pen(Color.FromArgb(203, 213, 225), 1f))
                {
                    g.FillRectangle(bgB, nameBox);
                    g.DrawRectangle(bPen, nameBox);
                }
                g.DrawString(tbl.Name ?? "Table1", boldFont, Brushes.Black, 16, 88);

                Rectangle resizeBtn = new Rectangle(12, 110, 82, 22);
                DrawInteractiveButton(g, resizeBtn, false, 3);
                DrawGridIcon(g, 15, 114, 14, 14, Color.FromArgb(16, 124, 65));
