                g.DrawLine(divPen, 102, 68, 102, 150);

                // ==================== Group 2: Công cụ (Tools) ====================
                Rectangle pivotBtn = new Rectangle(110, 69, 146, 20);
                DrawInteractiveButton(g, pivotBtn, false, 3);
                g.DrawString("📊 Tổng hợp PivotTable", btnFont, Brushes.Black, 112, 71);

                Rectangle dupBtn = new Rectangle(110, 91, 146, 20);
                DrawInteractiveButton(g, dupBtn, false, 3);
                g.DrawString("🗑 Xóa mục trùng lặp", btnFont, Brushes.Black, 112, 93);

                Rectangle rangeBtn = new Rectangle(110, 113, 146, 20);
                DrawInteractiveButton(g, rangeBtn, false, 3);
                g.DrawString("⊞ Chuyển thành Vùng ô", btnFont, Brushes.Black, 112, 115);

                g.DrawString("Công cụ", grpFont, Brushes.DimGray, 160, 137);
                g.DrawLine(divPen, 262, 68, 262, 150);

                // ==================== Group 3: Dữ liệu ngoài (External Data) ====================
                Rectangle expBox = new Rectangle(270, 70, 48, 58);
                DrawInteractiveButton(g, expBox, false, 3);
                DrawTableExportIcon(g, 283, 75, 20, 20, Color.FromArgb(79, 70, 229));
                g.DrawString("Xuất bảng ▾", labelFont, Brushes.Black, 268, 105);

                Rectangle refBox = new Rectangle(322, 70, 48, 58);
                DrawInteractiveButton(g, refBox, false, 3);
                DrawTableRefreshIcon(g, 335, 75, 20, 20, Color.FromArgb(16, 124, 65));
                g.DrawString("Làm mới ▾", labelFont, Brushes.Black, 321, 105);

                g.DrawString("Dữ liệu ngoài", grpFont, Brushes.DimGray, 290, 137);
                g.DrawLine(divPen, 376, 68, 376, 150);

                // ==================== Group 4: Tùy chọn Kiểu Bảng ====================
                // Col 1
                DrawTableCheckBox(g, 386, 71, "Dòng tiêu đề", tbl.HasHeaders, btnFont);
                DrawTableCheckBox(g, 386, 93, "Dòng tổng cộng", tbl.HasTotalRow, btnFont);
                DrawTableCheckBox(g, 386, 115, "Dòng xen kẽ", tbl.BandedRows, btnFont);

                // Col 2
                DrawTableCheckBox(g, 490, 71, "Cột đầu tiên", tbl.FirstColumn, btnFont);
                DrawTableCheckBox(g, 490, 93, "Cột cuối cùng", tbl.LastColumn, btnFont);
                DrawTableCheckBox(g, 490, 115, "Cột xen kẽ", tbl.BandedColumns, btnFont);

                // Col 3
                DrawTableCheckBox(g, 594, 71, "Nút lọc dữ liệu", tbl.ShowFilterButtons, btnFont);

                g.DrawString("Tùy chọn Kiểu Bảng", grpFont, Brushes.DimGray, 480, 137);
                g.DrawLine(divPen, 700, 68, 700, 150);

                // ==================== Group 5: Kiểu Bảng (Table Styles) ====================
                int[] styleHeaderColors = new int[] {
                    unchecked((int)0xFFF1F5F9), // 0: Xám sáng
                    unchecked((int)0xFFD97706), // 1: Vàng hổ phách
                    unchecked((int)0xFF0284C7), // 2: Xanh da trời
                    unchecked((int)0xFF16A34A), // 3: Xanh lá cây
                    unchecked((int)0xFF1F2937), // 4: Đen than
                    unchecked((int)0xFF1E40AF)  // 5: Xanh hải quân
                };
                int[] styleZebraColors = new int[] {
                    unchecked((int)0xFFF8FAFC),
                    unchecked((int)0xFFFFFBEB),
                    unchecked((int)0xFFF0F9FF),
                    unchecked((int)0xFFF0FDF4),
                    unchecked((int)0xFFF3F4F6),
                    unchecked((int)0xFFEFF6FF)
                };

                int galX = 710;
                for (int s = 0; s < 6; s++)
                {
                    Rectangle tileRect = new Rectangle(galX, 70, 56, 44);
                    bool isSelectedStyle = (tbl.StyleIndex == s);

                    using (SolidBrush hdrB = new SolidBrush(Color.FromArgb(styleHeaderColors[s])))
                    using (SolidBrush zbB = new SolidBrush(Color.FromArgb(styleZebraColors[s])))
                    using (Pen gridP = new Pen(Color.FromArgb(226, 232, 240), 1f))
                    {
                        g.FillRectangle(Brushes.White, tileRect);
                        g.FillRectangle(hdrB, tileRect.X, tileRect.Y, tileRect.Width, 12);
                        g.FillRectangle(zbB, tileRect.X, tileRect.Y + 22, tileRect.Width, 10);
                        g.DrawLine(gridP, tileRect.X + tileRect.Width / 2, tileRect.Y, tileRect.X + tileRect.Width / 2, tileRect.Bottom);
                        g.DrawLine(gridP, tileRect.X, tileRect.Y + 12, tileRect.Right, tileRect.Y + 12);
                        g.DrawLine(gridP, tileRect.X, tileRect.Y + 22, tileRect.Right, tileRect.Y + 22);
                        g.DrawLine(gridP, tileRect.X, tileRect.Y + 32, tileRect.Right, tileRect.Y + 32);
                    }

                    if (isSelectedStyle)
                    {
                        using (Pen selP = new Pen(Color.FromArgb(16, 124, 65), 2.5f))
                        {
                            g.DrawRectangle(selP, tileRect);
                        }
                    }
                    else
                    {
                        using (Pen bP = new Pen(Color.FromArgb(203, 213, 225), 1f))
                        {
                            g.DrawRectangle(bP, tileRect);
                        }
                    }

                    galX += 62;
                }

                // Up / down arrows for gallery
                Rectangle upBtn = new Rectangle(galX + 4, 70, 16, 21);
                Rectangle dnBtn = new Rectangle(galX + 4, 93, 16, 21);
                DrawInteractiveButton(g, upBtn, false, 2);
                DrawInteractiveButton(g, dnBtn, false, 2);
                g.DrawString("▲", labelFont, Brushes.DimGray, upBtn.X + 2, upBtn.Y + 3);
                g.DrawString("▼", labelFont, Brushes.DimGray, dnBtn.X + 2, dnBtn.Y + 3);

                g.DrawString("Kiểu Bảng", grpFont, Brushes.DimGray, 860, 137);
                g.DrawLine(divPen, galX + 26, 68, galX + 26, 150);
            }
        }

        private void DrawTableCheckBox(Graphics g, int x, int y, string text, bool isChecked, Font font)
        {
            Rectangle box = new Rectangle(x, y + 2, 13, 13);
            using (SolidBrush bg = new SolidBrush(Color.White))
            using (Pen p = new Pen(isChecked ? Color.FromArgb(16, 124, 65) : Color.FromArgb(148, 163, 184), 1.2f))
            {
                g.FillRectangle(bg, box);
                g.DrawRectangle(p, box);
            }
            if (isChecked)
            {
                using (SolidBrush chkBg = new SolidBrush(Color.FromArgb(16, 124, 65)))
                {
                    g.FillRectangle(chkBg, box.X + 2, box.Y + 2, box.Width - 3, box.Height - 3);
                }
                using (Font cf = new Font("Segoe UI", 7f, FontStyle.Bold))
                {
                    g.DrawString("✓", cf, Brushes.White, box.X - 1, box.Y - 1);
                }
            }
            g.DrawString(text, font, Brushes.Black, x + 18, y);
        }

        private void DrawGridIcon(Graphics g, int x, int y, int w, int h, Color color)
        {
            using (Pen p = new Pen(color, 1.2f))
            {
                g.DrawRectangle(p, x, y, w, h);
                g.DrawLine(p, x + w / 2, y, x + w / 2, y + h);
                g.DrawLine(p, x, y + h / 2, x + w, y + h / 2);
            }
        }

        private void DrawTableExportIcon(Graphics g, int x, int y, int w, int h, Color color)
        {
            using (Pen p = new Pen(color, 1.4f))
            {
                g.DrawRectangle(p, x, y, w - 4, h);
                g.DrawLine(p, x + w - 6, y + h / 2, x + w + 2, y + h / 2);
                g.DrawLine(p, x + w - 2, y + h / 2 - 3, x + w + 2, y + h / 2);
                g.DrawLine(p, x + w - 2, y + h / 2 + 3, x + w + 2, y + h / 2);
            }
        }

        private void DrawTableRefreshIcon(Graphics g, int x, int y, int w, int h, Color color)
        {
            using (Pen p = new Pen(color, 1.5f))
            {
                g.DrawArc(p, x, y, w, h, 45, 270);
                g.DrawLine(p, x + w / 2 + 3, y - 2, x + w / 2 + 3, y + 4);
                g.DrawLine(p, x + w / 2 - 3, y + 4, x + w / 2 + 3, y + 4);
            }
        }
