        private void DrawVAlignVector(Graphics g, int x, int y, int size, int vAlign, Color col)
        {
            using (Pen p = new Pen(col, 1.4f))
            {
                if (vAlign == 0) // Top
                {
                    g.DrawLine(p, x, y + 2, x + size, y + 2);
                    g.DrawLine(p, x + 2, y + 6, x + size - 2, y + 6);
                    g.DrawLine(p, x + 2, y + 10, x + size - 5, y + 10);
                }
                else if (vAlign == 1) // Middle
                {
                    g.DrawLine(p, x, y + size / 2, x + size, y + size / 2);
                    g.DrawLine(p, x + 2, y + 3, x + size - 2, y + 3);
                    g.DrawLine(p, x + 2, y + size - 3, x + size - 2, y + size - 3);
                }
                else // Bottom
                {
                    g.DrawLine(p, x, y + size - 2, x + size, y + size - 2);
                    g.DrawLine(p, x + 2, y + size - 6, x + size - 2, y + size - 6);
                    g.DrawLine(p, x + 2, y + size - 10, x + size - 5, y + size - 10);
                }
            }
        }



        private void DrawMergeCenterIcon(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.3f))
            {
                g.DrawRectangle(p, x, y + 1, w, h - 2);
                g.DrawLine(p, x + 3, y + h / 2, x + w - 3, y + h / 2);
                Point[] lArr = new Point[] { new Point(x + 2, y + h / 2), new Point(x + 5, y + h / 2 - 2), new Point(x + 5, y + h / 2 + 2) };
                Point[] rArr = new Point[] { new Point(x + w - 2, y + h / 2), new Point(x + w - 5, y + h / 2 - 2), new Point(x + w - 5, y + h / 2 + 2) };
                using (SolidBrush b = new SolidBrush(col))
                {
                    g.FillPolygon(b, lArr);
                    g.FillPolygon(b, rArr);
                }
            }
        }

