        private void DrawChartIcon(Graphics g, int x, int y, int size, int type, Color col)
        {
            using (SolidBrush b = new SolidBrush(col))
            {
                if (type == 0) // Column
                {
                    g.FillRectangle(b, x + 1, y + size - 6, 3, 6);
                    g.FillRectangle(b, x + 6, y + size - 12, 3, 12);
                    g.FillRectangle(b, x + 11, y + size - 16, 3, 16);
                }
                else if (type == 1) // Line
                {
                    using (Pen p = new Pen(col, 1.6f))
                    {
                        g.DrawLine(p, x + 1, y + size - 4, x + 6, y + 6);
                        g.DrawLine(p, x + 6, y + 6, x + 11, y + 10);
                        g.DrawLine(p, x + 11, y + 10, x + 16, y + 2);
                    }
                }
                else // Pie
                {
                    g.FillPie(b, x, y, size, size, 0, 270);
                }
            }
        }

