        private void DrawPictureVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.2f))
            {
                g.DrawRectangle(p, x, y, w, h);
                PointF[] mtn = new PointF[] {
                    new PointF(x + 2, y + h - 2), new PointF(x + w * 0.45f, y + h * 0.4f),
                    new PointF(x + w * 0.7f, y + h * 0.65f), new PointF(x + w - 2, y + h - 2)
                };
                g.DrawLines(p, mtn);
                using (SolidBrush b = new SolidBrush(col)) g.FillEllipse(b, x + w * 0.65f, y + h * 0.2f, Math.Min(w, h) * 0.2f, Math.Min(w, h) * 0.2f);
            }
        }
