        private void DrawPowerPointRibbonToolbar(Graphics g, int width, SlidesView slidesView = null)
        {
            if (slidesView != null && slidesView.IsRemovingBackground)
            {
                DrawPowerPointTabBackgroundRemoval(g, width, slidesView);
                return;
            }

            switch (ActiveRibbonTab)
            {
                case 0: DrawPowerPointTabHome(g, width, slidesView); break;
                case 1: DrawPowerPointTabInsert(g, width, slidesView); break;
                case 2: DrawPowerPointTabDesign(g, width, slidesView); break;
                case 3: DrawPowerPointTabTransitions(g, width, slidesView); break;
                case 4: DrawPowerPointTabAnimations(g, width, slidesView); break;
                case 5: DrawPowerPointTabSlideShow(g, width, slidesView); break;
                case 6: DrawPowerPointTabView(g, width, slidesView); break;
                case 7:
                    if (slidesView != null && slidesView.SelectedShape != null)
                    {
                        if (slidesView.SelectedShape.Type == ShapeType.Video || !string.IsNullOrEmpty(slidesView.SelectedShape.VideoPath))
                            DrawPowerPointTabVideoFormat(g, width, slidesView);
                        else if (slidesView.SelectedShape.Type == ShapeType.Table)
                            DrawPowerPointTabTableDesign(g, width, slidesView);
                        else if (slidesView.SelectedShape.Type == ShapeType.Image || slidesView.SelectedShape.CachedImage != null || !string.IsNullOrEmpty(slidesView.SelectedShape.ImagePath))
                            DrawPowerPointTabPictureFormat(g, width, slidesView);
                        else
                            DrawPowerPointTabShapeFormat(g, width, slidesView);
                    }
                    else
                    {
                        DrawPowerPointTabHome(g, width, slidesView);
                    }
                    break;
                case 8:
                    if (slidesView != null && slidesView.SelectedShape != null && (slidesView.SelectedShape.Type == ShapeType.Video || !string.IsNullOrEmpty(slidesView.SelectedShape.VideoPath)))
                    {
                        DrawPowerPointTabVideoPlayback(g, width, slidesView);
                    }
                    else
                    {
                        DrawPowerPointTabHome(g, width, slidesView);
                    }
                    break;
                default: DrawPowerPointTabHome(g, width, slidesView); break;
            }
        }

        private GraphicsPath CreateRoundedRectPath(Rectangle rect, int radius)
        {
            GraphicsPath path = new GraphicsPath();
            int d = radius * 2;
            path.AddArc(rect.X, rect.Y, d, d, 180, 90);
            path.AddArc(rect.Right - d, rect.Y, d, d, 270, 90);
            path.AddArc(rect.Right - d, rect.Bottom - d, d, d, 0, 90);
            path.AddArc(rect.X, rect.Bottom - d, d, d, 90, 90);
            path.CloseFigure();
            return path;
        }

        private void DrawPlusVector(Graphics g, int cx, int cy, int size, Color col)
        {
            int half = size / 2;
            int thick = Math.Max(2, size / 5);
            using (SolidBrush b = new SolidBrush(col))
            {
                g.FillRectangle(b, cx - thick / 2, cy - half, thick, size);
                g.FillRectangle(b, cx - half, cy - thick / 2, size, thick);
            }
        }

        private void DrawSlideLayoutVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.2f))
            using (SolidBrush b = new SolidBrush(Color.FromArgb(120, col)))
            {
                g.DrawRectangle(p, x, y, w, h);
                g.FillRectangle(b, x + 2, y + 2, w - 4, 3);
                g.DrawRectangle(p, x + 2, y + 7, (w - 6) / 2, h - 9);
                g.DrawRectangle(p, x + 4 + (w - 6) / 2, y + 7, (w - 6) / 2, h - 9);
            }
        }

        private void DrawResetVector(Graphics g, int cx, int cy, int r, Color col)
        {
            using (Pen p = new Pen(col, 1.6f))
            {
                g.DrawArc(p, cx - r, cy - r, r * 2, r * 2, 45, 270);
                Point[] arrow = new Point[] {
                    new Point(cx + r, cy - 2),
                    new Point(cx + r + 4, cy + 3),
                    new Point(cx + r - 3, cy + 3)
                };
                using (SolidBrush b = new SolidBrush(col)) g.FillPolygon(b, arrow);
            }
        }

        private void DrawDuplicateVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.2f))
            {
                g.DrawRectangle(p, x + 3, y, w - 3, h - 3);
                using (SolidBrush bg = new SolidBrush(Color.White))
                {
                    g.FillRectangle(bg, x, y + 3, w - 3, h - 3);
                }
                g.DrawRectangle(p, x, y + 3, w - 3, h - 3);
            }
        }

        private void DrawAlignVector(Graphics g, int x, int y, int w, int h, int align, Color col)
        {
            using (Pen p = new Pen(col, 1.5f))
            {
                int[] lineLens = new int[] { w, (w * 2) / 3, w, (w * 3) / 4 };
                for (int i = 0; i < 4; i++)
                {
                    int ly = y + i * (h / 4) + 1;
                    int lw = lineLens[i];
                    int lx = x;
                    if (align == 1) lx = x + (w - lw) / 2; // Center
                    else if (align == 2) lx = x + w - lw; // Right
                    g.DrawLine(p, lx, ly, lx + lw, ly);
                }
            }
        }

        private void DrawBulletsVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (SolidBrush b = new SolidBrush(col))
            using (Pen p = new Pen(col, 1.4f))
            {
                for (int i = 0; i < 3; i++)
                {
                    int ly = y + i * 5 + 2;
                    g.FillEllipse(b, x, ly, 3, 3);
                    g.DrawLine(p, x + 6, ly + 1, x + w, ly + 1);
                }
            }
        }

        private void DrawNumberingVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Font f = new Font("Segoe UI", 5.5f, FontStyle.Bold))
            using (Pen p = new Pen(col, 1.4f))
            {
                for (int i = 0; i < 3; i++)
                {
                    int ly = y + i * 5 + 1;
                    g.DrawString((i + 1).ToString(), f, Brushes.Black, x - 1, ly - 2);
                    g.DrawLine(p, x + 6, ly + 2, x + w, ly + 2);
                }
            }
        }

        private void DrawShapeIconVector(Graphics g, int x, int y, int w, int h, ShapeType type, Color col)
        {
            using (Pen p = new Pen(col, 1.3f))
            using (SolidBrush b = new SolidBrush(Color.FromArgb(40, col)))
            {
                Rectangle r = new Rectangle(x, y, w, h);
                if (type == ShapeType.TextBox)
                {
                    g.DrawRectangle(p, r);
                    using (Font f = new Font("Segoe UI", 7.0f, FontStyle.Bold))
                    {
                        g.DrawString("A", f, Brushes.Black, x + (w - 7) / 2, y + (h - 10) / 2);
                    }
                }
                else if (type == ShapeType.Line)
                {
                    g.DrawLine(p, x + 1, y + h / 2, x + w - 1, y + h / 2);
                }
                else
                {
                    using (GraphicsPath gp = SlidesView.CreateShapePath(type, x, y, w, h))
                    {
                        g.FillPath(b, gp);
                        g.DrawPath(p, gp);
                    }
                }
            }
        }

        private void DrawStarVector(Graphics g, int cx, int cy, int r, Color col)
        {
            PointF[] pts = new PointF[10];
            double innerR = r * 0.45;
            for (int i = 0; i < 10; i++)
            {
                double angle = i * Math.PI / 5.0 - Math.PI / 2.0;
                double cr = (i % 2 == 0) ? r : innerR;
                pts[i] = new PointF((float)(cx + cr * Math.Cos(angle)), (float)(cy + cr * Math.Sin(angle)));
            }
            using (SolidBrush b = new SolidBrush(Color.FromArgb(245, 158, 11)))
            using (Pen p = new Pen(col, 1.0f))
            {
                g.FillPolygon(b, pts);
                g.DrawPolygon(p, pts);
            }
        }

        private void DrawGalleryScrollButtons(Graphics g, int x, int y, int w, int h, bool enabled = true)
        {
            int btnH = h / 3;
            Rectangle upRect = new Rectangle(x, y, w, btnH);
            Rectangle downRect = new Rectangle(x, y + btnH, w, btnH);
            Rectangle moreRect = new Rectangle(x, y + btnH * 2, w, h - btnH * 2);

            Color borderColor = enabled ? Color.FromArgb(200, 205, 210) : Color.FromArgb(225, 228, 232);
            Color bgColor = enabled ? Color.FromArgb(245, 246, 248) : Color.FromArgb(248, 249, 250);
            Color arrowColor = enabled ? Color.FromArgb(60, 60, 60) : Color.FromArgb(180, 185, 190);

            using (Pen borderPen = new Pen(borderColor, 1.0f))
            using (SolidBrush bgBrush = new SolidBrush(bgColor))
            using (Pen arrowPen = new Pen(arrowColor, 1.4f))
            {
                g.FillRectangle(bgBrush, x, y, w, h);
                g.DrawRectangle(borderPen, x, y, w, h);
                g.DrawLine(borderPen, x, y + btnH, x + w, y + btnH);
                g.DrawLine(borderPen, x, y + btnH * 2, x + w, y + btnH * 2);

                // Up arrow ▲
                int mx = x + w / 2;
                g.DrawLine(arrowPen, mx - 3, y + btnH / 2 + 1, mx, y + btnH / 2 - 2);
                g.DrawLine(arrowPen, mx, y + btnH / 2 - 2, mx + 3, y + btnH / 2 + 1);

                // Down arrow ▼
                int dy = y + btnH;
                g.DrawLine(arrowPen, mx - 3, dy + btnH / 2 - 2, mx, dy + btnH / 2 + 1);
                g.DrawLine(arrowPen, mx, dy + btnH / 2 + 1, mx + 3, dy + btnH / 2 - 2);

                // More dropdown ⏷ (Line + Down arrow)
                int my = y + btnH * 2;
                g.DrawLine(arrowPen, mx - 4, my + 3, mx + 4, my + 3);
                g.DrawLine(arrowPen, mx - 3, my + 6, mx, my + 9);
                g.DrawLine(arrowPen, mx, my + 9, mx + 3, my + 6);
            }
        }

        private void DrawPaintBucketVector(Graphics g, int x, int y, Color col)
        {
            using (Pen p = new Pen(Color.FromArgb(60, 60, 60), 1.3f))
            using (SolidBrush b = new SolidBrush(col))
            {
                Point[] bucket = new Point[] {
                    new Point(x + 2, y + 2),
                    new Point(x + 9, y + 2),
                    new Point(x + 7, y + 9),
                    new Point(x + 1, y + 9)
                };
                g.FillPolygon(b, bucket);
                g.DrawPolygon(p, bucket);
                g.DrawArc(p, x + 3, y - 2, 6, 6, 180, 180);
                g.FillEllipse(b, x, y + 11, 3, 3);
            }
        }

