        private void DrawInsertVectorIcon(Graphics g, int x, int y, int idx, Color col)
        {
            using (Pen p = new Pen(col, 1.5f))
            using (SolidBrush b = new SolidBrush(col))
            using (SolidBrush bg = new SolidBrush(Color.FromArgb(35, col)))
            {
                switch (idx)
                {
                    case 0: // Slide Mới
                        g.FillRectangle(bg, x + 2, y + 2, 20, 16);
                        g.DrawRectangle(p, x + 2, y + 2, 20, 16);
                        DrawPlusVector(g, x + 12, y + 10, 10, Color.FromArgb(210, 71, 38));
                        break;
                    case 1: // Bảng biểu
                        g.DrawRectangle(p, x + 2, y + 2, 20, 16);
                        g.DrawLine(p, x + 2, y + 7, x + 22, y + 7);
                        g.DrawLine(p, x + 2, y + 12, x + 22, y + 12);
                        g.DrawLine(p, x + 8, y + 2, x + 8, y + 18);
                        g.DrawLine(p, x + 15, y + 2, x + 15, y + 18);
                        break;
                    case 2: // Hình ảnh
                        g.DrawRectangle(p, x + 2, y + 2, 20, 16);
                        g.FillEllipse(b, x + 6, y + 5, 4, 4);
                        Point[] mtn = new Point[] {
                            new Point(x + 3, y + 17),
                            new Point(x + 10, y + 9),
                            new Point(x + 15, y + 14),
                            new Point(x + 18, y + 11),
                            new Point(x + 21, y + 17)
                        };
                        g.DrawLines(p, mtn);
                        break;
                    case 3: // Hình vẽ
                        g.DrawRectangle(p, x + 3, y + 3, 10, 10);
                        g.DrawEllipse(p, x + 9, y + 7, 12, 12);
                        break;
                    case 4: // Hộp chữ
                        g.DrawRectangle(p, x + 2, y + 2, 20, 16);
                        using (Font f = new Font("Segoe UI", 8.5f, FontStyle.Bold))
                        {
                            g.DrawString("A", f, b, x + 6, y + 1);
                        }
                        break;
                    case 5: // WordArt
                        using (Font f = new Font("Georgia", 11f, FontStyle.Bold | FontStyle.Italic))
                        {
                            g.DrawString("A", f, Brushes.DarkOrange, x + 6, y + 1);
                        }
                        break;
                    case 6: // Biểu đồ
                        g.FillRectangle(b, x + 4, y + 10, 4, 8);
                        g.FillRectangle(b, x + 10, y + 5, 4, 13);
                        g.FillRectangle(b, x + 16, y + 2, 4, 16);
                        break;
                    case 7: // SmartArt
                        g.DrawRectangle(p, x + 2, y + 3, 5, 14);
                        g.DrawRectangle(p, x + 9, y + 3, 5, 14);
                        g.DrawRectangle(p, x + 16, y + 3, 5, 14);
                        g.DrawLine(p, x + 7, y + 10, x + 9, y + 10);
                        g.DrawLine(p, x + 14, y + 10, x + 16, y + 10);
                        break;
                    case 8: // Liên kết
                        g.DrawArc(p, x + 3, y + 6, 10, 8, 90, 180);
                        g.DrawArc(p, x + 11, y + 6, 10, 8, 270, 180);
                        g.DrawLine(p, x + 8, y + 10, x + 16, y + 10);
                        break;
                    case 9: // Bình luận
                        g.DrawRectangle(p, x + 3, y + 3, 18, 11);
                        Point[] tail = new Point[] { new Point(x + 6, y + 14), new Point(x + 6, y + 18), new Point(x + 11, y + 14) };
                        g.FillPolygon(b, tail);
                        g.DrawLine(p, x + 6, y + 7, x + 18, y + 7);
                        g.DrawLine(p, x + 6, y + 10, x + 14, y + 10);
                        break;
                    case 10: // Công thức
                        using (Font f = new Font("Cambria Math", 11f, FontStyle.Bold))
                        {
                            g.DrawString("π", f, b, x + 6, y + 1);
                        }
                        break;
                    case 11: // Ký hiệu
                        using (Font f = new Font("Segoe UI", 11f, FontStyle.Bold))
                        {
                            g.DrawString("Ω", f, b, x + 5, y + 1);
                        }
                        break;
                    case 12: // Video
                        g.DrawRectangle(p, x + 2, y + 3, 20, 14);
                        Point[] vplay = new Point[] { new Point(x + 9, y + 6), new Point(x + 15, y + 10), new Point(x + 9, y + 14) };
                        g.FillPolygon(b, vplay);
                        break;
                    case 13: // Âm thanh
                        g.FillRectangle(b, x + 4, y + 7, 4, 6);
                        Point[] spk = new Point[] { new Point(x + 8, y + 7), new Point(x + 13, y + 3), new Point(x + 13, y + 17), new Point(x + 8, y + 13) };
                        g.FillPolygon(b, spk);
                        g.DrawArc(p, x + 14, y + 5, 5, 10, -60, 120);
                        g.DrawArc(p, x + 16, y + 2, 7, 16, -60, 120);
                        break;
                }
            }
        }

        private void DrawMergeShapesIconVector(Graphics g, int x, int y, int w, int h, Color color)
        {
            using (SolidBrush b = new SolidBrush(Color.FromArgb(160, color)))
            using (Pen p = new Pen(color, 1.2f))
            {
                float r = w * 0.58f;
                g.FillEllipse(b, x, y, r, r);
                g.DrawEllipse(p, x, y, r, r);

                g.FillEllipse(b, x + w - r, y + h - r, r, r);
                g.DrawEllipse(p, x + w - r, y + h - r, r, r);
            }
        }

        public static Image CreateMergeIcon(MergeShapeOperation op)
        {
            Bitmap bmp = new Bitmap(24, 24);
            using (Graphics g = Graphics.FromImage(bmp))
            {
                g.SmoothingMode = SmoothingMode.AntiAlias;
                g.Clear(Color.Transparent);

                using (SolidBrush fillB = new SolidBrush(Color.FromArgb(148, 163, 184)))
                using (Pen strokeP = new Pen(Color.FromArgb(71, 85, 105), 1.2f))
                {
                    RectangleF r1 = new RectangleF(3, 3, 11, 11);
                    RectangleF r2 = new RectangleF(9, 9, 11, 11);

                    switch (op)
                    {
                        case MergeShapeOperation.Union:
                            using (GraphicsPath p = new GraphicsPath())
                            {
                                p.FillMode = FillMode.Winding;
                                p.AddEllipse(r1);
                                p.AddEllipse(r2);
                                g.FillPath(fillB, p);
                                g.DrawPath(strokeP, p);
                            }
                            break;
                        case MergeShapeOperation.Combine:
                            using (GraphicsPath p = new GraphicsPath())
                            {
                                p.FillMode = FillMode.Alternate;
                                p.AddEllipse(r1);
                                p.AddEllipse(r2);
                                g.FillPath(fillB, p);
                                g.DrawPath(strokeP, p);
                            }
                            break;
                        case MergeShapeOperation.Fragment:
                            using (GraphicsPath p1 = new GraphicsPath())
                            {
                                p1.AddEllipse(new RectangleF(2, 2, 10, 10));
                                using (Region reg1 = new Region(p1))
                                {
                                    GraphicsPath pOther = new GraphicsPath();
                                    pOther.AddEllipse(new RectangleF(9, 9, 10, 10));
                                    reg1.Exclude(pOther);
                                    g.FillRegion(fillB, reg1);
                                    g.DrawPath(strokeP, p1);
                                }
                            }
                            using (GraphicsPath p2 = new GraphicsPath())
                            {
                                p2.AddEllipse(new RectangleF(11, 11, 10, 10));
                                using (Region reg2 = new Region(p2))
                                {
                                    GraphicsPath pOther2 = new GraphicsPath();
                                    pOther2.AddEllipse(new RectangleF(2, 2, 10, 10));
                                    reg2.Exclude(pOther2);
                                    g.FillRegion(fillB, reg2);
                                    g.DrawPath(strokeP, p2);
                                }
                            }
                            using (GraphicsPath pCenter1 = new GraphicsPath())
                            {
                                pCenter1.AddEllipse(new RectangleF(2, 2, 10, 10));
                                using (Region regC = new Region(pCenter1))
                                {
                                    GraphicsPath pOther3 = new GraphicsPath();
                                    pOther3.AddEllipse(new RectangleF(11, 11, 10, 10));
                                    regC.Intersect(pOther3);
                                    g.FillRegion(fillB, regC);
                                }
                            }
                            break;
                        case MergeShapeOperation.Intersect:
                            using (GraphicsPath p1 = new GraphicsPath())
                            {
                                p1.AddEllipse(r1);
                                using (Region reg = new Region(p1))
                                {
                                    GraphicsPath p2 = new GraphicsPath();
                                    p2.AddEllipse(r2);
                                    reg.Intersect(p2);
                                    g.FillRegion(fillB, reg);
                                }
                                g.DrawEllipse(strokeP, r1);
                                g.DrawEllipse(strokeP, r2);
                            }
                            break;
                        case MergeShapeOperation.Subtract:
                            using (GraphicsPath p1 = new GraphicsPath())
                            {
                                p1.AddEllipse(r1);
                                using (Region reg = new Region(p1))
                                {
                                    GraphicsPath p2 = new GraphicsPath();
                                    p2.AddEllipse(r2);
                                    reg.Exclude(p2);
                                    g.FillRegion(fillB, reg);
                                }
                                g.DrawEllipse(strokeP, r1);
                                g.DrawEllipse(new Pen(Color.FromArgb(180, 180, 180), 1.0f) { DashStyle = DashStyle.Dot }, r2);
                            }
                            break;
                    }
                }
            }
            return bmp;
        }

        private void DrawArrangeIconVector(Graphics g, int x, int y, int w, int h)
        {
            int cx = x + (w - 24) / 2;
            int cy = y + 2;

            // Back square (Gold / Orange with white stroke)
            Rectangle backSquare = new Rectangle(cx + 8, cy + 6, 14, 14);
            using (SolidBrush goldBrush = new SolidBrush(Color.FromArgb(245, 158, 11)))
            using (Pen whitePen = new Pen(Color.White, 1.2f))
            {
                g.FillRectangle(goldBrush, backSquare);
                g.DrawRectangle(whitePen, backSquare);
            }

            // Front square (White with dark border)
            Rectangle frontSquare = new Rectangle(cx + 2, cy + 2, 14, 14);
            using (SolidBrush whiteBrush = new SolidBrush(Color.White))
            using (Pen darkPen = new Pen(Color.FromArgb(30, 41, 59), 1.4f))
            {
                g.FillRectangle(whiteBrush, frontSquare);
                g.DrawRectangle(darkPen, frontSquare);
            }
        }

        private void ShowArrangeMenu(Form parentForm, Point screenPos, SlidesView slidesView)
        {
            ContextMenuStrip menu = new ContextMenuStrip();
            menu.Font = new Font("Segoe UI", 9f);
            menu.ShowImageMargin = true;

            // 1. Order Objects (Thứ tự Đối tượng)
            ToolStripMenuItem miOrderHeader = new ToolStripMenuItem("Thứ tự Đối tượng (Order Objects)");
            miOrderHeader.Enabled = false;
            miOrderHeader.Font = new Font("Segoe UI", 8.5f, FontStyle.Bold);
            menu.Items.Add(miOrderHeader);

            ToolStripMenuItem miFront = new ToolStripMenuItem("Đưa lên trên cùng (Bring to Front)", SlidesView.CreateBringFrontIcon(), (s, e) => {
                slidesView.BringShapeToFront();
                if (parentForm != null) parentForm.Invalidate();
            });
            ToolStripMenuItem miBack = new ToolStripMenuItem("Đưa về sau cùng (Send to Back)", SlidesView.CreateSendBackIcon(), (s, e) => {
                slidesView.SendShapeToBack();
                if (parentForm != null) parentForm.Invalidate();
            });
            ToolStripMenuItem miForward = new ToolStripMenuItem("Lên trên một lớp (Bring Forward)", null, (s, e) => {
                slidesView.BringShapeForward();
                if (parentForm != null) parentForm.Invalidate();
            });
            ToolStripMenuItem miBackward = new ToolStripMenuItem("Xuống dưới một lớp (Send Backward)", null, (s, e) => {
                slidesView.SendShapeBackward();
                if (parentForm != null) parentForm.Invalidate();
            });

            menu.Items.AddRange(new ToolStripItem[] { miFront, miBack, miForward, miBackward, new ToolStripSeparator() });

            // 2. Group Objects (Nhóm Đối tượng)
            ToolStripMenuItem miGroupHeader = new ToolStripMenuItem("Nhóm Đối tượng (Group Objects)");
            miGroupHeader.Enabled = false;
            miGroupHeader.Font = new Font("Segoe UI", 8.5f, FontStyle.Bold);
            menu.Items.Add(miGroupHeader);

            ToolStripMenuItem miGroup = new ToolStripMenuItem("Nhóm (Group)", SlidesView.CreateGroupIcon(), (s, e) => {
                slidesView.MergeShapes(MergeShapeOperation.Union);
                if (parentForm != null) parentForm.Invalidate();
            });
            ToolStripMenuItem miUngroup = new ToolStripMenuItem("Rã nhóm (Ungroup)", null, (s, e) => {
                if (parentForm != null) parentForm.Invalidate();
            });
            ToolStripMenuItem miRegroup = new ToolStripMenuItem("Gom nhóm lại (Regroup)", null, (s, e) => {
                if (parentForm != null) parentForm.Invalidate();
            });

            menu.Items.AddRange(new ToolStripItem[] { miGroup, miUngroup, miRegroup, new ToolStripSeparator() });

            // 3. Position Objects (Định vị Đối tượng)
            ToolStripMenuItem miPosHeader = new ToolStripMenuItem("Định vị Đối tượng (Position Objects)");
            miPosHeader.Enabled = false;
            miPosHeader.Font = new Font("Segoe UI", 8.5f, FontStyle.Bold);
            menu.Items.Add(miPosHeader);

            // Align Submenu
            ToolStripMenuItem miAlign = new ToolStripMenuItem("Căn chỉnh (Align)");
            miAlign.DropDownItems.Add(new ToolStripMenuItem("Căn Trái (Align Left)", null, (s, e) => { slidesView.AlignShapes(ShapeAlignType.Left); if (parentForm != null) parentForm.Invalidate(); }));
            miAlign.DropDownItems.Add(new ToolStripMenuItem("Căn Giữa ngang (Align Center)", null, (s, e) => { slidesView.AlignShapes(ShapeAlignType.Center); if (parentForm != null) parentForm.Invalidate(); }));
            miAlign.DropDownItems.Add(new ToolStripMenuItem("Căn Phải (Align Right)", null, (s, e) => { slidesView.AlignShapes(ShapeAlignType.Right); if (parentForm != null) parentForm.Invalidate(); }));
            miAlign.DropDownItems.Add(new ToolStripMenuItem("Căn Trên (Align Top)", null, (s, e) => { slidesView.AlignShapes(ShapeAlignType.Top); if (parentForm != null) parentForm.Invalidate(); }));
            miAlign.DropDownItems.Add(new ToolStripMenuItem("Căn Giữa dọc (Align Middle)", null, (s, e) => { slidesView.AlignShapes(ShapeAlignType.Middle); if (parentForm != null) parentForm.Invalidate(); }));
            miAlign.DropDownItems.Add(new ToolStripMenuItem("Căn Dưới (Align Bottom)", null, (s, e) => { slidesView.AlignShapes(ShapeAlignType.Bottom); if (parentForm != null) parentForm.Invalidate(); }));
            menu.Items.Add(miAlign);

            // Rotate Submenu
            ToolStripMenuItem miRotate = new ToolStripMenuItem("Xoay (Rotate)");
            miRotate.DropDownItems.Add(new ToolStripMenuItem("Xoay Phải 90°", null, (s, e) => {
                if (slidesView.SelectedShape != null) slidesView.SelectedShape.Transform.Rotation += 90f;
                if (parentForm != null) parentForm.Invalidate();
            }));
            miRotate.DropDownItems.Add(new ToolStripMenuItem("Xoay Trái 90°", null, (s, e) => {
                if (slidesView.SelectedShape != null) slidesView.SelectedShape.Transform.Rotation -= 90f;
                if (parentForm != null) parentForm.Invalidate();
            }));
            miRotate.DropDownItems.Add(new ToolStripMenuItem("Lật Ngang (Flip Horizontal)", null, (s, e) => {
                if (slidesView.SelectedShape != null) slidesView.SelectedShape.Transform.FlipHorizontal = !slidesView.SelectedShape.Transform.FlipHorizontal;
                if (parentForm != null) parentForm.Invalidate();
            }));
            miRotate.DropDownItems.Add(new ToolStripMenuItem("Lật Dọc (Flip Vertical)", null, (s, e) => {
                if (slidesView.SelectedShape != null) slidesView.SelectedShape.Transform.FlipVertical = !slidesView.SelectedShape.Transform.FlipVertical;
                if (parentForm != null) parentForm.Invalidate();
            }));
            menu.Items.Add(miRotate);

            // Opacity Submenu
            ToolStripMenuItem miOpacity = new ToolStripMenuItem("Làm mờ / Độ trong suốt (Opacity)");
            miOpacity.DropDownItems.Add(new ToolStripMenuItem("100% Đặc (Opaque)", null, (s, e) => { if (slidesView.SelectedShape != null) slidesView.SelectedShape.FillOpacity = 1.0f; if (parentForm != null) parentForm.Invalidate(); }));
            miOpacity.DropDownItems.Add(new ToolStripMenuItem("80% Hơi mờ", null, (s, e) => { if (slidesView.SelectedShape != null) slidesView.SelectedShape.FillOpacity = 0.8f; if (parentForm != null) parentForm.Invalidate(); }));
            miOpacity.DropDownItems.Add(new ToolStripMenuItem("60% Bán trong suốt", null, (s, e) => { if (slidesView.SelectedShape != null) slidesView.SelectedShape.FillOpacity = 0.6f; if (parentForm != null) parentForm.Invalidate(); }));
            miOpacity.DropDownItems.Add(new ToolStripMenuItem("40% Mờ (Translucent)", null, (s, e) => { if (slidesView.SelectedShape != null) slidesView.SelectedShape.FillOpacity = 0.4f; if (parentForm != null) parentForm.Invalidate(); }));
            miOpacity.DropDownItems.Add(new ToolStripMenuItem("20% Rất mờ", null, (s, e) => { if (slidesView.SelectedShape != null) slidesView.SelectedShape.FillOpacity = 0.2f; if (parentForm != null) parentForm.Invalidate(); }));
            miOpacity.DropDownItems.Add(new ToolStripMenuItem("0% Trong suốt (Transparent)", null, (s, e) => { if (slidesView.SelectedShape != null) slidesView.SelectedShape.FillOpacity = 0.0f; if (parentForm != null) parentForm.Invalidate(); }));
            menu.Items.Add(miOpacity);

            menu.Items.Add(new ToolStripSeparator());

            // 4. Selection Pane (Ngăn Lựa chọn...)
            ToolStripMenuItem miSelectionPane = new ToolStripMenuItem("Ngăn Lựa chọn (Selection Pane)...", SlidesView.CreateSelectionPaneIcon(), (s, e) => {
                slidesView.SidebarPanel = SidebarPanelType.SelectionPane;
                slidesView.IsSidebarOpen = true;
                if (parentForm != null) parentForm.Invalidate();
            });
            menu.Items.Add(miSelectionPane);

            menu.Show(parentForm != null ? parentForm.PointToScreen(screenPos) : screenPos);
        }

        private void DrawPowerPointTabHome(Graphics g, int width, SlidesView slidesView)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.5f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 9f, FontStyle.Bold))
            {
                // ==================== Group 1: Open, Save & Clipboard (X: 12 to 204) ====================
                Rectangle openBox = new Rectangle(12, 68, 38, 62);
                DrawInteractiveButton(g, openBox, false, 4);
                DrawOpenIcon(g, 21, 73, 18, 18, Color.FromArgb(217, 119, 6));
                g.DrawString("Mở", boldFont, Brushes.Navy, 20, 110);

                Rectangle saveBox = new Rectangle(52, 68, 38, 62);
                DrawInteractiveButton(g, saveBox, false, 4);
                DrawSaveIcon(g, 61, 73, 18, 18, Color.FromArgb(210, 71, 38));
                g.DrawString("Lưu", boldFont, Brushes.Navy, 60, 110);

                Rectangle pasteBox = new Rectangle(92, 68, 42, 62);
                DrawInteractiveButton(g, pasteBox, false, 4);
                DrawPasteIcon(g, 102, 73, 20, 20, Color.FromArgb(13, 148, 136));
                g.DrawString("Dán ▾", labelFont, Brushes.Black, 98, 110);

                Rectangle cutBox = new Rectangle(136, 68, 64, 20);
                DrawInteractiveButton(g, cutBox, false, 3);
                DrawCutIcon(g, 138, 70, 14, 14, Color.FromArgb(234, 88, 12));
                g.DrawString("Cắt", btnFont, Brushes.Black, 156, 70);

                Rectangle copyBox = new Rectangle(136, 89, 64, 20);
                DrawInteractiveButton(g, copyBox, false, 3);
                DrawCopyIcon(g, 138, 91, 14, 14, Color.FromArgb(79, 70, 229));
                g.DrawString("Chép", btnFont, Brushes.Black, 156, 90);

                Rectangle fmtBox = new Rectangle(136, 110, 64, 20);
                DrawInteractiveButton(g, fmtBox, false, 3);
                DrawBrushIcon(g, 138, 112, Color.FromArgb(217, 119, 6));
                g.DrawString("Chổi", btnFont, Brushes.Black, 156, 110);

                g.DrawString("Bảng tạm", labelFont, Brushes.Gray, 82, 137);
                g.DrawLine(Pens.LightGray, 206, 68, 206, 148);

                // ==================== Group 2: Slides (X: 212 to 374) ====================
                Rectangle newSlideBox = new Rectangle(212, 68, 64, 62);
                DrawInteractiveButton(g, newSlideBox, false, 4);
                using (SolidBrush cardBg = new SolidBrush(Color.FromArgb(254, 243, 199)))
                using (Pen cardPen = new Pen(Color.FromArgb(210, 71, 38), 1.2f))
                {
                    g.FillRectangle(cardBg, 230, 72, 26, 18);
                    g.DrawRectangle(cardPen, 230, 72, 26, 18);
                }
                DrawPlusVector(g, 243, 81, 10, Color.FromArgb(210, 71, 38));
                g.DrawString("Slide Mới", boldFont, Brushes.Black, 217, 110);

                Rectangle layoutBox = new Rectangle(280, 68, 92, 20);
                DrawInteractiveButton(g, layoutBox, false, 3);
                DrawSlideLayoutVector(g, 283, 71, 14, 12, Color.FromArgb(15, 118, 110));
                g.DrawString("Bố cục ▾", btnFont, Brushes.Black, 302, 70);

                Rectangle resetBox = new Rectangle(280, 89, 92, 20);
                DrawInteractiveButton(g, resetBox, false, 3);
                DrawResetVector(g, 289, 98, 5, Color.FromArgb(37, 99, 235));
                g.DrawString("Đặt lại", btnFont, Brushes.Black, 302, 90);

                Rectangle dupBox = new Rectangle(280, 110, 92, 20);
                DrawInteractiveButton(g, dupBox, false, 3);
                DrawDuplicateVector(g, 284, 113, 13, 11, Color.FromArgb(217, 119, 6));
                g.DrawString("Nhân bản", btnFont, Brushes.Black, 302, 110);

                g.DrawString("Trang chiếu", labelFont, Brushes.Gray, 260, 137);
                g.DrawLine(Pens.LightGray, 378, 68, 378, 148);

                // ==================== Group 3: Font (X: 384 to 640) ====================
                string currFont = (slidesView != null && slidesView.SelectedShape != null) ? slidesView.SelectedShape.FontName : SelectedFont;
                float currSize = (slidesView != null && slidesView.SelectedShape != null) ? slidesView.SelectedShape.FontSize : FontSize;

                Rectangle fontCombo = new Rectangle(384, 68, 120, 24);
                DrawInteractiveButton(g, fontCombo, false, 3);
                g.DrawString(currFont.Length > 13 ? (currFont.Substring(0, 12) + "…") : currFont, btnFont, Brushes.Black, 387, 71);
                g.DrawString("▾", btnFont, Brushes.Gray, 488, 71);

                Rectangle sizeCombo = new Rectangle(508, 68, 44, 24);
                DrawInteractiveButton(g, sizeCombo, false, 3);
                g.DrawString(currSize.ToString("0"), btnFont, Brushes.Black, 512, 71);
                g.DrawString("▾", btnFont, Brushes.Gray, 536, 71);

                Rectangle aIncBox = new Rectangle(556, 68, 24, 24);
                DrawInteractiveButton(g, aIncBox, false, 3);
                g.DrawString("A", boldFont, Brushes.Navy, 558, 70);
                DrawPlusVector(g, 574, 76, 5, Color.Navy);

                Rectangle aDecBox = new Rectangle(584, 68, 24, 24);
                DrawInteractiveButton(g, aDecBox, false, 3);
                g.DrawString("A", btnFont, Brushes.Navy, 587, 72);
                using (SolidBrush b = new SolidBrush(Color.Navy)) g.FillRectangle(b, 600, 78, 5, 2);

                // Font style buttons row 2 (Y: 96)
                bool isB = (slidesView != null && slidesView.SelectedShape != null) ? slidesView.SelectedShape.Bold : IsBold;
                bool isI = (slidesView != null && slidesView.SelectedShape != null) ? slidesView.SelectedShape.Italic : IsItalic;
                bool isU = (slidesView != null && slidesView.SelectedShape != null) ? slidesView.SelectedShape.Underline : IsUnderline;

                Rectangle bBox = new Rectangle(384, 96, 24, 24);
                DrawInteractiveButton(g, bBox, isB, 3);
                g.DrawString("B", boldFont, isB ? Brushes.RoyalBlue : Brushes.Black, 390, 98);

                Rectangle iBox = new Rectangle(412, 96, 24, 24);
                DrawInteractiveButton(g, iBox, isI, 3);
                using (Font itFont = new Font("Segoe UI", 9f, FontStyle.Italic))
                {
                    g.DrawString("I", itFont, isI ? Brushes.RoyalBlue : Brushes.Black, 419, 98);
                }

                Rectangle uBox = new Rectangle(440, 96, 24, 24);
                DrawInteractiveButton(g, uBox, isU, 3);
                using (Font ulFont = new Font("Segoe UI", 9f, FontStyle.Underline))
                {
                    g.DrawString("U", ulFont, isU ? Brushes.RoyalBlue : Brushes.Black, 446, 98);
                }

                Rectangle sBox = new Rectangle(468, 96, 24, 24);
                DrawInteractiveButton(g, sBox, false, 3);
                g.DrawString("S", boldFont, Brushes.DimGray, 474, 98);

                Rectangle colBox = new Rectangle(496, 96, 28, 24);
                DrawInteractiveButton(g, colBox, false, 3);
                g.DrawString("A", boldFont, Brushes.DarkRed, 502, 97);
                using (SolidBrush barBrush = new SolidBrush(Color.FromArgb(210, 71, 38)))
                {
                    g.FillRectangle(barBrush, 500, 114, 20, 3);
                }

                g.DrawString("Phông chữ", labelFont, Brushes.Gray, 480, 137);
                g.DrawLine(Pens.LightGray, 644, 68, 644, 148);

                // ==================== Group 4: Paragraph (X: 648 to 776) ====================
                TextAlignment currAlign = (slidesView != null && slidesView.SelectedShape != null) ? slidesView.SelectedShape.Alignment : TextAlignment.Left;

                Rectangle leftAlign = new Rectangle(648, 68, 24, 24);
                DrawInteractiveButton(g, leftAlign, currAlign == TextAlignment.Left, 3);
                DrawAlignVector(g, 652, 73, 16, 12, 0, (currAlign == TextAlignment.Left) ? Color.FromArgb(210, 71, 38) : Color.Black);

                Rectangle centerAlign = new Rectangle(676, 68, 24, 24);
                DrawInteractiveButton(g, centerAlign, currAlign == TextAlignment.Center, 3);
                DrawAlignVector(g, 680, 73, 16, 12, 1, (currAlign == TextAlignment.Center) ? Color.FromArgb(210, 71, 38) : Color.Black);

                Rectangle rightAlign = new Rectangle(704, 68, 24, 24);
                DrawInteractiveButton(g, rightAlign, currAlign == TextAlignment.Right, 3);
                DrawAlignVector(g, 708, 73, 16, 12, 2, (currAlign == TextAlignment.Right) ? Color.FromArgb(210, 71, 38) : Color.Black);

                Rectangle bulletsBox = new Rectangle(648, 96, 38, 24);
                DrawInteractiveButton(g, bulletsBox, false, 3);
                DrawBulletsVector(g, 654, 100, 24, 14, Color.Black);

                Rectangle numBox = new Rectangle(690, 96, 38, 24);
                DrawInteractiveButton(g, numBox, false, 3);
                DrawNumberingVector(g, 696, 100, 24, 14, Color.Black);

                g.DrawString("Đoạn", labelFont, Brushes.Gray, 686, 137);
                g.DrawLine(Pens.LightGray, 780, 68, 780, 148);

                // ==================== Group 5: Drawing (X: 786 to 1098) ====================
                ShapeType[][] allShapeRows = new ShapeType[][] {
                    new ShapeType[] { ShapeType.TextBox, ShapeType.Line, ShapeType.Arrow, ShapeType.Rectangle, ShapeType.RoundedRectangle, ShapeType.Ellipse },
                    new ShapeType[] { ShapeType.Leaf, ShapeType.Clover, ShapeType.Flower, ShapeType.Sprout, ShapeType.LuxuryHexagon, ShapeType.Gem },
                    new ShapeType[] { ShapeType.Shield, ShapeType.Banner, ShapeType.Starburst, ShapeType.Arch, ShapeType.Hexagon, ShapeType.Diamond },
                    new ShapeType[] { ShapeType.Triangle, ShapeType.RightTriangle, ShapeType.Parallelogram, ShapeType.Trapezoid, ShapeType.Octagon, ShapeType.Pentagon },
                    new ShapeType[] { ShapeType.Heart, ShapeType.Callout, ShapeType.Cloud, ShapeType.Sun, ShapeType.Moon, ShapeType.Lightning },
                    new ShapeType[] { ShapeType.BlockArrowRight, ShapeType.BlockArrowLeft, ShapeType.BlockArrowUp, ShapeType.BlockArrowDown, ShapeType.Chevron, ShapeType.Smiley },
                    new ShapeType[] { ShapeType.Donut, ShapeType.Cross, ShapeType.Cube, ShapeType.Can, ShapeType.Star, ShapeType.TextBox }
                };
                int sRow = Math.Max(0, Math.Min(allShapeRows.Length - 3, slidesView.ShapeGalleryScrollRow));
                for (int r = 0; r < 3; r++)
                {
                    ShapeType[] rowShapes = allShapeRows[sRow + r];
                    for (int s = 0; s < rowShapes.Length; s++)
                    {
                        Rectangle sRect = new Rectangle(786 + s * 24, 68 + r * 18, 22, 17);
                        DrawInteractiveButton(g, sRect, false, 2);
                        DrawShapeIconVector(g, sRect.X + 3, sRect.Y + 2, 16, 13, rowShapes[s], Color.FromArgb(40, 40, 40));
                    }
                }

                // 3-Button Stack for Shapes Gallery (X: 932, Y: 68, W: 16, H: 54)
                DrawGalleryScrollButtons(g, 932, 68, 16, 54);

                // Arrange Button (X: 952, Y: 68, W: 54, H: 54)
                Rectangle btnArrange = new Rectangle(952, 68, 54, 54);
                DrawInteractiveButton(g, btnArrange, false, 3);
                DrawArrangeIconVector(g, btnArrange.X, btnArrange.Y + 2, btnArrange.Width, 24);
                g.DrawString("Sắp xếp ▾", labelFont, Brushes.Black, btnArrange.X + 4, btnArrange.Y + 34);

                // Format buttons (Tô màu & Viền)
                Rectangle btnFill = new Rectangle(1010, 68, 86, 26);
                DrawInteractiveButton(g, btnFill, false, 3);
                DrawPaintBucketVector(g, 1014, 73, Color.FromArgb(210, 71, 38));
                g.DrawString("Tô màu ▾", labelFont, Brushes.Black, 1032, 73);

                Rectangle btnLine = new Rectangle(1010, 96, 86, 26);
