                g.DrawString("Viền ▾", labelFont, Brushes.Black, 1032, 101);

                g.DrawString("Vẽ", labelFont, Brushes.Gray, 920, 137);
                g.DrawLine(Pens.LightGray, 1102, 68, 1102, 148);

                // ==================== Group 6: Fullscreen Presentation (X: 1106 to 1256) ====================
                Rectangle btnF5 = new Rectangle(1106, 68, 140, 62);
                DrawInteractiveButton(g, btnF5, false, 4);
                using (SolidBrush orangeFill = new SolidBrush(Color.FromArgb(210, 71, 38)))
                {
                    g.FillRectangle(orangeFill, btnF5);
                }
                DrawPresenterF5Vector(g, 1088, 73, 152, 20);
                g.DrawString("Trình Chiếu (F5)", boldFont, Brushes.White, 1112, 95);
                g.DrawString("Hiệu ứng 60 FPS", labelFont, Brushes.WhiteSmoke, 1122, 111);
            }
        }

        private void DrawPowerPointTabInsert(Graphics g, int width, SlidesView slidesView)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.5f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            using (Font smallFont = new Font("Segoe UI", 7.0f, FontStyle.Regular))
            {
                int curX = 10;

                // ==================== Group 1: Trang chiếu (Slides) (X: 10..72) ====================
                Rectangle newSlideBox = new Rectangle(curX, 68, 58, 56);
                DrawInteractiveButton(g, newSlideBox, false, 4);
                using (SolidBrush cardBg = new SolidBrush(Color.FromArgb(254, 243, 199)))
                using (Pen cardPen = new Pen(Color.FromArgb(210, 71, 38), 1.2f))
                {
                    g.FillRectangle(cardBg, curX + 16, 72, 26, 18);
