                }
                DrawPlusVector(g, curX + 29, 81, 10, Color.FromArgb(210, 71, 38));
                g.DrawString("Slide Mới ▾", labelFont, Brushes.Black, curX + 2, 98);
                curX += 62;

                g.DrawString("Trang chiếu", labelFont, Brushes.Gray, curX - 60, 137);
