                DrawInteractiveButton(g, waBox, false, 4);
                DrawTextWordArtVector(g, curX + 15, 72, 22, 20);
                g.DrawString("WordArt ▾", labelFont, Brushes.Black, curX + 2, 98);
                curX += 56;

                g.DrawString("Văn bản", labelFont, Brushes.Gray, curX - 105, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 8;

                // ==================== Group 7: Ký hiệu (Symbols) (X: 862..970) ====================
                Rectangle eqBox = new Rectangle(curX, 68, 52, 56);
                DrawInteractiveButton(g, eqBox, false, 4);
                DrawEquationVector(g, curX + 15, 72, 22, 20, Color.FromArgb(190, 24, 93));
                g.DrawString("C.thức ▾", labelFont, Brushes.Black, curX + 6, 98);
                curX += 56;

                Rectangle symBox = new Rectangle(curX, 68, 50, 56);
                DrawInteractiveButton(g, symBox, false, 4);
                DrawSymbolsOmegaVector(g, curX + 14, 72, 22);
                g.DrawString("Ký hiệu ▾", labelFont, Brushes.Black, curX + 3, 98);
                curX += 54;

                g.DrawString("Ký hiệu", labelFont, Brushes.Gray, curX - 65, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 8;

                // ==================== Group 8: Phương tiện (Media) (X: 978..1150) ====================
                Rectangle vidBox = new Rectangle(curX, 68, 52, 56);
                DrawInteractiveButton(g, vidBox, false, 4);
                DrawVideoVector(g, curX + 14, 72, 24, 20, Color.FromArgb(225, 29, 72));
                g.DrawString("Video ▾", labelFont, Brushes.Black, curX + 7, 98);
                curX += 56;

                Rectangle audBox = new Rectangle(curX, 68, 56, 56);
                DrawInteractiveButton(g, audBox, false, 4);
                DrawAudioVector(g, curX + 16, 72, 24, 20, Color.FromArgb(147, 51, 234));
                g.DrawString("Âm thanh ▾", smallFont, Brushes.Black, curX + 3, 98);
                curX += 60;

                Rectangle recBox = new Rectangle(curX, 68, 58, 56);
                DrawInteractiveButton(g, recBox, false, 4);
                DrawScreenRecordVector(g, curX + 17, 72, 24, 20, Color.FromArgb(239, 68, 68));
                g.DrawString("Ghi màn hình", smallFont, Brushes.Black, curX + 1, 98);
                curX += 62;

                g.DrawString("Phương tiện", labelFont, Brushes.Gray, curX - 110, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            }
        }

        public static void DrawThemeMiniCardPreview(Graphics g, Rectangle r, PresentationTheme theme, bool isSelected, bool isHovered)
        {
            if (theme == null) return;
            GraphicsState state = g.Save();
            g.SetClip(r);

            Color lightCol = Color.FromArgb(theme.LightColor | unchecked((int)0xFF000000));
            Color lightCol2 = Color.FromArgb(theme.LightColor2 | unchecked((int)0xFF000000));
            Color primCol = Color.FromArgb(theme.PrimaryColor | unchecked((int)0xFF000000));
            Color darkCol = Color.FromArgb(theme.DarkColor | unchecked((int)0xFF000000));

            // 1. Fill base background
            if (theme.Name == "Cyber Wave" || theme.Name == "Cyber Neon")
            {
                using (SolidBrush blackBrush = new SolidBrush(Color.FromArgb(5, 7, 14)))
                {
                    g.FillRectangle(blackBrush, r);
                }
            }
            else if (theme.Name == "Gold Luxury")
            {
                using (SolidBrush darkBrush = new SolidBrush(Color.FromArgb(24, 24, 27)))
                {
                    g.FillRectangle(darkBrush, r);
                }
            }
            else if (theme.IsGradient)
            {
                using (LinearGradientBrush lgb = new LinearGradientBrush(r, lightCol, lightCol2, 90f))
                {
                    g.FillRectangle(lgb, r);
                }
            }
            else
            {
                using (SolidBrush sb = new SolidBrush(lightCol))
                {
                    g.FillRectangle(sb, r);
                }
            }

            // 2. Draw Characteristic Vector Layout per Theme
            switch (theme.Name)
            {
                case "Slice":
                    // Dark navy header
                    using (SolidBrush navyBrush = new SolidBrush(Color.FromArgb(15, 23, 42)))
                    {
                        g.FillRectangle(navyBrush, r.X, r.Y, r.Width, (int)(r.Height * 0.46f));
                    }
                    // Red triangle
                    using (SolidBrush redBrush = new SolidBrush(Color.FromArgb(220, 38, 38)))
                    {
                        g.FillPolygon(redBrush, new PointF[] {
                            new PointF(r.X, r.Y + r.Height * 0.22f),
                            new PointF(r.X + r.Width * 0.20f, r.Y + r.Height * 0.46f),
                            new PointF(r.X, r.Y + r.Height * 0.46f)
                        });
                    }
                    // Teal polygon
                    using (SolidBrush tealBrush = new SolidBrush(Color.FromArgb(13, 148, 136)))
                    {
                        g.FillPolygon(tealBrush, new PointF[] {
                            new PointF(r.X + r.Width * 0.15f, r.Y + r.Height * 0.46f),
                            new PointF(r.X + r.Width * 0.55f, r.Y),
                            new PointF(r.X + r.Width * 0.72f, r.Y),
                            new PointF(r.X + r.Width * 0.40f, r.Y + r.Height * 0.46f)
                        });
                    }
                    // Cyan block
                    using (SolidBrush cyanBrush = new SolidBrush(Color.FromArgb(6, 182, 212)))
                    {
                        g.FillPolygon(cyanBrush, new PointF[] {
                            new PointF(r.X + r.Width * 0.60f, r.Y + r.Height * 0.22f),
                            new PointF(r.Right, r.Y),
                            new PointF(r.Right, r.Y + r.Height * 0.46f),
                            new PointF(r.X + r.Width * 0.60f, r.Y + r.Height * 0.46f)
                        });
                    }
                    // Wireframe card
                    using (Pen whitePen = new Pen(Color.FromArgb(200, 255, 255, 255), 1.0f))
                    {
                        g.DrawRectangle(whitePen, r.X + 6, r.Y + 2, (int)(r.Width * 0.35f), (int)(r.Height * 0.40f));
                        g.DrawRectangle(whitePen, r.X + (int)(r.Width * 0.45f), r.Y + 2, (int)(r.Width * 0.50f), (int)(r.Height * 0.40f));
                    }
                    break;

                case "Facet":
                    // Left slice
                    using (SolidBrush limeBrush = new SolidBrush(Color.FromArgb(132, 204, 22)))
                    {
                        g.FillPolygon(limeBrush, new PointF[] {
                            new PointF(r.X, r.Y),
                            new PointF(r.X + r.Width * 0.08f, r.Y),
                            new PointF(r.X + r.Width * 0.03f, r.Bottom),
                            new PointF(r.X, r.Bottom)
                        });
                        // Right edge
                        g.FillPolygon(limeBrush, new PointF[] {
                            new PointF(r.X + r.Width * 0.72f, r.Y),
                            new PointF(r.Right, r.Y),
                            new PointF(r.Right, r.Bottom),
                            new PointF(r.X + r.Width * 0.68f, r.Bottom)
                        });
                    }
                    // Deep forest wedge
                    using (SolidBrush forestBrush = new SolidBrush(Color.FromArgb(63, 98, 18)))
                    {
                        g.FillPolygon(forestBrush, new PointF[] {
                            new PointF(r.X + r.Width * 0.62f, r.Y),
                            new PointF(r.Right, r.Y),
                            new PointF(r.Right, r.Y + r.Height * 0.60f),
                            new PointF(r.X + r.Width * 0.72f, r.Y + r.Height * 0.50f)
                        });
                    }
                    // Emerald wedge
                    using (SolidBrush emeraldBrush = new SolidBrush(Color.FromArgb(21, 128, 61)))
                    {
                        g.FillPolygon(emeraldBrush, new PointF[] {
                            new PointF(r.X + r.Width * 0.62f, r.Y),
                            new PointF(r.X + r.Width * 0.76f, r.Y),
                            new PointF(r.X + r.Width * 0.74f, r.Y + r.Height * 0.60f),
                            new PointF(r.X + r.Width * 0.65f, r.Y + r.Height * 0.45f)
                        });
                    }
                    // Fine line
                    using (Pen fPen = new Pen(Color.FromArgb(120, 75, 85, 99), 1.0f))
                    {
                        g.DrawLine(fPen, r.X + r.Width * 0.62f, r.Y, r.X + r.Width * 0.70f, r.Bottom);
                    }
                    break;

                case "Cyber Wave":
                    // Top ruby wave
                    using (SolidBrush rubyBrush = new SolidBrush(Color.FromArgb(220, 38, 38)))
                    {
                        using (GraphicsPath topP = new GraphicsPath())
                        {
                            topP.AddBezier(r.X, r.Y + 4, r.X + r.Width * 0.3f, r.Y + 1, r.X + r.Width * 0.7f, r.Y, r.Right, r.Y + 3);
                            topP.AddLine(r.Right, r.Y + 3, r.Right, r.Y + 12);
                            topP.AddBezier(r.Right, r.Y + 12, r.X + r.Width * 0.7f, r.Y + 3, r.X + r.Width * 0.3f, r.Y + 8, r.X, r.Y + 15);
                            topP.CloseFigure();
                            g.FillPath(rubyBrush, topP);
                        }
                        // Bottom left ruby wave
                        using (GraphicsPath botRP = new GraphicsPath())
                        {
                            botRP.AddBezier(r.X, r.Y + r.Height * 0.6f, r.X + r.Width * 0.1f, r.Y + r.Height * 0.55f, r.X + r.Width * 0.2f, r.Y + r.Height * 0.75f, r.X + r.Width * 0.35f, r.Bottom);
                            botRP.AddLine(r.X + r.Width * 0.35f, r.Bottom, r.X, r.Bottom);
                            botRP.CloseFigure();
                            g.FillPath(rubyBrush, botRP);
                        }
                    }
                    // Bottom teal wave
                    using (SolidBrush tealB = new SolidBrush(Color.FromArgb(13, 148, 136)))
                    {
                        using (GraphicsPath botTP = new GraphicsPath())
                        {
                            botTP.AddBezier(r.X + r.Width * 0.25f, r.Bottom, r.X + r.Width * 0.5f, r.Y + r.Height * 0.68f, r.X + r.Width * 0.7f, r.Y + r.Height * 0.65f, r.X + r.Width * 0.85f, r.Y + r.Height * 0.75f);
                            botTP.AddLine(r.X + r.Width * 0.85f, r.Y + r.Height * 0.75f, r.X + r.Width * 0.85f, r.Bottom);
                            botTP.AddLine(r.X + r.Width * 0.85f, r.Bottom, r.X + r.Width * 0.25f, r.Bottom);
                            botTP.CloseFigure();
                            g.FillPath(tealB, botTP);
                        }
                    }
                    // Bottom cyan wave
                    using (SolidBrush cyanB = new SolidBrush(Color.FromArgb(6, 182, 212)))
                    {
                        using (GraphicsPath botCP = new GraphicsPath())
                        {
                            botCP.AddBezier(r.X + r.Width * 0.45f, r.Bottom, r.X + r.Width * 0.7f, r.Y + r.Height * 0.60f, r.X + r.Width * 0.85f, r.Y + r.Height * 0.55f, r.Right, r.Y + r.Height * 0.58f);
                            botCP.AddLine(r.Right, r.Y + r.Height * 0.58f, r.Right, r.Bottom);
                            botCP.AddLine(r.Right, r.Bottom, r.X + r.Width * 0.45f, r.Bottom);
                            botCP.CloseFigure();
                            g.FillPath(cyanB, botCP);
                        }
                    }
                    break;

                case "Organic":
                    // Left spine
                    using (SolidBrush spineBrush = new SolidBrush(Color.FromArgb(88, 94, 75)))
                    {
                        g.FillRectangle(spineBrush, r.X, r.Y, 3, r.Height);
                    }
                    // Grass stems
                    using (Pen stemPen = new Pen(Color.FromArgb(120, 125, 101), 1.0f))
                    {
                        g.DrawBezier(stemPen, r.X + 8, r.Bottom, r.X + 6, r.Y + r.Height * 0.7f, r.X + 4, r.Y + r.Height * 0.45f, r.X + 3, r.Y + r.Height * 0.3f);
                        g.DrawBezier(stemPen, r.X + 9, r.Bottom, r.X + 8, r.Y + r.Height * 0.75f, r.X + 7, r.Y + r.Height * 0.5f, r.X + 12, r.Y + r.Height * 0.4f);
                        g.DrawBezier(stemPen, r.X + 10, r.Bottom, r.X + 10, r.Y + r.Height * 0.65f, r.X + 12, r.Y + r.Height * 0.45f, r.X + 16, r.Y + r.Height * 0.35f);
                    }
                    // Crimson Chevron Tab
                    using (SolidBrush crimBrush = new SolidBrush(Color.FromArgb(153, 27, 27)))
                    {
                        g.FillPolygon(crimBrush, new PointF[] {
                            new PointF(r.X, r.Y + r.Height * 0.50f),
                            new PointF(r.X + 12, r.Y + r.Height * 0.50f),
                            new PointF(r.X + 16, r.Y + r.Height * 0.57f),
                            new PointF(r.X + 12, r.Y + r.Height * 0.64f),
                            new PointF(r.X, r.Y + r.Height * 0.64f)
                        });
                    }
                    break;

                case "Cyber Neon":
                    using (Pen cyanPen = new Pen(Color.FromArgb(6, 182, 212), 1.2f))
                    using (Pen purpPen = new Pen(Color.FromArgb(168, 85, 247), 1.0f))
                    {
                        g.DrawRectangle(cyanPen, r.Right - 22, r.Y + 6, 16, 16);
                        g.DrawRectangle(purpPen, r.Right - 16, r.Y + 12, 10, 10);
                        g.DrawLine(cyanPen, r.X, r.Y, r.X, r.Bottom);
                    }
                    break;

                case "Gold Luxury":
                    using (Pen goldPen = new Pen(Color.FromArgb(217, 119, 6), 1.2f))
                    using (SolidBrush shieldB = new SolidBrush(Color.FromArgb(146, 64, 14)))
                    {
                        g.DrawArc(goldPen, r.Right - 22, r.Y + 4, 16, 20, 180, 180);
                        g.FillRectangle(shieldB, r.Right - 18, r.Y + 10, 8, 10);
                        g.DrawRectangle(goldPen, r.Right - 18, r.Y + 10, 8, 10);
                    }
                    break;

                case "Floral Pastel":
                    using (SolidBrush roseB = new SolidBrush(Color.FromArgb(253, 164, 175)))
                    using (SolidBrush greenB = new SolidBrush(Color.FromArgb(16, 185, 129)))
                    {
                        g.FillEllipse(roseB, r.Right - 22, r.Y + 4, 16, 16);
                        g.FillEllipse(greenB, r.Right - 26, r.Y + 14, 8, 8);
                    }
                    break;

                case "Bauhaus":
                    using (SolidBrush redB = new SolidBrush(Color.FromArgb(220, 38, 38)))
                    using (SolidBrush blueB = new SolidBrush(Color.FromArgb(37, 99, 235)))
                    using (SolidBrush blackB = new SolidBrush(Color.FromArgb(17, 24, 39)))
                    {
                        g.FillPie(redB, r.Right - 24, r.Y - 4, 26, 26, 0, 180);
                        g.FillPolygon(blueB, new PointF[] { new PointF(r.Right - 16, r.Y + 12), new PointF(r.Right - 4, r.Y + 24), new PointF(r.Right - 24, r.Y + 24) });
                        g.FillRectangle(blackB, r.Right - 28, r.Y + 14, 4, 12);
                    }
                    break;

                case "Blank":
                    // Pure clean blank white template
                    using (Pen p = new Pen(Color.FromArgb(203, 213, 225), 1.0f) { DashStyle = DashStyle.Dot })
                    {
                        g.DrawRectangle(p, r.X + 6, r.Y + 6, r.Width - 12, 10);
                    }
                    break;

                case "Office":
                    using (SolidBrush topB = new SolidBrush(primCol))
                    using (Pen framePen = new Pen(primCol, 1.0f))
                    {
                        g.FillRectangle(topB, r.X, r.Y, r.Width, 3);
                        g.DrawRectangle(framePen, r.Right - 20, r.Y + 8, 14, 14);
                    }
                    break;

                default:
                    break;
            }

            // 3. Caption text (High contrast for light & dark themes)
            bool isDarkBg = (theme.Name == "Cyber Wave" || theme.Name == "Cyber Neon" || theme.Name == "Gold Luxury" || (lightCol.R * 0.299 + lightCol.G * 0.587 + lightCol.B * 0.114) <= 145);
            using (Font themeFont = new Font("Segoe UI", 6.5f, FontStyle.Bold))
            {
                string tName = theme.Name;
                if (tName.Length > 11) tName = tName.Substring(0, 10) + "..";

                if (isDarkBg)
                {
                    using (SolidBrush shadowB = new SolidBrush(Color.FromArgb(140, 0, 0, 0)))
                    {
                        g.DrawString(tName, themeFont, shadowB, r.X + 4, r.Bottom - 13);
                    }
                    g.DrawString(tName, themeFont, Brushes.White, r.X + 3, r.Bottom - 14);
                }
                else
                {
                    using (SolidBrush textB = new SolidBrush(Color.FromArgb(30, 41, 59)))
                    {
                        g.DrawString(tName, themeFont, textB, r.X + 3, r.Bottom - 14);
                    }
                }
            }

            // 4. Border & Selected badge
            if (isSelected)
            {
                using (Pen bPen = new Pen(Color.FromArgb(234, 88, 12), 2.5f))
                {
                    g.DrawRectangle(bPen, r.X + 1, r.Y + 1, r.Width - 2, r.Height - 2);
                }
                Rectangle badge = new Rectangle(r.Right - 14, r.Y + 2, 12, 10);
                using (SolidBrush bgb = new SolidBrush(Color.FromArgb(234, 88, 12)))
                {
                    g.FillRectangle(bgb, badge);
                }
                g.DrawString("✓", new Font("Segoe UI", 6.0f, FontStyle.Bold), Brushes.White, badge.X + 1, badge.Y);
            }
            else if (isHovered)
            {
                using (Pen hPen = new Pen(Color.FromArgb(59, 130, 246), 1.5f))
                {
                    g.DrawRectangle(hPen, r);
                }
            }
            else
            {
                using (Pen bPen = new Pen(Color.FromArgb(203, 213, 225), 1.0f))
                {
                    g.DrawRectangle(bPen, r);
                }
            }

            g.Restore(state);
        }

        private void DrawPowerPointTabDesign(Graphics g, int width, SlidesView slidesView)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.0f, FontStyle.Bold))
            using (Font titleFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            {
                int startX = 12;
                int cardW = 86;
                int cardH = 62;
                int btnStackW = 20;

                int availW = width - 260 - startX;
                int maxVisibleCards = Math.Max(2, (availW - btnStackW - 12) / (cardW + 6));

                if (slidesView != null && slidesView.Presentation != null)
                {
                    int totalThemes = slidesView.Presentation.Themes.Count;
                    int offset = Math.Max(0, Math.Min(slidesView.ThemeGalleryScrollOffset, totalThemes - maxVisibleCards));
                    slidesView.ThemeGalleryScrollOffset = offset;

                    int x = startX;
                    int renderCount = Math.Min(maxVisibleCards, totalThemes - offset);

                    for (int i = 0; i < renderCount; i++)
                    {
                        PresentationTheme theme = slidesView.Presentation.Themes[offset + i];
                        Rectangle themeBox = new Rectangle(x, 68, cardW, cardH);
                        bool isSel = (slidesView.Presentation.CurrentTheme == theme.Name);

                        DrawThemeMiniCardPreview(g, themeBox, theme, isSel, false);
                        x += cardW + 6;
                    }

                    // 3-Button Stack (▲, ▼, ⮛ More)
                    int stackX = x + 2;
                    Rectangle btnUp = new Rectangle(stackX, 68, btnStackW, 20);
                    Rectangle btnDown = new Rectangle(stackX, 89, btnStackW, 20);
                    Rectangle btnMore = new Rectangle(stackX, 110, btnStackW, 20);

                    DrawInteractiveButton(g, btnUp, false, 2);
                    DrawInteractiveButton(g, btnDown, false, 2);
                    DrawInteractiveButton(g, btnMore, false, 2);

                    using (Font arrowFont = new Font("Segoe UI", 6.5f, FontStyle.Bold))
                    {
                        g.DrawString("▲", arrowFont, Brushes.DimGray, btnUp.X + 4, btnUp.Y + 3);
                        g.DrawString("▼", arrowFont, Brushes.DimGray, btnDown.X + 4, btnDown.Y + 3);
                    }

                    // Draw More Gallery Icon (Line over down-arrow)
                    using (Pen iconPen = new Pen(Color.FromArgb(75, 85, 99), 1.2f))
                    {
                        g.DrawLine(iconPen, btnMore.X + 4, btnMore.Y + 5, btnMore.Right - 4, btnMore.Y + 5);
                        PointF[] arrowPts = new PointF[] {
                            new PointF(btnMore.X + 5, btnMore.Y + 8),
                            new PointF(btnMore.Right - 5, btnMore.Y + 8),
                            new PointF(btnMore.X + btnMore.Width / 2f, btnMore.Y + 14)
                        };
                        using (SolidBrush b = new SolidBrush(Color.FromArgb(75, 85, 99)))
                        {
                            g.FillPolygon(b, arrowPts);
                        }
                    }

                    x = stackX + btnStackW + 10;
                    g.DrawLine(Pens.LightGray, x, 68, x, 148);
                    x += 12;

                    // Slide Size buttons
                    Rectangle btn169 = new Rectangle(x, 68, 86, 26);
                    Rectangle btn43 = new Rectangle(x, 98, 86, 26);

                    bool is169 = slidesView.Presentation.IsWidescreen;
                    DrawInteractiveButton(g, btn169, is169, 3);
                    g.DrawString("16:9 Rộng", labelFont, Brushes.Black, btn169.X + 8, btn169.Y + 6);

                    DrawInteractiveButton(g, btn43, !is169, 3);
                    g.DrawString("4:3 Chuẩn", labelFont, Brushes.Black, btn43.X + 8, btn43.Y + 6);

                    x += 94;
                    g.DrawLine(Pens.LightGray, x + 2, 68, x + 2, 148);
                    x += 10;

                    // Format Background Button ("Định dạng Nền")
                    Rectangle btnFmtBg = new Rectangle(x, 68, 84, 56);
                    bool isFmtBgOpen = (slidesView.IsSidebarOpen && slidesView.SidebarPanel == SidebarPanelType.FormatBackground);
                    DrawInteractiveButton(g, btnFmtBg, isFmtBgOpen, 3);

                    // Draw Paint Bucket Vector Icon
                    DrawFormatBgIconVector(g, btnFmtBg.X + 32, btnFmtBg.Y + 8, Color.FromArgb(210, 71, 38));
                    g.DrawString("Định dạng", labelFont, Brushes.Black, btnFmtBg.X + 16, btnFmtBg.Y + 28);
                    g.DrawString("Nền", boldFont, Brushes.Black, btnFmtBg.X + 30, btnFmtBg.Y + 40);
                }
            }
        }

        private void DrawPowerPointTabTransitions(Graphics g, int width, SlidesView slidesView)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            {
                // ⭐ Preview button
                Rectangle btnPrev = new Rectangle(12, 68, 60, 62);
                DrawInteractiveButton(g, btnPrev, false, 4);
                DrawStarVector(g, 42, 82, 9, Color.FromArgb(245, 158, 11));
                g.DrawString("Xem trước", labelFont, Brushes.Black, 14, 110);

                g.DrawLine(Pens.LightGray, 78, 68, 78, 148);

                // Transitions Quick Gallery (7 visible tiles + 3-Button Stack)
                string[,] transTiles = new string[,] {
                    { "None", "None (Không)" },
                    { "Morph", "Biến hình ⭐" },
                    { "Fade", "Mờ dần" },
                    { "Push", "Đẩy slide" },
                    { "Wipe", "Quét ngang" },
                    { "Split", "Tách đôi" },
                    { "Reveal", "Hiển thị" }
                };

                TransitionType[] transTypes = new TransitionType[] {
                    TransitionType.None, TransitionType.Morph, TransitionType.Fade, TransitionType.Push,
                    TransitionType.Wipe, TransitionType.Split, TransitionType.Reveal
                };
                string[] transNames = new string[] { "Không có", "Biến hình", "Mờ dần", "Đẩy", "Quét", "Tách đôi", "Hiển thị" };

                int tx = 88;
                TransitionType currTrans = (slidesView != null && slidesView.ActiveSlide != null) ? slidesView.ActiveSlide.Transition : TransitionType.None;

                for (int i = 0; i < transTypes.Length; i++)
                {
                    Rectangle tBox = new Rectangle(tx, 68, 70, 58);
                    TransitionType tType = transTypes[i];
                    bool isSel = (currTrans == tType);

                    DrawInteractiveButton(g, tBox, isSel, 4);
                    if (isSel)
                    {
                        using (SolidBrush selBg = new SolidBrush(Color.FromArgb(204, 232, 255)))
                        {
                            g.FillRectangle(selBg, tBox);
                        }
                        using (Pen selPen = new Pen(Color.FromArgb(0, 120, 215), 1.5f))
                        {
                            g.DrawRectangle(selPen, tBox);
                        }
                    }

                    // Vector transition symbol (PowerPoint 365 exact)
                    Rectangle iconRect = new Rectangle(tBox.X + (tBox.Width - 28) / 2, tBox.Y + 8, 28, 18);
                    TransitionIconRenderer.DrawIcon(g, iconRect, tType, isSel);

                    using (Font f = new Font("Segoe UI", 7.5f, isSel ? FontStyle.Bold : FontStyle.Regular))
                    {
                        StringFormat sf = new StringFormat { Alignment = StringAlignment.Center };
                        g.DrawString(transNames[i], f, isSel ? Brushes.Navy : Brushes.Black, new RectangleF(tBox.X, tBox.Y + 36, tBox.Width, 20), sf);
                    }

                    tx += 74;
                }

                // 3-Button Stack for Transitions Gallery (X: tx, Y: 68, W: 18, H: 58)
                DrawGalleryScrollButtons(g, tx, 68, 18, 58);
                tx += 24;

                // Effect Options Button (Tùy chọn hiệu ứng ▾)
                bool hasEffectOptions = (currTrans == TransitionType.Push || currTrans == TransitionType.Wipe ||
                                         currTrans == TransitionType.Split || currTrans == TransitionType.Reveal ||
                                         currTrans == TransitionType.Cover || currTrans == TransitionType.Uncover ||
                                         currTrans == TransitionType.Pan || currTrans == TransitionType.Blinds ||
                                         currTrans == TransitionType.Comb || currTrans == TransitionType.FlyThrough ||
                                         currTrans == TransitionType.Cube || currTrans == TransitionType.Box ||
                                         currTrans == TransitionType.Zoom || currTrans == TransitionType.GenOffice_CanvaFlow ||
                                         currTrans == TransitionType.Morph);

                Rectangle effectOptBox = new Rectangle(tx, 68, 86, 58);
                DrawInteractiveButton(g, effectOptBox, false, 4);

                if (hasEffectOptions)
                {
                    Rectangle iconBox = new Rectangle(effectOptBox.X + (effectOptBox.Width - 24) / 2, 73, 24, 18);
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(37, 99, 235)))
                    using (Pen p = new Pen(Color.FromArgb(30, 64, 175), 1.2f))
                    {
                        g.FillRectangle(b, iconBox);
                        g.DrawRectangle(p, iconBox);
                    }

                    string dirSym = "↑";
                    TransitionDirection cDir = (slidesView != null && slidesView.ActiveSlide != null) ? slidesView.ActiveSlide.TransitionDirection : TransitionDirection.FromBottom;
                    if (currTrans == TransitionType.Morph) dirSym = "★";
                    else if (currTrans == TransitionType.Split) dirSym = (cDir == TransitionDirection.Horizontal) ? "↔" : "↕";
                    else if (currTrans == TransitionType.Blinds || currTrans == TransitionType.Comb) dirSym = (cDir == TransitionDirection.Horizontal) ? "=" : "||";
                    else if (currTrans == TransitionType.FlyThrough || currTrans == TransitionType.Box) dirSym = (cDir == TransitionDirection.In) ? "↘" : "↖";
                    else
                    {
                        if (cDir == TransitionDirection.FromLeft) dirSym = "→";
                        else if (cDir == TransitionDirection.FromRight) dirSym = "←";
                        else if (cDir == TransitionDirection.FromTop) dirSym = "↓";
                        else dirSym = "↑";
                    }

                    using (Font symF = new Font("Segoe UI", 9.0f, FontStyle.Bold))
                    using (Font optFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
                    {
                        StringFormat sfSym = new StringFormat { Alignment = StringAlignment.Center, LineAlignment = StringAlignment.Center };
                        g.DrawString(dirSym, symF, Brushes.White, iconBox, sfSym);
                        g.DrawString("Tùy chọn ▾", optFont, Brushes.Black, effectOptBox.X + 12, 106);
                    }
                }
                else
                {
                    Rectangle iconBox = new Rectangle(effectOptBox.X + (effectOptBox.Width - 24) / 2, 73, 24, 18);
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(240, 242, 245)))
                    using (Pen p = new Pen(Color.FromArgb(200, 205, 210), 1.0f))
                    {
                        g.FillRectangle(b, iconBox);
                        g.DrawRectangle(p, iconBox);
                    }
                    using (Font optFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
                    {
                        g.DrawString("Tùy chọn", optFont, Brushes.DarkGray, effectOptBox.X + 16, 106);
                    }
                }

                tx += 92;
                g.DrawLine(Pens.LightGray, tx, 68, tx, 148);
                tx += 14;

                // Duration Spinner Box & Apply To All
                float dur = (slidesView != null && slidesView.ActiveSlide != null) ? slidesView.ActiveSlide.TransitionDuration : 1.0f;
                Rectangle durBox = new Rectangle(tx, 68, 126, 24);
                DrawInteractiveButton(g, durBox, false, 3);
                g.DrawString("Thời lượng: " + dur.ToString("0.00") + "s", labelFont, Brushes.Black, durBox.X + 6, durBox.Y + 5);

                int spX = durBox.Right - 20;
                Rectangle spUp = new Rectangle(spX, durBox.Y + 1, 19, 10);
                Rectangle spDown = new Rectangle(spX, durBox.Y + 12, 19, 11);
                using (SolidBrush spBg = new SolidBrush(Color.FromArgb(240, 242, 245)))
                using (Pen spPen = new Pen(Color.FromArgb(200, 205, 210), 1f))
                using (Font spFont = new Font("Segoe UI", 5.5f, FontStyle.Bold))
                {
                    g.FillRectangle(spBg, spUp);
                    g.DrawRectangle(spPen, spUp);
                    g.DrawString("▲", spFont, Brushes.Black, spX + 4, spUp.Y);

                    g.FillRectangle(spBg, spDown);
                    g.DrawRectangle(spPen, spDown);
                    g.DrawString("▼", spFont, Brushes.Black, spX + 4, spDown.Y - 1);
                }

                Rectangle btnApplyAll = new Rectangle(tx, 98, 126, 26);
                DrawInteractiveButton(g, btnApplyAll, false, 3);
                g.DrawString("Áp dụng cho tất cả", labelFont, Brushes.Navy, btnApplyAll.X + 12, btnApplyAll.Y + 6);
            }
        }

        private void DrawPowerPointTabAnimations(Graphics g, int width, SlidesView slidesView)
        {
            bool hasSelectedShape = (slidesView != null && (slidesView.SelectedShape != null || (slidesView.SelectedShapeIndices != null && slidesView.SelectedShapeIndices.Count > 0)));
            bool hasAnimations = (slidesView != null && slidesView.ActiveSlide != null && slidesView.ActiveSlide.Animations.Count > 0);

            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            {
                // ⭐ 1. Preview button (Xem trước)
                Rectangle btnPrev = new Rectangle(12, 68, 62, 62);
                DrawInteractiveButton(g, btnPrev, false, 4);
                Color prevStarCol = hasAnimations ? Color.FromArgb(245, 158, 11) : Color.FromArgb(190, 195, 200);
                DrawStarVector(g, 43, 82, 10, prevStarCol);
                g.DrawString("Xem trước", labelFont, hasAnimations ? Brushes.Black : Brushes.Gray, 15, 110);

                g.DrawLine(Pens.LightGray, 80, 68, 80, 148);

                // 2. Animations Quick Gallery (7 visible tiles + 3-Button Stack)
                string[,] animTiles = new string[,] {
                    { "Appear", "Xuất hiện", "Green" },
                    { "FadeIn", "Mờ dần vào", "Green" },
                    { "FlyIn", "Bay vào", "Green" },
                    { "FloatIn", "Trôi nổi", "Green" },
                    { "ZoomIn", "Thu phóng", "Green" },
                    { "Bounce", "Nảy tưng", "Green" },
                    { "Pulse", "Xung nhịp", "Yellow" }
                };

                AnimationType[] quickAnims = new AnimationType[] {
                    AnimationType.Appear,
                    AnimationType.FadeIn,
                    AnimationType.FlyIn,
                    AnimationType.FloatIn,
                    AnimationType.ZoomIn,
                    AnimationType.Bounce,
                    AnimationType.Pulse
                };

                int ax = 88;
                for (int i = 0; i < animTiles.GetLength(0); i++)
                {
                    Rectangle aBox = new Rectangle(ax, 68, 70, 58);
                    DrawInteractiveButton(g, aBox, false, 4);

                    if (hasSelectedShape)
                    {
                        string cat = (animTiles[i, 2] == "Green") ? "Entrance" : "Emphasis";
                        AnimationsGalleryDropDownForm.DrawAnimationVector(g, aBox.X + 35, aBox.Y + 18, quickAnims[i], cat);
                    }
                    else
                    {
                        AnimationsGalleryDropDownForm.DrawStarVector(g, aBox.X + 35, aBox.Y + 18, 9.5f, 4.2f, Color.FromArgb(195, 200, 205), false);
                    }

                    StringFormat sf = new StringFormat { Alignment = StringAlignment.Center };
                    Brush textBrush = hasSelectedShape ? Brushes.Black : Brushes.Gray;
                    g.DrawString(animTiles[i, 1], labelFont, textBrush, new RectangleF(aBox.X, aBox.Y + 34, aBox.Width, 20), sf);
                    ax += 74;
                }

                // 3-Button Stack for Animations Gallery (X: ax, Y: 68, W: 18, H: 58)
                DrawGalleryScrollButtons(g, ax, 68, 18, 58, hasSelectedShape);
                ax += 24;

                // Tùy chọn hiệu ứng ▾ (Effect Options ▾)
                ShapeAnimation selAnimForOpts = (slidesView != null) ? slidesView.SelectedAnimation : null;
                bool hasAnimOptions = (hasSelectedShape && selAnimForOpts != null && ShapeAnimation.HasEffectOptions(selAnimForOpts.Type));
                Rectangle btnEffectOpts = new Rectangle(ax, 68, 92, 62);
                DrawInteractiveButton(g, btnEffectOpts, false, 4);

                Color optIconCol = hasAnimOptions ? Color.FromArgb(37, 99, 235) : Color.FromArgb(195, 200, 205);
                using (Pen optPen = new Pen(optIconCol, 1.8f))
                using (SolidBrush optBrush = new SolidBrush(optIconCol))
                {
                    int ocx = btnEffectOpts.X + 46;
                    int ocy = 82;
                    g.FillEllipse(optBrush, ocx - 3, ocy - 3, 6, 6);
                    g.DrawLine(optPen, ocx, ocy - 3, ocx, ocy - 10);
                    g.DrawLine(optPen, ocx, ocy + 3, ocx, ocy + 10);
                    g.DrawLine(optPen, ocx - 3, ocy, ocx - 10, ocy);
                    g.DrawLine(optPen, ocx + 3, ocy, ocx + 10, ocy);
                }
                g.DrawString("Tùy chọn\nhiệu ứng ▾", labelFont, hasAnimOptions ? Brushes.Black : Brushes.Gray, new RectangleF(btnEffectOpts.X, btnEffectOpts.Y + 30, btnEffectOpts.Width, 30), new StringFormat { Alignment = StringAlignment.Center });
                ax += 98;

                g.DrawLine(Pens.LightGray, ax, 68, ax, 148);
                ax += 14;

                // 3. Advanced Animation: Add Animation Button (Thêm Hoạt Họa ▾)
                Rectangle btnAddAnim = new Rectangle(ax, 68, 104, 62);
                DrawInteractiveButton(g, btnAddAnim, false, 4);

                // Star Vector (Green) + Plus Badge (Orange) -> Gray if no shape selected
                int starCX = btnAddAnim.X + 46;
                int starCY = 82;
                PointF[] starPts = new PointF[10];
                for (int si = 0; si < 10; si++)
                {
                    double a = si * Math.PI / 5.0 - Math.PI / 2.0;
                    float r = (si % 2 == 0) ? 9f : 4f;
                    starPts[si] = new PointF(starCX + (float)(r * Math.Cos(a)), starCY + (float)(r * Math.Sin(a)));
                }
                Color addStarCol = hasSelectedShape ? Color.FromArgb(34, 197, 94) : Color.FromArgb(195, 200, 205);
                using (SolidBrush starBrush = new SolidBrush(addStarCol))
                {
                    g.FillPolygon(starBrush, starPts);
                }
                // Small Plus Badge ➕ (Orange or Gray) on top-right of star
                Color plusCol = hasSelectedShape ? Color.FromArgb(210, 71, 38) : Color.FromArgb(170, 175, 180);
                using (Pen plusPen = new Pen(plusCol, 2.0f))
                {
                    g.DrawLine(plusPen, starCX + 7, starCY - 7, starCX + 13, starCY - 7);
                    g.DrawLine(plusPen, starCX + 10, starCY - 10, starCX + 10, starCY - 4);
                }

                g.DrawString("Thêm Hoạt Họa ▾", boldFont, hasSelectedShape ? Brushes.Black : Brushes.Gray, btnAddAnim.X + 4, 110);
                ax += 110;

                // Animation Pane Toggle Button (Khung Hoạt Họa) - Luôn hiển thị hoạt động
                Rectangle btnAnimPane = new Rectangle(ax, 68, 110, 62);
                bool isPaneOpen = (slidesView != null && slidesView.SidebarPanel == SidebarPanelType.AnimationPane && slidesView.IsSidebarOpen);
                DrawInteractiveButton(g, btnAnimPane, isPaneOpen, 4);

                using (Pen p = new Pen(Color.FromArgb(210, 71, 38), 1.5f))
                using (SolidBrush b = new SolidBrush(Color.FromArgb(210, 71, 38)))
                {
                    g.DrawRectangle(p, btnAnimPane.X + 43, 73, 24, 16);
                    g.FillRectangle(b, btnAnimPane.X + 43, 73, 24, 5);
                }

                g.DrawString("Khung Hoạt Họa", boldFont, isPaneOpen ? Brushes.RoyalBlue : Brushes.Black, btnAnimPane.X + 6, 110);
                ax += 118;

                g.DrawLine(Pens.LightGray, ax, 68, ax, 148);
                ax += 14;

                // 4. Timing Controls (Thời gian & Kích hoạt)
                ShapeAnimation selAnim = (slidesView != null) ? slidesView.SelectedAnimation : null;
                bool isTimingEnabled = (hasSelectedShape && selAnim != null);
                Brush timingTextBrush = isTimingEnabled ? Brushes.Black : Brushes.Gray;

                g.DrawString("Bắt đầu:", labelFont, timingTextBrush, ax, 74);
                Rectangle rTrigger = new Rectangle(ax + 54, 70, 116, 20);
                g.FillRectangle(isTimingEnabled ? Brushes.White : Brushes.GhostWhite, rTrigger);
                g.DrawRectangle(Pens.Silver, rTrigger);
                string trigStr = (selAnim != null)
                    ? ((selAnim.Trigger == AnimationTrigger.OnClick) ? "🖱️ Khi nhấp" : ((selAnim.Trigger == AnimationTrigger.WithPrevious) ? "⏱️ Cùng trước" : "⏳ Sau trước"))
                    : "🖱️ Khi nhấp";
                g.DrawString(trigStr, labelFont, timingTextBrush, rTrigger.X + 4, rTrigger.Y + 2);
                g.DrawString("▾", labelFont, isTimingEnabled ? Brushes.Gray : Brushes.LightGray, rTrigger.Right - 12, rTrigger.Y + 2);

                g.DrawString("Thời lượng:", labelFont, timingTextBrush, ax, 96);
                Rectangle rDur = new Rectangle(ax + 54, 92, 92, 20);
                g.FillRectangle(isTimingEnabled ? Brushes.White : Brushes.GhostWhite, rDur);
                g.DrawRectangle(Pens.Silver, rDur);
                string durStr = (selAnim != null) ? string.Format("{0:0.00} s", selAnim.Duration) : "00.50 s";
                g.DrawString(durStr, labelFont, timingTextBrush, rDur.X + 4, rDur.Y + 2);
                Rectangle rDurUp = new Rectangle(rDur.Right + 2, 92, 20, 9);
                Rectangle rDurDown = new Rectangle(rDur.Right + 2, 102, 20, 9);
                DrawInteractiveButton(g, rDurUp, false, 2);
                DrawInteractiveButton(g, rDurDown, false, 2);
                g.DrawString("▴", labelFont, isTimingEnabled ? Brushes.DimGray : Brushes.LightGray, rDurUp.X + 4, rDurUp.Y - 3);
                g.DrawString("▾", labelFont, isTimingEnabled ? Brushes.DimGray : Brushes.LightGray, rDurDown.X + 4, rDurDown.Y - 3);

                g.DrawString("Độ trễ:", labelFont, timingTextBrush, ax, 118);
                Rectangle rDel = new Rectangle(ax + 54, 114, 92, 20);
                g.FillRectangle(isTimingEnabled ? Brushes.White : Brushes.GhostWhite, rDel);
                g.DrawRectangle(Pens.Silver, rDel);
                string delStr = (selAnim != null) ? string.Format("{0:0.00} s", selAnim.Delay) : "00.00 s";
                g.DrawString(delStr, labelFont, timingTextBrush, rDel.X + 4, rDel.Y + 2);
                Rectangle rDelUp = new Rectangle(rDel.Right + 2, 114, 20, 9);
                Rectangle rDelDown = new Rectangle(rDel.Right + 2, 124, 20, 9);
                DrawInteractiveButton(g, rDelUp, false, 2);
                DrawInteractiveButton(g, rDelDown, false, 2);
                g.DrawString("▴", labelFont, isTimingEnabled ? Brushes.DimGray : Brushes.LightGray, rDelUp.X + 4, rDelUp.Y - 3);
                g.DrawString("▾", labelFont, isTimingEnabled ? Brushes.DimGray : Brushes.LightGray, rDelDown.X + 4, rDelDown.Y - 3);

                ax += 184;
                g.DrawLine(Pens.LightGray, ax, 68, ax, 148);
                ax += 14;

                // 5. Reorder Controls (Sắp xếp thứ tự)
                Rectangle rMoveUp = new Rectangle(ax, 72, 95, 26);
                Rectangle rMoveDown = new Rectangle(ax, 104, 95, 26);
                DrawInteractiveButton(g, rMoveUp, false, 3);
                DrawInteractiveButton(g, rMoveDown, false, 3);
                g.DrawString("▲ Sớm hơn", labelFont, isTimingEnabled ? Brushes.Black : Brushes.Gray, rMoveUp.X + 12, rMoveUp.Y + 5);
                g.DrawString("▼ Muộn hơn", labelFont, isTimingEnabled ? Brushes.Black : Brushes.Gray, rMoveDown.X + 12, rMoveDown.Y + 5);
            }
        }

        private void DrawOfficeCheckbox(Graphics g, int x, int y, bool isChecked, string text, Font font)
        {
            Rectangle boxR = new Rectangle(x, y + 2, 13, 13);
            using (SolidBrush bgB = new SolidBrush(isChecked ? Color.FromArgb(37, 99, 235) : Color.White))
            using (Pen bPen = new Pen(isChecked ? Color.FromArgb(37, 99, 235) : Color.DimGray, 1.2f))
            {
                g.FillRectangle(bgB, boxR);
                g.DrawRectangle(bPen, boxR);
                if (isChecked)
                {
                    using (Pen chkP = new Pen(Color.White, 1.8f))
                    {
                        g.DrawLines(chkP, new Point[] {
                            new Point(boxR.X + 2, boxR.Y + 6),
                            new Point(boxR.X + 5, boxR.Y + 10),
                            new Point(boxR.X + 10, boxR.Y + 3)
                        });
                    }
                }
            }
            g.DrawString(text, font, Brushes.Black, x + 18, y + 1);
        }

        private void DrawPowerPointTabSlideShow(Graphics g, int width, SlidesView slidesView)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            using (Font smallFont = new Font("Segoe UI", 7.0f, FontStyle.Regular))
            using (Font groupFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            {
                int curX = 12;

                // ==================== GROUP 1: Bắt đầu Trình chiếu (Start Slide Show) ====================
                // 1. From Beginning (F5)
                Rectangle btnF5 = new Rectangle(curX, 68, 74, 62);
                DrawInteractiveButton(g, btnF5, false, 4);
                using (Pen p = new Pen(Color.FromArgb(70, 70, 70), 1.4f))
                using (SolidBrush grn = new SolidBrush(Color.FromArgb(22, 163, 74)))
                {
                    g.DrawRectangle(p, btnF5.X + 22, 73, 30, 20);
                    g.DrawLine(p, btnF5.X + 37, 93, btnF5.X + 37, 98);
                    g.DrawLine(p, btnF5.X + 30, 98, btnF5.X + 44, 98);
                    Point[] ply = new Point[] { new Point(btnF5.X + 33, 78), new Point(btnF5.X + 43, 83), new Point(btnF5.X + 33, 88) };
                    g.FillPolygon(grn, ply);
                }
                g.DrawString("Từ đầu", boldFont, Brushes.Black, btnF5.X + 16, 102);
                g.DrawString("(F5)", smallFont, Brushes.DimGray, btnF5.X + 28, 116);
                curX += 78;

                // 2. From Current Slide (Shift+F5)
                Rectangle btnCur = new Rectangle(curX, 68, 86, 62);
                DrawInteractiveButton(g, btnCur, false, 4);
                using (Pen p = new Pen(Color.FromArgb(70, 70, 70), 1.4f))
                using (SolidBrush blu = new SolidBrush(Color.FromArgb(37, 99, 235)))
                using (Pen bPen = new Pen(Color.FromArgb(37, 99, 235), 1.2f))
                {
                    g.DrawRectangle(p, btnCur.X + 28, 73, 30, 20);
                    g.DrawLine(p, btnCur.X + 43, 93, btnCur.X + 43, 98);
                    g.DrawLine(p, btnCur.X + 36, 98, btnCur.X + 50, 98);
                    g.DrawRectangle(bPen, btnCur.X + 33, 76, 18, 12);
                    g.FillRectangle(blu, btnCur.X + 34, 77, 16, 3);
                }
                g.DrawString("Từ trang này", labelFont, Brushes.Black, btnCur.X + 10, 102);
                g.DrawString("(Shift+F5)", smallFont, Brushes.DimGray, btnCur.X + 18, 116);
                curX += 90;

                // 3. Custom Slide Show ▾
                Rectangle btnCustom = new Rectangle(curX, 68, 84, 62);
                DrawInteractiveButton(g, btnCustom, false, 4);
                using (Pen p = new Pen(Color.FromArgb(70, 70, 70), 1.4f))
                using (SolidBrush blu = new SolidBrush(Color.FromArgb(59, 130, 246)))
                {
                    g.DrawRectangle(p, btnCustom.X + 27, 73, 30, 20);
                    g.DrawLine(p, btnCustom.X + 42, 93, btnCustom.X + 42, 98);
                    g.DrawLine(p, btnCustom.X + 35, 98, btnCustom.X + 49, 98);
                    g.FillRectangle(blu, btnCustom.X + 28, 74, 13, 18);
                    g.DrawLine(p, btnCustom.X + 41, 73, btnCustom.X + 41, 93);
                }
                g.DrawString("Tùy chỉnh ▾", labelFont, Brushes.Black, btnCustom.X + 10, 102);
                g.DrawString("Custom Show", smallFont, Brushes.DimGray, btnCustom.X + 8, 116);
                curX += 88;

                // Group 1 Title & Separator
                g.DrawString("Bắt đầu Trình chiếu", groupFont, Brushes.Gray, 12 + (curX - 12) / 2 - 50, 136);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 10;

                // ==================== GROUP 2: Thiết lập (Set Up) ====================
                // 4. Set Up Slide Show
                Rectangle btnSetUp = new Rectangle(curX, 68, 76, 62);
                DrawInteractiveButton(g, btnSetUp, false, 4);
                using (Pen p = new Pen(Color.FromArgb(70, 70, 70), 1.4f))
                using (SolidBrush blu = new SolidBrush(Color.FromArgb(37, 99, 235)))
                using (Pen bPen = new Pen(Color.FromArgb(37, 99, 235), 1.2f))
                using (SolidBrush gearB = new SolidBrush(Color.FromArgb(249, 115, 22)))
                {
                    // Projector screen
                    g.FillRectangle(Brushes.White, btnSetUp.X + 24, 72, 28, 18);
                    g.DrawRectangle(p, btnSetUp.X + 24, 72, 28, 18);
                    g.FillRectangle(blu, btnSetUp.X + 25, 73, 26, 4);
                    // Stand legs
                    g.DrawLine(p, btnSetUp.X + 38, 90, btnSetUp.X + 38, 96);
                    g.DrawLine(p, btnSetUp.X + 30, 96, btnSetUp.X + 46, 96);
                    // Small gear setting badge
                    g.FillEllipse(gearB, btnSetUp.X + 40, 80, 12, 12);
                    g.FillEllipse(Brushes.White, btnSetUp.X + 44, 84, 4, 4);
                }
                g.DrawString("Thiết lập", labelFont, Brushes.Black, btnSetUp.X + 14, 102);
                g.DrawString("Trình chiếu", smallFont, Brushes.DimGray, btnSetUp.X + 11, 116);
                curX += 80;

                // 5. Hide Slide
                bool isSlideHidden = slidesView != null && slidesView.ActiveSlide != null && slidesView.ActiveSlide.IsHidden;
                Rectangle btnHide = new Rectangle(curX, 68, 64, 62);
                DrawInteractiveButton(g, btnHide, isSlideHidden, 4);
                using (Pen p = new Pen(isSlideHidden ? Color.FromArgb(220, 38, 38) : Color.FromArgb(70, 70, 70), 1.4f))
                using (SolidBrush blu = new SolidBrush(Color.FromArgb(59, 130, 246)))
                using (Pen slashP = new Pen(Color.FromArgb(220, 38, 38), 2.0f))
                {
                    g.FillRectangle(Brushes.White, btnHide.X + 18, 73, 28, 20);
                    g.DrawRectangle(p, btnHide.X + 18, 73, 28, 20);
                    Point[] corner = new Point[] { new Point(btnHide.X + 32, 74), new Point(btnHide.X + 45, 74), new Point(btnHide.X + 45, 87) };
                    g.FillPolygon(blu, corner);
                    if (isSlideHidden)
                    {
                        g.DrawLine(slashP, btnHide.X + 15, 70, btnHide.X + 49, 96);
                    }
                }
                g.DrawString("Ẩn Slide", labelFont, isSlideHidden ? Brushes.RoyalBlue : Brushes.Black, btnHide.X + 9, 102);
                g.DrawString(isSlideHidden ? "(Đang ẩn)" : "(Hide)", smallFont, isSlideHidden ? Brushes.RoyalBlue : Brushes.DimGray, btnHide.X + 11, 116);
                curX += 68;

                // 6. Rehearse Timings
                Rectangle btnRehearse = new Rectangle(curX, 68, 76, 62);
                DrawInteractiveButton(g, btnRehearse, slidesView != null && slidesView.IsRehearsingTimings, 4);
                using (Pen p = new Pen(Color.FromArgb(70, 70, 70), 1.4f))
                using (Pen clockPen = new Pen(Color.FromArgb(14, 165, 233), 1.8f))
                using (SolidBrush blu = new SolidBrush(Color.FromArgb(14, 165, 233)))
                {
                    // Slide frame
                    g.FillRectangle(Brushes.White, btnRehearse.X + 20, 73, 26, 18);
                    g.DrawRectangle(p, btnRehearse.X + 20, 73, 26, 18);
                    // Blue clock badge
                    Rectangle clockR = new Rectangle(btnRehearse.X + 32, 77, 18, 18);
                    g.FillEllipse(Brushes.White, clockR);
                    g.DrawEllipse(clockPen, clockR);
                    g.DrawLine(clockPen, clockR.X + 9, clockR.Y + 9, clockR.X + 9, clockR.Y + 4);
                    g.DrawLine(clockPen, clockR.X + 9, clockR.Y + 9, clockR.X + 14, clockR.Y + 9);
                    g.FillEllipse(blu, clockR.X + 7, clockR.Y + 7, 4, 4);
                }
                g.DrawString("Tập dượt", labelFont, Brushes.Black, btnRehearse.X + 12, 102);
                g.DrawString("Thời gian", smallFont, Brushes.DimGray, btnRehearse.X + 14, 116);
                curX += 80;

                // 7. Record Slide Show ▾
                Rectangle btnRecord = new Rectangle(curX, 68, 80, 62);
                DrawInteractiveButton(g, btnRecord, false, 4);
                using (Pen p = new Pen(Color.FromArgb(70, 70, 70), 1.4f))
                using (SolidBrush redB = new SolidBrush(Color.FromArgb(239, 68, 68)))
                using (Pen redP = new Pen(Color.FromArgb(239, 68, 68), 1.8f))
                {
                    g.FillRectangle(Brushes.White, btnRecord.X + 20, 73, 26, 18);
                    g.DrawRectangle(p, btnRecord.X + 20, 73, 26, 18);
                    // Glowing record dot
                    Rectangle recR = new Rectangle(btnRecord.X + 34, 77, 18, 18);
                    g.FillEllipse(Brushes.White, recR);
                    g.DrawEllipse(redP, recR);
                    g.FillEllipse(redB, recR.X + 4, recR.Y + 4, 10, 10);
                }
                g.DrawString("Ghi hình ▾", labelFont, Brushes.Black, btnRecord.X + 12, 102);
                g.DrawString("Record", smallFont, Brushes.DimGray, btnRecord.X + 20, 116);
                curX += 84;

                // 8. Cột 3 Checkboxes (Play Narrations, Use Timings, Show Media Controls)
                bool pNarr = slidesView != null && slidesView.PlayNarrations;
                bool pTime = slidesView != null && slidesView.UseTimings;
                bool pMedia = slidesView != null && slidesView.ShowMediaControls;

                DrawOfficeCheckbox(g, curX, 70, pNarr, "Phát lời thoại (Narrations)", labelFont);
                DrawOfficeCheckbox(g, curX, 90, pTime, "Dùng thời gian (Timings)", labelFont);
                DrawOfficeCheckbox(g, curX, 110, pMedia, "Hiện điều khiển (Controls)", labelFont);
                curX += 165;

                // Group 2 Title & Separator
                g.DrawString("Thiết lập", groupFont, Brushes.Gray, curX - 240, 136);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 10;

                // ==================== GROUP 3: Màn hình (Monitors) ====================
                // Monitor vector icon
                using (Pen monPen = new Pen(Color.FromArgb(37, 99, 235), 1.5f))
                using (SolidBrush monFill = new SolidBrush(Color.FromArgb(239, 246, 255)))
                {
                    Rectangle monR = new Rectangle(curX, 72, 20, 14);
                    g.FillRectangle(monFill, monR);
                    g.DrawRectangle(monPen, monR);
                    g.DrawLine(monPen, curX + 10, 86, curX + 10, 90);
                    g.DrawLine(monPen, curX + 5, 90, curX + 15, 90);
                }
                g.DrawString("Màn hình:", labelFont, Brushes.Black, curX + 24, 72);

                // Combobox Dropdown Button
                Rectangle cboMonRect = new Rectangle(curX + 80, 70, 130, 22);
                DrawInteractiveButton(g, cboMonRect, false, 3);
                string monText = (slidesView != null && slidesView.SelectedMonitorIndex > 0)
                    ? string.Format("Màn hình {0}", slidesView.SelectedMonitorIndex)
                    : "Tự động (Auto)";
                g.DrawString(monText, labelFont, Brushes.Black, cboMonRect.X + 6, cboMonRect.Y + 3);
                g.DrawString("▾", smallFont, Brushes.DimGray, cboMonRect.Right - 14, cboMonRect.Y + 4);

                // Checkbox: Use Presenter View
                bool pView = slidesView != null && slidesView.UsePresenterView;
                DrawOfficeCheckbox(g, curX, 98, pView, "Dùng Chế độ Người Thuyết Trình", labelFont);

                curX += 215;
                // Group 3 Title & Separator
                g.DrawString("Màn hình", groupFont, Brushes.Gray, curX - 140, 136);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            }
        }

        private void DrawPowerPointTabView(Graphics g, int width, SlidesView slidesView)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            {
                int x = 12;
                string[] viewModes = new string[] { "Soạn thảo", "Dàn bài", "Lưới Slide", "Ghi chú", "Slide Master" };

                for (int i = 0; i < viewModes.Length; i++)
                {
                    Rectangle vBox = new Rectangle(x, 68, 76, 62);
                    bool isSel = (slidesView != null && (int)slidesView.ViewMode == i);
                    DrawInteractiveButton(g, vBox, isSel, 4);
                    
                    // Vector View Mode Icons
                    using (Pen p = new Pen(isSel ? Color.FromArgb(210, 71, 38) : Color.DimGray, 1.4f))
                    using (SolidBrush b = new SolidBrush(isSel ? Color.FromArgb(210, 71, 38) : Color.DimGray))
                    {
                        if (i == 0) // Soạn thảo
                        {
                            g.DrawRectangle(p, vBox.X + 26, 73, 24, 16);
                            g.DrawLine(p, vBox.X + 32, 73, vBox.X + 32, 89);
                        }
                        else if (i == 1) // Dàn bài
                        {
                            g.DrawRectangle(p, vBox.X + 26, 73, 24, 16);
                            g.DrawLine(p, vBox.X + 29, 77, vBox.X + 47, 77);
                            g.DrawLine(p, vBox.X + 29, 81, vBox.X + 47, 81);
                            g.DrawLine(p, vBox.X + 29, 85, vBox.X + 43, 85);
                        }
                        else if (i == 2) // Lưới Slide
                        {
                            g.DrawRectangle(p, vBox.X + 26, 73, 10, 7);
                            g.DrawRectangle(p, vBox.X + 40, 73, 10, 7);
                            g.DrawRectangle(p, vBox.X + 26, 83, 10, 7);
                            g.DrawRectangle(p, vBox.X + 40, 83, 10, 7);
                        }
                        else if (i == 3) // Ghi chú
                        {
                            g.DrawRectangle(p, vBox.X + 28, 73, 20, 16);
                            g.DrawLine(p, vBox.X + 32, 82, vBox.X + 44, 82);
                            g.DrawLine(p, vBox.X + 32, 85, vBox.X + 40, 85);
                        }
                        else if (i == 4) // Slide Master
                        {
                            g.DrawRectangle(p, vBox.X + 26, 73, 24, 16);
                            DrawStarVector(g, vBox.X + 38, 81, 5, Color.FromArgb(245, 158, 11));
                        }
                    }

                    g.DrawString(viewModes[i], labelFont, isSel ? Brushes.RoyalBlue : Brushes.Black, vBox.X + 6, 110);
                    x += 82;
                }
            }
        }

        private void DrawPowerPointTabTableDesign(Graphics g, int width, SlidesView slidesView)
        {
            if (slidesView == null || slidesView.SelectedShape == null || slidesView.SelectedShape.Type != ShapeType.Table) return;
            ShapeNode shape = slidesView.SelectedShape;

            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.5f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            {
                int curX = 12;

                // ==================== Group 1: Tùy chọn Kiểu Bảng (Table Style Options) ====================
                Rectangle grp1Header = new Rectangle(curX, 68, 105, 25);
                DrawInteractiveButton(g, grp1Header, shape.TableHeaderRow, 3);
                g.DrawString(shape.TableHeaderRow ? "☑ Hàng Tiêu đề" : "☐ Hàng Tiêu đề", btnFont, shape.TableHeaderRow ? Brushes.Navy : Brushes.Black, curX + 4, 72);

                Rectangle grp1Banded = new Rectangle(curX, 96, 105, 25);
                DrawInteractiveButton(g, grp1Banded, shape.TableBandedRows, 3);
                g.DrawString(shape.TableBandedRows ? "☑ Hàng Xen kẽ" : "☐ Hàng Xen kẽ", btnFont, shape.TableBandedRows ? Brushes.Navy : Brushes.Black, curX + 4, 100);

                curX += 112;
                g.DrawString("Tùy chọn Kiểu", labelFont, Brushes.Gray, curX - 100, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 10;

                // ==================== Group 2: Kiểu Bảng (Table Styles Gallery - 6 Visual Cards) ====================
                int[][] presetStyles = new int[][] {
                    new int[] { 0x2563EB, 0xEFF6FF, 0x93C5FD }, // 0. Blue
                    new int[] { 0xEA580C, 0xFFF7ED, 0xFDBA74 }, // 1. Orange
                    new int[] { 0x059669, 0xECFDF5, 0x6EE7B7 }, // 2. Green
                    new int[] { 0x7C3AED, 0xF5F3FF, 0xC4B5FD }, // 3. Purple
                    new int[] { 0x1E293B, 0xF1F5F9, 0x94A3B8 }, // 4. Dark Slate
                    new int[] { 0xDC2626, 0xFFF1F2, 0xFCA5A5 }  // 5. Ruby Red
                };

                int cardW = 38;
                for (int pIdx = 0; pIdx < presetStyles.Length; pIdx++)
                {
                    Rectangle cardBox = new Rectangle(curX + pIdx * (cardW + 5), 68, cardW, 54);
                    DrawInteractiveButton(g, cardBox, false, 4);

                    Rectangle inner = new Rectangle(cardBox.X + 3, cardBox.Y + 3, cardBox.Width - 6, cardBox.Height - 6);
                    Color pHead = Color.FromArgb(255, Color.FromArgb(presetStyles[pIdx][0]));
                    Color pBanded = Color.FromArgb(255, Color.FromArgb(presetStyles[pIdx][1]));
                    Color pBorder = Color.FromArgb(255, Color.FromArgb(presetStyles[pIdx][2]));

                    // Mini table drawing inside card
                    using (SolidBrush hBrush = new SolidBrush(pHead))
                    using (SolidBrush bBrush = new SolidBrush(pBanded))
                    using (Pen bPen = new Pen(pBorder, 1f))
                    {
                        // Header row (height 14px)
                        g.FillRectangle(hBrush, inner.X, inner.Y, inner.Width, 14);
                        // Row 2 (even/white)
                        g.FillRectangle(Brushes.White, inner.X, inner.Y + 14, inner.Width, 16);
                        // Row 3 (odd/banded)
                        g.FillRectangle(bBrush, inner.X, inner.Y + 30, inner.Width, inner.Height - 30);
                        // Gridlines
                        g.DrawLine(bPen, inner.X + inner.Width / 2, inner.Y, inner.X + inner.Width / 2, inner.Bottom);
                        g.DrawLine(bPen, inner.X, inner.Y + 14, inner.Right, inner.Y + 14);
                        g.DrawLine(bPen, inner.X, inner.Y + 30, inner.Right, inner.Y + 30);
                        g.DrawRectangle(bPen, inner);
                    }
                }
                curX += presetStyles.Length * (cardW + 5) + 6;

                // Stack: Tô màu ô (Shading), Viền bảng (Borders)
                Rectangle fillBtn = new Rectangle(curX, 68, 106, 24);
                DrawInteractiveButton(g, fillBtn, false, 3);
                Color curFill = Color.FromArgb(255, Color.FromArgb(shape.FillColor));
                using (SolidBrush swB = new SolidBrush(shape.FillColor == 0x00FFFFFF ? Color.White : curFill))
                using (Pen swP = new Pen(Color.DimGray, 1f))
                {
                    g.FillRectangle(swB, fillBtn.X + 6, fillBtn.Y + 5, 14, 14);
                    g.DrawRectangle(swP, fillBtn.X + 6, fillBtn.Y + 5, 14, 14);
                }
                g.DrawString("Tô màu ô ▾", btnFont, Brushes.Black, fillBtn.X + 24, fillBtn.Y + 3);

                Rectangle borderBtn = new Rectangle(curX, 94, 106, 24);
                DrawInteractiveButton(g, borderBtn, false, 3);
                Color curStroke = Color.FromArgb(255, Color.FromArgb(shape.StrokeColor));
                using (Pen swP = new Pen(curStroke == Color.Transparent ? Color.Gray : curStroke, 2f))
                {
                    g.DrawRectangle(swP, borderBtn.X + 6, borderBtn.Y + 5, 14, 14);
                }
                g.DrawString("Viền ô ▾", btnFont, Brushes.Black, borderBtn.X + 24, borderBtn.Y + 3);

                curX += 114;
                g.DrawString("Kiểu Bảng", labelFont, Brushes.Gray, curX - 220, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 10;

                // ==================== Group 3: Định dạng Chữ (Font & Text Formatting) ====================
                Rectangle textColBtn = new Rectangle(curX, 68, 86, 25);
                DrawInteractiveButton(g, textColBtn, false, 3);
                g.DrawString("A", boldFont, Brushes.DarkRed, curX + 6, 72);
                g.DrawString("Màu chữ ▾", btnFont, Brushes.Black, curX + 22, 72);

                Rectangle boldBtn = new Rectangle(curX, 96, 40, 25);
                DrawInteractiveButton(g, boldBtn, false, 3);
                g.DrawString("B", boldFont, Brushes.Navy, curX + 12, 100);

                Rectangle italicBtn = new Rectangle(curX + 44, 96, 42, 25);
                DrawInteractiveButton(g, italicBtn, false, 3);
                using (Font itFont = new Font("Segoe UI", 8.5f, FontStyle.Italic | FontStyle.Bold))
                {
                    g.DrawString("I", itFont, Brushes.Navy, curX + 58, 100);
                }

                curX += 94;
                g.DrawString("Định dạng Chữ", labelFont, Brushes.Gray, curX - 90, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 10;

                // ==================== Group 4: Chèn Hàng & Cột (Insert Rows & Columns) ====================
                Rectangle insRowAbove = new Rectangle(curX, 68, 88, 25);
                DrawInteractiveButton(g, insRowAbove, false, 3);
                g.DrawString("▲ Chèn Trên", btnFont, Brushes.Black, curX + 4, 72);

                Rectangle insRowBelow = new Rectangle(curX, 96, 88, 25);
                DrawInteractiveButton(g, insRowBelow, false, 3);
                g.DrawString("▼ Chèn Dưới", btnFont, Brushes.Black, curX + 4, 100);

                Rectangle insColLeft = new Rectangle(curX + 92, 68, 88, 25);
                DrawInteractiveButton(g, insColLeft, false, 3);
                g.DrawString("◀ Chèn Trái", btnFont, Brushes.Black, curX + 96, 72);

                Rectangle insColRight = new Rectangle(curX + 92, 96, 88, 25);
                DrawInteractiveButton(g, insColRight, false, 3);
                g.DrawString("▶ Chèn Phải", btnFont, Brushes.Black, curX + 96, 100);

                curX += 188;
                g.DrawString("Hàng & Cột", labelFont, Brushes.Gray, curX - 176, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 10;

                // ==================== Group 5: Xóa (Delete) ====================
                Rectangle delRowBtn = new Rectangle(curX, 68, 78, 25);
                DrawInteractiveButton(g, delRowBtn, false, 3);
                g.DrawString("❌ Xóa Hàng", btnFont, Brushes.DarkRed, curX + 4, 72);

                Rectangle delColBtn = new Rectangle(curX, 96, 78, 25);
                DrawInteractiveButton(g, delColBtn, false, 3);
                g.DrawString("❌ Xóa Cột", btnFont, Brushes.DarkRed, curX + 4, 100);

                Rectangle delTableBtn = new Rectangle(curX + 82, 68, 86, 53);
                DrawInteractiveButton(g, delTableBtn, false, 4);
                g.DrawString("🗑️", boldFont, Brushes.DarkRed, curX + 90, 82);
                g.DrawString("Xóa Bảng", boldFont, Brushes.DarkRed, curX + 110, 77);
                g.DrawString("Delete", labelFont, Brushes.Gray, curX + 110, 95);

                curX += 176;
                g.DrawString("Thao tác Xóa", labelFont, Brushes.Gray, curX - 164, 137);
            }
        }

        #region PowerPoint Picture Format Helpers
        private void DrawMarkKeepIconVector(Graphics g, int x, int y, int w, int h)
        {
            // Green pencil + plus sign in circle badge
            using (SolidBrush bgB = new SolidBrush(Color.FromArgb(220, 252, 231)))
            using (Pen p = new Pen(Color.FromArgb(34, 197, 94), 1.8f))
            {
                g.FillEllipse(bgB, x, y, w, h);
                g.DrawEllipse(p, x, y, w, h);
                // Pencil body
                g.DrawLine(p, x + 5, y + h - 5, x + w - 7, y + 7);
                // Plus sign
                g.DrawLine(p, x + w - 7, y + 3, x + w - 7, y + 9);
                g.DrawLine(p, x + w - 10, y + 6, x + w - 4, y + 6);
            }
        }

        private void DrawMarkRemoveIconVector(Graphics g, int x, int y, int w, int h)
        {
            // Red pencil + minus sign in circle badge
            using (SolidBrush bgB = new SolidBrush(Color.FromArgb(254, 226, 226)))
            using (Pen p = new Pen(Color.FromArgb(239, 68, 68), 1.8f))
            {
                g.FillEllipse(bgB, x, y, w, h);
                g.DrawEllipse(p, x, y, w, h);
                // Pencil body
                g.DrawLine(p, x + 5, y + h - 5, x + w - 7, y + 7);
                // Minus sign
                g.DrawLine(p, x + w - 10, y + 6, x + w - 4, y + 6);
            }
        }

        private void DrawDeleteMarkIconVector(Graphics g, int x, int y, int w, int h)
        {
            using (Pen p = new Pen(Color.FromArgb(100, 116, 139), 1.6f))
            using (Pen redX = new Pen(Color.FromArgb(239, 68, 68), 1.8f))
            {
                g.DrawRectangle(p, x + 4, y + 5, w - 8, h - 10);
                g.DrawLine(redX, x + 6, y + 7, x + w - 6, y + h - 7);
                g.DrawLine(redX, x + w - 6, y + 7, x + 6, y + h - 7);
            }
        }

        private void DrawDiscardIconVector(Graphics g, int x, int y, int w, int h)
        {
            using (Pen p = new Pen(Color.FromArgb(100, 116, 139), 1.6f))
            {
                g.DrawLine(p, x + 4, y + 6, x + w - 4, y + 6);
                g.DrawLine(p, x + 8, y + 3, x + w - 8, y + 3);
                g.DrawRectangle(p, x + 6, y + 7, w - 12, h - 10);
                g.DrawLine(p, x + 10, y + 10, x + 10, y + h - 6);
                g.DrawLine(p, x + w - 10, y + 10, x + w - 10, y + h - 6);
            }
        }

        private void DrawKeepChangesIconVector(Graphics g, int x, int y, int w, int h)
        {
            using (Pen p = new Pen(Color.FromArgb(22, 163, 74), 2.8f))
            {
                p.StartCap = LineCap.Round;
                p.EndCap = LineCap.Round;
                g.DrawLine(p, x + 3, y + h / 2, x + w / 3 + 1, y + h - 4);
                g.DrawLine(p, x + w / 3 + 1, y + h - 4, x + w - 3, y + 4);
            }
        }

        private void DrawPowerPointTabBackgroundRemoval(Graphics g, int width, SlidesView slidesView)
        {
            using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
            using (Font btnFont = new Font("Segoe UI", 8.2f, FontStyle.Regular))
            using (Font boldFont = new Font("Segoe UI", 8.2f, FontStyle.Bold))
            {
                int curX = 12;

                // ==================== Nhóm 1: Tự động & Phông xanh ====================
                // 1. Xóa tự động (Auto Remove) (X: curX..curX+86)
                Rectangle autoBtn = new Rectangle(curX, 68, 86, 54);
                DrawInteractiveButton(g, autoBtn, false, 4);
                DrawAutoBgWandVector(g, autoBtn.X + 31, autoBtn.Y + 6, 24, 24);
                g.DrawString("Xóa tự động", boldFont, Brushes.Black, autoBtn.X + 8, autoBtn.Y + 34);
                curX += 92;

                // 2. Chọn màu xóa (Chroma Key CapCut) (X: curX..curX+92)
                Rectangle pickBtn = new Rectangle(curX, 68, 92, 54);
                bool isPickActive = (slidesView != null && slidesView.IsColorPickingMode);
                DrawInteractiveButton(g, pickBtn, isPickActive, 4);
                DrawChromaKeyPenVector(g, pickBtn.X + 34, pickBtn.Y + 6, 24, 24);
                g.DrawString("Chọn màu xóa", isPickActive ? boldFont : btnFont, isPickActive ? Brushes.DarkBlue : Brushes.Black, pickBtn.X + 8, pickBtn.Y + 34);
                curX += 98;

                g.DrawString("Tự động", labelFont, Brushes.Gray, 12 + (curX - 12 - 50) / 2, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==================== Nhóm 2: Tinh chỉnh (Refine) ====================
                // 3. Mark Areas to Keep (Giữ vùng +) (X: curX..curX+96)
                Rectangle keepBtn = new Rectangle(curX, 68, 96, 54);
                bool isKeepActive = (slidesView != null && slidesView.BgRemovalTool == "Keep" && !slidesView.IsColorPickingMode);
                DrawInteractiveButton(g, keepBtn, isKeepActive, 4);
                DrawMarkKeepIconVector(g, keepBtn.X + 37, keepBtn.Y + 6, 22, 22);
                g.DrawString("Giữ vùng (+)", isKeepActive ? boldFont : btnFont, isKeepActive ? Brushes.DarkGreen : Brushes.Black, keepBtn.X + 14, keepBtn.Y + 34);
                curX += 102;

                // 4. Mark Areas to Remove (Xóa vùng -) (X: curX..curX+96)
                Rectangle removeBtn = new Rectangle(curX, 68, 96, 54);
                bool isRemoveActive = (slidesView != null && slidesView.BgRemovalTool == "Remove" && !slidesView.IsColorPickingMode);
                DrawInteractiveButton(g, removeBtn, isRemoveActive, 4);
                DrawMarkRemoveIconVector(g, removeBtn.X + 37, removeBtn.Y + 6, 22, 22);
                g.DrawString("Xóa vùng (-)", isRemoveActive ? boldFont : btnFont, isRemoveActive ? Brushes.DarkRed : Brushes.Black, removeBtn.X + 14, removeBtn.Y + 34);
                curX += 102;

                // 5. Delete Mark (Xóa dấu) (X: curX..curX+78)
                Rectangle delMarkBtn = new Rectangle(curX, 68, 78, 54);
                DrawInteractiveButton(g, delMarkBtn, false, 4);
                DrawDeleteMarkIconVector(g, delMarkBtn.X + 28, delMarkBtn.Y + 6, 22, 22);
                g.DrawString("Xóa dấu", btnFont, Brushes.Black, delMarkBtn.X + 16, delMarkBtn.Y + 34);
                curX += 84;

                g.DrawString("Tinh chỉnh (Refine)", labelFont, Brushes.Gray, curX - 280 + (280 - 100) / 2, 137);
                g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
                curX += 12;

                // ==================== Nhóm 3: Đóng (Close) ====================
                // 6. Discard All Changes (Hủy thay đổi) (X: curX..curX+94)
                Rectangle discardBtn = new Rectangle(curX, 68, 94, 54);
                DrawInteractiveButton(g, discardBtn, false, 4);
                DrawDiscardIconVector(g, discardBtn.X + 36, discardBtn.Y + 6, 22, 22);
                g.DrawString("Hủy thay đổi", btnFont, Brushes.Black, discardBtn.X + 12, discardBtn.Y + 34);
                curX += 100;

                // 7. Keep Changes (Giữ thay đổi) (X: curX..curX+94)
                Rectangle keepChangesBtn = new Rectangle(curX, 68, 94, 54);
                DrawInteractiveButton(g, keepChangesBtn, false, 4);
                DrawKeepChangesIconVector(g, keepChangesBtn.X + 36, keepChangesBtn.Y + 6, 22, 22);
                g.DrawString("Giữ thay đổi", boldFont, Brushes.DarkGreen, keepChangesBtn.X + 12, keepChangesBtn.Y + 34);
                int group3Right = curX + 94;

                g.DrawString("Đóng (Close)", labelFont, Brushes.Gray, curX - 100 + (group3Right - (curX - 100) - 60) / 2, 137);
            }
        }

        private void DrawAutoBgWandVector(Graphics g, int x, int y, int w, int h)
        {
            // Thân đũa phép AI ma thuật màu tím Cyberpunk
            using (Pen wandPen = new Pen(Color.FromArgb(147, 51, 234), 2.4f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
            {
                g.DrawLine(wandPen, x + 3, y + h - 3, x + w - 7, y + 7);
            }
            // Đầu đũa phép màu vàng sáng
            using (SolidBrush tipB = new SolidBrush(Color.FromArgb(250, 204, 21)))
            {
                g.FillEllipse(tipB, x + w - 9, y + 5, 5, 5);
            }
            // Ngôi sao phát sáng Cyberpunk Cyan & Yellow
            DrawStarVector(g, x + w - 4, y + 4, 5, Color.FromArgb(6, 182, 212));
            DrawStarVector(g, x + 5, y + 6, 3, Color.FromArgb(245, 158, 11));
            DrawStarVector(g, x + w - 5, y + h - 7, 3, Color.FromArgb(168, 85, 247));
        }

        private void DrawChromaKeyPenVector(Graphics g, int x, int y, int w, int h)
        {
            // Vòng tròn mẫu màu phông xanh CapCut (Chroma Green & Cyan)
            using (SolidBrush chromaB = new SolidBrush(Color.FromArgb(34, 197, 94)))
            using (Pen borderP = new Pen(Color.FromArgb(22, 101, 52), 1.2f))
            {
                g.FillEllipse(chromaB, x + 2, y + h - 12, 10, 10);
                g.DrawEllipse(borderP, x + 2, y + h - 12, 10, 10);
            }

            // Cây bút hút màu CapCut (Eyedropper Pen) màu xanh ngọc Electric
            using (Pen penP = new Pen(Color.FromArgb(14, 165, 233), 2.2f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
            {
                g.DrawLine(penP, x + 6, y + h - 7, x + w - 4, y + 4);
            }
            // Nắp/bóng hút màu trên đỉnh
            using (SolidBrush topB = new SolidBrush(Color.FromArgb(2, 132, 199)))
            {
                g.FillEllipse(topB, x + w - 7, y + 2, 6, 6);
            }
            // Giọt màu lơ lửng
            DrawStarVector(g, x + w - 2, y + 8, 3, Color.FromArgb(16, 185, 129));
        }

        private void DrawRefineBgVector(Graphics g, int x, int y, int w, int h)
        {
            using (Pen p = new Pen(Color.FromArgb(234, 88, 12), 1.8f))
            {
                g.DrawLine(p, x + 4, y + h - 4, x + w - 8, y + 8);
            }
            DrawStarVector(g, x + w - 6, y + 6, 4, Color.FromArgb(245, 158, 11));
            DrawStarVector(g, x + 6, y + 8, 3, Color.FromArgb(59, 130, 246));
        }

        private void DrawSunVector(Graphics g, int cx, int cy, int size, Color col)
        {
            int r = size / 3;
            using (SolidBrush b = new SolidBrush(col))
            using (Pen p = new Pen(col, 1.6f))
            {
                g.FillEllipse(b, cx - r, cy - r, r * 2, r * 2);
                for (int angle = 0; angle < 360; angle += 45)
                {
                    double rad = angle * Math.PI / 180.0;
                    float x1 = cx + (float)(Math.Cos(rad) * (r + 2));
                    float y1 = cy + (float)(Math.Sin(rad) * (r + 2));
                    float x2 = cx + (float)(Math.Cos(rad) * (r + 5));
                    float y2 = cy + (float)(Math.Sin(rad) * (r + 5));
                    g.DrawLine(p, x1, y1, x2, y2);
                }
            }
        }

        private void DrawPaletteVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.4f))
            {
                g.DrawEllipse(p, x, y, w, h);
                using (SolidBrush b1 = new SolidBrush(Color.FromArgb(239, 68, 68))) g.FillEllipse(b1, x + 3, y + 3, 3, 3);
                using (SolidBrush b2 = new SolidBrush(Color.FromArgb(245, 158, 11))) g.FillEllipse(b2, x + 8, y + 3, 3, 3);
                using (SolidBrush b3 = new SolidBrush(Color.FromArgb(34, 197, 94))) g.FillEllipse(b3, x + 4, y + 8, 3, 3);
            }
        }

        private void DrawArtisticWandVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.5f))
            {
                g.DrawLine(p, x + 2, y + h - 2, x + w - 4, y + 4);
                DrawStarVector(g, x + w - 3, y + 3, 3, Color.FromArgb(234, 88, 12));
            }
        }

        private void DrawTransparencyGridVector(Graphics g, int x, int y, int w, int h)
        {
            using (SolidBrush bg = new SolidBrush(Color.White)) g.FillRectangle(bg, x, y, w, h);
            using (SolidBrush cb = new SolidBrush(Color.FromArgb(180, 180, 180)))
            {
                int step = 3;
                for (int r = 0; r < h; r += step)
                {
                    for (int c = 0; c < w; c += step)
                    {
                        if (((r / step) + (c / step)) % 2 == 0)
                        {
                            g.FillRectangle(cb, x + c, y + r, Math.Min(step, w - c), Math.Min(step, h - r));
                        }
                    }
                }
            }
            using (Pen p = new Pen(Color.FromArgb(120, 120, 120), 1f))
            {
                g.DrawRectangle(p, x, y, w, h);
            }
        }

        private void DrawCompressVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.4f))
            {
                g.DrawRectangle(p, x + 2, y + 2, w - 4, h - 4);
                g.DrawLine(p, x, y, x + 4, y + 4);
                g.DrawLine(p, x + w, y + h, x + w - 4, y + h - 4);
            }
        }

        private void DrawChangePicVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.2f))
            {
                g.DrawRectangle(p, x, y, w - 2, h - 2);
                g.DrawLine(p, x + 2, y + h - 5, x + 5, y + 5);
                g.DrawLine(p, x + 5, y + 5, x + w - 4, y + h - 5);
            }
        }

        private void DrawBorderVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.8f))
            {
                g.DrawRectangle(p, x + 1, y + 1, w - 2, h - 2);
            }
        }

        private void DrawLayoutGridVector(Graphics g, int x, int y, int w, int h, Color col)
        {
            using (Pen p = new Pen(col, 1.2f))
            {
                g.DrawRectangle(p, x, y, (w - 2) / 2, (h - 2) / 2);
                g.DrawRectangle(p, x + w / 2, y, (w - 2) / 2, (h - 2) / 2);
                g.DrawRectangle(p, x, y + h / 2, (w - 2) / 2, (h - 2) / 2);
                g.DrawRectangle(p, x + w / 2, y + h / 2, (w - 2) / 2, (h - 2) / 2);
            }
        }

        private void DrawAltTextVector(Graphics g, int x, int y, int w, int h)
        {
            using (Pen p = new Pen(Color.FromArgb(37, 99, 235), 1.4f))
            using (SolidBrush b = new SolidBrush(Color.FromArgb(240, 246, 255)))
            {
                Rectangle r = new Rectangle(x, y, w, h);
                g.FillRectangle(b, r);
                g.DrawRectangle(p, r);
                using (Pen lp = new Pen(Color.FromArgb(37, 99, 235), 1.2f))
                {
                    g.DrawLine(lp, x + 4, y + 7, x + w - 4, y + 7);
                    g.DrawLine(lp, x + 4, y + 12, x + w - 4, y + 12);
                    g.DrawLine(lp, x + 4, y + 17, x + w - 10, y + 17);
                }
            }
        }

        private void DrawCropVector(Graphics g, int cx, int cy, int size, Color col)
        {
            int h = size / 2;
            using (Pen p = new Pen(col, 2.2f))
            {
                // Top-Left crop corner
                g.DrawLine(p, cx - h, cy - h + 5, cx - h, cy - h);
                g.DrawLine(p, cx - h, cy - h, cx - h + 5, cy - h);
                // Bottom-Right crop corner
                g.DrawLine(p, cx + h, cy + h - 5, cx + h, cy + h);
                g.DrawLine(p, cx + h, cy + h, cx + h - 5, cy + h);
                // Inner frame
                using (Pen thin = new Pen(Color.Gray, 1f) { DashStyle = DashStyle.Dash })
                {
                    g.DrawRectangle(thin, cx - h + 2, cy - h + 2, size - 4, size - 4);
                }
            }
        }

        private void DrawPictureStyleThumbnail(Graphics g, Rectangle r, int styleIdx, Image img)
        {
            Rectangle inner = new Rectangle(r.X + 3, r.Y + 4, r.Width - 6, r.Height - 8);

            // Thumbnail sky & mountain gradient
            using (LinearGradientBrush sky = new LinearGradientBrush(inner, Color.FromArgb(56, 189, 248), Color.FromArgb(2, 132, 199), 90f))
            {
                g.FillRectangle(sky, inner);
            }
            using (SolidBrush sunB = new SolidBrush(Color.FromArgb(254, 240, 138)))
            {
                g.FillEllipse(sunB, inner.X + 4, inner.Y + 4, 6, 6);
            }
            using (SolidBrush mtnB = new SolidBrush(Color.FromArgb(16, 185, 129)))
            {
                Point[] mtn = new Point[] {
                    new Point(inner.X, inner.Bottom),
                    new Point(inner.X + inner.Width / 2, inner.Y + inner.Height / 3),
                    new Point(inner.Right, inner.Bottom)
                };
                g.FillPolygon(mtnB, mtn);
            }

            // Frame Styles
            if (styleIdx == 1) // Simple White
            {
                using (Pen p = new Pen(Color.White, 2f)) g.DrawRectangle(p, inner);
            }
            else if (styleIdx == 2) // Matte Dual
            {
                using (Pen p1 = new Pen(Color.FromArgb(220, 220, 220), 3f))
                using (Pen p2 = new Pen(Color.FromArgb(80, 80, 80), 1f))
                {
                    g.DrawRectangle(p1, inner);
                    g.DrawRectangle(p2, inner);
                }
            }
            else if (styleIdx == 3) // Metal
            {
                using (Pen p = new Pen(Color.FromArgb(203, 213, 225), 3f)) g.DrawRectangle(p, inner);
            }
            else if (styleIdx == 4) // Drop Shadow
            {
                using (SolidBrush sh = new SolidBrush(Color.FromArgb(60, 0, 0, 0))) g.FillRectangle(sh, inner.X + 2, inner.Y + 2, inner.Width, inner.Height);
                using (Pen p = new Pen(Color.White, 1f)) g.DrawRectangle(p, inner);
            }
            else if (styleIdx == 5) // Soft Edge
            {
                using (Pen p = new Pen(Color.FromArgb(150, 255, 255, 255), 2f)) g.DrawRectangle(p, inner);
            }
            else if (styleIdx == 6) // Double Frame
            {
                using (Pen p1 = new Pen(Color.FromArgb(37, 99, 235), 1.5f))
                using (Pen p2 = new Pen(Color.White, 1f))
                {
                    g.DrawRectangle(p1, inner);
                    g.DrawRectangle(p2, inner.X + 2, inner.Y + 2, inner.Width - 4, inner.Height - 4);
                }
            }
            else if (styleIdx == 7) // Beveled Oval
            {
                using (Pen p = new Pen(Color.White, 2f)) g.DrawEllipse(p, inner);
            }
        }
        #endregion

        private void DrawRemoveBgVector(Graphics g, int x, int y, int w, int h)
        {
            // Biểu tượng Xóa nền chuẩn PowerPoint (Person Silhouette with Magenta Background Removal)
            Rectangle rect = new Rectangle(x, y, w, h);
            using (SolidBrush bgB = new SolidBrush(Color.FromArgb(236, 72, 153)))
            {
                g.FillRectangle(bgB, rect);
            }
            using (SolidBrush headB = new SolidBrush(Color.White))
            {
                g.FillEllipse(headB, x + w / 2 - 4, y + 3, 8, 8);
                g.FillPie(headB, x + 2, y + 10, w - 4, h - 8, 180, 180);
            }
            DrawStarVector(g, x + w - 4, y + 4, 3, Color.FromArgb(250, 204, 21));
        }

