        private void DrawPowerPointCheckBox(Graphics g, int x, int y, int width, int height, bool isChecked, string text)
        {
            Rectangle boxRect = new Rectangle(x + 2, y + 2, 13, 13);
            DrawInteractiveButton(g, boxRect, false, 2);
            using (Pen borderPen = new Pen(Color.FromArgb(148, 163, 184), 1.2f))
            {
                g.DrawRectangle(borderPen, boxRect);
            }
            if (isChecked)
            {
                using (SolidBrush fillBrush = new SolidBrush(Color.FromArgb(37, 99, 235)))
                {
                    g.FillRectangle(fillBrush, boxRect.X + 2, boxRect.Y + 2, boxRect.Width - 3, boxRect.Height - 3);
                }
                using (Pen checkPen = new Pen(Color.White, 1.8f))
                {
                    g.DrawLines(checkPen, new PointF[] {
                        new PointF(boxRect.X + 3.5f, boxRect.Y + 6.5f),
                        new PointF(boxRect.X + 5.5f, boxRect.Y + 9.5f),
                        new PointF(boxRect.X + 9.5f, boxRect.Y + 4.0f)
                    });
                }
            }
            using (Font f = new Font("Segoe UI", 7.8f))
            {
                g.DrawString(text, f, Brushes.Black, x + 18, y + 2);
            }
        }

