        private void DrawVideoStyleThumbnail(Graphics g, Rectangle r, int styleIdx, bool isSelected)
        {
            DrawInteractiveButton(g, r, isSelected, 3);
            Rectangle inner = new Rectangle(r.X + 4, r.Y + 4, r.Width - 8, r.Height - 8);

            switch (styleIdx)
            {
                case 0: // Simple Frame
                    g.FillRectangle(Brushes.Black, inner);
                    using (Pen p = new Pen(Color.LightGray, 1.5f)) g.DrawRectangle(p, inner);
                    break;
                case 1: // Metal Bevel
                    using (LinearGradientBrush bg = new LinearGradientBrush(inner, Color.FromArgb(15, 23, 42), Color.FromArgb(51, 65, 85), 45f))
                    {
                        g.FillRectangle(bg, inner);
                    }
                    using (Pen p = new Pen(Color.FromArgb(203, 213, 225), 2.5f)) g.DrawRectangle(p, inner);
                    break;
                case 2: // Drop Shadow
                    using (SolidBrush shB = new SolidBrush(Color.FromArgb(80, 0, 0, 0)))
                    {
                        g.FillRectangle(shB, inner.X + 2, inner.Y + 2, inner.Width, inner.Height);
                    }
                    g.FillRectangle(Brushes.SlateGray, inner);
                    g.DrawRectangle(Pens.White, inner);
                    break;
                case 3: // Soft Rounded
                    using (GraphicsPath gp = CreateRoundedRectPath(inner, 6))
                    {
                        g.FillPath(Brushes.DarkSlateBlue, gp);
                        using (Pen p = new Pen(Color.FromArgb(99, 102, 241), 1.5f)) g.DrawPath(p, gp);
                    }
                    break;
                case 4: // Oval Frame
                    g.FillEllipse(Brushes.DarkBlue, inner);
                    using (Pen p = new Pen(Color.FromArgb(234, 179, 8), 1.8f)) g.DrawEllipse(p, inner);
                    break;
                case 5: // Perspective 3D
                    PointF[] pts = new PointF[] {
                        new PointF(inner.X + 4, inner.Y + 3),
                        new PointF(inner.Right - 2, inner.Y),
                        new PointF(inner.Right - 2, inner.Bottom - 3),
                        new PointF(inner.X + 4, inner.Bottom)
                    };
                    using (SolidBrush b = new SolidBrush(Color.FromArgb(30, 58, 138)))
                    {
                        g.FillPolygon(b, pts);
                    }
                    using (Pen p = new Pen(Color.White, 1.2f)) g.DrawPolygon(p, pts);
                    break;
                case 6: // Glowing Cyan
                default:
                    g.FillRectangle(Brushes.Black, inner);
                    using (Pen p = new Pen(Color.FromArgb(6, 182, 212), 2f)) g.DrawRectangle(p, inner);
                    break;
            }

            using (SolidBrush pb = new SolidBrush(Color.FromArgb(200, 255, 255, 255)))
            {
                g.FillPolygon(pb, new PointF[] {
                    new PointF(inner.X + inner.Width / 2 - 3, inner.Y + inner.Height / 2 - 4),
                    new PointF(inner.X + inner.Width / 2 + 4, inner.Y + inner.Height / 2),
                    new PointF(inner.X + inner.Width / 2 - 3, inner.Y + inner.Height / 2 + 4)
                });
            }
        }

        public bool HandleClick(int x, int y, WriterView writerView = null, Form parentForm = null, SlidesView slidesView = null, CalcView calcView = null, PdfView pdfView = null)
        {
            if (y >= 0 && y <= 36)
            {
                int formW = (parentForm != null) ? parentForm.ClientSize.Width : 1366;
                int docAreaX = 265;
                int docAreaW = Math.Max(10, formW - docAreaX - 10);
                Rectangle docClipRect = new Rectangle(docAreaX, 0, docAreaW, 36);

                // 1. Check Home Tab (Luôn cố định ở vị trí đầu tiên index 0)
                if (DocTabBounds.Count > 0 && DocTabBounds[0].Contains(x, y))
                {
                    SwitchDocTab(0, slidesView, writerView, calcView, pdfView);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }

                // 2. Check Add Tab Button (Nằm trong vùng cuộn tài liệu)
                if (!DocTabPlusBounds.IsEmpty && docClipRect.Contains(x, y) && DocTabPlusBounds.Contains(x, y))
                {
                    int idx = DocTabs.Count;
                    OfficeAppMode newMode = (CurrentMode == OfficeAppMode.Home) ? OfficeAppMode.Writer : CurrentMode;
                    string ext = (newMode == OfficeAppMode.Slides) ? ".pptx" : ((newMode == OfficeAppMode.Calc) ? ".xlsx" : ((newMode == OfficeAppMode.Pdf) ? ".pdf" : ".docx"));
                    string namePrefix = (newMode == OfficeAppMode.Slides) ? "Trình chiếu " : ((newMode == OfficeAppMode.Calc) ? "Bảng tính " : ((newMode == OfficeAppMode.Pdf) ? "Tài liệu PDF " : "Văn bản "));
                    AddDocTab(namePrefix + idx + ext, newMode, slidesView, writerView, calcView, pdfView);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }

                // 3. Check Document Tabs (Chỉ nhận click khi nằm trong vùng hiển thị docClipRect)
                if (docClipRect.Contains(x, y))
                {
                    for (int i = 1; i < DocTabs.Count; i++)
                    {
                        // Close Button
                        if (i < DocTabCloseBounds.Count && !DocTabCloseBounds[i].IsEmpty && DocTabCloseBounds[i].Contains(x, y))
                        {
                            CloseDocTab(i, slidesView, writerView, calcView, pdfView);
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }

                        // Switch Tab
                        if (i < DocTabBounds.Count && DocTabBounds[i].Contains(x, y))
                        {
                            SwitchDocTab(i, slidesView, writerView, calcView, pdfView);
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                    }
                }
            }
            else if (y > 36 && y <= 64 && CurrentMode != OfficeAppMode.Home)
            {
                if (RibbonTabBounds.Count == RibbonTabs.Length)
                {
                    for (int i = 0; i < RibbonTabs.Length; i++)
                    {
                        if (RibbonTabBounds[i].Contains(x, y))
                        {
                            ActiveRibbonTab = i;
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                    }
                }
                else
                {
                    int rTabX = 16;
                    using (Font rFont = new Font("Segoe UI", 9.5f, FontStyle.Regular))
                    using (Font rBoldFont = new Font("Segoe UI", 9.5f, FontStyle.Bold))
                    using (Bitmap tmpBmp = new Bitmap(1, 1))
                    using (Graphics gTmp = Graphics.FromImage(tmpBmp))
                    {
                        for (int i = 0; i < RibbonTabs.Length; i++)
                        {
                            bool isContextual = (RibbonTabs[i].Contains("Hình dạng") || RibbonTabs[i].Contains("Hình ảnh") || RibbonTabs[i].Contains("Biểu đồ") || RibbonTabs[i].Contains("Bảng") || RibbonTabs[i].Contains("Đầu trang"));
                            int rWidth = Math.Max(72, (int)gTmp.MeasureString(RibbonTabs[i], isContextual ? rBoldFont : rFont).Width + 24);
                            if (x >= rTabX && x <= rTabX + rWidth)
                            {
                                ActiveRibbonTab = i;
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                            rTabX += rWidth + 4;
                        }
                    }
                }
            }
            else if (y > 64 && y <= 155 && CurrentMode == OfficeAppMode.Writer)
            {
                if (ActiveRibbonTab == 0) // Trang đầu (Home)
                {
                    if (writerView != null)
                    {
                        // 📂 Big Open Button Click (Support DOCX, ODT, RTF, HTML, TXT)
