                        // A^ / Av Font Size Adjustment Buttons
                        if (x >= 418 && x <= 440 && y >= 68 && y <= 92)
                        {
                            FontSize += 2.0f;
                            writerView.ApplyFontSizeToSelectionOrTyping(FontSize);
                            return true;
                        }
                        if (x >= 442 && x <= 464 && y >= 68 && y <= 92)
                        {
                            if (FontSize > 6.0f) FontSize -= 2.0f;
                            writerView.ApplyFontSizeToSelectionOrTyping(FontSize);
