                            Point pLoc = parentForm != null ? parentForm.PointToScreen(new Point(686, 122)) : new Point(686, 122);
                            ParagraphBordersDropDownForm bdrMenu = new ParagraphBordersDropDownForm(pLoc, (borderId) =>
                            {
                                if (borderId == 16)
