                                    BordersShadingForm bsDlg = new BordersShadingForm(writerView);
                                    bsDlg.ShowDialog(parentForm);
                                }
                                else
                                {
                                    writerView.ApplyParagraphBorderPreset(borderId);
                                }
                                if (parentForm != null) parentForm.Invalidate();
                            });
                            bdrMenu.Show(parentForm);
                            return true;
