                        // Quick Styles Gallery (X: 730..)
                        int styleX = 730;
                        string[] styleNames = new string[] { "Normal", "No Spacing", "Heading 1", "Heading 2", "Heading 3", "Title", "Subtitle" };
                        int rWidth = parentForm != null ? parentForm.ClientSize.Width : 1280;
                        int numStyleCards = Math.Max(2, Math.Min(styleNames.Length, (rWidth - 130 - styleX) / 68));
                        if (numStyleCards > 5) numStyleCards = 5;

                        for (int s = 0; s < numStyleCards; s++)
                        {
                            if (x >= styleX && x <= styleX + 62 && y >= 68 && y <= 124)
                            {
                                ActiveStyle = styleNames[s];
                                return true;
                            }
                            styleX += 68;
                        }

                        int styleDividerX = 730 + (numStyleCards * 68) + 6;
                        int editX = styleDividerX + 8;

                        // Editing (Find / Navigation Pane, Replace & Select Buttons)
                        if (x >= editX && x <= editX + 108)
                        {
                            if (y >= 68 && y <= 88) // Tìm kiếm (Search / Nav Pane)
                            {
                                writerView.ShowNavigationPane = !writerView.ShowNavigationPane;
                                if (writerView.ShowNavigationPane)
                                {
                                    writerView.NavSearchFocused = true;
                                    writerView.NavActiveTab = 2;
                                    writerView.PerformNavSearch();
                                }
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                            else if (y >= 89 && y <= 109) // Thay thế (Find & Replace)
                            {
                                FindReplaceForm dlg = new FindReplaceForm();
                                dlg.OnFindNext += (q) => writerView.FindNext(q);
                                dlg.OnReplace += (q, r) => writerView.ReplaceCurrent(q, r);
                                dlg.OnReplaceAll += (q, r) =>
                                {
                                    int c = writerView.ReplaceAll(q, r);
                                    MessageBox.Show("Đã thay thế tất cả " + c + " vị trí trùng khớp trong tài liệu!", "GenOffice Writer", MessageBoxButtons.OK, MessageBoxIcon.Information);
                                };
                                dlg.ShowDialog();
                                if (parentForm != null) parentForm.Invalidate();
                                return true;
                            }
                            else if (y >= 110 && y <= 132) // Chọn vùng (Select ▾ Dropdown)
                            {
                                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(editX, 134)) : new Point(editX, 134);
                                SelectionDropDownForm selDlg = new SelectionDropDownForm(pt, (chosen) =>
                                {
                                    if (chosen == 0) // Chọn tất cả
                                    {
                                        writerView.SelectAll();
                                    }
                                    else if (chosen == 1) // Chọn đối tượng
                                    {
                                        writerView.IsSelectObjectsMode = !writerView.IsSelectObjectsMode;
                                    }
                                    else if (chosen == 2) // Chọn tất cả văn bản có định dạng tương tự
                                    {
                                        writerView.SelectAllTextWithSimilarFormatting();
                                    }
                                    else if (chosen == 3) // Ngăn chọn...
                                    {
                                        writerView.ShowSelectionPane = !writerView.ShowSelectionPane;
                                    }
                                    if (parentForm != null) parentForm.Invalidate();
                                });
                                selDlg.Show();
                                return true;
                            }
