                    }
                }
                else if (ActiveRibbonTab == 1) // Chèn (Insert Tab)
                {
                    if (writerView != null)
                    {
                        // 1. Nhóm Trang (X: 14..106)
                        if (x >= 14 && x <= 106)
                        {
                            if (y >= 68 && y <= 88) // Trang bìa
                            {
                                writerView.InsertCoverPage("Austin");
                            }
                            else if (y >= 88 && y <= 108) // Trang trắng
                            {
                                writerView.InsertBlankPage();
                            }
                            else if (y >= 108 && y <= 128) // Ngắt trang
                            {
                                writerView.InsertPageBreak();
                            }
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        // 2. Nhóm Bảng (X: 120..182)
                        if (x >= 120 && x <= 182 && y >= 68 && y <= 128)
