                    string curTxt = cell != null ? (cell.RawValue ?? "") : "";
                    using (var hDlg = new InsertHyperlinkForm(curTxt))
                    {
                        if (hDlg.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            calcView.InsertHyperlink(hDlg.DisplayText, hDlg.TargetUrl, hDlg.ScreenTip);
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    }
                    return true;
                }
                // Văn bản (Text ▾) (X: 742..794)
                else if (x >= 742 && x <= 794 && y >= 68 && y <= 124)
                {
                    ContextMenuStrip txtMenu = new ContextMenuStrip();
                    txtMenu.Items.Add("Hộp văn bản (Text Box)", null, (s, e) => { calcView.InsertTextBox(parentForm); });
                    txtMenu.Items.Add("Đầu trang & Chân trang (Header & Footer)...", null, (s, e) => {
                        using (CalcHeaderFooterForm hfDlg = new CalcHeaderFooterForm(calcView))
                        {
                            hfDlg.ShowDialog(parentForm);
                        }
                    });
                    txtMenu.Items.Add("Chữ nghệ thuật (WordArt)", null, (s, e) => { calcView.InsertWordArt(parentForm); });
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(742, 124)) : new Point(742, 124);
                    txtMenu.Show(pt);
                    return true;
                }
                // Ký hiệu (Symbols ▾) (X: 802..854)
                else if (x >= 802 && x <= 854 && y >= 68 && y <= 124)
                {
                    ContextMenuStrip symMenu = new ContextMenuStrip();
                    symMenu.Items.Add("Công thức Toán học (Equation: π)...", null, (s, e) => {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(802, 124)) : new Point(802, 124);
                        QuickEquationDropDownForm eqDlg = new QuickEquationDropDownForm(pt);
                        eqDlg.OnEquationSelected = (latex) => {
                            if (calcView.SelectedShape != null && calcView.SelectedShape.IsEditingText)
                            {
                                var sh = calcView.SelectedShape;
                                if (sh.TextContent == null) sh.TextContent = "";
                                int cur = Math.Max(0, Math.Min(sh.TextCursorIndex, sh.TextContent.Length));
                                sh.TextContent = sh.TextContent.Insert(cur, latex);
                                sh.TextCursorIndex = cur + latex.Length;
                            }
                            else
                            {
                                calcView.CurrentSheet.SetCellText(calcView.SelectedRow, calcView.SelectedCol, latex);
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        eqDlg.Show();
                    });
                    symMenu.Items.Add("Ký hiệu đặc biệt (Symbol: Ω)...", null, (s, e) => {
                        using (InsertSymbolForm symDlg = new InsertSymbolForm())
                        {
                            if (symDlg.ShowDialog(parentForm) == DialogResult.OK && !string.IsNullOrEmpty(symDlg.SelectedSymbol))
                            {
                                if (calcView.SelectedShape != null && calcView.SelectedShape.IsEditingText)
                                {
                                    var sh = calcView.SelectedShape;
                                    if (sh.TextContent == null) sh.TextContent = "";
                                    int cur = Math.Max(0, Math.Min(sh.TextCursorIndex, sh.TextContent.Length));
                                    sh.TextContent = sh.TextContent.Insert(cur, symDlg.SelectedSymbol);
                                    sh.TextCursorIndex = cur + symDlg.SelectedSymbol.Length;
                                }
                                else
                                {
                                    CellData cd = calcView.CurrentSheet.GetOrCreateCell(calcView.SelectedRow, calcView.SelectedCol);
                                    calcView.CurrentSheet.SetCellText(calcView.SelectedRow, calcView.SelectedCol, (cd.RawValue ?? "") + symDlg.SelectedSymbol);
                                }
                                if (parentForm != null) parentForm.Invalidate();
                            }
                        }
                    });
                    Point p = parentForm != null ? parentForm.PointToScreen(new Point(802, 124)) : new Point(802, 124);
                    symMenu.Show(p);
                    return true;
                }
            }
