        private bool HandleTableDesignRibbonClick(int x, int y, CalcView calcView, ExcelTableInfo tbl, Form parentForm)
        {
            if (tbl == null || calcView == null) return false;

            // Group 1: Thuộc tính (X: 10..102)
            if (x >= 10 && x <= 102)
            {
                // Table Name box
                if (y >= 85 && y <= 107)
                {
                    using (Form dlg = new Form())
                    {
                        dlg.Text = "Đổi tên Bảng (Rename Table)";
                        dlg.Size = new Size(320, 160);
                        dlg.StartPosition = FormStartPosition.CenterParent;
                        dlg.FormBorderStyle = FormBorderStyle.FixedDialog;
                        dlg.MaximizeBox = false;
                        dlg.MinimizeBox = false;
                        dlg.Font = new Font("Segoe UI", 9f);

                        Label lbl = new Label { Text = "Tên bảng mới (Table Name):", Location = new Point(16, 16), AutoSize = true };
                        TextBox txt = new TextBox { Text = tbl.Name, Location = new Point(18, 42), Width = 268 };
                        Button btnOk = new Button { Text = "Đồng ý", DialogResult = DialogResult.OK, Location = new Point(120, 80), Width = 80, Height = 28 };
                        Button btnCancel = new Button { Text = "Hủy bỏ", DialogResult = DialogResult.Cancel, Location = new Point(206, 80), Width = 80, Height = 28 };

                        dlg.Controls.AddRange(new Control[] { lbl, txt, btnOk, btnCancel });
                        dlg.AcceptButton = btnOk;
                        dlg.CancelButton = btnCancel;

                        if (dlg.ShowDialog(parentForm) == DialogResult.OK && !string.IsNullOrEmpty(txt.Text.Trim()))
                        {
                            tbl.Name = txt.Text.Trim();
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    }
                    return true;
                }
                // Resize Table button
                else if (y >= 110 && y <= 132)
                {
                    new CreateTableDialogForm(calcView).ShowDialog(parentForm);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            // Group 2: Công cụ (X: 110..262)
            if (x >= 110 && x <= 262)
            {
                // Summarize with PivotTable
                if (y >= 68 && y <= 88)
                {
                    new CreatePivotTableDialogForm(calcView).ShowDialog(parentForm);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Remove Duplicates
                else if (y >= 90 && y <= 110)
                {
                    calcView.RemoveTableDuplicates(tbl);
                    MessageBox.Show("Đã quét và làm sạch các dòng dữ liệu trùng lặp trong bảng " + tbl.Name + "!", "GenOffice Calc", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Convert to Range
                else if (y >= 112 && y <= 134)
                {
                    if (MessageBox.Show("Bạn có muốn chuyển đổi bảng này thành vùng dữ liệu thông thường không?", "GenOffice Calc", MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
                    {
                        calcView.ConvertTableToRange(tbl);
                        ActiveRibbonTab = 0;
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }
            }

            // Group 3: Dữ liệu ngoài (X: 268..376)
            if (x >= 268 && x <= 376)
            {
                // Export
                if (x <= 320 && y >= 70 && y <= 128)
                {
                    MessageBox.Show("Xuất dữ liệu bảng ra tệp CSV / Excel thành công!", "GenOffice Calc", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return true;
                }
                // Refresh
                else if (x >= 321 && y >= 70 && y <= 128)
                {
                    FormulaEngine.EvaluateSheet(calcView.CurrentSheet);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            // Group 4: Tùy chọn Kiểu Bảng (X: 380..700)
            if (x >= 380 && x <= 700)
            {
                // Col 1 (X: 380..485)
                if (x >= 380 && x <= 485)
                {
                    if (y >= 70 && y <= 90) // Dòng tiêu đề
                    {
                        tbl.HasHeaders = !tbl.HasHeaders;
                        calcView.ApplyTableStyle(tbl, tbl.StyleIndex);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    else if (y >= 91 && y <= 111) // Dòng tổng cộng
                    {
                        calcView.ToggleTableTotalRow(tbl);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    else if (y >= 112 && y <= 132) // Dòng xen kẽ
                    {
                        tbl.BandedRows = !tbl.BandedRows;
                        calcView.ApplyTableStyle(tbl, tbl.StyleIndex);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                }
                // Col 2 (X: 486..590)
                else if (x >= 486 && x <= 590)
                {
                    if (y >= 70 && y <= 90) // Cột đầu tiên
                    {
                        tbl.FirstColumn = !tbl.FirstColumn;
                        calcView.ApplyTableStyle(tbl, tbl.StyleIndex);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    else if (y >= 91 && y <= 111) // Cột cuối cùng
                    {
                        tbl.LastColumn = !tbl.LastColumn;
                        calcView.ApplyTableStyle(tbl, tbl.StyleIndex);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    else if (y >= 112 && y <= 132) // Cột xen kẽ
                    {
                        tbl.BandedColumns = !tbl.BandedColumns;
                        calcView.ApplyTableStyle(tbl, tbl.StyleIndex);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                }
                // Col 3 (X: 591..700)
                else if (x >= 591 && x <= 700)
                {
                    if (y >= 70 && y <= 90) // Nút lọc
                    {
                        tbl.ShowFilterButtons = !tbl.ShowFilterButtons;
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                }
            }

            // Group 5: Kiểu Bảng Gallery (X: 710..1085, Y: 70..118)
            if (x >= 710 && x <= 1085 && y >= 70 && y <= 118)
            {
                int clickedStyle = (x - 710) / 62;
                if (clickedStyle >= 0 && clickedStyle < 6)
                {
                    calcView.ApplyTableStyle(tbl, clickedStyle);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }

            return false;
        }

        private bool HandlePowerPointRibbonClick(int x, int y, SlidesView slidesView, Form parentForm)
        {
            if (slidesView != null && slidesView.IsRemovingBackground)
            {
                if (y >= 68 && y <= 122)
                {
                    // 1. Xóa tự động (Auto Remove) (X: 12..98)
                    if (x >= 12 && x <= 98)
                    {
                        if (slidesView.SelectedShape != null)
                        {
                            slidesView.AutoRemoveBackgroundDirect(slidesView.SelectedShape);
                            if (parentForm != null) parentForm.Invalidate();
                        }
                        return true;
                    }
                    // 2. Chọn màu xóa (Chroma Key CapCut) (X: 104..196)
                    else if (x >= 104 && x <= 196)
                    {
                        if (slidesView.SelectedShape != null)
                        {
                            slidesView.StartColorPickMode(slidesView.SelectedShape);
                            if (parentForm != null) parentForm.Invalidate();
                        }
                        return true;
                    }
                    // 3. Giữ vùng (+) (X: 208..304)
                    else if (x >= 208 && x <= 304)
                    {
                        slidesView.IsColorPickingMode = false;
                        slidesView.BgRemovalTool = "Keep";
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // 4. Xóa vùng (-) (X: 310..406)
                    else if (x >= 310 && x <= 406)
                    {
                        slidesView.IsColorPickingMode = false;
                        slidesView.BgRemovalTool = "Remove";
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // 5. Xóa dấu (Delete Mark) (X: 412..490)
                    else if (x >= 412 && x <= 490)
                    {
                        slidesView.DeleteLastBgMark();
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // 6. Hủy thay đổi (Discard All Changes) (X: 502..596)
                    else if (x >= 502 && x <= 596)
                    {
                        slidesView.EndBackgroundRemoval(false);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // 7. Giữ thay đổi (Keep Changes) (X: 602..696)
                    else if (x >= 602 && x <= 696)
                    {
                        slidesView.EndBackgroundRemoval(true);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                }
                return true;
            }

            if (ActiveRibbonTab == 0) // Trang đầu (Home)
            {
                // Mở tệp PPTX
                if (x >= 12 && x <= 50 && y >= 68 && y <= 130)
                {
                    using (OpenFileDialog ofd = new OpenFileDialog())
                    {
                        ofd.Filter = "Tệp Trình Chiếu PowerPoint (*.pptx;*.xml)|*.pptx;*.xml|Tất cả tệp (*.*)|*.*";
                        ofd.Title = "Mở Bản Trình Chiếu PowerPoint";
                        if (ofd.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            try
                            {
                                slidesView.Presentation = GenOffice.Format.PptxHandler.LoadPptx(ofd.FileName);
                                slidesView.ActiveSlideIndex = 0;
                                slidesView.SelectedShapeIndex = -1;
                                slidesView.CanvasScrollX = 0;
                                slidesView.CanvasScrollY = 0;
                                slidesView.ZoomLevel = 1.0f;
                                if (ActiveDocIndex >= 0 && ActiveDocIndex < DocTabs.Count)
                                {
                                    DocTabs[ActiveDocIndex].Title = System.IO.Path.GetFileName(ofd.FileName);
                                }
                                MessageBox.Show("Đã mở tệp PowerPoint thành công!", "GenOffice PowerPoint", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            }
                            catch (Exception ex)
                            {
                                MessageBox.Show("Lỗi khi mở tệp: " + ex.Message, "Lỗi", MessageBoxButtons.OK, MessageBoxIcon.Error);
                            }
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Lưu tệp PPTX
                else if (x >= 52 && x <= 90 && y >= 68 && y <= 130)
                {
                    using (SaveFileDialog sfd = new SaveFileDialog())
                    {
                        sfd.Filter = "Tệp Trình Chiếu PowerPoint (*.pptx)|*.pptx|Tệp XML Presentation (*.xml)|*.xml";
                        sfd.Title = "Lưu Bản Trình Chiếu Microsoft PowerPoint 2016-365";
                        if (sfd.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            try
                            {
                                GenOffice.Format.PptxHandler.SavePptx(sfd.FileName, slidesView.Presentation);
                                if (ActiveDocIndex >= 0 && ActiveDocIndex < DocTabs.Count)
                                {
                                    DocTabs[ActiveDocIndex].Title = System.IO.Path.GetFileName(sfd.FileName);
                                    DocTabs[ActiveDocIndex].IsModified = false;
                                }
                                MessageBox.Show("Đã lưu bản trình chiếu chuẩn .pptx thành công!", "GenOffice PowerPoint", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            }
                            catch (Exception ex)
                            {
                                MessageBox.Show("Lỗi khi lưu tệp: " + ex.Message, "Lỗi", MessageBoxButtons.OK, MessageBoxIcon.Error);
                            }
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Dán (Paste)
                else if (x >= 92 && x <= 134 && y >= 68 && y <= 130)
                {
                    slidesView.Paste();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Cắt (Cut)
                else if (x >= 136 && x <= 204 && y >= 68 && y <= 88)
                {
                    slidesView.Cut();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Chép (Copy)
                else if (x >= 136 && x <= 204 && y >= 89 && y <= 109)
                {
                    slidesView.Copy();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Slide Mới
                else if (x >= 212 && x <= 276 && y >= 68 && y <= 130)
                {
                    slidesView.AddSlide();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Bố cục Layout
                else if (x >= 280 && x <= 372 && y >= 68 && y <= 88)
                {
                    slidesView.SetLayout(SlideLayoutType.TwoContent);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Đặt lại Reset
                else if (x >= 280 && x <= 372 && y >= 89 && y <= 109)
                {
                    slidesView.SetLayout(SlideLayoutType.TitleAndContent);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nhân bản Duplicate
                else if (x >= 280 && x <= 372 && y >= 110 && y <= 130)
                {
                    slidesView.DuplicateActiveSlide();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Phông chữ (Font Family Dropdown) (X: 384 to 504, Y: 68 to 92)
                else if (x >= 384 && x <= 504 && y >= 68 && y <= 92)
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(384, 96)) : new Point(384, 96);
                    string curF = (slidesView.SelectedShape != null) ? slidesView.SelectedShape.FontName : SelectedFont;
                    FontDropDownForm fontDlg = new FontDropDownForm(curF, pt, AvailableSystemFonts);
                    fontDlg.OnFontSelected += (font) =>
                    {
                        SelectedFont = font;
                        if (slidesView.SelectedShape != null)
                        {
                            slidesView.SelectedShape.FontName = font;
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    fontDlg.Show();
                    return true;
                }
                // Cỡ chữ (Font Size Dropdown) (X: 508 to 552, Y: 68 to 92)
                else if (x >= 508 && x <= 552 && y >= 68 && y <= 92)
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(508, 96)) : new Point(508, 96);
                    float curSz = (slidesView.SelectedShape != null) ? slidesView.SelectedShape.FontSize : FontSize;
                    SizeDropDownForm sizeDlg = new SizeDropDownForm(curSz, pt);
                    sizeDlg.OnSizeSelected += (sz) =>
                    {
                        FontSize = sz;
                        if (slidesView.SelectedShape != null)
                        {
                            slidesView.SelectedShape.FontSize = sz;
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    sizeDlg.Show();
                    return true;
                }
                // Tăng cỡ chữ A^
                else if (x >= 556 && x <= 580 && y >= 68 && y <= 92)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.SelectedShape.FontSize = Math.Min(96f, slidesView.SelectedShape.FontSize + 4f);
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Giảm cỡ chữ Av
                else if (x >= 584 && x <= 608 && y >= 68 && y <= 92)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.SelectedShape.FontSize = Math.Max(8f, slidesView.SelectedShape.FontSize - 4f);
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Đậm Bold
                else if (x >= 384 && x <= 408 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        if (slidesView.SelectedShape.Type == ShapeType.Table)
                        {
                            ShapeNode tShape = slidesView.SelectedShape;
                            string cellKey = (tShape.TableSelectedCellRow >= 0 ? tShape.TableSelectedCellRow : 0) + "," + (tShape.TableSelectedCellCol >= 0 ? tShape.TableSelectedCellCol : 0);
                            bool isCurrentlyBold = (tShape.TableCellBolds != null && tShape.TableCellBolds.ContainsKey(cellKey) && tShape.TableCellBolds[cellKey]);
                            slidesView.SetSelectedTableCellBold(!isCurrentlyBold);
                        }
                        else
                        {
                            slidesView.SelectedShape.Bold = !slidesView.SelectedShape.Bold;
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nghiêng Italic
                else if (x >= 412 && x <= 436 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.SelectedShape.Italic = !slidesView.SelectedShape.Italic;
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Gạch dưới Underline
                else if (x >= 440 && x <= 464 && y >= 96 && y <= 120)
                {
                    if (slidesView.SelectedShape != null)
                    {
                        slidesView.SelectedShape.Underline = !slidesView.SelectedShape.Underline;
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Màu phông chữ
                else if (x >= 496 && x <= 524 && y >= 96 && y <= 120)
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(496, 124)) : new Point(496, 124);
                    Color curC = Color.Black;
                    if (slidesView.SelectedShape != null)
                    {
                        int tc = slidesView.SelectedShape.TextColor;
                        curC = Color.FromArgb((tc >> 16) & 0xFF, (tc >> 8) & 0xFF, tc & 0xFF);
                    }
                    ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, false);
                    colDlg.OnColorSelected += (c) =>
                    {
                        if (slidesView.SelectedShape != null)
                        {
                            if (slidesView.SelectedShape.Type == ShapeType.Table)
                            {
                                slidesView.SetSelectedTableCellTextColor(c.ToArgb());
                            }
                            else
                            {
                                slidesView.SelectedShape.TextColor = c.ToArgb() & 0xFFFFFF;
                            }
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    colDlg.Show();
                    return true;
                }
                // Căn trái
                else if (x >= 648 && x <= 672 && y >= 68 && y <= 92)
                {
                    if (slidesView.SelectedShape != null) slidesView.SelectedShape.Alignment = TextAlignment.Left;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Căn giữa
                else if (x >= 676 && x <= 700 && y >= 68 && y <= 92)
                {
                    if (slidesView.SelectedShape != null) slidesView.SelectedShape.Alignment = TextAlignment.Center;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Căn phải
                else if (x >= 704 && x <= 728 && y >= 68 && y <= 92)
                {
                    if (slidesView.SelectedShape != null) slidesView.SelectedShape.Alignment = TextAlignment.Right;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Quick Shapes 3x6 Grid (X: 786..930, Y: 68..122)
                else if (x >= 786 && x <= 930 && y >= 68 && y <= 122)
                {
                    int col = (x - 786) / 24;
                    int r = (y - 68) / 18;
                    ShapeType[][] allShapeRows = new ShapeType[][] {
                        new ShapeType[] { ShapeType.TextBox, ShapeType.Line, ShapeType.Arrow, ShapeType.Rectangle, ShapeType.RoundedRectangle, ShapeType.Ellipse },
                        new ShapeType[] { ShapeType.Leaf, ShapeType.Clover, ShapeType.Flower, ShapeType.Sprout, ShapeType.LuxuryHexagon, ShapeType.Gem },
                        new ShapeType[] { ShapeType.Shield, ShapeType.Banner, ShapeType.Starburst, ShapeType.Arch, ShapeType.Hexagon, ShapeType.Diamond },
                        new ShapeType[] { ShapeType.Triangle, ShapeType.RightTriangle, ShapeType.Parallelogram, ShapeType.Trapezoid, ShapeType.Octagon, ShapeType.Pentagon },
                        new ShapeType[] { ShapeType.Heart, ShapeType.Callout, ShapeType.Cloud, ShapeType.Sun, ShapeType.Moon, ShapeType.Lightning },
                        new ShapeType[] { ShapeType.BlockArrowRight, ShapeType.BlockArrowLeft, ShapeType.BlockArrowUp, ShapeType.BlockArrowDown, ShapeType.Chevron, ShapeType.Smiley },
                        new ShapeType[] { ShapeType.Donut, ShapeType.Cross, ShapeType.Cube, ShapeType.Can, ShapeType.Star, ShapeType.TextBox }
                    };
                    int sRow = Math.Max(0, Math.Min(allShapeRows.Length - 3, slidesView.ShapeGalleryScrollRow));
                    if (r >= 0 && r < 3 && col >= 0 && col < 6)
                    {
                        int actualRow = sRow + r;
                        if (actualRow >= 0 && actualRow < allShapeRows.Length)
                        {
                            ShapeType selShape = allShapeRows[actualRow][col];
                            slidesView.StartShapeDrawMode(selShape);
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Gallery Up/Down/More Buttons (X: 932..948, Y: 68..122)
                else if (x >= 932 && x <= 948 && y >= 68 && y <= 122)
                {
                    ShapeType[][] allShapeRows = new ShapeType[][] {
                        new ShapeType[] { ShapeType.TextBox, ShapeType.Line, ShapeType.Arrow, ShapeType.Rectangle, ShapeType.RoundedRectangle, ShapeType.Ellipse },
                        new ShapeType[] { ShapeType.Leaf, ShapeType.Clover, ShapeType.Flower, ShapeType.Sprout, ShapeType.LuxuryHexagon, ShapeType.Gem },
                        new ShapeType[] { ShapeType.Shield, ShapeType.Banner, ShapeType.Starburst, ShapeType.Arch, ShapeType.Hexagon, ShapeType.Diamond },
                        new ShapeType[] { ShapeType.Triangle, ShapeType.RightTriangle, ShapeType.Parallelogram, ShapeType.Trapezoid, ShapeType.Octagon, ShapeType.Pentagon },
                        new ShapeType[] { ShapeType.Heart, ShapeType.Callout, ShapeType.Cloud, ShapeType.Sun, ShapeType.Moon, ShapeType.Lightning },
                        new ShapeType[] { ShapeType.BlockArrowRight, ShapeType.BlockArrowLeft, ShapeType.BlockArrowUp, ShapeType.BlockArrowDown, ShapeType.Chevron, ShapeType.Smiley },
                        new ShapeType[] { ShapeType.Donut, ShapeType.Cross, ShapeType.Cube, ShapeType.Can, ShapeType.Star, ShapeType.TextBox }
                    };
                    // Up button ▲ (Y: 68..85)
                    if (y >= 68 && y < 86)
                    {
                        slidesView.ShapeGalleryScrollRow = Math.Max(0, slidesView.ShapeGalleryScrollRow - 1);
                    }
                    // Down button ▼ (Y: 86..103)
                    else if (y >= 86 && y < 104)
                    {
                        slidesView.ShapeGalleryScrollRow = Math.Min(allShapeRows.Length - 3, slidesView.ShapeGalleryScrollRow + 1);
                    }
                    // More button ▾ (Y: 104..122)
                    else
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(786, 128)) : new Point(786, 128);
                        ShapesGalleryDropDownForm drop = new ShapesGalleryDropDownForm(pt);
                        drop.OnShapeSelected += (st) =>
                        {
                            slidesView.StartShapeDrawMode(st);
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        drop.Show();
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Arrange Button (Sắp xếp ▾ / ARR) (X: 952..1006, Y: 68..122)
                else if (x >= 952 && x <= 1006 && y >= 68 && y <= 122)
                {
                    ShowArrangeMenu(parentForm, new Point(952, 126), slidesView);
                    return true;
                }
                // Màu tô hình (Fill Color) (X: 1010..1096, Y: 68..94)
                else if (x >= 1010 && x <= 1096 && y >= 68 && y <= 94)
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(1010, 96)) : new Point(1010, 96);
                    Color curC = Color.LightSteelBlue;
                    if (slidesView.SelectedShape != null)
                    {
                        int fc = slidesView.SelectedShape.FillColor;
                        curC = Color.FromArgb((fc >> 16) & 0xFF, (fc >> 8) & 0xFF, fc & 0xFF);
                    }
                    ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, true);
                    colDlg.OnColorSelected += (c) =>
                    {
                        if (slidesView.SelectedShape != null)
                        {
                            if (slidesView.SelectedShape.Type == ShapeType.Table)
                            {
                                slidesView.SetSelectedTableCellFillColor(c.ToArgb());
                            }
                            else
                            {
                                if (c == Color.Transparent)
                                {
                                    slidesView.SelectedShape.FillOpacity = 0.0f;
                                }
                                else
                                {
                                    slidesView.SelectedShape.FillColor = c.ToArgb() & 0xFFFFFF;
                                    slidesView.SelectedShape.FillOpacity = 1.0f;
                                }
                            }
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    colDlg.Show();
                    return true;
                }
                // Màu viền hình (Border Color) (X: 1010..1096, Y: 96..122)
                else if (x >= 1010 && x <= 1096 && y >= 96 && y <= 122)
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(1010, 124)) : new Point(1010, 124);
                    Color curC = Color.DarkSlateBlue;
                    if (slidesView.SelectedShape != null)
                    {
                        int sc = slidesView.SelectedShape.StrokeColor;
                        curC = Color.FromArgb((sc >> 16) & 0xFF, (sc >> 8) & 0xFF, sc & 0xFF);
                    }
                    ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, true);
                    colDlg.OnColorSelected += (c) =>
                    {
                        if (slidesView.SelectedShape != null)
                        {
                            if (c == Color.Transparent)
                            {
                                slidesView.SelectedShape.StrokeWidth = 0.0f;
                            }
                            else
                            {
                                slidesView.SelectedShape.StrokeColor = c.ToArgb() & 0xFFFFFF;
                                if (slidesView.SelectedShape.StrokeWidth <= 0) slidesView.SelectedShape.StrokeWidth = 1.5f;
                            }
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    colDlg.Show();
                    return true;
                }
                // F5 Trình Chiếu Fullscreen (X: 1106..1246, Y: 68..130)
                else if (x >= 1106 && x <= 1246 && y >= 68 && y <= 130)
                {
                    AppForm af = parentForm as AppForm;
                    if (af != null) af.StartSlideShow(true);
                    else slidesView.StartPresenting(true);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }
            else if (ActiveRibbonTab == 1) // Chèn (Insert)
            {
                // ==================== Group 1: Trang chiếu (Slides) (X: 10..72, Y: 68..124) ====================
                if (x >= 10 && x <= 68 && y >= 68 && y <= 124)
                {
                    slidesView.AddSlide();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // ==================== Group 2: Bảng (Tables) (X: 80..132, Y: 68..124) ====================
                else if (x >= 80 && x <= 132 && y >= 68 && y <= 124)
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(80, 130)) : new Point(80, 130);
                    TablePickerForm pickerDlg = new TablePickerForm(pt);
                    pickerDlg.OnTableHovered += (cols, rows) =>
                    {
                        slidesView.SetTableInsertPreview(cols, rows);
                    };
                    pickerDlg.OnTableHoverLeave += () =>
                    {
                        slidesView.ClearTableInsertPreview();
                    };
                    pickerDlg.OnTableSelected += (cols, rows) =>
                    {
                        slidesView.InsertTable(cols, rows);
                        ActiveRibbonTab = 7;
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    pickerDlg.OnCustomInsertClicked += () =>
                    {
                        using (CustomTableForm customDlg = new CustomTableForm())
                        {
                            if (customDlg.ShowDialog(parentForm) == DialogResult.OK)
                            {
                                slidesView.InsertTable(customDlg.Columns, customDlg.Rows);
                                ActiveRibbonTab = 7;
                                if (parentForm != null) parentForm.Invalidate();
                            }
                        }
                    };
                    pickerDlg.OnDrawTableClicked += () =>
                    {
                        slidesView.InsertTable(4, 3);
                        ActiveRibbonTab = 7;
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    pickerDlg.OnExcelTableClicked += () =>
                    {
                        slidesView.InsertTable(5, 5);
                        ActiveRibbonTab = 7;
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    pickerDlg.Show();
                    return true;
                }
                // ==================== Group 3: Hình ảnh (Images) (X: 144..280) ====================
                else if (x >= 144 && x <= 200 && y >= 68 && y <= 124) // Hình ảnh ▾
                {
                    using (OpenFileDialog ofd = new OpenFileDialog())
                    {
                        ofd.Filter = "Tệp hình ảnh (*.png;*.jpg;*.jpeg;*.bmp;*.gif;*.webp)|*.png;*.jpg;*.jpeg;*.bmp;*.gif;*.webp|Tất cả tệp (*.*)|*.*";
                        if (ofd.ShowDialog(parentForm) == DialogResult.OK && slidesView.ActiveSlide != null)
                        {
                            try
                            {
                                Image loadedImg = Image.FromFile(ofd.FileName);
                                float maxW = 500f;
                                float maxH = 350f;
                                float imgW = loadedImg.Width;
                                float imgH = loadedImg.Height;

                                if (imgW > maxW)
                                {
                                    imgH = (maxW / imgW) * imgH;
                                    imgW = maxW;
                                }
                                if (imgH > maxH)
                                {
                                    imgW = (maxH / imgH) * imgW;
                                    imgH = maxH;
                                }

                                ShapeNode imgShape = new ShapeNode
                                {
                                    Type = ShapeType.Image,
                                    ImagePath = ofd.FileName,
                                    CachedImage = loadedImg,
                                    Transform = new Transform2D(150f, 100f, imgW, imgH),
                                    Text = "",
                                    FillColor = 0x00FFFFFF,
                                    StrokeWidth = 0f
                                };
                                slidesView.SaveUndoState();
                                slidesView.ActiveSlide.AddShape(imgShape);
                                slidesView.SelectedShapeIndex = slidesView.ActiveSlide.Shapes.Count - 1;
                                ActiveRibbonTab = 7;
                            }
                            catch (Exception ex)
                            {
                                MessageBox.Show("Không thể tải hình ảnh: " + ex.Message, "Lỗi Chèn Ảnh", MessageBoxButtons.OK, MessageBoxIcon.Error);
                            }
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (x >= 204 && x <= 280 && y >= 68 && y <= 94) // Ảnh chụp màn hình ▾ (Chụp cắt màn hình trực tiếp - Screen Snip)
                {
                    using (ScreenSnippingForm snipDlg = new ScreenSnippingForm())
                    {
                        if (snipDlg.ShowDialog(parentForm) == DialogResult.OK && snipDlg.CapturedBitmap != null && slidesView.ActiveSlide != null)
                        {
                            try
                            {
                                string tempPath = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "SlideScreenClip_" + DateTime.Now.Ticks + ".png");
                                snipDlg.CapturedBitmap.Save(tempPath, System.Drawing.Imaging.ImageFormat.Png);

                                Image loadedImg = (Image)snipDlg.CapturedBitmap.Clone();
                                float maxW = 500f;
                                float maxH = 350f;
                                float imgW = loadedImg.Width;
                                float imgH = loadedImg.Height;

                                if (imgW > maxW)
                                {
                                    imgH = (maxW / imgW) * imgH;
                                    imgW = maxW;
                                }
                                if (imgH > maxH)
                                {
                                    imgW = (maxH / imgH) * imgW;
                                    imgH = maxH;
                                }

                                ShapeNode imgShape = new ShapeNode
                                {
                                    Type = ShapeType.Image,
                                    ImagePath = tempPath,
                                    CachedImage = loadedImg,
                                    Transform = new Transform2D(150f, 100f, imgW, imgH),
                                    Text = "",
                                    FillColor = 0x00FFFFFF,
                                    StrokeWidth = 0f
                                };
                                slidesView.SaveUndoState();
                                slidesView.ActiveSlide.AddShape(imgShape);
                                slidesView.SelectedShapeIndex = slidesView.ActiveSlide.Shapes.Count - 1;
                                ActiveRibbonTab = 7;
                            }
                            catch (Exception ex)
                            {
                                MessageBox.Show("Không thể chèn ảnh chụp màn hình: " + ex.Message, "Lỗi Chụp Màn Hình", MessageBoxButtons.OK, MessageBoxIcon.Error);
                            }
                        }
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (x >= 204 && x <= 280 && y >= 95 && y <= 124) // Album ảnh
                {
                    using (OpenFileDialog ofd = new OpenFileDialog())
                    {
                        ofd.Multiselect = true;
                        ofd.Filter = "Tệp hình ảnh (*.png;*.jpg;*.jpeg)|*.png;*.jpg;*.jpeg";
                        if (ofd.ShowDialog(parentForm) == DialogResult.OK)
                        {
                            foreach (var fn in ofd.FileNames)
                            {
                                slidesView.AddSlide();
                                Image loadedImg = Image.FromFile(fn);
                                ShapeNode imgShape = new ShapeNode
                                {
                                    Type = ShapeType.Image,
                                    ImagePath = fn,
                                    CachedImage = loadedImg,
                                    Transform = new Transform2D(100f, 60f, 600f, 400f),
                                    Text = "",
                                    FillColor = 0x00FFFFFF,
                                    StrokeWidth = 0f
                                };
                                slidesView.ActiveSlide.AddShape(imgShape);
