                if (x >= ax && x <= ax + 110 && y >= 68 && y <= 130)
                {
                    slidesView.ToggleAnimationPane();
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                ax += 118 + 14;

                // 6. Timing Controls: Trigger (X: ax + 54..ax + 170, Y: 70..90)
                if (x >= ax + 54 && x <= ax + 170 && y >= 70 && y <= 90)
                {
                    if (hasSelectedShape && slidesView.SelectedAnimation != null)
                    {
                        ContextMenuStrip trigMenu = new ContextMenuStrip();
                        trigMenu.Font = new Font("Segoe UI", 9f);
                        trigMenu.Items.Add("🖱️ Bắt đầu khi nhấp chuột (Start On Click)", null, (s, e) => {
                            slidesView.SetSelectedAnimationTrigger(AnimationTrigger.OnClick);
                            if (parentForm != null) parentForm.Invalidate();
                        });
                        trigMenu.Items.Add("⏱️ Bắt đầu cùng với trước đó (Start With Previous)", null, (s, e) => {
                            slidesView.SetSelectedAnimationTrigger(AnimationTrigger.WithPrevious);
                            if (parentForm != null) parentForm.Invalidate();
                        });
                        trigMenu.Items.Add("⏳ Bắt đầu sau trước đó (Start After Previous)", null, (s, e) => {
                            slidesView.SetSelectedAnimationTrigger(AnimationTrigger.AfterPrevious);
                            if (parentForm != null) parentForm.Invalidate();
                        });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(ax + 54, 92)) : new Point(ax + 54, 92);
                        trigMenu.Show(pt);
                    }
                    return true;
                }

                // Timing Controls: Duration (X: ax + 54..ax + 170, Y: 92..112)
                if (x >= ax + 54 && x <= ax + 170 && y >= 92 && y <= 112)
                {
                    if (hasSelectedShape && slidesView.SelectedAnimation != null)
                    {
                        ShapeAnimation sa = slidesView.SelectedAnimation;
                        float curDur = (sa != null) ? sa.Duration : 0.5f;
                        if (x >= ax + 146)
                        {
                            if (y <= 101) slidesView.SetSelectedAnimationDuration(curDur + 0.25f);
                            else slidesView.SetSelectedAnimationDuration(Math.Max(0.1f, curDur - 0.25f));
                        }
                        else
                        {
                            ContextMenuStrip durMenu = new ContextMenuStrip();
                            durMenu.Font = new Font("Segoe UI", 9f);
                            float[] dPresets = new float[] { 0.25f, 0.50f, 0.75f, 1.00f, 1.50f, 2.00f, 3.00f, 5.00f };
                            foreach (float dp in dPresets)
                            {
                                float targetD = dp;
                                durMenu.Items.Add(string.Format("{0:0.00} giây", targetD), null, (s, e) => {
                                    slidesView.SetSelectedAnimationDuration(targetD);
                                    if (parentForm != null) parentForm.Invalidate();
                                });
                            }
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(ax + 54, 114)) : new Point(ax + 54, 114);
                            durMenu.Show(pt);
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }

                // Timing Controls: Delay (X: ax + 54..ax + 170, Y: 114..134)
                if (x >= ax + 54 && x <= ax + 170 && y >= 114 && y <= 134)
                {
                    if (hasSelectedShape && slidesView.SelectedAnimation != null)
                    {
                        ShapeAnimation sa = slidesView.SelectedAnimation;
                        float curDel = (sa != null) ? sa.Delay : 0.0f;
                        if (x >= ax + 146)
                        {
                            if (y <= 123) slidesView.SetSelectedAnimationDelay(curDel + 0.25f);
                            else slidesView.SetSelectedAnimationDelay(Math.Max(0.0f, curDel - 0.25f));
                        }
                        else
                        {
                            ContextMenuStrip delMenu = new ContextMenuStrip();
                            delMenu.Font = new Font("Segoe UI", 9f);
                            float[] dlPresets = new float[] { 0.00f, 0.25f, 0.50f, 0.75f, 1.00f, 1.50f, 2.00f };
                            foreach (float dlp in dlPresets)
                            {
                                float targetDl = dlp;
                                delMenu.Items.Add(string.Format("{0:0.00} giây", targetDl), null, (s, e) => {
                                    slidesView.SetSelectedAnimationDelay(targetDl);
                                    if (parentForm != null) parentForm.Invalidate();
                                });
                            }
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(ax + 54, 136)) : new Point(ax + 54, 136);
                            delMenu.Show(pt);
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }

                ax += 184 + 14;

                // 7. Reorder Controls: Move Earlier (X: ax..ax + 95, Y: 72..98)
                if (x >= ax && x <= ax + 95 && y >= 72 && y <= 98)
                {
                    if (hasSelectedShape && slidesView.SelectedAnimation != null)
                    {
                        slidesView.MoveAnimationEarlier();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }

                // Reorder Controls: Move Later (X: ax..ax + 95, Y: 104..130)
                if (x >= ax && x <= ax + 95 && y >= 104 && y <= 130)
                {
                    if (hasSelectedShape && slidesView.SelectedAnimation != null)
                    {
                        slidesView.MoveAnimationLater();
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }
            }
            else if (ActiveRibbonTab == 5) // Trình chiếu (Slide Show)
            {
                AppForm af = parentForm as AppForm;

                // 1. From Beginning (F5) (X: 12..86, Y: 68..130)
                if (x >= 12 && x <= 86 && y >= 68 && y <= 130)
                {
                    if (af != null) af.StartSlideShow(true);
                    else slidesView.StartPresenting(true);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // 2. From Current Slide (Shift+F5) (X: 90..176, Y: 68..130)
                else if (x >= 90 && x <= 176 && y >= 68 && y <= 130)
                {
                    if (af != null) af.StartSlideShow(false);
                    else slidesView.StartPresenting(false);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // 3. Custom Slide Show ▾ (X: 180..264, Y: 68..130)
                else if (x >= 180 && x <= 264 && y >= 68 && y <= 130)
                {
                    slidesView.ShowCustomSlideShowManager(parentForm);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // 4. Set Up Slide Show (X: 278..354, Y: 68..130)
                else if (x >= 278 && x <= 354 && y >= 68 && y <= 130)
                {
                    slidesView.ShowSetUpSlideShowDialog(parentForm);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // 5. Hide Slide (X: 358..422, Y: 68..130)
                else if (x >= 358 && x <= 422 && y >= 68 && y <= 130)
                {
                    if (slidesView.ActiveSlide != null)
                    {
                        slidesView.ActiveSlide.IsHidden = !slidesView.ActiveSlide.IsHidden;
                        if (parentForm != null) parentForm.Invalidate();
                    }
                    return true;
                }
                // 6. Rehearse Timings (X: 426..502, Y: 68..130)
                else if (x >= 426 && x <= 502 && y >= 68 && y <= 130)
                {
                    slidesView.StartRehearsingTimings();
                    if (af != null) af.StartSlideShow(true);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // 7. Record Slide Show ▾ (X: 506..584, Y: 68..130)
                else if (x >= 506 && x <= 584 && y >= 68 && y <= 130)
                {
                    ContextMenuStrip recMenu = new ContextMenuStrip();
                    ToolStripMenuItem miCur = new ToolStripMenuItem("🔴 Bắt đầu Ghi từ slide hiện tại (Record from Current Slide)...");
                    miCur.Click += (s, e) => {
                        using (RecordSlideShowForm recForm = new RecordSlideShowForm(slidesView, slidesView.ActiveSlideIndex))
                        {
                            recForm.ShowDialog(parentForm);
                        }
                    };
                    recMenu.Items.Add(miCur);

                    ToolStripMenuItem miBeg = new ToolStripMenuItem("🔴 Bắt đầu Ghi từ slide đầu tiên (Record from Beginning)...");
                    miBeg.Click += (s, e) => {
                        using (RecordSlideShowForm recForm = new RecordSlideShowForm(slidesView, 0))
                        {
                            recForm.ShowDialog(parentForm);
                        }
                    };
                    recMenu.Items.Add(miBeg);

                    recMenu.Items.Add(new ToolStripSeparator());

                    ToolStripMenuItem miClrCur = new ToolStripMenuItem("🗑️ Xóa thời gian đã ghi trên slide này");
                    miClrCur.Click += (s, e) => {
                        if (slidesView.ActiveSlide != null)
                        {
                            slidesView.ActiveSlide.AutoAdvance = false;
                            slidesView.ActiveSlide.AutoAdvanceSeconds = 0;
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    recMenu.Items.Add(miClrCur);

                    ToolStripMenuItem miClrAll = new ToolStripMenuItem("🗑️ Xóa thời gian trên tất cả slide");
                    miClrAll.Click += (s, e) => {
                        if (slidesView.Presentation != null)
                        {
                            foreach (var sl in slidesView.Presentation.Slides)
                            {
                                sl.AutoAdvance = false;
                                sl.AutoAdvanceSeconds = 0;
                            }
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    recMenu.Items.Add(miClrAll);

                    Control hostCtrl = parentForm ?? Form.ActiveForm;
                    if (hostCtrl != null) recMenu.Show(hostCtrl, new Point(506, 130));
                    else recMenu.Show(Cursor.Position);
                    return true;
                }
                // 8. Cột 3 Checkboxes (Play Narrations, Use Timings, Show Media Controls) (X: 592..755)
                else if (x >= 592 && x <= 755 && y >= 68 && y <= 86)
                {
                    slidesView.PlayNarrations = !slidesView.PlayNarrations;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (x >= 592 && x <= 755 && y >= 88 && y <= 106)
                {
                    slidesView.UseTimings = !slidesView.UseTimings;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                else if (x >= 592 && x <= 755 && y >= 108 && y <= 128)
                {
                    slidesView.ShowMediaControls = !slidesView.ShowMediaControls;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // 9. Monitors Dropdown (X: 840..980, Y: 68..92)
                else if (x >= 840 && x <= 980 && y >= 68 && y <= 92)
                {
                    ContextMenuStrip monMenu = new ContextMenuStrip();
                    ToolStripMenuItem mAuto = new ToolStripMenuItem("Tự động (Automatic)");
                    mAuto.Click += (s, e) => {
                        slidesView.SelectedMonitorIndex = 0;
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    monMenu.Items.Add(mAuto);

                    for (int m = 0; m < Screen.AllScreens.Length; m++)
                    {
                        int capturedM = m + 1;
                        ToolStripMenuItem mItem = new ToolStripMenuItem(string.Format("Màn hình {0}: {1}", capturedM, Screen.AllScreens[m].DeviceName));
                        mItem.Click += (s, e) => {
                            slidesView.SelectedMonitorIndex = capturedM;
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        monMenu.Items.Add(mItem);
                    }
                    Control hostCtrl = parentForm ?? Form.ActiveForm;
                    if (hostCtrl != null) monMenu.Show(hostCtrl, new Point(840, 92));
                    else monMenu.Show(Cursor.Position);
                    return true;
                }
                // 10. Checkbox: Use Presenter View (X: 765..980, Y: 96..120)
                else if (x >= 765 && x <= 980 && y >= 96 && y <= 120)
                {
                    slidesView.UsePresenterView = !slidesView.UsePresenterView;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }
            else if (ActiveRibbonTab == 6) // Hiển thị (View)
            {
                int vIdx = (x - 12) / 82;
                if (vIdx >= 0 && vIdx <= 4)
                {
                    slidesView.ViewMode = (ImpressViewMode)vIdx;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }
            else if (ActiveRibbonTab == 7 && slidesView != null && slidesView.SelectedShape != null) // Định dạng Video, Thiết kế Bảng hoặc Định dạng Hình dạng
            {
                ShapeNode shape = slidesView.SelectedShape;

                if (shape.Type == ShapeType.Video || !string.IsNullOrEmpty(shape.VideoPath))
                {
                    // 1. Nhóm Xem trước (Preview): Phát (X: 12..60, Y: 68..122)
                    if (x >= 12 && x <= 60 && y >= 68 && y <= 122)
                    {
                        slidesView.PlayVideoPreview(shape, parentForm);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // 2. Nhóm Điều chỉnh: Hiệu chỉnh ▾ (X: 74..182, Y: 68..92)
                    else if (x >= 74 && x <= 182 && y >= 68 && y <= 92)
                    {
                        ContextMenuStrip corrMenu = new ContextMenuStrip();
                        corrMenu.RenderMode = ToolStripRenderMode.System;
                        corrMenu.Items.Add("☀️ Sáng +40%, Tương phản +20%", null, (s, e) => { shape.VideoCorrections = "BrightHigh"; if (parentForm != null) parentForm.Invalidate(); });
                        corrMenu.Items.Add("☀️ Sáng +20%, Tương phản 0%", null, (s, e) => { shape.VideoCorrections = "BrightMed"; if (parentForm != null) parentForm.Invalidate(); });
                        corrMenu.Items.Add("⚖️ Chuẩn: Sáng 0%, Tương phản 0%", null, (s, e) => { shape.VideoCorrections = "Normal"; if (parentForm != null) parentForm.Invalidate(); });
                        corrMenu.Items.Add("🌙 Tối -20%, Tương phản 0%", null, (s, e) => { shape.VideoCorrections = "DarkMed"; if (parentForm != null) parentForm.Invalidate(); });
                        corrMenu.Items.Add("🌙 Tối -40%, Tương phản +20%", null, (s, e) => { shape.VideoCorrections = "DarkHigh"; if (parentForm != null) parentForm.Invalidate(); });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(74, 92)) : new Point(74, 92);
                        corrMenu.Show(pt);
                        return true;
                    }
                    // Khung áp phích ▾ (Poster Frame) (X: 186..308, Y: 68..92)
                    else if (x >= 186 && x <= 308 && y >= 68 && y <= 92)
                    {
                        ContextMenuStrip posMenu = new ContextMenuStrip();
                        posMenu.RenderMode = ToolStripRenderMode.System;
                        posMenu.Items.Add("🖼️ Hình ảnh từ Tệp...", null, (s, e) => {
                            using (OpenFileDialog ofd = new OpenFileDialog())
                            {
                                ofd.Filter = "Tệp hình ảnh (*.png;*.jpg;*.jpeg;*.bmp;*.webp)|*.png;*.jpg;*.jpeg;*.bmp;*.webp|Tất cả tệp (*.*)|*.*";
                                ofd.Title = "Chọn hình ảnh làm Khung áp phích (Poster Frame)";
                                if (ofd.ShowDialog() == DialogResult.OK)
                                {
                                    shape.VideoPosterFramePath = ofd.FileName;
                                    if (parentForm != null) parentForm.Invalidate();
                                }
                            }
                        });
                        posMenu.Items.Add("🔄 Đặt lại Khung áp phích", null, (s, e) => {
                            shape.VideoPosterFramePath = null;
                            if (parentForm != null) parentForm.Invalidate();
                        });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(186, 92)) : new Point(186, 92);
                        posMenu.Show(pt);
                        return true;
                    }
                    // Màu sắc ▾ (Color) (X: 74..182, Y: 96..120)
                    else if (x >= 74 && x <= 182 && y >= 96 && y <= 120)
                    {
                        ContextMenuStrip colMenu = new ContextMenuStrip();
                        colMenu.RenderMode = ToolStripRenderMode.System;
                        colMenu.Items.Add("Chuẩn (Normal)", null, (s, e) => { shape.VideoColorFilter = "None"; if (parentForm != null) parentForm.Invalidate(); });
                        colMenu.Items.Add("Trắng đen (Grayscale)", null, (s, e) => { shape.VideoColorFilter = "Grayscale"; if (parentForm != null) parentForm.Invalidate(); });
                        colMenu.Items.Add("Màu nâu cổ điển (Sepia)", null, (s, e) => { shape.VideoColorFilter = "Sepia"; if (parentForm != null) parentForm.Invalidate(); });
                        colMenu.Items.Add("Tông Xanh Dương (Blue)", null, (s, e) => { shape.VideoColorFilter = "Blue"; if (parentForm != null) parentForm.Invalidate(); });
                        colMenu.Items.Add("Tông Cam Nắng (Orange)", null, (s, e) => { shape.VideoColorFilter = "Orange"; if (parentForm != null) parentForm.Invalidate(); });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(74, 120)) : new Point(74, 120);
                        colMenu.Show(pt);
                        return true;
                    }
                    // Đặt lại Thiết kế ▾ (Reset Design) (X: 186..308, Y: 96..120)
                    else if (x >= 186 && x <= 308 && y >= 96 && y <= 120)
                    {
                        ContextMenuStrip rstMenu = new ContextMenuStrip();
                        rstMenu.RenderMode = ToolStripRenderMode.System;
                        rstMenu.Items.Add("🔄 Đặt lại Thiết kế Video", null, (s, e) => {
                            shape.VideoStyleIndex = 0;
                            shape.VideoColorFilter = "None";
                            shape.VideoCorrections = "Normal";
                            if (parentForm != null) parentForm.Invalidate();
                        });
                        rstMenu.Items.Add("📐 Đặt lại Thiết kế & Kích cỡ", null, (s, e) => {
                            shape.VideoStyleIndex = 0;
                            shape.VideoColorFilter = "None";
                            shape.VideoCorrections = "Normal";
                            if (shape.OriginalWidth > 0 && shape.OriginalHeight > 0)
                            {
                                shape.Transform.Width = shape.OriginalWidth;
                                shape.Transform.Height = shape.OriginalHeight;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(186, 120)) : new Point(186, 120);
                        rstMenu.Show(pt);
                        return true;
                    }
                    // 3. 7 Video Style Cards (X: 320..614, Y: 68..122)
                    else if (x >= 320 && x < 320 + 7 * 42 && y >= 68 && y <= 122)
                    {
                        int sIdx = (x - 320) / 42;
                        if (sIdx >= 0 && sIdx < 7)
                        {
                            shape.VideoStyleIndex = sIdx;
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                    }
                    // Hình dạng Video ▾ (X: 620..736, Y: 68..86)
                    else if (x >= 620 && x <= 736 && y >= 68 && y <= 86)
                    {
                        ContextMenuStrip vShapeMenu = new ContextMenuStrip();
                        vShapeMenu.RenderMode = ToolStripRenderMode.System;
                        vShapeMenu.Items.Add("Chữ nhật", null, (s, e) => { shape.Type = ShapeType.Rectangle; if (parentForm != null) parentForm.Invalidate(); });
                        vShapeMenu.Items.Add("Chữ nhật bo góc", null, (s, e) => { shape.Type = ShapeType.RoundedRectangle; if (parentForm != null) parentForm.Invalidate(); });
                        vShapeMenu.Items.Add("Hình Elip / Tròn", null, (s, e) => { shape.Type = ShapeType.Ellipse; if (parentForm != null) parentForm.Invalidate(); });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(620, 86)) : new Point(620, 86);
                        vShapeMenu.Show(pt);
                        return true;
                    }
                    // Viền Video ▾ (X: 620..736, Y: 88..106)
                    else if (x >= 620 && x <= 736 && y >= 88 && y <= 106)
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(620, 106)) : new Point(620, 106);
                        int oc = shape.StrokeColor;
                        Color curC = Color.FromArgb((oc >> 16) & 0xFF, (oc >> 8) & 0xFF, oc & 0xFF);
                        ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, false);
                        colDlg.OnColorSelected += (c) =>
                        {
                            shape.StrokeColor = c.ToArgb() & 0xFFFFFF;
                            if (shape.StrokeWidth < 1f) shape.StrokeWidth = 2f;
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        colDlg.Show();
                        return true;
                    }
                    // Hiệu ứng Video ▾ (X: 620..736, Y: 108..126)
                    else if (x >= 620 && x <= 736 && y >= 108 && y <= 126)
                    {
                        ContextMenuStrip efxMenu = new ContextMenuStrip();
                        efxMenu.RenderMode = ToolStripRenderMode.System;
                        efxMenu.Items.Add("Đổ bóng (Shadow)", null, (s, e) => { shape.VideoStyleIndex = 2; if (parentForm != null) parentForm.Invalidate(); });
                        efxMenu.Items.Add("Phát sáng (Glow)", null, (s, e) => { shape.VideoStyleIndex = 6; if (parentForm != null) parentForm.Invalidate(); });
                        efxMenu.Items.Add("Hiệu ứng 3D", null, (s, e) => { shape.VideoStyleIndex = 5; if (parentForm != null) parentForm.Invalidate(); });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(620, 126)) : new Point(620, 126);
                        efxMenu.Show(pt);
                        return true;
                    }
                    // 4. Khả năng truy cập: Văn bản Thay thế (X: 744..808, Y: 68..122)
                    else if (x >= 744 && x <= 808 && y >= 68 && y <= 122)
                    {
                        MessageBox.Show("Văn bản thay thế (Alt Text) giúp người dùng khiếm thị hiểu được nội dung video này.", "Văn bản Thay thế (Alt Text)", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return true;
                    }
                    // 5. Nhóm Sắp xếp: Đưa lên trên (X: 822..918, Y: 68..86)
                    else if (x >= 822 && x <= 918 && y >= 68 && y <= 86)
                    {
                        if (slidesView.ActiveSlide != null && slidesView.SelectedShapeIndex < slidesView.ActiveSlide.Shapes.Count - 1)
                        {
                            int idx = slidesView.SelectedShapeIndex;
                            ShapeNode s1 = slidesView.ActiveSlide.Shapes[idx];
                            slidesView.ActiveSlide.Shapes[idx] = slidesView.ActiveSlide.Shapes[idx + 1];
                            slidesView.ActiveSlide.Shapes[idx + 1] = s1;
                            slidesView.SelectedShapeIndex = idx + 1;
                        }
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // Đưa ra sau (X: 822..918, Y: 88..106)
                    else if (x >= 822 && x <= 918 && y >= 88 && y <= 106)
                    {
                        if (slidesView.ActiveSlide != null && slidesView.SelectedShapeIndex > 0)
                        {
                            int idx = slidesView.SelectedShapeIndex;
                            ShapeNode s1 = slidesView.ActiveSlide.Shapes[idx];
                            slidesView.ActiveSlide.Shapes[idx] = slidesView.ActiveSlide.Shapes[idx - 1];
                            slidesView.ActiveSlide.Shapes[idx - 1] = s1;
                            slidesView.SelectedShapeIndex = idx - 1;
                        }
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // Ngăn Lựa chọn (X: 822..918, Y: 108..126)
                    else if (x >= 822 && x <= 918 && y >= 108 && y <= 126)
                    {
                        slidesView.SidebarPanel = SidebarPanelType.SelectionPane;
                        slidesView.IsSidebarOpen = true;
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // Căn chỉnh ▾ (X: 922..1010, Y: 68..86)
                    else if (x >= 922 && x <= 1010 && y >= 68 && y <= 86)
                    {
                        ContextMenuStrip alignMenu = new ContextMenuStrip();
                        alignMenu.RenderMode = ToolStripRenderMode.System;
                        alignMenu.Items.Add("Căn Trái", null, (s, e) => { shape.Transform.X = 0; if (parentForm != null) parentForm.Invalidate(); });
                        alignMenu.Items.Add("Căn Giữa ngang", null, (s, e) => { shape.Transform.X = (slidesView.Presentation.CanvasWidth - shape.Transform.Width) / 2f; if (parentForm != null) parentForm.Invalidate(); });
                        alignMenu.Items.Add("Căn Phải", null, (s, e) => { shape.Transform.X = slidesView.Presentation.CanvasWidth - shape.Transform.Width; if (parentForm != null) parentForm.Invalidate(); });
                        alignMenu.Items.Add(new ToolStripSeparator());
                        alignMenu.Items.Add("Căn Trên", null, (s, e) => { shape.Transform.Y = 0; if (parentForm != null) parentForm.Invalidate(); });
                        alignMenu.Items.Add("Căn Giữa dọc", null, (s, e) => { shape.Transform.Y = (slidesView.Presentation.CanvasHeight - shape.Transform.Height) / 2f; if (parentForm != null) parentForm.Invalidate(); });
                        alignMenu.Items.Add("Căn Dưới", null, (s, e) => { shape.Transform.Y = slidesView.Presentation.CanvasHeight - shape.Transform.Height; if (parentForm != null) parentForm.Invalidate(); });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(922, 86)) : new Point(922, 86);
                        alignMenu.Show(pt);
                        return true;
                    }
                    // Nhóm ▾ (X: 922..1010, Y: 88..106)
                    else if (x >= 922 && x <= 1010 && y >= 88 && y <= 106)
                    {
                        return true;
                    }
                    // Xoay ▾ (X: 922..1010, Y: 108..126)
                    else if (x >= 922 && x <= 1010 && y >= 108 && y <= 126)
                    {
                        ContextMenuStrip rotMenu = new ContextMenuStrip();
                        rotMenu.RenderMode = ToolStripRenderMode.System;
                        rotMenu.Items.Add("Xoay phải 90°", null, (s, e) => { shape.Transform.Rotation = (shape.Transform.Rotation + 90f) % 360f; if (parentForm != null) parentForm.Invalidate(); });
                        rotMenu.Items.Add("Xoay trái 90°", null, (s, e) => { shape.Transform.Rotation = (shape.Transform.Rotation + 270f) % 360f; if (parentForm != null) parentForm.Invalidate(); });
                        rotMenu.Items.Add("Lật dọc", null, (s, e) => { shape.Transform.FlipVertical = !shape.Transform.FlipVertical; if (parentForm != null) parentForm.Invalidate(); });
                        rotMenu.Items.Add("Lật ngang", null, (s, e) => { shape.Transform.FlipHorizontal = !shape.Transform.FlipHorizontal; if (parentForm != null) parentForm.Invalidate(); });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(922, 126)) : new Point(922, 126);
                        rotMenu.Show(pt);
                        return true;
                    }
                    // 6. Nhóm Kích cỡ: Cắt tỉa (X: 1024..1072, Y: 68..122)
                    else if (x >= 1024 && x <= 1072 && y >= 68 && y <= 122)
                    {
                        slidesView.ToggleCropMode();
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // Chiều cao ▲ / ▼ (X: 1076..1194, Y: 68..93)
                    else if (x >= 1076 && x <= 1194 && y >= 68 && y <= 93)
                    {
                        bool isUp = (y <= 80);
                        shape.Transform.Height = Math.Max(20f, shape.Transform.Height + (isUp ? 25f : -25f));
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // Chiều rộng ▲ / ▼ (X: 1076..1194, Y: 96..121)
                    else if (x >= 1076 && x <= 1194 && y >= 96 && y <= 121)
                    {
                        bool isUp = (y <= 108);
                        shape.Transform.Width = Math.Max(20f, shape.Transform.Width + (isUp ? 25f : -25f));
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                }
                else if (shape.Type == ShapeType.Table)
                {
                    // Group 1: Tùy chọn Kiểu Bảng
                    if (x >= 12 && x <= 117 && y >= 68 && y <= 93)
                    {
                        shape.TableHeaderRow = !shape.TableHeaderRow;
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    else if (x >= 12 && x <= 117 && y >= 96 && y <= 121)
                    {
                        shape.TableBandedRows = !shape.TableBandedRows;
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // Group 2: Thư viện Kiểu Bảng (6 Preset Cards)
                    else if (x >= 132 && x <= 390 && y >= 68 && y <= 122)
                    {
                        int cardIdx = (x - 132) / 43;
                        if (cardIdx >= 0 && cardIdx < 6)
                        {
                            slidesView.ApplyTableStylePreset(shape, cardIdx);
                            if (parentForm != null) parentForm.Invalidate();
                        }
                        return true;
                    }
                    // Stack: Tô màu ô (Shading) & Viền ô (Borders)
                    else if (x >= 396 && x <= 502 && y >= 68 && y <= 92) // Tô màu ô (Shading)
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(396, 94)) : new Point(396, 94);
                        int curFill = (shape.FillColor != 0x00FFFFFF) ? shape.FillColor : 0x2563EB;
                        Color curC = Color.FromArgb((curFill >> 16) & 0xFF, (curFill >> 8) & 0xFF, curFill & 0xFF);
                        ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, true);
                        colDlg.OnColorSelected += (c) =>
                        {
                            if (c == Color.Transparent)
                            {
                                slidesView.SetSelectedTableCellFillColor(0x00FFFFFF);
                            }
                            else
                            {
                                slidesView.SetSelectedTableCellFillColor(c.ToArgb() & 0xFFFFFF);
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        colDlg.Show();
                        return true;
                    }
                    else if (x >= 396 && x <= 502 && y >= 94 && y <= 118) // Viền ô ▾ (Borders)
                    {
                        ContextMenuStrip borderMenu = new ContextMenuStrip();
                        borderMenu.Items.Add(new ToolStripMenuItem("▦ Tất cả viền (All Borders)", null, (s, e) => {
                            shape.StrokeColor = (shape.FillColor != 0x00FFFFFF) ? shape.FillColor : 0x2563EB;
                            if (parentForm != null) parentForm.Invalidate();
                        }));
                        borderMenu.Items.Add(new ToolStripMenuItem("▢ Chỉ viền ngoài (Outside Borders)", null, (s, e) => {
                            shape.StrokeColor = 0x2563EB;
                            if (parentForm != null) parentForm.Invalidate();
                        }));
                        borderMenu.Items.Add(new ToolStripMenuItem("⛶ Không viền (No Border)", null, (s, e) => {
                            shape.StrokeColor = 0x00FFFFFF;
                            if (parentForm != null) parentForm.Invalidate();
                        }));
                        borderMenu.Items.Add(new ToolStripSeparator());
                        borderMenu.Items.Add(new ToolStripMenuItem("🎨 Bảng màu viền (Border Color)...", null, (s, e) => {
                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(396, 120)) : new Point(396, 120);
                            int sc = (shape.StrokeColor != 0x00FFFFFF) ? shape.StrokeColor : 0x2563EB;
                            Color curC = Color.FromArgb((sc >> 16) & 0xFF, (sc >> 8) & 0xFF, sc & 0xFF);
                            ColorPaletteForm bDlg = new ColorPaletteForm(pt, curC, true);
                            bDlg.OnColorSelected += (c) =>
                            {
                                shape.StrokeColor = (c == Color.Transparent) ? 0x00FFFFFF : (c.ToArgb() & 0xFFFFFF);
                                if (parentForm != null) parentForm.Invalidate();
                            };
                            bDlg.Show();
                        }));
                        Control hostCtrl = parentForm ?? Form.ActiveForm;
                        if (hostCtrl != null) borderMenu.Show(hostCtrl, new Point(396, 120));
                        else borderMenu.Show(Cursor.Position);
                        return true;
                    }
                    // Group 3: Định dạng Chữ
                    else if (x >= 522 && x <= 608 && y >= 68 && y <= 93) // Màu chữ
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(522, 94)) : new Point(522, 94);
                        Color curC = Color.Black;
                        ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, false);
                        colDlg.OnColorSelected += (c) =>
                        {
                            slidesView.SetSelectedTableCellTextColor(c.ToArgb() & 0xFFFFFF);
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        colDlg.Show();
                        return true;
                    }
                    else if (x >= 522 && x <= 562 && y >= 96 && y <= 121) // Chữ Đậm (Bold)
                    {
                        string cellKey = (shape.TableSelectedCellRow >= 0 ? shape.TableSelectedCellRow : 0) + "," + (shape.TableSelectedCellCol >= 0 ? shape.TableSelectedCellCol : 0);
                        bool isCurrentlyBold = (shape.TableCellBolds != null && shape.TableCellBolds.ContainsKey(cellKey) && shape.TableCellBolds[cellKey]);
                        slidesView.SetSelectedTableCellBold(!isCurrentlyBold);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    else if (x >= 566 && x <= 608 && y >= 96 && y <= 121) // Chữ Nghiêng (Italic)
                    {
                        shape.Italic = !shape.Italic;
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // Group 4: Chèn Hàng & Cột
                    else if (x >= 628 && x <= 716 && y >= 68 && y <= 93) // Chèn Trên
                    {
                        slidesView.InsertTableRow(true);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    else if (x >= 628 && x <= 716 && y >= 96 && y <= 121) // Chèn Dưới
                    {
                        slidesView.InsertTableRow(false);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    else if (x >= 720 && x <= 808 && y >= 68 && y <= 93) // Chèn Trái
                    {
                        slidesView.InsertTableColumn(true);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    else if (x >= 720 && x <= 808 && y >= 96 && y <= 121) // Chèn Phải
                    {
                        slidesView.InsertTableColumn(false);
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // Group 5: Xóa
                    else if (x >= 828 && x <= 906 && y >= 68 && y <= 93) // Xóa Hàng
                    {
                        slidesView.DeleteTableRow();
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    else if (x >= 828 && x <= 906 && y >= 96 && y <= 121) // Xóa Cột
                    {
                        slidesView.DeleteTableColumn();
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    else if (x >= 910 && x <= 996 && y >= 68 && y <= 121) // Xóa Bảng
                    {
                        if (slidesView.ActiveSlide != null)
                        {
                            slidesView.ActiveSlide.Shapes.Remove(shape);
                            slidesView.SelectedShapeIndex = -1;
                            slidesView.EndTableInlineEditing();
                        }
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                }
                else if (shape.Type == ShapeType.Image || shape.CachedImage != null || !string.IsNullOrEmpty(shape.ImagePath))
                {
                    // 1. Xóa nền (Remove Background - Chuyển sang Tab Loại bỏ nền) (X: 12..80, Y: 68..122)
                    if (x >= 12 && x <= 80 && y >= 68 && y <= 122)
                    {
                        if (slidesView != null)
                        {
                            slidesView.StartBackgroundRemoval();
                            if (parentForm != null) parentForm.Invalidate();
                        }
                        return true;
                    }
                    // 2. Chỉnh sửa ▾ (Corrections ▾) (X: 84..156, Y: 68..122)
                    else if (x >= 84 && x <= 156 && y >= 68 && y <= 122)
                    {
                        ContextMenuStrip corrMenu = new ContextMenuStrip();
                        corrMenu.RenderMode = ToolStripRenderMode.System;

                        ToolStripMenuItem mSharp = new ToolStripMenuItem("🔍 Độ nét / Làm mờ (Sharpen / Soften)");
                        mSharp.DropDownItems.Add("Làm nét +50% (Sharpen 50%)", null, (s, e) => { shape.ImageContrast = 1.4f; if (parentForm != null) parentForm.Invalidate(); });
                        mSharp.DropDownItems.Add("Làm nét +25% (Sharpen 25%)", null, (s, e) => { shape.ImageContrast = 1.2f; if (parentForm != null) parentForm.Invalidate(); });
                        mSharp.DropDownItems.Add("Chuẩn 0% (Normal)", null, (s, e) => { shape.ImageContrast = 1.0f; if (parentForm != null) parentForm.Invalidate(); });
                        mSharp.DropDownItems.Add("Làm mờ -25% (Soften 25%)", null, (s, e) => { shape.ImageContrast = 0.85f; if (parentForm != null) parentForm.Invalidate(); });
                        mSharp.DropDownItems.Add("Làm mờ -50% (Soften 50%)", null, (s, e) => { shape.ImageContrast = 0.7f; if (parentForm != null) parentForm.Invalidate(); });
                        corrMenu.Items.Add(mSharp);

                        ToolStripMenuItem mBright = new ToolStripMenuItem("☀️ Độ sáng / Độ tương phản (Brightness / Contrast)");
                        mBright.DropDownItems.Add("☀️ Sáng +40%, Tương phản +20%", null, (s, e) => { shape.ImageBrightness = 0.35f; shape.ImageContrast = 1.2f; if (parentForm != null) parentForm.Invalidate(); });
                        mBright.DropDownItems.Add("☀️ Sáng +20%, Tương phản 0%", null, (s, e) => { shape.ImageBrightness = 0.20f; shape.ImageContrast = 1.0f; if (parentForm != null) parentForm.Invalidate(); });
                        mBright.DropDownItems.Add("⚖️ Chuẩn: Sáng 0%, Tương phản 0%", null, (s, e) => { shape.ImageBrightness = 0.0f; shape.ImageContrast = 1.0f; if (parentForm != null) parentForm.Invalidate(); });
                        mBright.DropDownItems.Add("🌙 Tối -20%, Tương phản 0%", null, (s, e) => { shape.ImageBrightness = -0.20f; shape.ImageContrast = 1.0f; if (parentForm != null) parentForm.Invalidate(); });
                        mBright.DropDownItems.Add("🌙 Tối -40%, Tương phản +20%", null, (s, e) => { shape.ImageBrightness = -0.35f; shape.ImageContrast = 1.2f; if (parentForm != null) parentForm.Invalidate(); });
                        mBright.DropDownItems.Add("🌓 Tương phản cao +40%", null, (s, e) => { shape.ImageContrast = 1.4f; if (parentForm != null) parentForm.Invalidate(); });
                        mBright.DropDownItems.Add("🌓 Tương phản thấp -40%", null, (s, e) => { shape.ImageContrast = 0.6f; if (parentForm != null) parentForm.Invalidate(); });
                        corrMenu.Items.Add(mBright);

                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(84, 124)) : new Point(84, 124);
                        corrMenu.Show(pt);
                        return true;
                    }
                    // 3. Màu sắc ▾ (Color ▾) (X: 160..270, Y: 68..92)
                    else if (x >= 160 && x <= 270 && y >= 68 && y <= 92)
                    {
                        ContextMenuStrip colMenu = new ContextMenuStrip();
                        colMenu.RenderMode = ToolStripRenderMode.System;

                        ToolStripMenuItem mSat = new ToolStripMenuItem("🎨 Độ bão hòa màu (Color Saturation)");
                        mSat.DropDownItems.Add("0% Trắng đen (Grayscale)", null, (s, e) => { shape.ImageSaturation = 0.0f; shape.ImageRecolor = "None"; if (parentForm != null) parentForm.Invalidate(); });
                        mSat.DropDownItems.Add("50% Nhạt màu", null, (s, e) => { shape.ImageSaturation = 0.5f; if (parentForm != null) parentForm.Invalidate(); });
                        mSat.DropDownItems.Add("100% Màu chuẩn (Normal)", null, (s, e) => { shape.ImageSaturation = 1.0f; if (parentForm != null) parentForm.Invalidate(); });
                        mSat.DropDownItems.Add("200% Rực rỡ (Vibrant)", null, (s, e) => { shape.ImageSaturation = 2.0f; if (parentForm != null) parentForm.Invalidate(); });
                        mSat.DropDownItems.Add("300% Cực rực rỡ (High Saturation)", null, (s, e) => { shape.ImageSaturation = 3.0f; if (parentForm != null) parentForm.Invalidate(); });
                        colMenu.Items.Add(mSat);

                        ToolStripMenuItem mTone = new ToolStripMenuItem("🌡️ Tông màu (Color Tone / Nhiệt độ K)");
                        mTone.DropDownItems.Add("4700K (Tông ấm / Vàng nắng)", null, (s, e) => { shape.ImageRecolor = "Orange"; if (parentForm != null) parentForm.Invalidate(); });
                        mTone.DropDownItems.Add("6500K (Tông chuẩn / Neutral)", null, (s, e) => { shape.ImageRecolor = "None"; if (parentForm != null) parentForm.Invalidate(); });
                        mTone.DropDownItems.Add("8800K (Tông lạnh / Xanh lam)", null, (s, e) => { shape.ImageRecolor = "Blue"; if (parentForm != null) parentForm.Invalidate(); });
                        colMenu.Items.Add(mTone);

                        ToolStripMenuItem mRecol = new ToolStripMenuItem("🖌️ Đổi màu nghệ thuật (Recolor)");
                        mRecol.DropDownItems.Add("Không đổi màu (No Recolor)", null, (s, e) => { shape.ImageRecolor = "None"; shape.ImageSaturation = 1.0f; if (parentForm != null) parentForm.Invalidate(); });
                        mRecol.DropDownItems.Add("Trắng đen (Grayscale)", null, (s, e) => { shape.ImageRecolor = "Grayscale"; if (parentForm != null) parentForm.Invalidate(); });
                        mRecol.DropDownItems.Add("Màu nâu cổ điển (Sepia)", null, (s, e) => { shape.ImageRecolor = "Sepia"; if (parentForm != null) parentForm.Invalidate(); });
                        mRecol.DropDownItems.Add("Mờ làm hình nền (Washout)", null, (s, e) => { shape.ImageRecolor = "Washout"; if (parentForm != null) parentForm.Invalidate(); });
                        mRecol.DropDownItems.Add("Tông Xanh Dương (Blue Tint)", null, (s, e) => { shape.ImageRecolor = "Blue"; if (parentForm != null) parentForm.Invalidate(); });
                        mRecol.DropDownItems.Add("Tông Cam Nắng (Orange Tint)", null, (s, e) => { shape.ImageRecolor = "Orange"; if (parentForm != null) parentForm.Invalidate(); });
                        mRecol.DropDownItems.Add("Tông Xanh Lá (Green Tint)", null, (s, e) => { shape.ImageRecolor = "Green"; if (parentForm != null) parentForm.Invalidate(); });
                        mRecol.DropDownItems.Add("Tông Tím Hoàng Gia (Purple Tint)", null, (s, e) => { shape.ImageRecolor = "Purple"; if (parentForm != null) parentForm.Invalidate(); });
                        colMenu.Items.Add(mRecol);

                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(160, 94)) : new Point(160, 94);
                        colMenu.Show(pt);
                        return true;
                    }
                    // 4. Hiệu ứng vẽ ▾ (Artistic Effects ▾) (X: 160..270, Y: 94..118)
                    else if (x >= 160 && x <= 270 && y >= 94 && y <= 118)
                    {
                        ContextMenuStrip artMenu = new ContextMenuStrip();
                        artMenu.RenderMode = ToolStripRenderMode.System;
                        artMenu.Items.Add("Không hiệu ứng (None)", null, (s, e) => { shape.ImageRecolor = "None"; shape.ImageContrast = 1.0f; shape.ImageSaturation = 1.0f; if (parentForm != null) parentForm.Invalidate(); });
                        artMenu.Items.Add("✏️ Phác thảo bút chì (Pencil Sketch)", null, (s, e) => { shape.ImageRecolor = "Grayscale"; shape.ImageContrast = 2.0f; if (parentForm != null) parentForm.Invalidate(); });
                        artMenu.Items.Add("🎨 Tranh màu nước (Watercolor)", null, (s, e) => { shape.ImageSaturation = 2.5f; shape.ImageContrast = 1.2f; if (parentForm != null) parentForm.Invalidate(); });
                        artMenu.Items.Add("🎞️ Phim cổ điển (Film Grain Sepia)", null, (s, e) => { shape.ImageRecolor = "Sepia"; shape.ImageContrast = 1.3f; if (parentForm != null) parentForm.Invalidate(); });
                        artMenu.Items.Add("💡 Đèn Neon phát sáng (Glow Neon)", null, (s, e) => { shape.ImageRecolor = "Blue"; shape.ImageBrightness = 0.2f; shape.ImageContrast = 1.5f; if (parentForm != null) parentForm.Invalidate(); });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(160, 120)) : new Point(160, 120);
                        artMenu.Show(pt);
                        return true;
                    }
                    // 5. Trong suốt ▾ (Transparency ▾) (X: 160..270, Y: 120..144)
                    else if (x >= 160 && x <= 270 && y >= 120 && y <= 144)
                    {
                        ContextMenuStrip transMenu = new ContextMenuStrip();
                        transMenu.RenderMode = ToolStripRenderMode.System;
                        transMenu.Items.Add("0% Trong suốt (100% Đặc)", null, (s, e) => { shape.FillOpacity = 1.0f; if (parentForm != null) parentForm.Invalidate(); });
                        transMenu.Items.Add("15% Trong suốt", null, (s, e) => { shape.FillOpacity = 0.85f; if (parentForm != null) parentForm.Invalidate(); });
                        transMenu.Items.Add("30% Trong suốt", null, (s, e) => { shape.FillOpacity = 0.70f; if (parentForm != null) parentForm.Invalidate(); });
                        transMenu.Items.Add("50% Bán trong suốt", null, (s, e) => { shape.FillOpacity = 0.50f; if (parentForm != null) parentForm.Invalidate(); });
                        transMenu.Items.Add("65% Trong suốt", null, (s, e) => { shape.FillOpacity = 0.35f; if (parentForm != null) parentForm.Invalidate(); });
                        transMenu.Items.Add("80% Rất mờ", null, (s, e) => { shape.FillOpacity = 0.20f; if (parentForm != null) parentForm.Invalidate(); });
                        transMenu.Items.Add("95% Gần trong suốt", null, (s, e) => { shape.FillOpacity = 0.05f; if (parentForm != null) parentForm.Invalidate(); });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(160, 144)) : new Point(160, 144);
                        transMenu.Show(pt);
                        return true;
                    }
                    // 6. Nén ảnh (Compress Pictures) (X: 274..382, Y: 68..92)
                    else if (x >= 274 && x <= 382 && y >= 68 && y <= 92)
                    {
                        if (shape.CachedImage != null)
                        {
                            MessageBox.Show("Đã nén tối ưu hóa dung lượng hình ảnh trong Slide thành công!", "Nén hình ảnh (Compress)", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        }
                        return true;
                    }
                    // 7. Đổi ảnh ▾ (Change Picture ▾) (X: 274..382, Y: 94..118)
                    else if (x >= 274 && x <= 382 && y >= 94 && y <= 118)
                    {
                        using (OpenFileDialog ofd = new OpenFileDialog())
                        {
                            ofd.Filter = "Tệp hình ảnh (*.png;*.jpg;*.jpeg;*.bmp;*.webp;*.gif)|*.png;*.jpg;*.jpeg;*.bmp;*.webp;*.gif|Tất cả tệp (*.*)|*.*";
                            ofd.Title = "Chọn hình ảnh mới để thay thế";
                            if (ofd.ShowDialog() == DialogResult.OK)
                            {
                                try
                                {
                                    shape.ImagePath = ofd.FileName;
                                    shape.CachedImage = Image.FromFile(ofd.FileName);
                                    shape.OriginalWidth = shape.CachedImage.Width;
                                    shape.OriginalHeight = shape.CachedImage.Height;
                                    if (parentForm != null) parentForm.Invalidate();
                                }
                                catch (Exception ex)
                                {
                                    MessageBox.Show("Không thể tải hình ảnh: " + ex.Message, "Lỗi", MessageBoxButtons.OK, MessageBoxIcon.Error);
                                }
                            }
                        }
                        return true;
                    }
                    // 8. Đặt lại ảnh ▾ (Reset Picture ▾) (X: 274..382, Y: 120..144)
                    else if (x >= 274 && x <= 382 && y >= 120 && y <= 144)
                    {
                        ContextMenuStrip rstMenu = new ContextMenuStrip();
                        rstMenu.RenderMode = ToolStripRenderMode.System;
                        rstMenu.Items.Add("🔄 Đặt lại hình ảnh (Reset Picture)", null, (s, e) => {
                            shape.ImageBrightness = 0.0f;
                            shape.ImageContrast = 1.0f;
                            shape.ImageSaturation = 1.0f;
                            shape.ImageRecolor = "None";
                            shape.FillOpacity = 1.0f;
                            shape.PictureStyleIndex = 0;
                            shape.CropLeft = 0f; shape.CropTop = 0f; shape.CropRight = 0f; shape.CropBottom = 0f;
                            if (parentForm != null) parentForm.Invalidate();
                        });
                        rstMenu.Items.Add("📐 Đặt lại ảnh & Kích thước (Reset Picture & Size)", null, (s, e) => {
                            shape.ImageBrightness = 0.0f;
                            shape.ImageContrast = 1.0f;
                            shape.ImageSaturation = 1.0f;
                            shape.ImageRecolor = "None";
                            shape.FillOpacity = 1.0f;
                            shape.PictureStyleIndex = 0;
                            shape.CropLeft = 0f; shape.CropTop = 0f; shape.CropRight = 0f; shape.CropBottom = 0f;
                            if (shape.OriginalWidth > 0 && shape.OriginalHeight > 0)
                            {
                                shape.Transform.Width = shape.OriginalWidth;
                                shape.Transform.Height = shape.OriginalHeight;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(274, 144)) : new Point(274, 144);
                        rstMenu.Show(pt);
                        return true;
                    }
                    // 9. 7 Picture Style Thumbnails (X: 394..643, Y: 68..122)
                    else if (x >= 394 && x <= 643 && y >= 68 && y <= 122)
                    {
                        int pIdx = 1 + (x - 394) / 35;
                        if (pIdx >= 1 && pIdx <= 7)
                        {
                            shape.PictureStyleIndex = (shape.PictureStyleIndex == pIdx) ? 0 : pIdx;
                            if (parentForm != null) parentForm.Invalidate();
                        }
                        return true;
                    }
                    // 10. Viền ảnh ▾ (Picture Border ▾) (X: 647..757, Y: 68..92)
                    else if (x >= 647 && x <= 757 && y >= 68 && y <= 92)
                    {
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(647, 94)) : new Point(647, 94);
                        int sc = shape.StrokeColor;
                        Color curC = Color.FromArgb((sc >> 16) & 0xFF, (sc >> 8) & 0xFF, sc & 0xFF);
                        ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, true);
                        colDlg.OnColorSelected += (c) =>
                        {
                            if (c == Color.Transparent)
                            {
                                shape.StrokeWidth = 0.0f;
                            }
                            else
                            {
                                shape.StrokeColor = c.ToArgb() & 0xFFFFFF;
                                if (shape.StrokeWidth <= 0) shape.StrokeWidth = 2.0f;
                            }
                            if (parentForm != null) parentForm.Invalidate();
                        };
                        colDlg.Show();
                        return true;
                    }
                    // 11. Hiệu ứng ảnh ▾ (Picture Effects ▾) (X: 647..757, Y: 94..118)
                    else if (x >= 647 && x <= 757 && y >= 94 && y <= 118)
                    {
                        ContextMenuStrip fxMenu = new ContextMenuStrip();
                        fxMenu.RenderMode = ToolStripRenderMode.System;
                        fxMenu.Items.Add("Bóng đổ nhẹ (Drop Shadow)", null, (s, e) => { shape.PictureStyleIndex = 4; if (parentForm != null) parentForm.Invalidate(); });
                        fxMenu.Items.Add("Viền mềm mờ dần (Soft Edges)", null, (s, e) => { shape.PictureStyleIndex = 5; if (parentForm != null) parentForm.Invalidate(); });
                        fxMenu.Items.Add("Cắt hình Oval vát cạnh (Beveled Oval)", null, (s, e) => { shape.PictureStyleIndex = 7; if (parentForm != null) parentForm.Invalidate(); });
                        fxMenu.Items.Add("Khung viền đôi (Double Frame)", null, (s, e) => { shape.PictureStyleIndex = 6; if (parentForm != null) parentForm.Invalidate(); });
                        fxMenu.Items.Add("Không hiệu ứng (None)", null, (s, e) => { shape.PictureStyleIndex = 0; if (parentForm != null) parentForm.Invalidate(); });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(647, 120)) : new Point(647, 120);
                        fxMenu.Show(pt);
                        return true;
                    }
                    // 12. Bố cục ảnh ▾ (Picture Layout ▾) (X: 647..757, Y: 120..144)
                    else if (x >= 647 && x <= 757 && y >= 120 && y <= 144)
                    {
                        ContextMenuStrip layMenu = new ContextMenuStrip();
                        layMenu.RenderMode = ToolStripRenderMode.System;
                        layMenu.Items.Add("🖼️ Chú thích dưới ảnh (Caption Below)", null, (s, e) => {
                            if (slidesView.ActiveSlide != null)
                            {
                                ShapeNode cap = new ShapeNode {
                                    Type = ShapeType.TextBox,
                                    Text = "Chú thích hình ảnh...",
                                    FontSize = 14f,
                                    TextColor = 0x475569,
                                    Transform = new Transform2D(shape.Transform.X, shape.Transform.Bottom + 6f, shape.Transform.Width, 36f)
                                };
                                slidesView.ActiveSlide.Shapes.Add(cap);
                                if (parentForm != null) parentForm.Invalidate();
                            }
                        });
                        layMenu.Items.Add("💬 Chú thích thẻ bo tròn (Rounded Card Frame)", null, (s, e) => {
                            shape.PictureStyleIndex = 8;
                            if (parentForm != null) parentForm.Invalidate();
                        });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(647, 144)) : new Point(647, 144);
                        layMenu.Show(pt);
                        return true;
                    }
                    // 13. Văn bản Alt (Accessibility Alt Text) (X: 771..839, Y: 68..122)
                    else if (x >= 771 && x <= 839 && y >= 68 && y <= 122)
                    {
                        string currentAlt = string.IsNullOrEmpty(shape.AltText) ? shape.Name : shape.AltText;
                        using (Form altDlg = new Form())
                        {
                            altDlg.Text = "Văn bản thay thế (Alt Text)";
                            altDlg.Size = new Size(380, 200);
                            altDlg.StartPosition = FormStartPosition.CenterParent;
                            altDlg.FormBorderStyle = FormBorderStyle.FixedDialog;
                            altDlg.MaximizeBox = false;
                            altDlg.MinimizeBox = false;
                            altDlg.Font = new Font("Segoe UI", 9f);

                            Label lbl = new Label { Text = "Mô tả / Tiêu đề văn bản thay thế (Alt Text) cho hình ảnh:", Location = new Point(16, 16), AutoSize = true };
                            TextBox txt = new TextBox { Text = currentAlt, Location = new Point(18, 42), Width = 328, Height = 56, Multiline = true };
                            Button btnOk = new Button { Text = "Đồng ý", DialogResult = DialogResult.OK, Location = new Point(170, 115), Width = 80, Height = 28 };
                            Button btnCancel = new Button { Text = "Hủy bỏ", DialogResult = DialogResult.Cancel, Location = new Point(262, 115), Width = 80, Height = 28 };

                            altDlg.Controls.AddRange(new Control[] { lbl, txt, btnOk, btnCancel });
                            altDlg.AcceptButton = btnOk;
                            altDlg.CancelButton = btnCancel;

                            if (altDlg.ShowDialog(parentForm) == DialogResult.OK)
                            {
                                shape.AltText = txt.Text;
                                shape.Name = txt.Text;
                                if (parentForm != null) parentForm.Invalidate();
                            }
                        }
                        return true;
                    }
                    // 14. Sắp xếp: Lên trước (X: 853..941, Y: 68..92)
                    else if (x >= 853 && x <= 941 && y >= 68 && y <= 92)
                    {
                        if (slidesView.ActiveSlide != null && slidesView.SelectedShapeIndex < slidesView.ActiveSlide.Shapes.Count - 1)
                        {
                            int idx = slidesView.SelectedShapeIndex;
                            ShapeNode s1 = slidesView.ActiveSlide.Shapes[idx];
                            slidesView.ActiveSlide.Shapes[idx] = slidesView.ActiveSlide.Shapes[idx + 1];
                            slidesView.ActiveSlide.Shapes[idx + 1] = s1;
                            slidesView.SelectedShapeIndex = idx + 1;
                        }
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // Sắp xếp: Ra sau (X: 853..941, Y: 94..118)
                    else if (x >= 853 && x <= 941 && y >= 94 && y <= 118)
                    {
                        if (slidesView.ActiveSlide != null && slidesView.SelectedShapeIndex > 0)
                        {
                            int idx = slidesView.SelectedShapeIndex;
                            ShapeNode s1 = slidesView.ActiveSlide.Shapes[idx];
                            slidesView.ActiveSlide.Shapes[idx] = slidesView.ActiveSlide.Shapes[idx - 1];
                            slidesView.ActiveSlide.Shapes[idx - 1] = s1;
                            slidesView.SelectedShapeIndex = idx - 1;
                        }
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // Căn chỉnh (X: 853..941, Y: 120..144)
                    else if (x >= 853 && x <= 941 && y >= 120 && y <= 144)
                    {
                        ContextMenuStrip alignMenu = new ContextMenuStrip();
                        alignMenu.RenderMode = ToolStripRenderMode.System;
                        alignMenu.Items.Add("Căn Trái", null, (s, e) => { shape.Transform.X = 0; if (parentForm != null) parentForm.Invalidate(); });
                        alignMenu.Items.Add("Căn Giữa ngang", null, (s, e) => { shape.Transform.X = (slidesView.Presentation.CanvasWidth - shape.Transform.Width) / 2f; if (parentForm != null) parentForm.Invalidate(); });
                        alignMenu.Items.Add("Căn Phải", null, (s, e) => { shape.Transform.X = slidesView.Presentation.CanvasWidth - shape.Transform.Width; if (parentForm != null) parentForm.Invalidate(); });
                        alignMenu.Items.Add(new ToolStripSeparator());
                        alignMenu.Items.Add("Căn Trên", null, (s, e) => { shape.Transform.Y = 0; if (parentForm != null) parentForm.Invalidate(); });
                        alignMenu.Items.Add("Căn Giữa dọc", null, (s, e) => { shape.Transform.Y = (slidesView.Presentation.CanvasHeight - shape.Transform.Height) / 2f; if (parentForm != null) parentForm.Invalidate(); });
                        alignMenu.Items.Add("Căn Dưới", null, (s, e) => { shape.Transform.Y = slidesView.Presentation.CanvasHeight - shape.Transform.Height; if (parentForm != null) parentForm.Invalidate(); });
                        Point pt = parentForm != null ? parentForm.PointToScreen(new Point(853, 144)) : new Point(853, 144);
                        alignMenu.Show(pt);
                        return true;
                    }
                    // Xoay 90° (X: 945..1029, Y: 68..92)
                    else if (x >= 945 && x <= 1029 && y >= 68 && y <= 92)
                    {
                        shape.Transform.Rotation = (shape.Transform.Rotation + 90f) % 360f;
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // Lật ngang (X: 945..1029, Y: 94..118)
                    else if (x >= 945 && x <= 1029 && y >= 94 && y <= 118)
                    {
                        shape.Transform.FlipHorizontal = !shape.Transform.FlipHorizontal;
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // Lật dọc (X: 945..1029, Y: 120..144)
                    else if (x >= 945 && x <= 1029 && y >= 120 && y <= 144)
                    {
                        shape.Transform.FlipVertical = !shape.Transform.FlipVertical;
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // 15. Cắt ảnh (Crop Split Button) (X: 1041..1103, Y: 68..122)
                    else if (x >= 1041 && x <= 1103 && y >= 68 && y <= 122)
                    {
                        if (y <= 104)
                        {
                            // Nhấp nút Cắt ảnh ở trên (không nhấp mũi tên): Bật/Tắt chế độ Cắt ảnh tương tác
                            slidesView.ToggleCropMode();
                            if (parentForm != null) parentForm.Invalidate();
                            return true;
                        }
                        else
                        {
                            // Nhấp vào mũi tên ▾ ở dưới: Mở Menu Cắt ảnh đầy đủ chức năng Crop to Shape & Aspect Ratio
                            ContextMenuStrip cropMenu = new ContextMenuStrip();
                            cropMenu.RenderMode = ToolStripRenderMode.System;

                            cropMenu.Items.Add("✂️ Cắt ảnh (Crop)", null, (s, e) => {
                                slidesView.ToggleCropMode();
                                if (parentForm != null) parentForm.Invalidate();
                            });

                            // 1. Cắt theo Hình dạng (Crop to Shape)
                            ToolStripMenuItem cropToShapeItem = new ToolStripMenuItem("🔷 Cắt theo Hình dạng (Crop to Shape)");

                            ToolStripMenuItem rectsGroup = new ToolStripMenuItem("Hình chữ nhật (Rectangles)");
                            rectsGroup.DropDownItems.Add("Chữ nhật (Rectangle)", null, (s, e) => { slidesView.SetCropShape("Rectangle"); if (parentForm != null) parentForm.Invalidate(); });
                            rectsGroup.DropDownItems.Add("Chữ nhật bo góc (Rounded Rectangle)", null, (s, e) => { slidesView.SetCropShape("RoundedRectangle"); if (parentForm != null) parentForm.Invalidate(); });
                            cropToShapeItem.DropDownItems.Add(rectsGroup);

                            ToolStripMenuItem basicGroup = new ToolStripMenuItem("Hình cơ bản (Basic Shapes)");
                            basicGroup.DropDownItems.Add("Hình Elip / Tròn (Ellipse)", null, (s, e) => { slidesView.SetCropShape("Ellipse"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Tam giác đều (Triangle)", null, (s, e) => { slidesView.SetCropShape("Triangle"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Tam giác vuông (Right Triangle)", null, (s, e) => { slidesView.SetCropShape("RightTriangle"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Hình thoi (Diamond)", null, (s, e) => { slidesView.SetCropShape("Diamond"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Ngũ giác (Pentagon)", null, (s, e) => { slidesView.SetCropShape("Pentagon"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Lục giác (Hexagon)", null, (s, e) => { slidesView.SetCropShape("Hexagon"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Bát giác (Octagon)", null, (s, e) => { slidesView.SetCropShape("Octagon"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Hình trái tim (Heart)", null, (s, e) => { slidesView.SetCropShape("Heart"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Mặt cười (Smiley)", null, (s, e) => { slidesView.SetCropShape("Smiley"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Mặt trời (Sun)", null, (s, e) => { slidesView.SetCropShape("Sun"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Mặt trăng (Moon)", null, (s, e) => { slidesView.SetCropShape("Moon"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Đám mây (Cloud)", null, (s, e) => { slidesView.SetCropShape("Cloud"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Tia sét (Lightning)", null, (s, e) => { slidesView.SetCropShape("Lightning"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Bánh Donut (Donut)", null, (s, e) => { slidesView.SetCropShape("Donut"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Dấu thập (Cross)", null, (s, e) => { slidesView.SetCropShape("Cross"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Hình trụ (Can)", null, (s, e) => { slidesView.SetCropShape("Can"); if (parentForm != null) parentForm.Invalidate(); });
                            basicGroup.DropDownItems.Add("Hình lập phương (Cube)", null, (s, e) => { slidesView.SetCropShape("Cube"); if (parentForm != null) parentForm.Invalidate(); });
                            cropToShapeItem.DropDownItems.Add(basicGroup);

                            ToolStripMenuItem arrowGroup = new ToolStripMenuItem("Mũi tên khối (Block Arrows)");
                            arrowGroup.DropDownItems.Add("Mũi tên Phải (Right Arrow)", null, (s, e) => { slidesView.SetCropShape("BlockArrowRight"); if (parentForm != null) parentForm.Invalidate(); });
                            arrowGroup.DropDownItems.Add("Mũi tên Trái (Left Arrow)", null, (s, e) => { slidesView.SetCropShape("BlockArrowLeft"); if (parentForm != null) parentForm.Invalidate(); });
                            arrowGroup.DropDownItems.Add("Mũi tên Lên (Up Arrow)", null, (s, e) => { slidesView.SetCropShape("BlockArrowUp"); if (parentForm != null) parentForm.Invalidate(); });
                            arrowGroup.DropDownItems.Add("Mũi tên Xuống (Down Arrow)", null, (s, e) => { slidesView.SetCropShape("BlockArrowDown"); if (parentForm != null) parentForm.Invalidate(); });
                            arrowGroup.DropDownItems.Add("Mũi tên Chữ V (Chevron)", null, (s, e) => { slidesView.SetCropShape("Chevron"); if (parentForm != null) parentForm.Invalidate(); });
                            cropToShapeItem.DropDownItems.Add(arrowGroup);

                            ToolStripMenuItem starGroup = new ToolStripMenuItem("Sao & Biểu ngữ (Stars & Banners)");
                            starGroup.DropDownItems.Add("Ngôi sao (Star)", null, (s, e) => { slidesView.SetCropShape("Star"); if (parentForm != null) parentForm.Invalidate(); });
                            starGroup.DropDownItems.Add("Dải ruy băng (Banner)", null, (s, e) => { slidesView.SetCropShape("Banner"); if (parentForm != null) parentForm.Invalidate(); });
                            starGroup.DropDownItems.Add("Sao bừng sáng (Starburst)", null, (s, e) => { slidesView.SetCropShape("Starburst"); if (parentForm != null) parentForm.Invalidate(); });
                            cropToShapeItem.DropDownItems.Add(starGroup);

                            ToolStripMenuItem natureGroup = new ToolStripMenuItem("Hình độc quyền & Tự nhiên (Special Shapes)");
                            natureGroup.DropDownItems.Add("Bong bóng thoại (Callout)", null, (s, e) => { slidesView.SetCropShape("Callout"); if (parentForm != null) parentForm.Invalidate(); });
                            natureGroup.DropDownItems.Add("Chiếc lá (Leaf)", null, (s, e) => { slidesView.SetCropShape("Leaf"); if (parentForm != null) parentForm.Invalidate(); });
                            natureGroup.DropDownItems.Add("Cỏ 4 lá (Clover)", null, (s, e) => { slidesView.SetCropShape("Clover"); if (parentForm != null) parentForm.Invalidate(); });
                            natureGroup.DropDownItems.Add("Bông hoa (Flower)", null, (s, e) => { slidesView.SetCropShape("Flower"); if (parentForm != null) parentForm.Invalidate(); });
                            natureGroup.DropDownItems.Add("Viên ngọc (Gem)", null, (s, e) => { slidesView.SetCropShape("Gem"); if (parentForm != null) parentForm.Invalidate(); });
                            natureGroup.DropDownItems.Add("Khiên bảo vệ (Shield)", null, (s, e) => { slidesView.SetCropShape("Shield"); if (parentForm != null) parentForm.Invalidate(); });
                            natureGroup.DropDownItems.Add("Vòm cung (Arch)", null, (s, e) => { slidesView.SetCropShape("Arch"); if (parentForm != null) parentForm.Invalidate(); });
                            cropToShapeItem.DropDownItems.Add(natureGroup);

                            cropMenu.Items.Add(cropToShapeItem);

                            // 2. Tỉ lệ Khung hình (Aspect Ratio)
                            ToolStripMenuItem ratioItem = new ToolStripMenuItem("📐 Tỉ lệ Khung hình (Aspect Ratio)");

                            ToolStripMenuItem sqGroup = new ToolStripMenuItem("Vuông (Square)");
                            sqGroup.DropDownItems.Add("1:1", null, (s, e) => { slidesView.SetCropAspectRatio(1f, 1f); if (parentForm != null) parentForm.Invalidate(); });
                            ratioItem.DropDownItems.Add(sqGroup);

                            ToolStripMenuItem portraitGroup = new ToolStripMenuItem("Dọc (Portrait)");
                            portraitGroup.DropDownItems.Add("2:3", null, (s, e) => { slidesView.SetCropAspectRatio(2f, 3f); if (parentForm != null) parentForm.Invalidate(); });
                            portraitGroup.DropDownItems.Add("3:4", null, (s, e) => { slidesView.SetCropAspectRatio(3f, 4f); if (parentForm != null) parentForm.Invalidate(); });
                            portraitGroup.DropDownItems.Add("3:5", null, (s, e) => { slidesView.SetCropAspectRatio(3f, 5f); if (parentForm != null) parentForm.Invalidate(); });
                            portraitGroup.DropDownItems.Add("4:5", null, (s, e) => { slidesView.SetCropAspectRatio(4f, 5f); if (parentForm != null) parentForm.Invalidate(); });
                            portraitGroup.DropDownItems.Add("9:16", null, (s, e) => { slidesView.SetCropAspectRatio(9f, 16f); if (parentForm != null) parentForm.Invalidate(); });
                            ratioItem.DropDownItems.Add(portraitGroup);

                            ToolStripMenuItem landscapeGroup = new ToolStripMenuItem("Ngang (Landscape)");
                            landscapeGroup.DropDownItems.Add("16:9 (Chuẩn Màn ảnh rộng)", null, (s, e) => { slidesView.SetCropAspectRatio(16f, 9f); if (parentForm != null) parentForm.Invalidate(); });
                            landscapeGroup.DropDownItems.Add("16:10", null, (s, e) => { slidesView.SetCropAspectRatio(16f, 10f); if (parentForm != null) parentForm.Invalidate(); });
                            landscapeGroup.DropDownItems.Add("4:3 (Truyền thống)", null, (s, e) => { slidesView.SetCropAspectRatio(4f, 3f); if (parentForm != null) parentForm.Invalidate(); });
                            landscapeGroup.DropDownItems.Add("3:2", null, (s, e) => { slidesView.SetCropAspectRatio(3f, 2f); if (parentForm != null) parentForm.Invalidate(); });
                            landscapeGroup.DropDownItems.Add("5:4", null, (s, e) => { slidesView.SetCropAspectRatio(5f, 4f); if (parentForm != null) parentForm.Invalidate(); });
                            landscapeGroup.DropDownItems.Add("5:3", null, (s, e) => { slidesView.SetCropAspectRatio(5f, 3f); if (parentForm != null) parentForm.Invalidate(); });
                            ratioItem.DropDownItems.Add(landscapeGroup);

                            cropMenu.Items.Add(ratioItem);

                            // 3. Lấp đầy & Vừa vặn (Fill & Fit)
                            cropMenu.Items.Add("🖼️ Lấp đầy (Fill)", null, (s, e) => {
                                slidesView.FillCrop();
                                if (parentForm != null) parentForm.Invalidate();
                            });
                            cropMenu.Items.Add("🎯 Vừa vặn (Fit)", null, (s, e) => {
                                slidesView.FitCrop();
                                if (parentForm != null) parentForm.Invalidate();
                            });

                            cropMenu.Items.Add(new ToolStripSeparator());
                            cropMenu.Items.Add("↩️ Bỏ cắt ảnh (Reset Crop)", null, (s, e) => {
                                slidesView.ResetCrop();
                                if (parentForm != null) parentForm.Invalidate();
                            });

                            Point pt = parentForm != null ? parentForm.PointToScreen(new Point(1045, 124)) : new Point(1045, 124);
                            cropMenu.Show(pt);
                            return true;
                        }
                    }
                    // 16. Kích thước (Size): Chiều cao ▲ / ▼ (X: 1113..1237, Y: 68..102)
                    else if (x >= 1113 && x <= 1237 && y >= 68 && y <= 102)
                    {
                        bool isUp = (y <= 84);
                        shape.Transform.Height = Math.Max(20f, shape.Transform.Height + (isUp ? 25f : -25f));
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // Kích thước (Size): Chiều rộng ▲ / ▼ (X: 1113..1237, Y: 106..140)
                    else if (x >= 1113 && x <= 1237 && y >= 106 && y <= 140)
                    {
                        bool isUp = (y <= 122);
                        shape.Transform.Width = Math.Max(20f, shape.Transform.Width + (isUp ? 25f : -25f));
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                }
                else
                {
                    // 1. Chèn Hình vẽ (Insert Shapes)
                    // Quick Shapes Row 1 (X: 12..156, Y: 68..93)
                    if (x >= 12 && x <= 156 && y >= 68 && y <= 93)
                    {
                        int qIdx = (x - 12) / 24;
                        ShapeType[] quick1 = new ShapeType[] { ShapeType.TextBox, ShapeType.Rectangle, ShapeType.RoundedRectangle, ShapeType.Ellipse, ShapeType.Leaf, ShapeType.Flower };
                        if (qIdx >= 0 && qIdx < quick1.Length)
                        {
                            slidesView.StartShapeDrawMode(quick1[qIdx]);
                        }
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                    // Quick Shapes Row 2 (X: 12..156, Y: 96..121)
                    else if (x >= 12 && x <= 156 && y >= 96 && y <= 121)
                    {
                        int qIdx = (x - 12) / 24;
                        ShapeType[] quick2 = new ShapeType[] { ShapeType.LuxuryHexagon, ShapeType.Gem, ShapeType.Shield, ShapeType.Banner, ShapeType.Heart, ShapeType.Star };
                        if (qIdx >= 0 && qIdx < quick2.Length)
                        {
                            slidesView.StartShapeDrawMode(quick2[qIdx]);
                        }
                        if (parentForm != null) parentForm.Invalidate();
                        return true;
                    }
                // Đổi hình ▾ (Change Shape) (X: 160..240, Y: 68..93)
                else if (x >= 160 && x <= 240 && y >= 68 && y <= 93)
                {
                    ContextMenuStrip changeMenu = new ContextMenuStrip();
                    changeMenu.RenderMode = ToolStripRenderMode.System;

                    // 1. Cây Cỏ & Tự Nhiên
                    ToolStripMenuItem natureMenu = new ToolStripMenuItem("🌿 Cây Cỏ & Tự Nhiên (Botanical)");
                    ShapeType[] natureTypes = new ShapeType[] { ShapeType.Leaf, ShapeType.Clover, ShapeType.Flower, ShapeType.Sprout, ShapeType.Sun, ShapeType.Cloud, ShapeType.Moon };
                    string[] natureNames = new string[] { "Chiếc lá tự nhiên (Leaf)", "Cỏ 4 lá may mắn (Clover)", "Bông hoa 6 cánh (Flower)", "Mầm cây non (Sprout)", "Mặt trời (Sun)", "Đám mây (Cloud)", "Mặt trăng (Moon)" };
                    for (int i = 0; i < natureTypes.Length; i++)
                    {
                        ShapeType st = natureTypes[i];
                        ToolStripMenuItem mi = new ToolStripMenuItem(natureNames[i], null, (s, e) => { shape.Type = st; if (parentForm != null) parentForm.Invalidate(); });
                        if (shape.Type == st) mi.Checked = true;
                        natureMenu.DropDownItems.Add(mi);
                    }
                    changeMenu.Items.Add(natureMenu);

                    // 2. Hình Học Sang Trọng & Huy Hiệu
                    ToolStripMenuItem luxuryMenu = new ToolStripMenuItem("💎 Hình Học Sang Trọng (Luxury)");
                    ShapeType[] luxuryTypes = new ShapeType[] { ShapeType.LuxuryHexagon, ShapeType.Hexagon, ShapeType.Gem, ShapeType.Shield, ShapeType.Banner, ShapeType.Starburst, ShapeType.Arch, ShapeType.Octagon, ShapeType.Pentagon, ShapeType.Heart };
                    string[] luxuryNames = new string[] { "Ô Lục giác sang trọng (Luxury Hexagon)", "Lục giác đều (Hexagon)", "Viên đá quý (Gem Diamond)", "Huy hiệu khiên hoàng gia (Shield)", "Dải ruy băng (Banner)", "Huy chương 12 cánh (Starburst)", "Cổng vòm (Arch)", "Bát giác (Octagon)", "Ngũ giác (Pentagon)", "Hình trái tim (Heart)" };
                    for (int i = 0; i < luxuryTypes.Length; i++)
                    {
                        ShapeType st = luxuryTypes[i];
                        ToolStripMenuItem mi = new ToolStripMenuItem(luxuryNames[i], null, (s, e) => { shape.Type = st; if (parentForm != null) parentForm.Invalidate(); });
                        if (shape.Type == st) mi.Checked = true;
                        luxuryMenu.DropDownItems.Add(mi);
                    }
                    changeMenu.Items.Add(luxuryMenu);

                    // 3. Hình Khối Cơ Bản
                    ToolStripMenuItem basicMenu = new ToolStripMenuItem("🔷 Hình Khối Cơ Bản (Basic Shapes)");
                    ShapeType[] basicTypes = new ShapeType[] { ShapeType.Rectangle, ShapeType.RoundedRectangle, ShapeType.Ellipse, ShapeType.Triangle, ShapeType.RightTriangle, ShapeType.Diamond, ShapeType.Parallelogram, ShapeType.Trapezoid, ShapeType.Cross, ShapeType.Donut, ShapeType.Cube, ShapeType.Can, ShapeType.TextBox };
                    string[] basicNames = new string[] { "Hình chữ nhật", "Hình chữ nhật bo tròn", "Hình tròn / Elip", "Hình tam giác", "Tam giác vuông", "Hình thoi", "Hình bình hành", "Hình thang", "Dấu chữ thập", "Vành khuyên Donut", "Khối lập phương 3D", "Hình trụ Can", "Hộp văn bản" };
                    for (int i = 0; i < basicTypes.Length; i++)
                    {
                        ShapeType st = basicTypes[i];
                        ToolStripMenuItem mi = new ToolStripMenuItem(basicNames[i], null, (s, e) => { shape.Type = st; if (parentForm != null) parentForm.Invalidate(); });
                        if (shape.Type == st) mi.Checked = true;
                        basicMenu.DropDownItems.Add(mi);
                    }
                    changeMenu.Items.Add(basicMenu);

                    // 4. Mũi Tên & Ký Hiệu
                    ToolStripMenuItem arrowMenu = new ToolStripMenuItem("➡️ Mũi Tên & Ký Hiệu (Arrows & Symbols)");
                    ShapeType[] arrowTypes = new ShapeType[] { ShapeType.Arrow, ShapeType.Chevron, ShapeType.BlockArrowRight, ShapeType.BlockArrowLeft, ShapeType.BlockArrowUp, ShapeType.BlockArrowDown, ShapeType.Lightning, ShapeType.Callout, ShapeType.Smiley };
                    string[] arrowNames = new string[] { "Mũi tên phải", "Mũi tên Chevron", "Khối mũi tên phải", "Khối mũi tên trái", "Khối mũi tên lên", "Khối mũi tên xuống", "Tia chớp", "Hộp thoại Callout", "Mặt cười Smiley" };
                    for (int i = 0; i < arrowTypes.Length; i++)
                    {
                        ShapeType st = arrowTypes[i];
                        ToolStripMenuItem mi = new ToolStripMenuItem(arrowNames[i], null, (s, e) => { shape.Type = st; if (parentForm != null) parentForm.Invalidate(); });
                        if (shape.Type == st) mi.Checked = true;
                        arrowMenu.DropDownItems.Add(mi);
                    }
                    changeMenu.Items.Add(arrowMenu);

                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(160, 96)) : new Point(160, 96);
                    changeMenu.Show(pt);
                    return true;
                }
                // Hộp chữ (Insert Text Box) (X: 160..240, Y: 96..121)
                else if (x >= 160 && x <= 240 && y >= 96 && y <= 121)
                {
                    slidesView.StartShapeDrawMode(ShapeType.TextBox);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Hợp nhất Hình dạng ▾ (Merge Shapes) (X: 244..348, Y: 68..122)
                else if (x >= 244 && x <= 348 && y >= 68 && y <= 122)
                {
                    ContextMenuStrip mergeMenu = new ContextMenuStrip();
                    mergeMenu.Font = new Font("Segoe UI", 9f);
                    mergeMenu.ShowImageMargin = true;

                    ToolStripMenuItem mUnion = new ToolStripMenuItem("&Union (Hợp nhất)", CreateMergeIcon(MergeShapeOperation.Union), (s, e) =>
                    {
                        slidesView.MergeShapes(MergeShapeOperation.Union);
                        if (parentForm != null) parentForm.Invalidate();
                    });

                    ToolStripMenuItem mCombine = new ToolStripMenuItem("&Combine (Kết hợp)", CreateMergeIcon(MergeShapeOperation.Combine), (s, e) =>
                    {
                        slidesView.MergeShapes(MergeShapeOperation.Combine);
                        if (parentForm != null) parentForm.Invalidate();
                    });

                    ToolStripMenuItem mFragment = new ToolStripMenuItem("&Fragment (Phân mảnh)", CreateMergeIcon(MergeShapeOperation.Fragment), (s, e) =>
                    {
                        slidesView.MergeShapes(MergeShapeOperation.Fragment);
                        if (parentForm != null) parentForm.Invalidate();
                    });

                    ToolStripMenuItem mIntersect = new ToolStripMenuItem("&Intersect (Giao nhau)", CreateMergeIcon(MergeShapeOperation.Intersect), (s, e) =>
                    {
                        slidesView.MergeShapes(MergeShapeOperation.Intersect);
                        if (parentForm != null) parentForm.Invalidate();
                    });

                    ToolStripMenuItem mSubtract = new ToolStripMenuItem("&Subtract (Trừ hình)", CreateMergeIcon(MergeShapeOperation.Subtract), (s, e) =>
                    {
                        slidesView.MergeShapes(MergeShapeOperation.Subtract);
                        if (parentForm != null) parentForm.Invalidate();
                    });

                    mergeMenu.Items.AddRange(new ToolStripItem[] { mUnion, mCombine, mFragment, mIntersect, mSubtract });

                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(244, 122)) : new Point(244, 122);
                    mergeMenu.Show(pt);
                    return true;
                }
                // 2. Shape Styles Presets 1..4 (X: 360..504, Y: 68..122)
                else if (x >= 360 && x <= 504 && y >= 68 && y <= 122)
                {
                    int pIdx = (x - 360) / 36;
                    if (pIdx == 0) // White fill, Green outline
                    {
                        shape.FillColor = 0x00FFFFFF;
                        shape.StrokeColor = 0x22C55E;
                        shape.StrokeWidth = 2.0f;
                    }
                    else if (pIdx == 1) // Dark Slate
                    {
                        shape.FillColor = 0x1E293B;
                        shape.StrokeColor = 0x0F172A;
                        shape.StrokeWidth = 1.0f;
                        shape.TextColor = 0xFFFFFF;
                    }
                    else if (pIdx == 2) // Theme Blue
                    {
                        shape.FillColor = 0x2563EB;
                        shape.StrokeColor = 0x1D4ED8;
                        shape.StrokeWidth = 1.0f;
                        shape.TextColor = 0xFFFFFF;
                    }
                    else if (pIdx == 3) // Coral Orange
                    {
                        shape.FillColor = 0xEA580C;
                        shape.StrokeColor = 0xC2410C;
                        shape.StrokeWidth = 1.0f;
                        shape.TextColor = 0xFFFFFF;
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // 2. Màu tô hình (Shape Fill) (X: 508..600, Y: 68..92)
                else if (x >= 508 && x <= 600 && y >= 68 && y <= 92)
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(508, 94)) : new Point(508, 94);
                    int fc = shape.FillColor;
                    Color curC = Color.FromArgb((fc >> 16) & 0xFF, (fc >> 8) & 0xFF, fc & 0xFF);
                    ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, true);
                    colDlg.OnColorSelected += (c) =>
                    {
                        if (c == Color.Transparent)
                        {
                            shape.FillOpacity = 0.0f;
                        }
                        else
                        {
                            shape.FillColor = c.ToArgb() & 0xFFFFFF;
                            shape.FillOpacity = 1.0f;
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    colDlg.Show();
                    return true;
                }
                // Viền hình (Shape Outline) (X: 508..600, Y: 94..118)
                else if (x >= 508 && x <= 600 && y >= 94 && y <= 118)
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(508, 120)) : new Point(508, 120);
                    int sc = shape.StrokeColor;
                    Color curC = Color.FromArgb((sc >> 16) & 0xFF, (sc >> 8) & 0xFF, sc & 0xFF);
                    ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, true);
                    colDlg.OnColorSelected += (c) =>
                    {
                        if (c == Color.Transparent)
                        {
                            shape.StrokeWidth = 0.0f;
                        }
                        else
                        {
                            shape.StrokeColor = c.ToArgb() & 0xFFFFFF;
                            if (shape.StrokeWidth <= 0) shape.StrokeWidth = 1.5f;
                        }
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    colDlg.Show();
                    return true;
                }
                // Hiệu ứng hình (Shape Effects) (X: 508..600, Y: 120..144)
                else if (x >= 508 && x <= 600 && y >= 120 && y <= 144)
                {
                    ContextMenuStrip fxMenu = new ContextMenuStrip();
                    fxMenu.RenderMode = ToolStripRenderMode.System;
                    fxMenu.Items.Add("Nét liền (Solid)", null, (s, e) => { shape.DashStyle = DashStyle.Solid; if (parentForm != null) parentForm.Invalidate(); });
                    fxMenu.Items.Add("Nét đứt (Dashed)", null, (s, e) => { shape.DashStyle = DashStyle.Dash; if (parentForm != null) parentForm.Invalidate(); });
                    fxMenu.Items.Add("Nét chấm (Dotted)", null, (s, e) => { shape.DashStyle = DashStyle.Dot; if (parentForm != null) parentForm.Invalidate(); });
                    fxMenu.Items.Add(new ToolStripSeparator());
                    fxMenu.Items.Add("Độ dày nét 1.0 pt", null, (s, e) => { shape.StrokeWidth = 1.0f; if (parentForm != null) parentForm.Invalidate(); });
                    fxMenu.Items.Add("Độ dày nét 2.0 pt", null, (s, e) => { shape.StrokeWidth = 2.0f; if (parentForm != null) parentForm.Invalidate(); });
                    fxMenu.Items.Add("Độ dày nét 3.5 pt", null, (s, e) => { shape.StrokeWidth = 3.5f; if (parentForm != null) parentForm.Invalidate(); });
                    fxMenu.Items.Add("Không có viền", null, (s, e) => { shape.StrokeWidth = 0f; if (parentForm != null) parentForm.Invalidate(); });
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(508, 144)) : new Point(508, 144);
                    fxMenu.Show(pt);
                    return true;
                }
                // Nút Làm mờ / Độ trong suốt (Opacity) (X: 604..700, Y: 68..92)
                else if (x >= 604 && x <= 700 && y >= 68 && y <= 92)
                {
                    ContextMenuStrip opMenu = new ContextMenuStrip();
                    opMenu.RenderMode = ToolStripRenderMode.System;
                    opMenu.Items.Add("100% Đặc (Opaque)", null, (s, e) => { shape.FillOpacity = 1.0f; if (parentForm != null) parentForm.Invalidate(); });
                    opMenu.Items.Add("80% Hơi mờ", null, (s, e) => { shape.FillOpacity = 0.8f; if (parentForm != null) parentForm.Invalidate(); });
                    opMenu.Items.Add("60% Bán trong suốt", null, (s, e) => { shape.FillOpacity = 0.6f; if (parentForm != null) parentForm.Invalidate(); });
                    opMenu.Items.Add("40% Mờ (Translucent)", null, (s, e) => { shape.FillOpacity = 0.4f; if (parentForm != null) parentForm.Invalidate(); });
                    opMenu.Items.Add("20% Rất mờ", null, (s, e) => { shape.FillOpacity = 0.2f; if (parentForm != null) parentForm.Invalidate(); });
                    opMenu.Items.Add("0% Trong suốt (Transparent)", null, (s, e) => { shape.FillOpacity = 0.0f; if (parentForm != null) parentForm.Invalidate(); });
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(604, 94)) : new Point(604, 94);
                    opMenu.Show(pt);
                    return true;
                }
                // Nút Mờ + (X: 604..650, Y: 94..118)
                else if (x >= 604 && x <= 650 && y >= 94 && y <= 118)
                {
                    shape.FillOpacity = Math.Max(0.0f, (float)Math.Round(shape.FillOpacity - 0.15f, 2));
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nút Đặc - (X: 652..700, Y: 94..118)
                else if (x >= 652 && x <= 700 && y >= 94 && y <= 118)
                {
                    shape.FillOpacity = Math.Min(1.0f, (float)Math.Round(shape.FillOpacity + 0.15f, 2));
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nút Lật gương nhanh (X: 604..700, Y: 120..144)
                else if (x >= 604 && x <= 700 && y >= 120 && y <= 144)
                {
                    shape.Transform.FlipHorizontal = !shape.Transform.FlipHorizontal;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // 3. WordArt Presets 1..3 (X: 714..807, Y: 68..122)
                else if (x >= 714 && x <= 807 && y >= 68 && y <= 122)
                {
                    int wIdx = (x - 714) / 31;
                    if (wIdx == 0)
                    {
                        shape.Bold = true;
                        shape.TextColor = 0x0F172A;
                    }
                    else if (wIdx == 1)
                    {
                        shape.Bold = true;
                        shape.TextColor = 0x2563EB;
                    }
                    else if (wIdx == 2)
                    {
                        shape.Bold = true;
                        shape.TextColor = 0xEA580C;
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Màu chữ (Text Fill) (X: 811..903, Y: 68..92)
                else if (x >= 811 && x <= 903 && y >= 68 && y <= 92)
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(811, 94)) : new Point(811, 94);
                    int tc = shape.TextColor;
                    Color curC = Color.FromArgb((tc >> 16) & 0xFF, (tc >> 8) & 0xFF, tc & 0xFF);
                    ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, false);
                    colDlg.OnColorSelected += (c) =>
                    {
                        shape.TextColor = c.ToArgb() & 0xFFFFFF;
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    colDlg.Show();
                    return true;
                }
                // Viền chữ (Text Outline) (X: 811..903, Y: 94..118)
                else if (x >= 811 && x <= 903 && y >= 94 && y <= 118)
                {
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(811, 120)) : new Point(811, 120);
                    int tc = shape.TextColor;
                    Color curC = Color.FromArgb((tc >> 16) & 0xFF, (tc >> 8) & 0xFF, tc & 0xFF);
                    ColorPaletteForm colDlg = new ColorPaletteForm(pt, curC, true);
                    colDlg.OnColorSelected += (c) =>
                    {
                        shape.TextColor = c.ToArgb() & 0xFFFFFF;
                        if (parentForm != null) parentForm.Invalidate();
                    };
                    colDlg.Show();
                    return true;
                }
                // 4. Sắp xếp: Lên trước (Bring Forward) (X: 918..1006, Y: 68..92)
                else if (x >= 918 && x <= 1006 && y >= 68 && y <= 92)
                {
                    if (slidesView.ActiveSlide != null && slidesView.SelectedShapeIndex < slidesView.ActiveSlide.Shapes.Count - 1)
                    {
                        int idx = slidesView.SelectedShapeIndex;
                        ShapeNode s1 = slidesView.ActiveSlide.Shapes[idx];
                        slidesView.ActiveSlide.Shapes[idx] = slidesView.ActiveSlide.Shapes[idx + 1];
                        slidesView.ActiveSlide.Shapes[idx + 1] = s1;
                        slidesView.SelectedShapeIndex = idx + 1;
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Sắp xếp: Ra sau (Send Backward) (X: 918..1006, Y: 94..118)
                else if (x >= 918 && x <= 1006 && y >= 94 && y <= 118)
                {
                    if (slidesView.ActiveSlide != null && slidesView.SelectedShapeIndex > 0)
                    {
                        int idx = slidesView.SelectedShapeIndex;
                        ShapeNode s1 = slidesView.ActiveSlide.Shapes[idx];
                        slidesView.ActiveSlide.Shapes[idx] = slidesView.ActiveSlide.Shapes[idx - 1];
                        slidesView.ActiveSlide.Shapes[idx - 1] = s1;
                        slidesView.SelectedShapeIndex = idx - 1;
                    }
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Căn chỉnh (Align dropdown) (X: 918..1006, Y: 120..144)
                else if (x >= 918 && x <= 1006 && y >= 120 && y <= 144)
                {
                    ContextMenuStrip alignMenu = new ContextMenuStrip();
                    alignMenu.RenderMode = ToolStripRenderMode.System;
                    alignMenu.Items.Add("Căn Trái", null, (s, e) => { shape.Transform.X = 0; if (parentForm != null) parentForm.Invalidate(); });
                    alignMenu.Items.Add("Căn Giữa ngang", null, (s, e) => { shape.Transform.X = (slidesView.Presentation.CanvasWidth - shape.Transform.Width) / 2f; if (parentForm != null) parentForm.Invalidate(); });
                    alignMenu.Items.Add("Căn Phải", null, (s, e) => { shape.Transform.X = slidesView.Presentation.CanvasWidth - shape.Transform.Width; if (parentForm != null) parentForm.Invalidate(); });
                    alignMenu.Items.Add(new ToolStripSeparator());
                    alignMenu.Items.Add("Căn Trên", null, (s, e) => { shape.Transform.Y = 0; if (parentForm != null) parentForm.Invalidate(); });
                    alignMenu.Items.Add("Căn Giữa dọc", null, (s, e) => { shape.Transform.Y = (slidesView.Presentation.CanvasHeight - shape.Transform.Height) / 2f; if (parentForm != null) parentForm.Invalidate(); });
                    alignMenu.Items.Add("Căn Dưới", null, (s, e) => { shape.Transform.Y = slidesView.Presentation.CanvasHeight - shape.Transform.Height; if (parentForm != null) parentForm.Invalidate(); });
                    Point pt = parentForm != null ? parentForm.PointToScreen(new Point(918, 144)) : new Point(918, 144);
                    alignMenu.Show(pt);
                    return true;
                }
                // Xoay 90° (X: 1010..1094, Y: 68..92)
                else if (x >= 1010 && x <= 1094 && y >= 68 && y <= 92)
                {
                    shape.Transform.Rotation = (shape.Transform.Rotation + 90f) % 360f;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Lật ngang (X: 1010..1094, Y: 94..118)
                else if (x >= 1010 && x <= 1094 && y >= 94 && y <= 118)
                {
                    shape.Transform.FlipHorizontal = !shape.Transform.FlipHorizontal;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Lật dọc (X: 1010..1094, Y: 120..144)
                else if (x >= 1010 && x <= 1094 && y >= 120 && y <= 144)
                {
                    shape.Transform.FlipVertical = !shape.Transform.FlipVertical;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // 5. Kích thước (Size): Chiều cao ▲ / ▼ (X: 1110..1240, Y: 68..102)
                else if (x >= 1110 && x <= 1240 && y >= 68 && y <= 102)
                {
                    bool isUp = (y <= 84);
                    shape.Transform.Height = Math.Max(20f, shape.Transform.Height + (isUp ? 25f : -25f));
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Kích thước (Size): Chiều rộng ▲ / ▼ (X: 1110..1240, Y: 106..140)
                else if (x >= 1110 && x <= 1240 && y >= 106 && y <= 140)
                {
                    bool isUp = (y <= 122);
                    shape.Transform.Width = Math.Max(20f, shape.Transform.Width + (isUp ? 25f : -25f));
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
            }
        }
        else if (ActiveRibbonTab == 8 && slidesView != null && slidesView.SelectedShape != null && (slidesView.SelectedShape.Type == ShapeType.Video || !string.IsNullOrEmpty(slidesView.SelectedShape.VideoPath)))
        {
            ShapeNode shape = slidesView.SelectedShape;
            // Nhóm Xem trước (Preview): Phát (X: 12..60, Y: 68..122)
            if (x >= 12 && x <= 60 && y >= 68 && y <= 122)
                {
                    slidesView.PlayVideoPreview(shape, parentForm);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nhóm Dấu trang (Bookmarks): Thêm Dấu trang (X: 74..186, Y: 68..92)
                else if (x >= 74 && x <= 186 && y >= 68 && y <= 92)
                {
                    slidesView.AddVideoBookmark(shape);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nhóm Dấu trang: Xóa Dấu trang (X: 74..186, Y: 96..120)
                else if (x >= 74 && x <= 186 && y >= 96 && y <= 120)
                {
                    slidesView.RemoveVideoBookmark(shape);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nhóm Chỉnh sửa (Editing): Cắt Video (X: 200..260, Y: 68..122)
                else if (x >= 200 && x <= 260 && y >= 68 && y <= 122)
                {
                    slidesView.ShowTrimVideoDialog(shape);
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nhóm Chỉnh sửa: Mờ dần vào ▲ / ▼ (X: 266..400, Y: 68..93)
                else if (x >= 266 && x <= 400 && y >= 68 && y <= 93)
                {
                    bool isUp = (y <= 80);
                    slidesView.SaveUndoState();
                    shape.VideoFadeInDuration = (float)Math.Max(0.0, Math.Round(shape.VideoFadeInDuration + (isUp ? 0.25 : -0.25), 2));
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nhóm Chỉnh sửa: Mờ dần ra ▲ / ▼ (X: 266..400, Y: 96..121)
                else if (x >= 266 && x <= 400 && y >= 96 && y <= 121)
                {
                    bool isUp = (y <= 108);
                    slidesView.SaveUndoState();
                    shape.VideoFadeOutDuration = (float)Math.Max(0.0, Math.Round(shape.VideoFadeOutDuration + (isUp ? 0.25 : -0.25), 2));
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nhóm Tùy chọn Video: Âm lượng ▾ (X: 414..500, Y: 68..92)
                else if (x >= 414 && x <= 500 && y >= 68 && y <= 92)
                {
                    ContextMenuStrip menu = new ContextMenuStrip();
                    ToolStripMenuItem miMute = new ToolStripMenuItem("Tắt tiếng (Mute)");
                    ToolStripMenuItem miLow = new ToolStripMenuItem("Nhỏ (Low - 25%)");
                    ToolStripMenuItem miMed = new ToolStripMenuItem("Trung bình (Medium - 50%)");
                    ToolStripMenuItem miHigh = new ToolStripMenuItem("Lớn (High - 100%)");

                    miMute.Checked = (shape.VideoVolume == VideoVolumeLevel.Mute);
                    miLow.Checked = (shape.VideoVolume == VideoVolumeLevel.Low);
                    miMed.Checked = (shape.VideoVolume == VideoVolumeLevel.Medium);
                    miHigh.Checked = (shape.VideoVolume == VideoVolumeLevel.High);

                    miMute.Click += (s, ev) => { slidesView.SaveUndoState(); shape.VideoVolume = VideoVolumeLevel.Mute; if (parentForm != null) parentForm.Invalidate(); };
                    miLow.Click += (s, ev) => { slidesView.SaveUndoState(); shape.VideoVolume = VideoVolumeLevel.Low; if (parentForm != null) parentForm.Invalidate(); };
                    miMed.Click += (s, ev) => { slidesView.SaveUndoState(); shape.VideoVolume = VideoVolumeLevel.Medium; if (parentForm != null) parentForm.Invalidate(); };
                    miHigh.Click += (s, ev) => { slidesView.SaveUndoState(); shape.VideoVolume = VideoVolumeLevel.High; if (parentForm != null) parentForm.Invalidate(); };

                    menu.Items.AddRange(new ToolStripItem[] { miMute, miLow, miMed, miHigh });
                    if (parentForm != null) menu.Show(parentForm, new Point(x, y + 10));
                    return true;
                }
                // Nhóm Tùy chọn Video: Bắt đầu: [ ... ▾ ] (X: 506..692, Y: 68..92)
                else if (x >= 506 && x <= 692 && y >= 68 && y <= 92)
                {
                    ContextMenuStrip menu = new ContextMenuStrip();
                    ToolStripMenuItem miClickSeq = new ToolStripMenuItem("Theo trình tự nhấp (In Click Sequence)");
                    ToolStripMenuItem miAuto = new ToolStripMenuItem("Tự động (Automatically)");
                    ToolStripMenuItem miWhenClicked = new ToolStripMenuItem("Khi nhấp vào (When Clicked On)");

                    miClickSeq.Checked = (shape.VideoStartMode == VideoStartMode.InClickSequence);
                    miAuto.Checked = (shape.VideoStartMode == VideoStartMode.Automatically);
                    miWhenClicked.Checked = (shape.VideoStartMode == VideoStartMode.WhenClickedOn);

                    miClickSeq.Click += (s, ev) => { slidesView.SaveUndoState(); shape.VideoStartMode = VideoStartMode.InClickSequence; if (parentForm != null) parentForm.Invalidate(); };
                    miAuto.Click += (s, ev) => { slidesView.SaveUndoState(); shape.VideoStartMode = VideoStartMode.Automatically; if (parentForm != null) parentForm.Invalidate(); };
                    miWhenClicked.Click += (s, ev) => { slidesView.SaveUndoState(); shape.VideoStartMode = VideoStartMode.WhenClickedOn; if (parentForm != null) parentForm.Invalidate(); };

                    menu.Items.AddRange(new ToolStripItem[] { miClickSeq, miAuto, miWhenClicked });
                    if (parentForm != null) menu.Show(parentForm, new Point(x, y + 10));
                    return true;
                }
                // Checkbox: Phát toàn màn hình (X: 414..548, Y: 97..115)
                else if (x >= 414 && x <= 548 && y >= 97 && y <= 115)
                {
                    slidesView.SaveUndoState();
                    shape.VideoPlayFullScreen = !shape.VideoPlayFullScreen;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Checkbox: Ẩn khi không phát (X: 554..692, Y: 97..115)
                else if (x >= 554 && x <= 692 && y >= 97 && y <= 115)
                {
                    slidesView.SaveUndoState();
                    shape.VideoHideWhileNotPlaying = !shape.VideoHideWhileNotPlaying;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Checkbox: Lặp lại cho đến khi dừng (X: 414..548, Y: 118..136)
                else if (x >= 414 && x <= 548 && y >= 118 && y <= 136)
                {
                    slidesView.SaveUndoState();
                    shape.VideoLoopUntilStopped = !shape.VideoLoopUntilStopped;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Checkbox: Tua lại sau khi phát (X: 554..692, Y: 118..136)
                else if (x >= 554 && x <= 692 && y >= 118 && y <= 136)
                {
                    slidesView.SaveUndoState();
                    shape.VideoRewindAfterPlaying = !shape.VideoRewindAfterPlaying;
                    if (parentForm != null) parentForm.Invalidate();
                    return true;
                }
                // Nhóm Tùy chọn Phụ đề (Caption Options): Chèn Phụ đề ▾ (X: 706..796, Y: 68..122)
                else if (x >= 706 && x <= 796 && y >= 68 && y <= 122)
                {
                    ContextMenuStrip menu = new ContextMenuStrip();
                    ToolStripMenuItem miAddCap = new ToolStripMenuItem("Chèn Phụ đề WebVTT (*.vtt, *.srt)...");
                    ToolStripMenuItem miRemCap = new ToolStripMenuItem("Xóa Phụ đề Đã chèn");

                    miAddCap.Click += (s, ev) =>
                    {
                        using (OpenFileDialog ofd = new OpenFileDialog())
                        {
                            ofd.Title = "Chọn tệp Phụ đề cho Video";
                            ofd.Filter = "Tệp Phụ đề (*.vtt;*.srt)|*.vtt;*.srt|Tất cả tệp (*.*)|*.*";
                            if (ofd.ShowDialog() == DialogResult.OK)
                            {
                                slidesView.SaveUndoState();
                                shape.VideoCaptionPath = ofd.FileName;
                                if (parentForm != null) parentForm.Invalidate();
                                MessageBox.Show("Đã chèn phụ đề:\n" + ofd.FileName, "Chèn Phụ đề Video", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            }
                        }
                    };

                    miRemCap.Click += (s, ev) =>
                    {
                        slidesView.SaveUndoState();
                        shape.VideoCaptionPath = null;
                        if (parentForm != null) parentForm.Invalidate();
                        MessageBox.Show("Đã xóa phụ đề khỏi video.", "Phụ đề Video", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    };

                    menu.Items.AddRange(new ToolStripItem[] { miAddCap, miRemCap });
                    if (parentForm != null) menu.Show(parentForm, new Point(x, y + 10));
                    return true;
                }
            }
            return false;
        }

        #region PDF Editor Ribbon Toolbar & Click Handling
    private void DrawPdfRibbonToolbar(Graphics g, int width, PdfView pdfView)
    {
        if (pdfView == null) return;
        switch (ActiveRibbonTab)
        {
            case 0: DrawPdfTabTrangDau(g, width, pdfView); break;
            case 1: DrawPdfTabChuThich(g, width, pdfView); break;
            case 2: DrawPdfTabChinhSua(g, width, pdfView); break;
            case 3: DrawPdfTabTrang(g, width, pdfView); break;
            case 4: DrawPdfTabKyBaoMat(g, width, pdfView); break;
            case 5: DrawPdfTabHienThi(g, width, pdfView); break;
            case 6: DrawPdfTabDinhDangHopChu(g, width, pdfView); break;
            default: DrawPdfTabTrangDau(g, width, pdfView); break;
        }
    }

    private void DrawPdfTabTrangDau(Graphics g, int width, PdfView pdfView)
    {
        int curX = 10;
        using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
        using (Font btnFont = new Font("Segoe UI", 8.2f, FontStyle.Regular))
        using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
        {
            // 1. Nhóm Tệp (File)
            DrawVectorToolBtnLarge(g, curX, 68, 42, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(Color.FromArgb(220, 38, 38), 1.8f))
                {
                    g1.DrawRectangle(p, x1 + 2, y1 + 5, 16, 12);
                    g1.DrawLine(p, x1 + 2, y1 + 5, x1 + 7, y1 + 2);
                    g1.DrawLine(p, x1 + 7, y1 + 2, x1 + 12, y1 + 2);
                }
            }, "Mở");
            curX += 44;

            DrawVectorToolBtnLarge(g, curX, 68, 42, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(Color.FromArgb(220, 38, 38), 1.8f))
                {
                    g1.DrawRectangle(p, x1 + 2, y1 + 2, 16, 16);
                    g1.DrawRectangle(p, x1 + 5, y1 + 2, 10, 6);
                }
            }, "Lưu");
            curX += 46;

            g.DrawString("Tệp", labelFont, Brushes.Gray, curX - 60, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 2. Nhóm Công cụ Chọn & Soạn thảo (Tools)
            bool isSelect = (pdfView.SelectedTool == 0);
            DrawVectorToolBtnLarge(g, curX, 68, 54, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(isSelect ? Color.FromArgb(220, 38, 38) : Color.FromArgb(71, 85, 105), 1.8f))
                {
                    g1.DrawLine(p, x1 + 4, y1 + 3, x1 + 4, y1 + 17);
                    g1.DrawLine(p, x1 + 4, y1 + 3, x1 + 14, y1 + 12);
                    g1.DrawLine(p, x1 + 14, y1 + 12, x1 + 9, y1 + 12);
                    g1.DrawLine(p, x1 + 9, y1 + 12, x1 + 13, y1 + 18);
                }
            }, "Con trỏ", isSelect);
            curX += 58;

            bool isAddText = (pdfView.SelectedTool == 1);
            DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => {
                using (Font tf = new Font("Segoe UI", 12f, FontStyle.Bold))
                using (SolidBrush tb = new SolidBrush(isAddText ? Color.FromArgb(220, 38, 38) : Color.FromArgb(71, 85, 105)))
                {
                    g1.DrawString("T", tf, tb, x1 + 3, y1 + 1);
                    g1.DrawString("+", new Font("Segoe UI", 8.5f, FontStyle.Bold), Brushes.Green, x1 + 13, y1);
                }
            }, "Thêm chữ", isAddText);
            curX += 66;

            bool isEdit = (pdfView.SelectedTool == 2);
            DrawVectorToolBtnLarge(g, curX, 68, 58, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(isEdit ? Color.FromArgb(220, 38, 38) : Color.FromArgb(71, 85, 105), 1.6f))
                {
                    g1.DrawLine(p, x1 + 3, y1 + 16, x1 + 16, y1 + 3);
                    g1.DrawLine(p, x1 + 13, y1 + 3, x1 + 16, y1 + 6);
                }
            }, "Sửa chữ", isEdit);
            curX += 62;

            g.DrawString("Công cụ", labelFont, Brushes.Gray, curX - 110, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 3. Nhóm Phông chữ & Định dạng (Font Family & Size Picker like Writer)
            PdfTextElement selTxt = pdfView.SelectedText ?? pdfView.EditingText;
            string curF = (selTxt != null && !string.IsNullOrEmpty(selTxt.FontName)) ? selTxt.FontName : (pdfView.ActiveFontName ?? "Segoe UI");
            float curSz = (selTxt != null) ? selTxt.FontSize : (pdfView.ActiveFontSize > 0 ? pdfView.ActiveFontSize : 12f);
            bool isB = (selTxt != null && selTxt.IsBold);
            bool isI = (selTxt != null && selTxt.IsItalic);
            bool isU = (selTxt != null && selTxt.IsUnderline);

            // Font Combo (X: curX, W: 110, H: 22)
            Rectangle fontBox = new Rectangle(curX, 70, 110, 22);
            DrawInteractiveButton(g, fontBox, false, 3);
            g.DrawString(curF, btnFont, Brushes.Black, fontBox.X + 4, fontBox.Y + 3);
            g.DrawString("▾", btnFont, Brushes.Gray, fontBox.Right - 14, fontBox.Y + 3);

            // Size Combo (X: curX + 114, W: 45, H: 22)
            Rectangle sizeBox = new Rectangle(curX + 114, 70, 45, 22);
            DrawInteractiveButton(g, sizeBox, false, 3);
            g.DrawString(curSz.ToString("0.#"), btnFont, Brushes.Black, sizeBox.X + 4, sizeBox.Y + 3);
            g.DrawString("▾", btnFont, Brushes.Gray, sizeBox.Right - 14, sizeBox.Y + 3);

            // A ▲ / A ▼ (X: curX + 162, W: 24 each)
            Rectangle aUpBox = new Rectangle(curX + 162, 70, 24, 22);
            DrawInteractiveButton(g, aUpBox, false, 3);
            g.DrawString("A▲", labelFont, Brushes.Black, aUpBox.X + 2, aUpBox.Y + 4);

            Rectangle aDownBox = new Rectangle(curX + 188, 70, 24, 22);
            DrawInteractiveButton(g, aDownBox, false, 3);
            g.DrawString("A▼", labelFont, Brushes.Black, aDownBox.X + 2, aDownBox.Y + 4);

            // Row 2: B, I, U, Color
            DrawVectorBtn(g, curX, 96, 26, 22, (g1, x1, y1) => {
                g1.DrawString("B", boldFont, isB ? Brushes.Blue : Brushes.Black, x1 + 6, y1 + 2);
            }, "", isB);
            DrawVectorBtn(g, curX + 29, 96, 26, 22, (g1, x1, y1) => {
                using (Font itF = new Font("Segoe UI", 8.5f, FontStyle.Italic))
                    g1.DrawString("I", itF, isI ? Brushes.Blue : Brushes.Black, x1 + 8, y1 + 2);
            }, "", isI);
            DrawVectorBtn(g, curX + 58, 96, 26, 22, (g1, x1, y1) => {
                using (Font unF = new Font("Segoe UI", 8.5f, FontStyle.Underline))
                    g1.DrawString("U", unF, isU ? Brushes.Blue : Brushes.Black, x1 + 7, y1 + 2);
            }, "", isU);

            Rectangle clrBox = new Rectangle(curX + 87, 96, 45, 22);
            DrawInteractiveButton(g, clrBox, false, 3);
            using (Font af = new Font("Segoe UI", 8.5f, FontStyle.Bold))
            using (SolidBrush ab = new SolidBrush(selTxt != null ? selTxt.TextColor : Color.Black))
            {
                g.DrawString("A", af, ab, clrBox.X + 6, clrBox.Y + 2);
                using (Pen ap = new Pen(ab.Color, 2.5f)) g.DrawLine(ap, clrBox.X + 5, clrBox.Y + 16, clrBox.X + 17, clrBox.Y + 16);
                g.DrawString("▾", btnFont, Brushes.Gray, clrBox.Right - 14, clrBox.Y + 3);
            }

            curX += 216;
            g.DrawString("Phông chữ", labelFont, Brushes.Gray, curX - 140, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 4. Nhóm Thu phóng & Khớp trang (Zoom & Fit)
            Rectangle zInBtn = new Rectangle(curX, 68, 70, 24);
            DrawInteractiveButton(g, zInBtn, false, 3);
            g.DrawString("🔍+", boldFont, Brushes.Black, zInBtn.X + 4, zInBtn.Y + 3);
            g.DrawString("Phóng to", btnFont, Brushes.Black, zInBtn.X + 22, zInBtn.Y + 3);

            Rectangle zOutBtn = new Rectangle(curX, 94, 70, 24);
            DrawInteractiveButton(g, zOutBtn, false, 3);
            g.DrawString("🔍-", boldFont, Brushes.Black, zOutBtn.X + 4, zOutBtn.Y + 3);
            g.DrawString("Thu nhỏ", btnFont, Brushes.Black, zOutBtn.X + 22, zOutBtn.Y + 3);

            Rectangle zResetBtn = new Rectangle(curX, 120, 70, 24);
            DrawInteractiveButton(g, zResetBtn, false, 3);
            string zPct = (int)(pdfView.ZoomLevel * 100) + "%";
            g.DrawString("100% (" + zPct + ")", btnFont, Brushes.DarkBlue, zResetBtn.X + 4, zResetBtn.Y + 3);

            curX += 76;

            Rectangle fitWBtn = new Rectangle(curX, 68, 88, 24);
            DrawInteractiveButton(g, fitWBtn, false, 3);
            g.DrawString("↔ Vừa rộng", btnFont, Brushes.Black, fitWBtn.X + 4, fitWBtn.Y + 3);

            Rectangle fitPBtn = new Rectangle(curX, 94, 88, 24);
            DrawInteractiveButton(g, fitPBtn, false, 3);
            g.DrawString("↕ Vừa trang", btnFont, Brushes.Black, fitPBtn.X + 4, fitPBtn.Y + 3);

            curX += 94;
            g.DrawString("Thu phóng", labelFont, Brushes.Gray, curX - 110, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 5. Nhóm Tìm kiếm (Find)
            bool isSearchActive = pdfView.ShowSearchBar;
            DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(isSearchActive ? Color.FromArgb(220, 38, 38) : Color.FromArgb(71, 85, 105), 1.8f))
                {
                    g1.DrawEllipse(p, x1 + 2, y1 + 2, 11, 11);
                    g1.DrawLine(p, x1 + 10, y1 + 10, x1 + 17, y1 + 17);
                }
            }, "Tìm kiếm", isSearchActive);
            curX += 66;

            g.DrawString("Tìm kiếm", labelFont, Brushes.Gray, curX - 54, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 6. Nhóm AI OCR Văn Bản
            bool isOcrActive = pdfView.IsOcrScanning;
            DrawVectorToolBtnLarge(g, curX, 68, 76, 60, (g1, x1, y1) => {
                using (Font sf = new Font("Segoe UI", 11.5f, FontStyle.Bold))
                {
                    g1.DrawString("✨", sf, Brushes.MediumPurple, x1 + 4, y1 + 1);
                }
            }, "Quét AI OCR", isOcrActive);
            curX += 80;

            g.DrawString("AI OCR", labelFont, Brushes.Gray, curX - 58, 137);
        }
    }

    private void DrawPdfTabChuThich(Graphics g, int width, PdfView pdfView)
    {
        int curX = 10;
        using (Font labelFont = new Font("Segoe UI", 7.5f, FontStyle.Regular))
        using (Font btnFont = new Font("Segoe UI", 8.2f, FontStyle.Regular))
        using (Font boldFont = new Font("Segoe UI", 8.5f, FontStyle.Bold))
        {
            // 1. Nhóm Bút Dạ Quang Highlight (Tool 3)
            bool isHl = (pdfView.SelectedTool == 3);
            DrawVectorToolBtnLarge(g, curX, 68, 68, 60, (g1, x1, y1) => {
                using (SolidBrush hb = new SolidBrush(Color.FromArgb(250, 204, 21)))
                {
                    g1.FillRectangle(hb, x1 + 2, y1 + 4, 16, 12);
                }
                using (Pen hp = new Pen(Color.FromArgb(202, 138, 4), 1.5f))
                {
                    g1.DrawRectangle(hp, x1 + 2, y1 + 4, 16, 12);
                }
            }, "Dạ quang", isHl);
            curX += 72;

            // Màu Highlight (Vàng, Xanh lá, Xanh dương, Hồng)
            Rectangle yBtn = new Rectangle(curX, 72, 18, 18);
            Rectangle gBtn = new Rectangle(curX + 22, 72, 18, 18);
            Rectangle bBtn = new Rectangle(curX, 96, 18, 18);
            Rectangle pBtn = new Rectangle(curX + 22, 96, 18, 18);

            using (SolidBrush yb = new SolidBrush(Color.FromArgb(250, 204, 21))) g.FillRectangle(yb, yBtn);
            using (SolidBrush gb = new SolidBrush(Color.FromArgb(74, 222, 128))) g.FillRectangle(gb, gBtn);
            using (SolidBrush bb = new SolidBrush(Color.FromArgb(96, 165, 250))) g.FillRectangle(bb, bBtn);
            using (SolidBrush pb = new SolidBrush(Color.FromArgb(244, 114, 182))) g.FillRectangle(pb, pBtn);

            g.DrawRectangle(Pens.Gray, yBtn);
            g.DrawRectangle(Pens.Gray, gBtn);
            g.DrawRectangle(Pens.Gray, bBtn);
            g.DrawRectangle(Pens.Gray, pBtn);

            curX += 48;
            g.DrawString("Tô màu", labelFont, Brushes.Gray, curX - 70, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 2. Nhóm Gạch Chân & Gạch Bỏ
            bool isUnder = (pdfView.SelectedTool == 4);
            DrawVectorToolBtnLarge(g, curX, 68, 62, 60, (g1, x1, y1) => {
                using (Font uf = new Font("Segoe UI", 11f, FontStyle.Underline | FontStyle.Bold))
                {
                    g1.DrawString("U", uf, Brushes.Black, x1 + 5, y1 + 1);
                }
            }, "Gạch chân", isUnder);
            curX += 66;

            bool isStrike = (pdfView.SelectedTool == 5);
            DrawVectorToolBtnLarge(g, curX, 68, 60, 60, (g1, x1, y1) => {
                using (Font sf = new Font("Segoe UI", 11f, FontStyle.Strikeout | FontStyle.Bold))
                {
                    g1.DrawString("S", sf, Brushes.Black, x1 + 5, y1 + 1);
                }
            }, "Gạch bỏ", isStrike);
            curX += 64;

            bool isNote = (pdfView.SelectedTool == 6);
            DrawVectorToolBtnLarge(g, curX, 68, 60, 60, (g1, x1, y1) => {
                using (SolidBrush nb = new SolidBrush(Color.FromArgb(250, 204, 21)))
                {
                    g1.FillRectangle(nb, x1 + 2, y1 + 3, 16, 14);
                    g1.DrawString("✎", new Font("Segoe UI", 9f, FontStyle.Bold), Brushes.Brown, x1 + 4, y1 + 2);
                }
            }, "Ghi chú", isNote);
            curX += 64;

            g.DrawString("Đánh dấu", labelFont, Brushes.Gray, curX - 110, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 3. Nhóm Bút Vẽ Tay Tự Do (Freehand Ink)
            bool isInk = (pdfView.SelectedTool == 7);
            DrawVectorToolBtnLarge(g, curX, 68, 66, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(Color.FromArgb(220, 38, 38), 2.2f) { StartCap = LineCap.Round, EndCap = LineCap.Round })
                {
                    g1.DrawLine(p, x1 + 2, y1 + 16, x1 + 8, y1 + 10);
                    g1.DrawLine(p, x1 + 8, y1 + 10, x1 + 14, y1 + 14);
                    g1.DrawLine(p, x1 + 14, y1 + 14, x1 + 18, y1 + 4);
                }
            }, "Bút vẽ tay", isInk);
            curX += 70;

            // 4. Nhóm Hình khối (Shapes)
            bool isRect = (pdfView.SelectedTool == 8);
            Color rectCol = pdfView.ActiveColor != Color.Empty ? pdfView.ActiveColor : Color.FromArgb(239, 68, 68);
            DrawVectorToolBtnLarge(g, curX, 68, 58, 60, (g1, x1, y1) => {
                using (Pen p = new Pen(rectCol, 2.0f))
                {
                    g1.DrawRectangle(p, x1 + 2, y1 + 2, 16, 12);
                }
                using (SolidBrush cBar = new SolidBrush(rectCol))
                {
                    g1.FillRectangle(cBar, x1, y1 + 17, 20, 3);
                }
            }, "Khung vuông", isRect);
            curX += 66;

            // Dãy chấm màu tròn phổ biến chọn nhanh cho Khung vuông
            Color[] shapeSwatches = new Color[] {
                Color.FromArgb(239, 68, 68),  // Đỏ
                Color.FromArgb(59, 130, 246),  // Xanh dương
                Color.FromArgb(16, 185, 129),  // Xanh lá
                Color.FromArgb(245, 158, 11),  // Vàng
                Color.FromArgb(139, 92, 246),  // Tím
                Color.FromArgb(15, 23, 42)     // Đen
            };

            // Hàng 1 (y: 74..88): Đỏ, Xanh dương, Xanh lá
            for (int k = 0; k < 3; k++)
            {
                int sx = curX + (k * 18);
                int sy = 74;
                using (SolidBrush sb = new SolidBrush(shapeSwatches[k]))
                {
                    g.FillEllipse(sb, sx, sy, 14, 14);
                }
                if (pdfView.ActiveColor.ToArgb() == shapeSwatches[k].ToArgb())
                {
                    g.DrawEllipse(Pens.Black, sx - 1, sy - 1, 16, 16);
                }
            }

            // Hàng 2 (y: 96..110): Vàng, Tím, Đen
            for (int k = 3; k < 6; k++)
            {
                int sx = curX + ((k - 3) * 18);
                int sy = 96;
                using (SolidBrush sb = new SolidBrush(shapeSwatches[k]))
                {
                    g.FillEllipse(sb, sx, sy, 14, 14);
                }
                if (pdfView.ActiveColor.ToArgb() == shapeSwatches[k].ToArgb())
                {
                    g.DrawEllipse(Pens.Black, sx - 1, sy - 1, 16, 16);
                }
            }

            // Nút mở Bảng màu đầy đủ giống Writer (Biểu tượng bảng màu 4 chấm + mũi tên dropdown)
            int paletteBtnX = curX + 56;
            using (SolidBrush pBg = new SolidBrush(Color.FromArgb(241, 245, 249)))
            using (Pen pBorder = new Pen(Color.FromArgb(203, 213, 225)))
            {
                g.FillRectangle(pBg, paletteBtnX, 74, 24, 36);
                g.DrawRectangle(pBorder, paletteBtnX, 74, 24, 36);

                g.FillEllipse(Brushes.Crimson, paletteBtnX + 4, 78, 6, 6);
                g.FillEllipse(Brushes.DodgerBlue, paletteBtnX + 13, 78, 6, 6);
                g.FillEllipse(Brushes.Goldenrod, paletteBtnX + 4, 88, 6, 6);
                g.FillEllipse(Brushes.MediumPurple, paletteBtnX + 13, 88, 6, 6);

                using (Font arrFont = new Font("Segoe UI", 6f, FontStyle.Bold))
                {
                    g.DrawString("▼", arrFont, Brushes.DimGray, paletteBtnX + 6, 97);
                }
            }
            curX += 86;

            g.DrawString("Vẽ hình", labelFont, Brushes.Gray, curX - 105, 137);
            g.DrawLine(Pens.LightGray, curX, 68, curX, 148);
            curX += 10;

            // 5. Nhóm Con Dấu (Stamps)
            bool isStamp = (pdfView.SelectedTool == 10);
            Color stampC = pdfView.ActiveStampColor != Color.Empty ? pdfView.ActiveStampColor : Color.FromArgb(16, 185, 129);
            DrawVectorToolBtnLarge(g, curX, 68, 68, 60, (g1, x1, y1) => {
                using (Pen sp = new Pen(stampC, 1.8f))
                {
                    g1.DrawRectangle(sp, x1 + 2, y1 + 3, 18, 14);
                    g1.DrawString("✓", new Font("Segoe UI", 9f, FontStyle.Bold), new SolidBrush(stampC), x1 + 4, y1 + 2);
                }
            }, "Con dấu ▾", isStamp);
            curX += 72;

