                g.DrawString("A", af, ab, clrBox.X + 4, clrBox.Y + 2);
                using (Pen ap = new Pen(ab.Color, 2.5f)) g.DrawLine(ap, clrBox.X + 3, clrBox.Y + 16, clrBox.X + 15, clrBox.Y + 16);
                g.DrawString("▾", btnFont, Brushes.Gray, clrBox.Right - 14, clrBox.Y + 3);
