                            pdfView.Document.IsModified = true;
                            pdfView.SelectedSignature = sigElem;
                            pdfView.SelectedShape = null;
                            pdfView.SelectedText = null;
                            pdfView.SelectedAnnotation = null;
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    }
                }
                return true;
            }

            // 3. Tải ảnh chữ ký - Upload (x: 170..246)
            if (x >= 170 && x <= 246 && y >= 68 && y <= 130)
            {
                using (var dlg = new PdfSignatureInputDialog(initialTab: 2))
                {
                    if (dlg.ShowDialog(parentForm) == DialogResult.OK)
                    {
                        if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        {
                            pdfView.PushUndoState("Chèn chữ ký ảnh");
                            var page = pdfView.Document.Pages[pdfView.ActivePageIndex];
                            SizeF reqSize = PdfView.CalculateSignatureAutoBounds(dlg.SignerName, dlg.SignDate, dlg.Reason, dlg.SignatureImage);
                            float sigW = reqSize.Width;
                            float sigH = reqSize.Height;
                            float sigX = (page.Width - sigW) / 2f;
                            float sigY = (page.Height - sigH) / 2f;
                            var sigElem = new PdfSignatureElement(new RectangleF(sigX, sigY, sigW, sigH), dlg.SignerName);
                            sigElem.SignDate = dlg.SignDate;
                            sigElem.Reason = dlg.Reason;
                            sigElem.SignatureColor = dlg.SignatureColor;
                            if (dlg.SignatureImage != null) sigElem.SignatureImage = dlg.SignatureImage;
                            if (dlg.SignatureStrokes != null) sigElem.SignatureStrokes = new List<List<PointF>>(dlg.SignatureStrokes);
                            page.Signatures.Add(sigElem);
                            page.InvalidateCache();
                            pdfView.Document.IsModified = true;
                            pdfView.SelectedSignature = sigElem;
                            pdfView.SelectedShape = null;
                            pdfView.SelectedText = null;
                            pdfView.SelectedAnnotation = null;
                            if (parentForm != null) parentForm.Invalidate();
                        }
                    }
                }
                return true;
            }

            // 4. Hình mờ Watermark (x: 256..332) -> Mở WatermarkDropDownForm giống Writer
            if (x >= 256 && x <= 332 && y >= 68 && y <= 130)
            {
                if (pdfView == null) return false;
                if (pdfView.Document == null) pdfView.Document = new PdfDocument();

                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(256, 132)) : new Point(256, 132);
                WatermarkDropDownForm wmDlg = new WatermarkDropDownForm(pt);
                wmDlg.Owner = parentForm;
                wmDlg.OnWatermarkSelected = (wmTxt, isDiag) =>
                {
                    if (pdfView == null) return;
                    if (pdfView.Document == null) pdfView.Document = new PdfDocument();
                    if (pdfView.Document.GlobalWatermark == null) pdfView.Document.GlobalWatermark = new PdfWatermark();
                    pdfView.PushUndoState("Áp dụng hình mờ");
                    pdfView.Document.GlobalWatermark.Text = wmTxt;
                    pdfView.Document.GlobalWatermark.AngleDegrees = isDiag ? -45f : 0f;
                    pdfView.Document.GlobalWatermark.IsEnabled = true;
                    pdfView.Document.IsModified = true;
                    pdfView.InvalidateAllCaches();
                    if (parentForm != null && !parentForm.IsDisposed) parentForm.Invalidate();
                };
                wmDlg.OnCustomWatermarkClicked = () =>
                {
                    if (parentForm != null && !parentForm.IsDisposed) { parentForm.Activate(); parentForm.BringToFront(); }
                    if (pdfView == null) return;
                    if (pdfView.Document == null) pdfView.Document = new PdfDocument();
                    string curText = (pdfView.Document.GlobalWatermark != null && !string.IsNullOrEmpty(pdfView.Document.GlobalWatermark.Text))
                        ? pdfView.Document.GlobalWatermark.Text : "BẢO MẬT";
                    bool isDiag = (pdfView.Document.GlobalWatermark != null) ? (pdfView.Document.GlobalWatermark.AngleDegrees != 0) : true;
                    using (CustomWatermarkDialogForm custDlg = new CustomWatermarkDialogForm(curText, isDiag))
                    {
                        custDlg.ShowInTaskbar = false;
                        custDlg.StartPosition = FormStartPosition.CenterParent;
                        custDlg.OnApplyTextWatermark = (txt, diag, col, isSemi) =>
                        {
                            if (pdfView == null) return;
                            if (pdfView.Document == null) pdfView.Document = new PdfDocument();
                            if (pdfView.Document.GlobalWatermark == null) pdfView.Document.GlobalWatermark = new PdfWatermark();
                            pdfView.PushUndoState("Áp dụng hình mờ tùy chỉnh");
                            pdfView.Document.GlobalWatermark.Text = txt;
                            pdfView.Document.GlobalWatermark.AngleDegrees = diag ? -45f : 0f;
                            pdfView.Document.GlobalWatermark.Color = col;
                            pdfView.Document.GlobalWatermark.Opacity = isSemi ? 0.18f : 0.45f;
                            pdfView.Document.GlobalWatermark.IsEnabled = true;
                            pdfView.Document.IsModified = true;
                            pdfView.InvalidateAllCaches();
                            if (parentForm != null && !parentForm.IsDisposed) parentForm.Invalidate();
                        };
                        custDlg.OnRemoveWatermark = () =>
                        {
                            if (pdfView == null || pdfView.Document == null) return;
                            if (pdfView.Document.GlobalWatermark != null)
                            {
                                pdfView.PushUndoState("Gỡ hình mờ");
                                pdfView.Document.GlobalWatermark.IsEnabled = false;
                                pdfView.Document.IsModified = true;
                                pdfView.InvalidateAllCaches();
                            }
                            if (parentForm != null && !parentForm.IsDisposed) parentForm.Invalidate();
                        };
                        custDlg.ShowDialog(parentForm);
                    }
                    if (parentForm != null && !parentForm.IsDisposed) { parentForm.Activate(); parentForm.BringToFront(); }
                };
                wmDlg.OnRemoveWatermarkClicked = () =>
                {
                    if (pdfView == null || pdfView.Document == null) return;
                    if (pdfView.Document.GlobalWatermark != null)
                    {
                        pdfView.PushUndoState("Gỡ hình mờ");
                        pdfView.Document.GlobalWatermark.IsEnabled = false;
                        pdfView.Document.IsModified = true;
                        pdfView.InvalidateAllCaches();
                    }
                    if (parentForm != null && !parentForm.IsDisposed) parentForm.Invalidate();
                };
                if (parentForm != null && !parentForm.IsDisposed) wmDlg.Show(parentForm); else wmDlg.Show();
                return true;
            }

            // Bảo vệ PDF (x: 256..332)
            if (x >= 256 && x <= 332 && y >= 68 && y <= 130)
            {
                MessageBox.Show("Tài liệu PDF hiện đã được mã hóa bảo vệ theo tiêu chuẩn bảo mật PDF 1.7.", "Bảo mật GenOffice PDF", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return true;
            }
        }
        else if (ActiveRibbonTab == 5) // Hiển thị
        {
            // Trang thu nhỏ (x: 10..86)
            if (x >= 10 && x <= 86 && y >= 68 && y <= 130)
            {
                pdfView.ShowThumbnailsSidebar = !pdfView.ShowThumbnailsSidebar;
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // Vừa trang (Fit Best) (x: 90..166)
            if (x >= 90 && x <= 166 && y >= 68 && y <= 130)
            {
                pdfView.ZoomFitBest(formW, formH);
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // Vừa rộng (Fit Width) (x: 170..246)
            if (x >= 170 && x <= 246 && y >= 68 && y <= 130)
            {
                pdfView.ZoomFitWidth(formW, formH);
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // 100% Thực (x: 250..326)
            if (x >= 250 && x <= 326 && y >= 68 && y <= 130)
            {
                pdfView.ZoomActualSize();
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }
        }
        else if (ActiveRibbonTab == 6) // Định dạng Hộp chữ
        {
            PdfTextElement txt = pdfView.SelectedText ?? pdfView.EditingText;
            if (txt == null) return false;

            // Nút Màu Nền Ô (x: 10..74)
            if (x >= 10 && x <= 74 && y >= 68 && y <= 130)
            {
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(10, 132)) : new Point(10, 132);
                ColorPaletteForm colDlg = new ColorPaletteForm(pt, false);
                colDlg.OnColorSelected += (c) =>
                {
                    pdfView.PushUndoState("Đổi màu nền ô");
                    txt.BackgroundColor = c;
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                };
                colDlg.Show();
                return true;
            }

            // Bảng màu nhanh Màu Nền (x: 78..146)
            if (x >= 78 && x <= 96 && y >= 72 && y <= 90) { pdfView.PushUndoState("Đổi màu nền"); txt.BackgroundColor = Color.Transparent; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 100 && x <= 118 && y >= 72 && y <= 90) { pdfView.PushUndoState("Đổi màu nền"); txt.BackgroundColor = Color.White; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 122 && x <= 140 && y >= 72 && y <= 90) { pdfView.PushUndoState("Đổi màu nền"); txt.BackgroundColor = Color.FromArgb(254, 240, 138); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 78 && x <= 96 && y >= 98 && y <= 116) { pdfView.PushUndoState("Đổi màu nền"); txt.BackgroundColor = Color.FromArgb(191, 219, 254); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 100 && x <= 118 && y >= 98 && y <= 116) { pdfView.PushUndoState("Đổi màu nền"); txt.BackgroundColor = Color.FromArgb(251, 207, 232); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 122 && x <= 140 && y >= 98 && y <= 116) { pdfView.PushUndoState("Đổi màu nền"); txt.BackgroundColor = Color.FromArgb(241, 245, 249); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }

            // Nút Màu Viền Khung (x: 160..224)
            if (x >= 160 && x <= 224 && y >= 68 && y <= 130)
            {
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(160, 132)) : new Point(160, 132);
                ColorPaletteForm colDlg = new ColorPaletteForm(pt, false);
                colDlg.OnColorSelected += (c) =>
                {
                    pdfView.PushUndoState("Đổi màu viền");
                    txt.BorderColor = c;
                    txt.BorderWidth = Math.Max(1.5f, txt.BorderWidth);
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                };
                colDlg.Show();
                return true;
            }

            // Bảng màu nhanh Viền Khung (x: 228..296)
            if (x >= 228 && x <= 246 && y >= 72 && y <= 90) { pdfView.PushUndoState("Đổi màu viền"); txt.BorderColor = Color.Transparent; txt.BorderWidth = 0f; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 250 && x <= 268 && y >= 72 && y <= 90) { pdfView.PushUndoState("Đổi màu viền"); txt.BorderColor = Color.FromArgb(37, 99, 235); txt.BorderWidth = 1.5f; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 272 && x <= 290 && y >= 72 && y <= 90) { pdfView.PushUndoState("Đổi màu viền"); txt.BorderColor = Color.FromArgb(220, 38, 38); txt.BorderWidth = 1.5f; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 228 && x <= 246 && y >= 98 && y <= 116) { pdfView.PushUndoState("Đổi màu viền"); txt.BorderColor = Color.FromArgb(15, 23, 42); txt.BorderWidth = 1.5f; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 250 && x <= 268 && y >= 98 && y <= 116) { pdfView.PushUndoState("Đổi màu viền"); txt.BorderColor = Color.FromArgb(16, 185, 129); txt.BorderWidth = 1.5f; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 272 && x <= 290 && y >= 98 && y <= 116) { pdfView.PushUndoState("Đổi màu viền"); txt.BorderColor = Color.FromArgb(148, 163, 184); txt.BorderWidth = 1.5f; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }

            // === NHÓM PHÔNG CHỮ & ĐỊNH DẠNG (Tab 6) ===
            // Font Family Dropdown Popup (X: 310..425, Y: 70..92) - Khai thác toàn bộ font chữ của máy như Writer
            if (x >= 310 && x <= 425 && y >= 70 && y <= 92)
            {
                string curFont = txt != null ? txt.FontName : pdfView.ActiveFontName;
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(310, 94)) : new Point(310, 94);
                FontDropDownForm fontDlg = new FontDropDownForm(curFont, pt, AvailableSystemFonts);
                fontDlg.OnFontSelected += (font) =>
                {
                    pdfView.PushUndoState("Đổi phông chữ");
                    txt.FontName = font;
                    pdfView.ActiveFontName = font;
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                };
                fontDlg.Show();
                return true;
            }

            // Font Size Dropdown Popup (X: 429..474, Y: 70..92)
            if (x >= 429 && x <= 474 && y >= 70 && y <= 92)
            {
                float curSize = txt != null ? txt.FontSize : pdfView.ActiveFontSize;
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(429, 94)) : new Point(429, 94);
                SizeDropDownForm sizeDlg = new SizeDropDownForm(curSize, pt);
                sizeDlg.OnSizeSelected += (sz) =>
                {
                    pdfView.PushUndoState("Đổi cỡ chữ");
                    txt.FontSize = sz;
                    pdfView.ActiveFontSize = sz;
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                };
                sizeDlg.Show();
                return true;
            }

            // A▲ (X: 478..502, Y: 70..92)
            if (x >= 478 && x <= 502 && y >= 70 && y <= 92)
            {
                pdfView.PushUndoState("Tăng cỡ chữ");
                txt.FontSize = Math.Min(72f, txt.FontSize + 2f);
                pdfView.ActiveFontSize = txt.FontSize;
                if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                    pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                pdfView.Document.IsModified = true;
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // A▼ (X: 504..528, Y: 70..92)
            if (x >= 504 && x <= 528 && y >= 70 && y <= 92)
            {
                pdfView.PushUndoState("Giảm cỡ chữ");
                txt.FontSize = Math.Max(6f, txt.FontSize - 2f);
                pdfView.ActiveFontSize = txt.FontSize;
                if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                    pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                pdfView.Document.IsModified = true;
                if (parentForm != null) parentForm.Invalidate();
                return true;
            }

            // Căn lề Trái, Giữa, Phải (X: 532..608, Y: 70..92)
            if (x >= 532 && x <= 556 && y >= 70 && y <= 92) { txt.Alignment = StringAlignment.Near; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 558 && x <= 582 && y >= 70 && y <= 92) { txt.Alignment = StringAlignment.Center; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 584 && x <= 608 && y >= 70 && y <= 92) { txt.Alignment = StringAlignment.Far; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }

            // B (X: 310..334, Y: 96..118)
            if (x >= 310 && x <= 334 && y >= 96 && y <= 118) { txt.IsBold = !txt.IsBold; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            // I (X: 336..360, Y: 96..118)
            if (x >= 336 && x <= 360 && y >= 96 && y <= 118) { txt.IsItalic = !txt.IsItalic; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            // U (X: 362..386, Y: 96..118)
            if (x >= 362 && x <= 386 && y >= 96 && y <= 118) { txt.IsUnderline = !txt.IsUnderline; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }

            // Nút Màu Chữ (x: 388..426, y: 96..118)
            if (x >= 388 && x <= 426 && y >= 96 && y <= 118)
            {
                Point pt = parentForm != null ? parentForm.PointToScreen(new Point(388, 120)) : new Point(388, 120);
                ColorPaletteForm colDlg = new ColorPaletteForm(pt, false);
                colDlg.OnColorSelected += (c) =>
                {
                    pdfView.PushUndoState("Đổi màu chữ");
                    txt.TextColor = c;
                    if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                        pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                };
                colDlg.Show();
                return true;
            }

            // Bảng màu nhanh Màu Chữ (X: 428..528, Y: 96..118)
            if (x >= 428 && x <= 446 && y >= 96 && y <= 118) { pdfView.PushUndoState("Đổi màu chữ"); txt.TextColor = Color.Black; if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 448 && x <= 466 && y >= 96 && y <= 118) { pdfView.PushUndoState("Đổi màu chữ"); txt.TextColor = Color.FromArgb(220, 38, 38); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 468 && x <= 486 && y >= 96 && y <= 118) { pdfView.PushUndoState("Đổi màu chữ"); txt.TextColor = Color.FromArgb(37, 99, 235); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 488 && x <= 506 && y >= 96 && y <= 118) { pdfView.PushUndoState("Đổi màu chữ"); txt.TextColor = Color.FromArgb(16, 185, 129); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }
            if (x >= 508 && x <= 526 && y >= 96 && y <= 118) { pdfView.PushUndoState("Đổi màu chữ"); txt.TextColor = Color.FromArgb(147, 51, 234); if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count) pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache(); if (parentForm != null) parentForm.Invalidate(); return true; }

            // Nhân bản & Xóa (x: 532..608, y: 96..118)
            if (x >= 532 && x <= 568 && y >= 96 && y <= 118)
            {
                if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                {
                    pdfView.PushUndoState("Nhân bản");
                    var dup = txt.Clone();
                    dup.Bounds = new RectangleF(dup.Bounds.X + 20, dup.Bounds.Y + 20, dup.Bounds.Width, dup.Bounds.Height);
                    pdfView.Document.Pages[pdfView.ActivePageIndex].TextElements.Add(dup);
                    pdfView.SelectedText = dup;
                    pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                }
                return true;
            }
            if (x >= 570 && x <= 608 && y >= 96 && y <= 118)
            {
                if (pdfView.ActivePageIndex < pdfView.Document.Pages.Count)
                {
                    pdfView.PushUndoState("Xóa");
                    pdfView.Document.Pages[pdfView.ActivePageIndex].TextElements.Remove(txt);
                    pdfView.SelectedText = null;
                    pdfView.EditingText = null;
                    pdfView.Document.Pages[pdfView.ActivePageIndex].InvalidateCache();
                    pdfView.Document.IsModified = true;
                    if (parentForm != null) parentForm.Invalidate();
                }
                return true;
            }
        }

        return false;
    }
    #endregion

    public static Bitmap CreateExcelBorderIcon(int preset)
    {
        Bitmap bmp = new Bitmap(16, 16);
        using (Graphics g = Graphics.FromImage(bmp))
        {
            g.SmoothingMode = SmoothingMode.None;
            using (Pen gridPen = new Pen(Color.FromArgb(210, 215, 220), 1f))
            {
                gridPen.DashStyle = DashStyle.Dot;
                g.DrawRectangle(gridPen, 2, 2, 11, 11);
                g.DrawLine(gridPen, 7, 2, 7, 13);
                g.DrawLine(gridPen, 2, 7, 13, 7);
            }

            using (Pen activePen = new Pen(Color.FromArgb(15, 23, 42), 2f))
            using (Pen thinPen = new Pen(Color.FromArgb(15, 23, 42), 1f))
            {
                switch (preset)
                {
                    case 0: // Bottom
                        g.DrawLine(activePen, 2, 13, 13, 13);
                        break;
                    case 1: // Top
                        g.DrawLine(activePen, 2, 2, 13, 2);
                        break;
                    case 2: // Left
                        g.DrawLine(activePen, 2, 2, 2, 13);
                        break;
                    case 3: // Right
                        g.DrawLine(activePen, 13, 2, 13, 13);
                        break;
                    case 4: // No border
                        using (Pen redX = new Pen(Color.FromArgb(239, 68, 68), 1.5f))
                        {
                            g.DrawLine(redX, 4, 4, 11, 11);
                            g.DrawLine(redX, 11, 4, 4, 11);
                        }
                        break;
                    case 5: // All borders
                        g.DrawRectangle(thinPen, 2, 2, 11, 11);
                        g.DrawLine(thinPen, 7, 2, 7, 13);
                        g.DrawLine(thinPen, 2, 7, 13, 7);
                        break;
                    case 6: // Outside borders
                        g.DrawRectangle(thinPen, 2, 2, 11, 11);
                        break;
                    case 7: // Thick outside border
                        g.DrawRectangle(activePen, 2, 2, 11, 11);
                        break;
                    case 8: // Bottom double border
                        g.DrawLine(thinPen, 2, 12, 13, 12);
                        g.DrawLine(thinPen, 2, 14, 13, 14);
                        break;
                    case 9: // Thick bottom border
                        using (Pen thick = new Pen(Color.FromArgb(15, 23, 42), 3f))
                        {
                            g.DrawLine(thick, 2, 13, 13, 13);
                        }
                        break;
                    case 10: // Top and bottom
                        g.DrawLine(thinPen, 2, 2, 13, 2);
                        g.DrawLine(thinPen, 2, 13, 13, 13);
                        break;
                    case 11: // Top and thick bottom
                        g.DrawLine(thinPen, 2, 2, 13, 2);
                        using (Pen thick = new Pen(Color.FromArgb(15, 23, 42), 3f))
                        {
                            g.DrawLine(thick, 2, 13, 13, 13);
                        }
                        break;
                    case 12: // Top and double bottom
                        g.DrawLine(thinPen, 2, 2, 13, 2);
                        g.DrawLine(thinPen, 2, 12, 13, 12);
                        g.DrawLine(thinPen, 2, 14, 13, 14);
                        break;
                }
            }
        }
        return bmp;
    }
}
}
